def relative_strength_values(sector_tr: pd.Series, spy_tr: pd.Series,
                             sector_raw: pd.Series, spy_raw: pd.Series, M) -> pd.DataFrame:
    rel = (sector_tr / spy_tr.replace(0, np.nan)).astype(float)
    out = pd.DataFrame(index=rel.index)
    out["REL_MOM_21"] = M._mom(rel, 21)
    out["REL_MOM_63"] = M._mom(rel, 63)
    out["REL_MOM_126"] = M._mom(rel, 126)
    out["REL_MOM_12_1"] = rel.shift(21) / rel.shift(252) - 1.0
    ma50 = rel.rolling(50, min_periods=40).mean()
    ma200 = rel.rolling(200, min_periods=150).mean()
    out["REL_MA_50_200"] = ma50 / ma200.replace(0, np.nan) - 1.0
    out["REL_DD_252H"] = rel / rel.rolling(252, min_periods=120).max() - 1.0
    _delta = rel.diff()
    _gain = _delta.clip(lower=0).ewm(alpha=1 / 14, adjust=False).mean()
    _loss = (-_delta.clip(upper=0)).ewm(alpha=1 / 14, adjust=False).mean()
    out["REL_RSI_14"] = 100.0 - 100.0 / (1.0 + _gain / _loss.replace(0, np.nan))
    r_i = np.log(sector_tr.replace(0, np.nan)).diff()
    r_spy = np.log(spy_tr.replace(0, np.nan)).diff()
    vol_ratio = r_i.rolling(20).std() / r_spy.rolling(20).std().replace(0, np.nan)
    out["REL_VOL_RATIO"] = M._z(vol_ratio, 100)
    ext_i = sector_raw / sector_raw.rolling(200, min_periods=150).mean().replace(0, np.nan) - 1.0
    ext_spy = spy_raw / spy_raw.rolling(200, min_periods=150).mean().replace(0, np.nan) - 1.0
    out["REL_EXT_200"] = ext_i - ext_spy
    # [v0.3.0 §1.E-3] 상대가격 200일선'기울기' — REL_MA_50_200(수준)과 다른 정보.
    out["REL_MA200_SLOPE"] = ma200 / ma200.shift(20) - 1.0
    # [v0.40.0 §S5] 상대가격의 200MA 이격도를 252일 롤링 z로(인과 — M._z는 과거 창만 사용).
    out["REL_MA200_Z"] = M._z(rel / ma200.replace(0, np.nan) - 1.0, 252)
    return out.replace([np.inf, -np.inf], np.nan)


# ---- (c) SPY 계층 결과 + 베타 상호작용(v0.1 가족 C, 마스킹 전 백분위로 교체) ----------------------
def spy_layer_series(res: dict, M) -> Dict[str, pd.Series]:
    """M 결과 번들에서 '마스킹 전' 전체이력 백분위를 만든다. res["score_pct"]/["haz_pct"]는
    SIGNAL_START 이후만 값이 있는 리포트용 마스킹 시리즈라(v0.1 결함 (c)) 그대로 쓰면 커버리지
    게이트에서 전멸한다. res["score"]/["haz_score"]는 워크포워드 가중치가 생긴 시점부터 값이 있고
    M.score_percentile은 expanding rank(인과)이므로, 그날까지의 정보만으로 만든 백분위가 된다.
    급락트리거 백분위도 M.run()과 같은 산식(원시값×(-사전방향)의 expanding 백분위)으로 마스킹 없이 재계산."""
    out: Dict[str, pd.Series] = {}
    out["SCORE_PCT"] = M.score_percentile(res["score"])
    out["HAZ_PCT"] = M.score_percentile(res["haz_score"])
    cfg = res["cfg"]
    ft_key = getattr(cfg, "FAST_TRIGGER_INDICATOR", "VIX_TERM")
    ft_spec = next((s for s in M.INDICATOR_SPECS if s.key == ft_key), None)
    ind = res["ind"]
    if ft_spec is not None and ft_key in ind.columns and ind[ft_key].notna().any():
        out["FAST_PCT"] = M.score_percentile(ind[ft_key] * (-ft_spec.prior_sign))
    else:
        out["FAST_PCT"] = pd.Series(np.nan, index=ind.index)
    return out


def market_ok_series(res: dict, M) -> pd.Series:
    """[v0.40.0 §S3] 섹터 추세오버라이드의 '시장 확인' 시리즈 —
    **SPY가 하락 추세(가격<200일선)이거나 M의 확정 국면이 RISK_OFF인 날만 True**.

    왜: 리포트39 실측에서 SPY가 상승인데 섹터만 하락으로 판정된 218일은 21일 뒤 78%가 올랐다
    (하락적중 0.216 · μ +2.33%). 섹터 단독 200일선 하회는 섹터 고유 조정의 저점 근처인 경우가
    많아, 시장 확인 없이 강제 위험회피로 가면 반등을 안고 나온다.

    룩어헤드: 두 입력 모두 t일 종가로 확정되는 값이다. res["ind"]["TREND_200"]은 M이 그날까지의
    가격으로 만든 지표이고, res["sig"]["state"]는 M이 t일 종가로 확정한 국면(체결은 t+1 시가)이다.
    미래 정보가 없다 — sector_lookahead_audit의 절단재계산이 이를 재확인한다.
    둘 중 하나라도 없으면 전부 True를 돌려 '제약 없음'(= v0.39.0 동작)으로 안전하게 되돌아간다."""
    idx = res["ind"].index
    parts: List[pd.Series] = []
    tr = res["ind"].get("TREND_200")
    if tr is not None and tr.notna().any():
        parts.append((tr < 0).reindex(idx).fillna(False))
    sig = res.get("sig")
    if isinstance(sig, pd.DataFrame) and "state" in sig.columns:
        parts.append(sig["state"].reindex(idx).astype(str).eq("RISK_OFF").fillna(False))
    if not parts:
        return pd.Series(True, index=idx)
    out = parts[0]
    for q in parts[1:]:
        out = out | q
    return out.astype(bool)


def spy_layer_specs(beta_med: Optional[float] = None, beta_conditional: bool = False) -> List[_RawSpec]:
    """[v0.13.0 ⚠] SPY 계층 후보의 '사전방향'을 그 섹터의 베타에 따라 정한다(beta_conditional=True).

    왜: 종전에는 SPY_SCORE_PCT=+1("시장이 강하면 섹터도 오른다"), SPY_HAZ_PCT=-1("시장 위험이 높으면 섹터가
    내린다")을 **11개 섹터 전부에 똑같이** 적용했다. 그런데 CAPM의 정의상 이 방향은 베타가 1보다 큰 자산에만
    맞고, 베타<1인 방어 섹터에는 상대적으로 반대다 — 시장이 흔들릴 때 자금이 저베타로 이동하기 때문이다.
    리포트14 실측이 정확히 그 모양이다(SPY 위험점수 H와 그 섹터 익일 초과수익(SPY 대비)의 상관, 베타 오름차순):
      XLU(β0.45) +0.025 · XLP(0.51) +0.004 · XLV(0.63) +0.025 · XLRE(0.74) +0.019 · XLE(0.80) +0.015 ·
      XLI(0.90) -0.001 · XLF(0.93) +0.001 · XLB(0.94) +0.033 | XLC(1.03) -0.001 · XLY(1.14) -0.004 · XLK(1.32) -0.016
    즉 부호가 베타 1 근처에서 갈린다. 03_지표검증의 '사전방향일치' 열도 같은 말을 하고 있었다 — SPY_SCORE_PCT가
    XLP·XLV·XLRE·XLE에서 '불일치(주의)'인데도 워크포워드가 XLV·XLP·XLE에서 이 후보를 채택한 이력이 있다
    (방향이 반대인 신호를 그대로 쓴 것). 그 결과가 12_섹터요약의 전략/B&H 배율이다: XLE 0.42배 · XLV 0.62배 ·
    XLP 0.88배 · XLU 0.89배 — 저베타 섹터만 단순보유보다 못하다.
    무엇을: beta_med(그 섹터의 인과 롤링베타 중앙값)가 1 미만이면 두 후보의 사전방향을 뒤집는다. 새 지표를
    만들지도, 임계값을 탐색하지도 않는다 — CAPM이 정하는 분기점 β=1을 그대로 쓴다(BETA_X_* 후보가 이미
    (β−1) 곱으로 쓰던 바로 그 분기점). 채택 여부는 여전히 6기준 검증 + 워크포워드가 정한다.
    beta_conditional=False면 v0.12.0과 완전히 동일(모든 섹터에 +1/-1 고정).
    """
    defensive = bool(beta_conditional and beta_med is not None and np.isfinite(beta_med) and beta_med < 1.0)
    sc_sign = -1 if defensive else +1
    hz_sign = +1 if defensive else -1
    sc_why = ("베타<1(방어 성격) 섹터는 시장 강세 국면에서 상대적으로 뒤진다 — CAPM의 베타 정의 그대로"
              if defensive else "시장 전체 강세 확신이 높을수록 섹터도 상승 확률이 높다(섹터는 시장 베타를 공유)")
    hz_why = ("베타<1(방어 성격) 섹터는 시장 위험이 높아질수록 상대적으로 유리하다(저베타로의 자금 이동)"
              if defensive else "시장 위험(해저드)이 높을수록 섹터 하락 확률이 높다")
    return [
        _RawSpec("SPY_SCORE_PCT", "SPY 복합점수 백분위(M 계층, 마스킹 전)", "I.SPY계층", sc_sign,
                 sc_why, "SPY 계층 확정 출력의 재사용", "M.res[score] → score_percentile"),
        _RawSpec("SPY_HAZ_PCT", "SPY 위험점수(H) 백분위(M 계층, 마스킹 전)", "I.SPY계층", hz_sign,
                 hz_why, "SPY 계층 확정 출력의 재사용",
                 "M.res[haz_score] → score_percentile"),
        _RawSpec("BETA_X_SCORE", "(베타-1)×SPY복합점수백분위", "C.국면상호작용", +1,
                 "강세 확신이 높을수록 고베타 섹터가 더 크게 상승", "강세장에서 고베타 우위",
                 "SPY_SCORE_PCT × 롤링베타"),
        _RawSpec("BETA_X_H", "(베타-1)×SPY위험점수백분위", "C.국면상호작용", -1,
                 "시장 위험이 높을수록 고베타 섹터가 더 크게 하락", "위험 프리미엄 확대 시 고베타 할인",
                 "SPY_HAZ_PCT × 롤링베타"),
        _RawSpec("BETA_X_DH", "(베타-1)×SPY위험점수 15일변화", "C.국면상호작용", -1,
                 "위험이 가속(ΔH 급등)하는 국면에서 고베타가 더 취약", "위험 '가속도'에 대한 고베타 민감도",
                 "SPY_HAZ_PCT.diff(15) × 롤링베타"),
        _RawSpec("BETA_X_FT", "(베타-1)×급락트리거백분위", "C.국면상호작용", -1,
                 "급성 변동성 급등 국면에서 고베타가 즉각 열위", "옵션 헤지수요 급증은 고베타 자산부터 매도",
                 "FAST_PCT × 롤링베타"),
    ]


def spy_layer_values(spy_series: Dict[str, pd.Series], beta: pd.Series) -> pd.DataFrame:
    idx = beta.index
    out = pd.DataFrame(index=idx)
    sp = spy_series["SCORE_PCT"].reindex(idx)
    hp = spy_series["HAZ_PCT"].reindex(idx)
    fp = spy_series["FAST_PCT"].reindex(idx)
    bx = beta - 1.0
    out["SPY_SCORE_PCT"] = sp
    out["SPY_HAZ_PCT"] = hp
    out["BETA_X_SCORE"] = bx * sp
    out["BETA_X_H"] = bx * hp
    out["BETA_X_DH"] = bx * hp.diff(15)
    out["BETA_X_FT"] = bx * fp
    return out.replace([np.inf, -np.inf], np.nan)


