def own_evidence_lines(sres: Dict[str, Any]) -> List[Tuple[str, str]]:
    """[v0.67.0 R85] 00 줄 — 노란색이 이번에 왜 바뀌었나 · 사전등록 판정 · 장기 검증 요약."""
    out: List[Tuple[str, str]] = []
    od = (((sres.get("alloc") or {}).get("diag") or {}).get("own_evidence")) or {}
    if not od.get("enabled"):
        if od.get("error"):
            out.append(("⚠ 섹터 자기근거 채움(R85)", f"산출 실패 — {od['error']} · ★는 v0.66.0 그대로"))
        return out
    o, l_ = od.get("off", {}), od.get("live", {})
    if float(od.get("fill", 0) or 0) > 0:
        out.append(("★★★ 노란색(라이브) 수익배수 — R85에서 바뀐 이유",
                    f"사용자 지시대로 **섹터 자신의 상승 근거**로 M 예산 위를 채웠다: M이 일부만 준 날(0<E_t<1) 남는 현금의 "
                    f"{od['fill']:.0%}를 상승 근거 섹터 상위 {od.get('k', 2)}개(주력 제외)로. "
                    f"★ 배수 {o.get('배수', np.nan):.3f} → **{l_.get('배수', np.nan):.3f}** · CAGR {o.get('CAGR', np.nan) * 100:.2f}% → "
                    f"{l_.get('CAGR', np.nan) * 100:.2f}% · MDD {o.get('MDD', np.nan) * 100:.2f}% → {l_.get('MDD', np.nan) * 100:.2f}% · "
                    f"칼마 {o.get('칼마', np.nan):.3f} → {l_.get('칼마', np.nan):.3f} · 발동 {od.get('fill_days', 0)}일. "
                    "⚠ 노출을 늘리는 위험 파라미터 변경이다 — 되돌리기 s_overrides={'OWN_EVIDENCE_FILL': 0.0}. 세부는 00S 시트."))
    else:
        out.append(("★★ 노란색(라이브) 수익배수 — R86: R85 채움 되돌림",
                    f"R85 사전등록 (d)대로 채움을 껐다(OWN_EVIDENCE_FILL=0) — ★는 v0.66.0 규칙과 같다(채움 OFF 행 = ★). 근거: 엔진 장기 검증 "
                    "2000~2017(독립)에서 섹터 자기 근거 채움이 SPY 채움과 무작위 섹터보다 나빴다(R85: 칼마 0.329 vs 0.362 · 대조군 95% 0.366). "
                    "표본 안(2018~) 배수 +1.6%는 표본 운일 가능성이 크다. 다시 켜기 s_overrides={'OWN_EVIDENCE_FILL': 0.25}. 이번 판정은 00S."))
    cr = od.get("criteria") or {}
    out.append(("★★ [섹터근거격자] 사전등록 판정(R85 · 엔진 값)",
                " · ".join(f"{k} {'O' if v else 'X'}" for k, v in cr.items())
                + f" | 대조군(같은 날·같은 몫 무작위) 95% {od.get('ctl_q95', np.nan):.3f} · 백분위 {od.get('pctile', np.nan):.0f}"
                + (" → ⚠ 되돌림 조건 해당(다음 라운드 OWN_EVIDENCE_FILL=0.0)" if od.get("revert_next") else " → 되돌림 조건 해당 없음")))
    lg = od.get("long") or {}
    tb = lg.get("table") if isinstance(lg, dict) else None
    if isinstance(tb, pd.DataFrame) and len(tb):
        parts = []
        for era in tb["구간"].unique():
            t_ = tb[tb["구간"] == era].set_index("변형")
            try:
                b = t_[t_.index.str.startswith("M 단독")].iloc[0]
                f1 = t_[t_.index.str.startswith("①")].iloc[0]
                f2 = t_[t_.index.str.startswith("②")].iloc[0]
                f3 = t_[t_.index.str.startswith("③ ")].iloc[0]
                _src = str(t_["예산 출처"].iloc[0]) if "예산 출처" in t_.columns else "M E_t"
                parts.append(f"{era}[{_src}]: 기준 칼마 {b['칼마']:.3f} | ①SPY 채움 {f1['칼마']:.3f} · ②상승근거 채움 {f2['칼마']:.3f}"
                             f"(대조군 95% {f2.get('대조군 칼마 95%', np.nan):.3f} · 백분위 {f2.get('대조군 대비 백분위', np.nan):.0f}) | "
                             f"③E_t=0 상승근거 {f3['칼마']:.3f}(백분위 {f3.get('대조군 대비 백분위', np.nan):.0f}) · "
                             f"하락포착 {b['하락포착']:.2f}→{f3['하락포착']:.2f}")
            except Exception:
                continue
        if parts:
            out.append(("★★ 섹터 자기근거 장기 검증(엔진 1999~ · M E_t · 측정 전용)", " || ".join(parts)))
    elif isinstance(lg, dict) and lg.get("error"):
        out.append(("⚠ 섹터 자기근거 장기 검증", f"산출 실패 — {lg['error']}"))
    return out


# =============================================================================
# [v0.68.0 R86 ★★★ 신규] 사용자 정의 신뢰도 — "하락을 잘 피하고 상승을 잘 타는가"(노란색 배수로 드러나는 것)
# =============================================================================
#   사용자 지시(2026-09-22): "신뢰도를 높이라는건 하락 잘 피하고 상승 잘타는 건데 그걸 잘하면 수익배수도 늘어나게 되는데",
#     "신뢰도는 내가 얘기했던 방법인거 알지?". ⇒ R82~R84의 '신뢰도'(IC·t̄ 등급)는 **선택 신호 통계**로 이름을 바꾸고,
#     00 맨 앞의 '신뢰도'는 이 정의로 잰다.
#   정의(같은 잣대로 M·S★·I★·단일 예측을 잰다 — 진단 전용, 사후 구간 분할이라 신호에 쓰지 않는다):
#     포트폴리오(노란색 행) — SPY 단순보유 곡선의 지그재그 구간(USER_REL_SEG_PORT = 5% · 3거래일)마다 전략 수익(구간 복리):
#       하락 회피율 = 1 − Σ(하락구간 전략 수익) / Σ(하락구간 SPY 수익)   (SPY가 잃은 것 중 피한 몫 · 1.0 = 전부 피함)
#       상승 참여율 = Σ(상승구간 전략 수익) / Σ(상승구간 SPY 수익)       (SPY가 번 것 중 탄 몫 · 1.0 = 다 탐 · >1 = 더 탐)
#     단일 예측(섹터·산업별 라이브 단독 노출) — 그 자산 B&H 지그재그(USER_REL_SEG_ASSET = 7% · 3거래일 · I 00D와 같다):
#       하락 회피율 = 1 − Σ_하락(w·r) / Σ_하락(r) · 상승 참여율 = Σ_상승(w·r) / Σ_상승(r)  (자산-일 단순합 · 전 자산 합산)
#   등급(R86 사전등록 — 숫자를 보기 전에 정한 둥근 값, 바꾸지 않는다):
#     높음 = 회피율 ≥ 0.70 그리고 참여율 ≥ 0.90 · 중간 = 회피율 ≥ 0.50 그리고 참여율 ≥ 0.70 · 낮음 = 그 밖(순효과 > 0) · 없음 = 순효과 ≤ 0.
#     구간 안정성: 앞(2018~2021)·뒤(2022~) 절반의 등급이 같으면 '확정', 다르면 '(구간 불안정)'을 붙인다.

def user_grade(av: float, pa: float, net: float, cfg) -> str:
    hi = tuple(getattr(cfg, "USER_REL_HIGH", (0.70, 0.90)))
    mid = tuple(getattr(cfg, "USER_REL_MID", (0.50, 0.70)))
    if not (av == av and pa == pa):
        return "-"
    if net == net and net <= 0:
        return "없음"
    if av >= hi[0] and pa >= hi[1]:
        return "높음"
    if av >= mid[0] and pa >= mid[1]:
        return "중간"
    return "낮음"


def _zz_valid(level: pd.Series, mm: float, md: int) -> List[Tuple[str, pd.Timestamp, pd.Timestamp]]:
    s = pd.Series(level).dropna().astype(float)
    out = []
    for kind, a, b in zigzag_segments(s, mm, md):
        if str(kind) not in ("상승", "하락") or b - a < int(md):
            continue
        out.append((str(kind), s.index[a], s.index[b]))
    return out


def user_rel_portfolio(rets: Dict[str, pd.Series], spy_ret: pd.Series, cfg,
                       split: Optional[str] = None) -> pd.DataFrame:
    """노란색(포트폴리오) 행들의 사용자 신뢰도. rets: {라벨: 일수익}, spy_ret: SPY 일수익(같은 창)."""
    mm, md = tuple(getattr(cfg, "USER_REL_SEG_PORT", (0.05, 3)))
    sp = pd.to_numeric(pd.Series(spy_ret), errors="coerce").fillna(0.0)
    lev = (1.0 + sp).cumprod()
    segs = _zz_valid(lev, float(mm), int(md))
    spl = pd.Timestamp(split or getattr(cfg, "USER_REL_SPLIT", "2022-01-01"))
    rows = []
    for lab, r in rets.items():
        rr = pd.to_numeric(pd.Series(r), errors="coerce").reindex(sp.index).fillna(0.0)
        eq = (1.0 + rr).cumprod()

        def _agg(sel):
            dn_s = dn_b = up_s = up_b = 0.0
            nd = nu = 0
            for kind, a, b in sel:
                bs = float(lev.loc[b] / lev.loc[a] - 1.0)
                ss = float(eq.loc[b] / eq.loc[a] - 1.0)
                if kind == "하락":
                    dn_s += ss; dn_b += bs; nd += 1
                else:
                    up_s += ss; up_b += bs; nu += 1
            av = 1.0 - dn_s / dn_b if dn_b < 0 else np.nan
            pa = up_s / up_b if up_b > 0 else np.nan
            net = (dn_s - dn_b + up_s - up_b) * 100.0
            return av, pa, net, nd, nu
        av, pa, net, nd, nu = _agg(segs)
        a1, p1, n1, _, _ = _agg([x for x in segs if x[1] < spl])
        a2, p2, n2, _, _ = _agg([x for x in segs if x[1] >= spl])
        g, g1, g2 = user_grade(av, pa, net, cfg), user_grade(a1, p1, n1, cfg), user_grade(a2, p2, n2, cfg)
        n = len(rr)
        cg = float(eq.iloc[-1] ** (252.0 / max(n, 1)) - 1.0) if n else np.nan
        mdd = float((eq / eq.cummax() - 1.0).min()) if n else np.nan
        rows.append({"전략": lab, "하락구간 수": nd, "상승구간 수": nu,
                     "하락 회피율": round(av, 4) if av == av else np.nan, "상승 참여율": round(pa, 4) if pa == pa else np.nan,
                     "순효과(%p)": round(net, 1), "등급": g,
                     f"앞 절반(~{spl.year - 1}) 회피/참여": (f"{a1:.3f}/{p1:.3f}" if a1 == a1 and p1 == p1 else "-"),
                     f"뒤 절반({spl.year}~) 회피/참여": (f"{a2:.3f}/{p2:.3f}" if a2 == a2 and p2 == p2 else "-"),
                     "절반 등급": f"{g1}/{g2}", "안정성": ("확정" if g1 == g2 == g else "(구간 불안정)"),
                     "배수": round(float(eq.iloc[-1]), 3) if n else np.nan, "MDD": round(mdd, 4),
                     "칼마": (round(cg / abs(mdd), 3) if mdd < 0 else np.nan)})
    return pd.DataFrame(rows)


def user_rel_single(pos: pd.DataFrame, ret: pd.DataFrame, cfg) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """단일 예측(자산별 라이브 단독 노출 w, **체결** 기준)의 사용자 신뢰도 — 자산별 + 전 자산 합산(I 00D와 같은 산식)."""
    mm, md = tuple(getattr(cfg, "USER_REL_SEG_ASSET", (0.07, 3)))
    rows = []
    T = {"dn_s": 0.0, "dn_b": 0.0, "up_s": 0.0, "up_b": 0.0}
    for c in ret.columns:
        r = pd.to_numeric(ret[c], errors="coerce")
        w = pd.to_numeric(pos[c], errors="coerce").reindex(r.index) if c in pos.columns else None
        m = r.notna()
        if w is None or int(m.sum()) < 120:
            continue
        r = r[m]; w = w[m].fillna(0.0)
        lev = (1.0 + r).cumprod()
        d = {"dn_s": 0.0, "dn_b": 0.0, "up_s": 0.0, "up_b": 0.0}
        for kind, a, b in _zz_valid(lev, float(mm), int(md)):
            sel = (r.index > a) & (r.index <= b)
            k = "dn" if kind == "하락" else "up"
            d[k + "_s"] += float((w[sel] * r[sel]).sum()); d[k + "_b"] += float(r[sel].sum())
        for k in T:
            T[k] += d[k]
        av = 1.0 - d["dn_s"] / d["dn_b"] if d["dn_b"] < 0 else np.nan
        pa = d["up_s"] / d["up_b"] if d["up_b"] > 0 else np.nan
        net = (d["dn_s"] - d["dn_b"] + d["up_s"] - d["up_b"]) * 100.0
        rows.append({"자산": c, "하락 회피율": round(av, 4) if av == av else np.nan,
                     "상승 참여율": round(pa, 4) if pa == pa else np.nan, "순효과(%p)": round(net, 1),
                     "등급": user_grade(av, pa, net, cfg)})
    av = 1.0 - T["dn_s"] / T["dn_b"] if T["dn_b"] < 0 else np.nan
    pa = T["up_s"] / T["up_b"] if T["up_b"] > 0 else np.nan
    net = (T["dn_s"] - T["dn_b"] + T["up_s"] - T["up_b"]) * 100.0
    agg = {"하락 회피율": av, "상승 참여율": pa, "순효과(%p)": net, "등급": user_grade(av, pa, net, cfg), "자산 수": len(rows)}
    return pd.DataFrame(rows), agg


# =============================================================================
# [v0.68.0 R86 ★★ 신규 · 측정 전용] 섹터 거시 근거 — 가격 추세가 아닌 **섹터 고유 경제 동인**으로 '국면을 안 따라가는 섹터'를 찾는다
# =============================================================================
#   왜: R85에서 섹터 자기 가격 근거(자기 추세·상대 추세·국면기계)는 엔진 장기 검증 2000~2017에서 SPY·무작위보다 나빴다
#     (② 칼마 0.329 < ① 0.362 · 대조군 95% 0.366 · ③ E_t=0 0.230 < M 단독 0.359). 남은 '섹터별 근거'는 섹터마다 다른 경제 동인이다.
#   동인(사전 지정 — 교과서적 방향 하나씩, 결과를 보고 바꾸지 않는다):
#     XLE ← 유가 CL=F(+) · XLB ← 구리 HG=F(+) · XLI ← 구리 HG=F(+) · XLF ← 장단기 금리차 T10Y2Y(+)
#     XLU ← 10년 금리 DGS10(−) · XLRE ← 10년 금리 DGS10(−) · XLK ← 10년 실질금리 DFII10(−) · XLY ← 하이일드 스프레드 BAMLH0A0HYM2(−)
#     XLP·XLV·XLC ← 없음(방어·혼합 — 억지로 붙이지 않는다).
#   순풍 = 부호 × (X_t − X_{t−63}) > 0 · 역풍 = < 0. FRED는 M의 발표 지연(lag_days)만큼 늦춘다(없으면 1일). 전부 t일까지의 값.
#   M에 있는 자료만 쓴다(res["px_dict"] · res["fred"]). 없는 동인은 그 섹터를 '동인 없음'으로 두고 로그에 남긴다.

def macro_driver_states(res: dict, idx: pd.DatetimeIndex, secs: List[str], cfg, M=None
                        ) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    drv = dict(getattr(cfg, "SECTOR_MACRO_DRIVERS", {}) or {})
    lb = int(getattr(cfg, "MACRO_LOOKBACK", 63))
    px = (res or {}).get("px_dict") or {}
    fred = (res or {}).get("fred") or {}
    lagmap = {}
    try:
        lagmap = {k: int(v[1]) for k, v in dict(getattr(M, "FRED_SERIES", {}) or {}).items()}
    except Exception:
        lagmap = {}
    tail = pd.DataFrame(False, index=idx, columns=secs)
    head = pd.DataFrame(False, index=idx, columns=secs)
    info: Dict[str, Any] = {}
    for s in secs:
        spec = drv.get(s)
        if not spec:
            info[s] = "동인 없음(사전 지정)"
            continue
        sid, sgn = str(spec[0]), float(spec[1])
        x = None
        try:
            if sid in px and isinstance(px[sid], pd.DataFrame) and len(px[sid]):
                _d = px[sid]
                _c = "Adj Close" if "Adj Close" in _d.columns else ("Close" if "Close" in _d.columns else None)
                if _c is not None:
                    x = pd.to_numeric(_d[_c], errors="coerce")
                    x = x[~x.index.duplicated(keep="last")].sort_index().reindex(idx).ffill()
                    x = np.log(x.where(x > 0))                   # 가격은 로그 변화
            elif sid in fred and fred[sid] is not None and len(pd.Series(fred[sid]).dropna()):
                _f = pd.to_numeric(pd.Series(fred[sid]), errors="coerce")
                _f = _f[~_f.index.duplicated(keep="last")].sort_index()
                x = _f.reindex(idx).ffill().shift(max(1, int(lagmap.get(sid, 1))))   # 발표 지연만큼 늦춘다(룩어헤드 차단)
        except Exception as _e:
            info[s] = f"{sid} 읽기 실패 {type(_e).__name__}"
            continue
        if x is None or int(x.notna().sum()) < lb + 60:
            info[s] = f"{sid} 없음/부족 — 동인 없음 처리"
            continue
        ch = (x - x.shift(lb)) * sgn
        tail[s] = (ch > 0).fillna(False)
        head[s] = (ch < 0).fillna(False)
        info[s] = f"{sid}({'+' if sgn > 0 else '−'}) · 첫 값 {str(ch.first_valid_index())[:10]} · 순풍 비율 {float(tail[s][ch.notna()].mean()):.2f}"
    return tail, head, info


def macro_long_audit(level: pd.DataFrame, E: pd.Series, spy_ret: pd.Series, spy_level: Optional[pd.Series],
                     tail: pd.DataFrame, rf: Optional[pd.Series], cfg, cost_bps: float = 5.0, M=None) -> Dict[str, Any]:
    """[R86 측정 전용] 장기 검증(엔진 전체 이력) — 기준선 M 단독(E_t×SPY) 위에:
       L2 E_t=0일 거시 순풍 & 자기 추세 상승 섹터 1위 × pos(사용자 가설: 국면을 안 따라가는 섹터를 **경제 동인**으로)
       L3 부분예산일 남는 현금 × f → 거시 순풍 & 자기 추세 상승 상위 k
       각각 같은 날·같은 몫 무작위 섹터 대조군과 비교하고, **사용자 신뢰도(회피율·참여율)**와 칼마를 구간(2000~2017 · 2018~)별로 싣는다.
       예산: 그 구간에 M E_t 부분예산일이 60일 미만이면 M 대용 3상태(SPY 200일선·12개월 — own_long_audit과 같은 정의)."""
    t0 = time.time()
    f = float(getattr(cfg, "MACRO_FILL", 0.25) or 0.25)
    k = int(getattr(cfg, "OWN_EVIDENCE_FILL_K", 2) or 2)
    pos = float(getattr(cfg, "MACRO_OFF_POS", 0.25) or 0.25)
    nctl = int(getattr(cfg, "MACRO_CONTROLS", 12) or 0)
    seed = int(getattr(cfg, "MACRO_SEED", 20260924))
    L = level.sort_index(); idx = L.index; secs = list(L.columns)
    fr = own_evidence_frames(L, None, int(getattr(cfg, "OWN_EVIDENCE_N_LONG", 200)), int(getattr(cfg, "OWN_EVIDENCE_N_SHORT", 50)),
                             int(getattr(cfg, "OWN_EVIDENCE_N_REL", 50)), int(getattr(cfg, "OWN_EVIDENCE_N_RS", 63)))
    R = L.pct_change(fill_method=None)
    sp = pd.to_numeric(spy_ret.reindex(idx), errors="coerce")
    rfv = (pd.to_numeric(rf.reindex(idx), errors="coerce").fillna(0.0) if rf is not None else pd.Series(0.0, index=idx))
    listed = L.notna()
    cand = tail.reindex(index=idx, columns=secs).fillna(False).astype(bool) & fr["own_up"] & listed
    pool = fr["own_up"] & listed
    E_m = pd.to_numeric(E.reindex(idx), errors="coerce").fillna(0.0).clip(lower=0.0)
    E_px = None
    if spy_level is not None and len(pd.Series(spy_level).dropna()) > 300:
        _P = pd.to_numeric(pd.Series(spy_level), errors="coerce").reindex(idx).ffill()
        _tr = _P > _P.rolling(200, min_periods=200).mean()
        _mo = (_P / _P.shift(252) - 1.0) > 0
        _ok = _P.rolling(252, min_periods=252).mean().notna()
        E_px = pd.Series(np.where(_tr & _mo, 1.0, np.where((~_tr) & (~_mo), 0.0, 0.5)), index=idx).where(_ok, 0.0)
    cb = float(cost_bps) / 1e4
    zero = pd.DataFrame(0.0, index=idx, columns=secs)

    def _run(Ws: pd.DataFrame, Wp: pd.Series) -> pd.Series:
        ws = Ws.reindex(columns=secs).fillna(0.0); wp = Wp.reindex(idx).fillna(0.0)
        g = (ws.shift(2).fillna(0.0) * R.fillna(0.0)).sum(axis=1) + wp.shift(2).fillna(0.0) * sp.fillna(0.0)
        ex = ws.shift(2).fillna(0.0).sum(axis=1) + wp.shift(2).fillna(0.0)
        tn = (ws.diff().abs().sum(axis=1) + wp.diff().abs()).shift(2).fillna(0.0)
        return g + (1.0 - ex).clip(lower=0.0) * rfv - tn * cb
    sel_k = _own_top_by(fr["rs"], cand, k); sel_1 = _own_top_by(fr["rs"], cand, 1)

    def _suite(Ev: pd.Series) -> Dict[str, Any]:
        part = (Ev > 1e-12) & (Ev < 1.0 - 1e-12); off = Ev <= 1e-12
        rem = ((1.0 - Ev).clip(lower=0.0) * f).where(part & (sel_k.sum(axis=1) > 0), 0.0)
        offd = off & (sel_1.sum(axis=1) > 0)
        runs = {"M 단독(E_t×SPY)": _run(zero, Ev),
                f"L2 E_t=0일 거시 순풍 섹터 1위 × {pos:.0%}": _run(sel_1.mul(pos * offd.astype(float), axis=0), Ev),
                f"L2' 같은 날 SPY × {pos:.0%}(비교)": _run(zero, Ev + pos * offd.astype(float)),
                f"L3 부분예산일 남는 현금×{f:.0%} → 거시 순풍 상위{k}": _run(sel_k.mul(rem, axis=0), Ev),
                f"L3' 같은 몫 SPY(비교)": _run(zero, Ev + rem)}
        ctl = {"L2": [], "L3": []}
        for j in range(nctl):
            r1 = _own_rand_sel(pool, 1, seed + j)
            ctl["L2"].append(_run(r1.mul(pos * (off & (r1.sum(axis=1) > 0) & offd).astype(float), axis=0), Ev))
            rk = _own_rand_sel(pool, k, seed + 500 + j)
            ctl["L3"].append(_run(rk.mul(rem.where(rk.sum(axis=1) > 0, 0.0), axis=0), Ev))
        return {"runs": runs, "ctl": ctl, "rem": rem, "offd": offd, "part": part}
    suites = {"M E_t": _suite(E_m)}
    eras = (("2000~2017(독립)", pd.Timestamp("2000-01-01"), pd.Timestamp("2017-12-31")),
            ("2018~(★ 평가창)", pd.Timestamp("2018-01-01"), idx[-1] if len(idx) else pd.Timestamp("2018-01-01")))
    rows: List[Dict[str, Any]] = []
    for en, s0, s1 in eras:
        m = (idx >= s0) & (idx <= s1)
        if int(m.sum()) < 250:
            continue
        src = "M E_t"
        if int((suites["M E_t"]["part"] & m).sum()) < 60 and E_px is not None:
            if "M 대용 3상태" not in suites:
                suites["M 대용 3상태"] = _suite(E_px)
            src = "M 대용 3상태"
        su = suites[src]
        ur = user_rel_portfolio({lab: r[m] for lab, r in su["runs"].items()}, sp[m].fillna(0.0), cfg)
        urc = {key: user_rel_portfolio({f"c{j}": c[m] for j, c in enumerate(cl)}, sp[m].fillna(0.0), cfg)
               for key, cl in su["ctl"].items()}
        b = ur.iloc[0]
        for _, u in ur.iterrows():
            lab = str(u["전략"]); key = lab.split(" ")[0]
            row = {"구간": en, "예산 출처": src, "변형": lab, "하락 회피율": u["하락 회피율"], "상승 참여율": u["상승 참여율"],
                   "Δ회피(%p)": round((u["하락 회피율"] - b["하락 회피율"]) * 100, 2),
                   "Δ참여(%p)": round((u["상승 참여율"] - b["상승 참여율"]) * 100, 2),
                   "등급": u["등급"], "배수": u["배수"], "MDD": u["MDD"], "칼마": u["칼마"],
                   "발동일": (int((su["offd"] & m).sum()) if key.startswith("L2") else
                             (int(((su["rem"] > 0) & m).sum()) if key.startswith("L3") else None))}
            if key in urc:
                cc = urc[key]["칼마"].astype(float).dropna().values
                cs = (urc[key]["하락 회피율"] + urc[key]["상승 참여율"]).astype(float).dropna().values
                row.update({"대조군 칼마 95%": round(float(np.quantile(cc, 0.95)), 3) if len(cc) else np.nan,
                            "대조군 칼마 백분위": round(float((cc < u["칼마"]).mean() * 100), 1) if len(cc) else np.nan,
                            "대조군 (회피+참여) 95%": round(float(np.quantile(cs, 0.95)), 4) if len(cs) else np.nan})
            rows.append(row)
    tab = pd.DataFrame(rows)
    verdict = {}
    for key in ("L2", "L3"):
        ok = []
        for en, _, _ in eras:
            t_ = tab[(tab["구간"] == en) & (tab["변형"].str.startswith(key + " "))] if len(tab) else tab
            if not len(t_):
                ok.append(None); continue
            r_ = t_.iloc[0]
            ok.append(bool(r_["Δ회피(%p)"] >= -1.0 and r_["Δ참여(%p)"] >= -1.0 and (r_["Δ회피(%p)"] + r_["Δ참여(%p)"]) >= 2.0
                           and r_["칼마"] == r_["칼마"] and r_.get("대조군 칼마 95%") == r_.get("대조군 칼마 95%")
                           and r_["칼마"] > r_["대조군 칼마 95%"]))
        verdict[key] = {"eras": ok, "pass": bool(ok and all(x is True for x in ok))}
    for r_ in rows:
        log("MACRO", kv(event="long_audit_row", era=r_["구간"][:9], src=r_["예산 출처"], variant=str(r_["변형"])[:30],
                        avoid=r_["하락 회피율"], part=r_["상승 참여율"], d_avoid=r_["Δ회피(%p)"], d_part=r_["Δ참여(%p)"],
                        calmar=r_["칼마"], ctl_q95=r_.get("대조군 칼마 95%"), days=r_.get("발동일")), M=M)
    log("MACRO", kv(event="long_audit_done", rows=len(rows), L2_pass=verdict.get("L2", {}).get("pass"),
                    L3_pass=verdict.get("L3", {}).get("pass"), fill=f, pos=pos, controls=nctl, seed=seed,
                    sec=round(time.time() - t0, 1), note="측정 전용 — ★ 무변경"), M=M)
    return {"enabled": True, "table": tab, "verdict": verdict, "fill": f, "pos": pos, "controls": nctl, "seed": seed}


def user_reliability_pack(sres: Dict[str, Any], cfg) -> Dict[str, Any]:
    """[v0.68.0 R86] 리포트 단계에서 사용자 신뢰도를 한 번에 계산 — M · S★ · ★ 계열 격자(프런티어) · 섹터 단일 예측."""
    al = sres.get("alloc") or {}
    dg = al.get("diag") or {}
    bts = al.get("bts") or {}
    lp = dg.get("label_primary")
    spy = al.get("spy_ret")
    out: Dict[str, Any] = {"enabled": False}
    if not (lp in bts and spy is not None and len(pd.Series(spy).dropna())):
        out["error"] = "S★ 또는 SPY 수익 없음"
        return out
    spy = pd.to_numeric(pd.Series(spy), errors="coerce").fillna(0.0)
    rets = {lp: bts[lp]["strategy_ret"]}
    mret = al.get("spy_m_ret")
    if mret is not None:
        rets["M(SPY 국면전략)"] = mret
    rets["SPY 단순보유(B&H)"] = spy
    head = user_rel_portfolio(rets, spy, cfg)
    fr_labels = [l for l in bts if l != lp and "대조" not in str(l)]
    front = user_rel_portfolio({l: bts[l]["strategy_ret"] for l in fr_labels}, spy, cfg) if fr_labels else pd.DataFrame()
    hi = tuple(getattr(cfg, "USER_REL_HIGH", (0.70, 0.90)))
    if len(front):
        front["높음까지 거리(%p)"] = ((np.maximum(0.0, hi[0] - front["하락 회피율"]) + np.maximum(0.0, hi[1] - front["상승 참여율"])) * 100).round(1)
        front = front.sort_values("높음까지 거리(%p)").reset_index(drop=True)
    secs = sres.get("sectors") or {}
    pos = pd.DataFrame({t: pd.Series(r.get("pos_exec")) for t, r in secs.items() if isinstance(r, dict) and r.get("pos_exec") is not None})
    ret = pd.DataFrame({t: pd.Series(r.get("bh_ret")) for t, r in secs.items() if isinstance(r, dict) and r.get("bh_ret") is not None})
    single, sagg = (user_rel_single(pos, ret, cfg) if len(pos.columns) and len(ret.columns) else (pd.DataFrame(), {}))
    out.update({"enabled": True, "head": head, "front": front, "single": single, "single_agg": sagg, "label_primary": lp,
                "n_front": int(len(front)), "n_high": int((front["등급"] == "높음").sum()) if len(front) else 0})
    return out


def build_user_reliability_sheet(sres: Dict[str, Any], cfg, pack: Optional[Dict[str, Any]] = None,
                                 layer: str = "섹터") -> pd.DataFrame:
    """[v0.68.0 R86] 00U_사용자신뢰도 — 사용자 정의 신뢰도(하락 회피·상승 참여) 판정 시트(맨 앞). layer="산업"이면 I가 같은 함수로 쓴다."""
    pk = pack if pack is not None else user_reliability_pack(sres, cfg)
    _star = "S★" if layer == "섹터" else "I★"
    hi = tuple(getattr(cfg, "USER_REL_HIGH", (0.70, 0.90))); mid = tuple(getattr(cfg, "USER_REL_MID", (0.50, 0.70)))
    pm = tuple(getattr(cfg, "USER_REL_SEG_PORT", (0.05, 3))); am = tuple(getattr(cfg, "USER_REL_SEG_ASSET", (0.07, 3)))
    parts: List[pd.DataFrame] = []

    def _t(blk: str, rows: List[Dict[str, Any]]) -> None:
        parts.append(pd.DataFrame([{"블록": blk, **r} for r in rows]))
    _t("A. 읽는 법", [
        {"항목": "신뢰도(사용자 정의)", "값": "하락을 잘 피하고 상승을 잘 타는가 — 잘하면 노란색(라이브) 수익배수가 오른다. R82~R84의 IC·t̄ 등급은 "
                                       "'선택 신호 통계'(00R · 참고)로 이름을 바꿨다."},
        {"항목": "포트폴리오(노란색 행)", "값": f"SPY 단순보유 곡선 지그재그 구간({pm[0]:.0%} · {int(pm[1])}거래일). 하락 회피율 = 1 − Σ하락구간 전략수익 / "
                                         "Σ하락구간 SPY수익 · 상승 참여율 = Σ상승구간 전략수익 / Σ상승구간 SPY수익(1.0 초과 = SPY보다 더 탐)."},
        {"항목": f"단일 예측({layer}별)", "값": f"그 {layer} B&H 지그재그({am[0]:.0%} · {int(am[1])}거래일) · 라이브 단독 체결비중 w: 회피율 = 1 − Σ하락(w·r)/Σ하락(r) · "
                                      f"참여율 = Σ상승(w·r)/Σ상승(r) · 전 {layer} 합산(I 00D와 같은 산식)."},
        {"항목": "등급(R86 사전등록 · 바꾸지 않음)", "값": f"높음 = 회피 ≥ {hi[0]:.0%} & 참여 ≥ {hi[1]:.0%} · 중간 = 회피 ≥ {mid[0]:.0%} & 참여 ≥ {mid[1]:.0%} · "
                                                   "낮음 = 그 밖(순효과 > 0) · 없음 = 순효과 ≤ 0. 앞(~2021)·뒤(2022~) 절반 등급이 같으면 '확정'."},
        {"항목": "⚠", "값": "구간은 사후 분할이다 — 판정(진단)에만 쓰고 신호에는 쓰지 않는다. 연구·교육용이며 투자 자문이 아니다."}])
    if not pk.get("enabled"):
        _t("B. 등급", [{"항목": "상태", "값": f"산출 실패 — {pk.get('error', '-')}"}])
        return pd.concat(parts, ignore_index=True, sort=False)
    hd = pk["head"].copy(); hd.insert(0, "항목", hd.pop("전략"))
    parts.append(hd.assign(블록=f"B. 등급 — 노란색({_star})·M·SPY"))
    sa = pk.get("single_agg") or {}
    if sa:
        _t(f"B. 등급 — 노란색({_star})·M·SPY", [{"항목": f"{layer} 단일 예측 합산({sa.get('자산 수', 0)}개)",
                                          "하락 회피율": round(sa["하락 회피율"], 4), "상승 참여율": round(sa["상승 참여율"], 4),
                                          "순효과(%p)": round(sa["순효과(%p)"], 1), "등급": sa["등급"]}])
    sg = pk.get("single")
    if isinstance(sg, pd.DataFrame) and len(sg):
        s2 = sg.copy(); s2.insert(0, "항목", s2.pop("자산"))
        parts.append(s2.assign(블록=f"C. {layer}별 단일 예측"))
    fr = pk.get("front")
    if isinstance(fr, pd.DataFrame) and len(fr):
        _t("D. 프런티어 — 지금 가진 손잡이로 어디까지 가나", [{"항목": "읽는 법", "값": (
            f"13 시트의 모든 비교·격자 행({len(fr)}행 · 대조군 제외)을 같은 잣대로 잰 것. '높음' 도달 {pk.get('n_high', 0)}행. "
            "위에서부터 '높음까지 거리'(회피·참여 부족분 합)가 가까운 순. 한쪽을 올리면 다른 쪽이 내려가면 **프런티어 위를 움직일 뿐**이다 — "
            "둘 다 올리려면 M보다 나은 타이밍 정보(새 근거)가 필요하다.")}])
        f2 = fr.copy(); f2.insert(0, "항목", f2.pop("전략"))
        parts.append(f2.assign(블록="D. 프런티어 — 지금 가진 손잡이로 어디까지 가나"))
    md = (((sres.get("alloc") or {}).get("diag") or {}).get("macro_evidence")) or {}
    if md.get("enabled"):
        _t("E. 섹터 거시 근거(R86 · 측정)", [{"항목": "동인", "값": " | ".join(f"{k}: {v}" for k, v in (md.get("drivers") or {}).items())},
                                           {"항목": "기준(★)", "값": " · ".join(f"{k} {v}" for k, v in (md.get("base") or {}).items())}])
        e1 = pd.DataFrame(md.get("rows") or [])
        if len(e1):
            e1.insert(0, "항목", e1.pop("변형"))
            parts.append(e1.assign(블록="E. 섹터 거시 근거(R86 · 측정)"))
        lg = md.get("long") or {}
        if isinstance(lg.get("table"), pd.DataFrame) and len(lg["table"]):
            e2 = lg["table"].copy(); e2.insert(0, "항목", e2["구간"].astype(str) + " · " + e2["변형"].astype(str))
            parts.append(e2.drop(columns=["구간", "변형"]).assign(블록="E2. 섹터 거시 근거 장기 검증(엔진 1999~)"))
        _t("E. 섹터 거시 근거(R86 · 측정)", [{"항목": "사전등록 승격(다음 라운드)", "값": " · ".join(
            f"{g}: {'✓ 조건 충족 — 라이브 후보' if v else '미충족'}" for g, v in (md.get("promote") or {}).items())}])
    elif md.get("error"):
        _t("E. 섹터 거시 근거(R86 · 측정)", [{"항목": "상태", "값": f"산출 실패 — {md['error']}"}])
    df = pd.concat(parts, ignore_index=True, sort=False)
    lead = ["블록", "항목", "값"]
    return df[[c for c in lead if c in df.columns] + [c for c in df.columns if c not in lead]]


def user_reliability_lines(sres: Dict[str, Any], cfg, pack: Optional[Dict[str, Any]] = None, layer: str = "섹터"
                           ) -> List[Tuple[str, str]]:
    """[v0.68.0 R86] 00 맨 앞 줄 — 사용자 정의 신뢰도(하락 회피·상승 참여)."""
    pk = pack if pack is not None else user_reliability_pack(sres, cfg)
    out: List[Tuple[str, str]] = []
    if not pk.get("enabled"):
        out.append((f"⚠ 신뢰도(사용자 기준) — {layer}", f"산출 실패 — {pk.get('error', '-')}"))
        return out
    hi = tuple(getattr(cfg, "USER_REL_HIGH", (0.70, 0.90)))
    hd = pk["head"].set_index("전략")

    def _f(lbl: str) -> str:
        if lbl not in hd.index:
            return "-"
        r = hd.loc[lbl]
        return (f"**{r['등급']}**(회피 {r['하락 회피율']:.1%} · 참여 {r['상승 참여율']:.1%} · 순효과 {r['순효과(%p)']:+.0f}%p · "
                f"앞/뒤 절반 {r['절반 등급']})")
    sa = pk.get("single_agg") or {}
    fr = pk.get("front")
    near = ""
    if isinstance(fr, pd.DataFrame) and len(fr):
        n0 = fr.iloc[0]
        near = (f" · 가장 가까운 행: {str(n0['전략'])[:40]} (회피 {n0['하락 회피율']:.1%} · 참여 {n0['상승 참여율']:.1%} · "
                f"거리 {n0['높음까지 거리(%p)']:.1f}%p)")
    _star = "S★" if layer == "섹터" else "I★"
    out.append((f"★★★ 신뢰도(사용자 기준 — 하락 회피·상승 참여) · {layer}",
                f"노란색 {_star} {_f(pk['label_primary'])} | M {_f('M(SPY 국면전략)')} | "
                + (f"{layer} 단일 예측 **{sa['등급']}**(회피 {sa['하락 회피율']:.1%} · 참여 {sa['상승 참여율']:.1%}) | " if sa else "")
                + f"높음 = 회피 ≥ {hi[0]:.0%} & 참여 ≥ {hi[1]:.0%} — 격자 {pk.get('n_front', 0)}행 중 도달 {pk.get('n_high', 0)}행{near}. 세부 00U."))
    md = (((sres.get("alloc") or {}).get("diag") or {}).get("macro_evidence")) or {}
    if md.get("enabled"):
        rr = md.get("rows") or []
        seg = " | ".join(f"{str(r['변형']).split('·')[1].strip()[:22]} Δ회피 {r['Δ회피(%p)']:+.1f} · Δ참여 {r['Δ참여(%p)']:+.1f}"
                         for r in rr if "·" in str(r["변형"]))
        lv = ((md.get("long") or {}).get("verdict") or {})
        out.append(("★★ 섹터 거시 근거(R86 · 유가·구리·금리·신용 — 측정 전용)",
                    seg + " || 장기 검증(두 구간 모두 조건): " + " · ".join(f"{k} {'통과' if (v or {}).get('pass') else '미통과'}"
                                                              for k, v in lv.items())
                    + " → 승격: " + " · ".join(f"{g} {'✓' if v else '✗'}" for g, v in (md.get("promote") or {}).items())
                    + " (사전등록 — 두 구간 모두 회피·참여를 함께 올리고 무작위를 이겨야 다음 라운드 라이브 후보)."))
    elif md.get("error"):
        out.append(("⚠ 섹터 거시 근거(R86)", f"산출 실패 — {md['error']}"))
    return out


def build_sector_allocation(results: Dict[str, Dict[str, Any]], res: dict, eval_idx: pd.DatetimeIndex,
                            scfg: SectorConfig, M, rf_daily: Optional[pd.Series] = None,
                            spy_series: Optional[Dict[str, pd.Series]] = None) -> Dict[str, Any]:
    """[v0.4.0 §1.F → v0.5.0] 일별 섹터 배분비중(목표, t일 종가 확정 → t+1 시가 체결)과 배분 전략들의 백테스트.
    v0.5.0: (1) 후보 순위신호를 전체 이력으로 만들고 rotation_walkforward_select()로 매년 채택 (2) 주 전략 "leader3" =
    명확한 1위 100% / 명확한 꼴찌 회피 균등 / 폴백(SPY 또는 균등) (3) 'SPY' 열을 포트폴리오에 포함(폴백 매수 대상).
    반환 dict: target_w(주 전략, E_t 곱한 실제 비중 — 열에 SPY 포함), composite(적격 마스킹·평활 복합순위), composite_all
    (상장 전체·평활 — 검증용), tier/leader/laggard(일별 판단), eligible, listed, E, n_eligible, rank_pos, bts/perf/curve,
    diag, signals(평가창 원시 신호 행렬), wf(워크포워드 결과), ret_cc, state, cols."""
    t0 = time.time()
    cols = [t for t in scfg.SECTORS if t in results]
    cap = float(scfg.ROTATION_MAX_WEIGHT)
    E = res["sig"]["target_pos"].reindex(eval_idx).fillna(0.0).astype(float)
    if not cols:
        return {}
    full_idx = res["cal"]
    state = pd.DataFrame({t: results[t]["state"].reindex(eval_idx) for t in cols})
    listed = state.notna()
    eligible = listed & ~state.isin(list(scfg.ROTATION_EXCLUDE_STATES))
    ret_co = pd.DataFrame({t: results[t]["ret_co"].reindex(eval_idx) for t in cols})
    ret_oc = pd.DataFrame({t: results[t]["ret_oc"].reindex(eval_idx) for t in cols})
    ret_cc = pd.DataFrame({t: results[t]["bh_ret"].reindex(eval_idx) for t in cols})
    # SPY(폴백 매수 대상) 수익 분해 — M의 bt(run_backtest 산출)에서 그대로
    spy_bt = res["bt"]
    ret_co["SPY"] = spy_bt["ret_co"].reindex(eval_idx)
    ret_oc["SPY"] = spy_bt["ret_oc"].reindex(eval_idx)
    all_cols = cols + ["SPY"]
    # [v0.8.0] SPY를 12번째 후보로 횡단면에 포함 — 순위·투표·워크포워드 통계 전부 cand 열 기준. 섹터 전용 표(13c 순위·요약)는 cols.
    include_spy = bool(getattr(scfg, "ROTATION_INCLUDE_SPY_CANDIDATE", True))
    cand = cols + (["SPY"] if include_spy else [])
    spy_cc_full = (spy_bt["ret_cc"] if "ret_cc" in spy_bt.columns else res["px_adj"].pct_change()).reindex(full_idx)
    if include_spy:
        ret_cc["SPY"] = spy_cc_full.reindex(eval_idx)
        listed["SPY"] = ret_cc["SPY"].notna()
        eligible["SPY"] = listed["SPY"]                      # SPY는 항상 적격(E_t=0이면 어차피 현금)
        state["SPY"] = res["sig"]["state"].reindex(eval_idx) if "state" in res["sig"].columns else np.nan

    # ---- 전체 이력 원시 신호 행렬(날짜×섹터) + 국면×베타 결합 ----
    ret_cc_full = pd.DataFrame({t: results[t]["ret_cc_full"].reindex(full_idx) for t in cols})
    if include_spy:
        ret_cc_full["SPY"] = spy_cc_full
    listed_full = ret_cc_full.notna()
    raw_full: Dict[str, pd.DataFrame] = {}
    for name in scfg.ROTATION_SIGNALS:
        if name not in ROTATION_SIGNAL_SPECS:
            log("ROTATION", kv(event="unknown_rotation_signal", signal=name), M=M, level="warning")
            continue
        if name in ROTATION_COMPOSITE_MEMBERS:
            continue   # [v0.5.1] 복합 후보는 원시 행렬이 없다 — rotation_walkforward_select()가 구성원 순위로 만든다
        if name in ("BETA_X_MSCORE", "BETA_X_MHAZ"):
            if spy_series is None:
                log("ROTATION", kv(event="signal_unavailable", signal=name, reason="spy_series 없음"), M=M, level="warning")
                continue
            beta = pd.DataFrame({t: results[t]["rot_raw"]["BETA"].reindex(full_idx) for t in cols
                                 if isinstance(results[t].get("rot_raw"), pd.DataFrame) and "BETA" in results[t]["rot_raw"].columns})
            if beta.empty:
                continue
            if name == "BETA_X_MSCORE":
                f = (spy_series["SCORE_PCT"].reindex(full_idx) - 0.5)
            else:
                f = (0.5 - spy_series["HAZ_PCT"].reindex(full_idx))
            raw_full[name] = beta.mul(f, axis=0).reindex(columns=cols)
            continue
        parts = {}
        for t in cols:
            rr = results[t].get("rot_raw")
            if isinstance(rr, pd.DataFrame) and name in rr.columns and rr[name].notna().any():
                parts[t] = rr[name].reindex(full_idx)
        if parts:
            raw_full[name] = pd.DataFrame(parts).reindex(columns=cols)
        else:
            log("ROTATION", kv(event="signal_unavailable_all_sectors", signal=name), M=M, level="warning")
    # [v0.42.0 S-J] SCORE_CS_Z — 여기서 한 번에 **횡단면 z**로 표준화한다(행 단위 단조 변환이라 순위는
    #   원시 복합점수 순위와 동치이고, 13d·13g에 찍히는 값의 해석만 쉬워진다). 그날 유효 섹터가 3개
    #   미만이거나 표준편차가 0인 행은 NaN(순위 없음).
    if "SCORE_CS_Z" in raw_full:
        _m = raw_full["SCORE_CS_Z"]
        _mu = _m.mean(axis=1, skipna=True)
        _sd = _m.std(axis=1, skipna=True).replace(0.0, np.nan)
        _ok = _m.notna().sum(axis=1) >= 3
        raw_full["SCORE_CS_Z"] = _m.sub(_mu, axis=0).div(_sd, axis=0).where(_ok, np.nan)
        log("ROTATION", kv(event="score_cs_z_built", days=int(raw_full["SCORE_CS_Z"].notna().any(axis=1).sum()),
                           note="원시 복합점수의 횡단면 z(순위는 원시값과 동치)"), M=M)
    if not raw_full:
        raise RuntimeError("ROTATION_SIGNALS 중 사용 가능한 신호가 없습니다 — 배분 계층을 만들 수 없음")
    if include_spy:   # [v0.8.0] 각 신호에 SPY 등가값 열 추가(상장 = SPY 수익 존재일)
        for name in list(raw_full):
            m = raw_full[name].reindex(columns=cand)
            m["SPY"] = spy_equivalent_signal(name, full_idx, spy_series).where(listed_full["SPY"])
            raw_full[name] = m
        log("ROTATION", kv(event="spy_candidate_included", signals=len(raw_full),
                           spy_score_available=bool(spy_series is not None)), M=M)
    signals = {k: v.reindex(eval_idx) for k, v in raw_full.items()}   # 평가창(13d 진단용)

    # ---- 횡단면 워크포워드 검증 → 연도별 채택 신호 → 복합순위 ----
    # [v0.6.0] 외부 검증(FF49) — 실패/미사용이면 빈 dict(로컬 기준만 적용)
    external: Dict[int, Dict[str, float]] = {}
    ext_log = pd.DataFrame()
    # 로컬 데이터 시작일(상장 섹터 ≥5개가 되는 첫날) — 외부 검증 '동일 시대' 창의 시작
    n_listed_full = listed_full[cols].sum(axis=1)
    local_start = n_listed_full.index[n_listed_full >= min(5, len(cols))][0] if (n_listed_full >= min(5, len(cols))).any() else full_idx[0]
    try:
        external, ext_log = external_validation_ff49(scfg, M, sorted(set(eval_idx.year)), spy_series,
                                                     local_start=local_start, include_market=include_spy)
    except Exception as e:
        log("EXTERNAL", kv(event="ff49_validation_failed", err=type(e).__name__, msg=str(e)[:160]), M=M, level="warning")
    # [v0.10.0 §1.A] 감쇠 반감기: SectorConfig가 명시하지 않으면(기본) M cfg의 HALF_LIFE_DAYS를 그대로 쓴다(새 값을 고르지 않음).
    hl_override = getattr(scfg, "ROTATION_DECAY_HALF_LIFE_DAYS", None)
    hl = int(hl_override) if hl_override else getattr(res["cfg"], "HALF_LIFE_DAYS", None)
    wf = rotation_walkforward_select(raw_full, ret_cc_full, listed_full, eval_idx, scfg, M, external=external, half_life_days=hl)
    wf["external_log"] = ext_log
    for cname in ROTATION_COMPOSITE_MEMBERS:          # [v0.5.1] 13d 진단표에도 복합 후보를 올린다(평가창 순위 행렬)
        if cname in wf["rank_full"]:
            signals[cname] = wf["rank_full"][cname].reindex(eval_idx)
    composite_all = wf["composite_all"].reindex(columns=cand).where(listed[cand])
    smooth = int(getattr(scfg, "ROTATION_SMOOTH_DAYS", 21) or 1)
    composite_all_s = composite_all.rolling(smooth, min_periods=1).mean().where(listed[cand]) if smooth > 1 else composite_all
    composite = composite_all_s.where(eligible[cand])
    rankable = composite.notna()
    n_elig = rankable[cols].sum(axis=1)                 # 적격 '섹터' 수(리포트용, SPY 제외)
    rank_pos = composite.rank(axis=1, ascending=False, method="first")   # 1 = 그날 최고(SPY 포함 시 SPY도 순위를 가짐)
    # 채택 신호별(평활) 순위 — 과반 투표용
    rank_sel_s: Dict[str, pd.DataFrame] = {}
    for name, rk in wf["rank_full"].items():
        r = rk.reindex(index=eval_idx, columns=cand).where(listed[cand])
        rank_sel_s[name] = (r.rolling(smooth, min_periods=1).mean().where(listed[cand]) if smooth > 1 else r).where(eligible[cand])

    # ---- tilt → 비율(E_t 대비) → 상한 ---- (비교 변형 상위K/순위가중은 섹터만 — SPY는 폴백 자산)
    def _frac_from_tilt(tilt: pd.DataFrame) -> Tuple[pd.DataFrame, pd.Series]:
        s = tilt.sum(axis=1).replace(0, np.nan)
        raw = tilt.div(s, axis=0).fillna(0.0)
        w, short = _cap_waterfill(raw, cap, scfg.ROTATION_CAP_STRICT)
        w["SPY"] = 0.0
        return w.reindex(columns=all_cols), short

    comp_sec = composite[cols]
    rank_pos_sec = comp_sec.rank(axis=1, ascending=False, method="first")
    tilt_linear = comp_sec.rank(axis=1, ascending=True, method="average").fillna(0.0)
    tilt_topk = ((rank_pos_sec <= scfg.ROTATION_TOP_K) & rankable[cols]).astype(float)
    frac_lin, short_lin = _frac_from_tilt(tilt_linear)
    frac_topk, short_topk = _frac_from_tilt(tilt_topk)
    frac_ctrl_b, _ = _frac_from_tilt(eligible[cols].astype(float))
    # [v0.5.0] 비교용 상위K/순위가중도 '그 해 채택 신호가 없어 순위가 없는 날'은 주 전략과 같은 폴백을 쓴다(비교 공정성)
    no_rank = n_elig == 0
    if no_rank.any():
        if str(scfg.ROTATION_FALLBACK).lower() == "spy":
            for fr in (frac_lin, frac_topk):
                fr.loc[no_rank, :] = 0.0
                fr.loc[no_rank, "SPY"] = 1.0
        else:
            eq = eligible[cols].astype(float).div(eligible[cols].sum(axis=1).replace(0, np.nan), axis=0).fillna(0.0)
            for fr in (frac_lin, frac_topk):
                fr.loc[no_rank, cols] = eq.loc[no_rank, cols].values
    n_listed = listed[cols].sum(axis=1).replace(0, np.nan)
    frac_ctrl_a = listed[cols].astype(float).div(n_listed, axis=0).fillna(0.0)
    frac_ctrl_a["SPY"] = 0.0
    frac_ctrl_a = frac_ctrl_a.reindex(columns=all_cols)

    # ---- [v0.5.0] 주 전략 leader3: 명확한 1위 / 명확한 꼴찌 회피 / 폴백 ----
    #   [v0.8.0] (1) 교차확인: 리더·회피는 서로 다른 채택 신호 ≥ ROTATION_MIN_AGREE개가 지목해야(과반과 함께) — 채택 1개인 해는 폴백.
    #            (2) SPY 후보 포함 시 순위 1위가 SPY면 판단 'SPY우위'(섹터가 SPY보다 나아 보이지 않음 → SPY에 E_t). SPY는 꼴찌 회피 대상이 아님.
    years_arr = eval_idx.year
    sel_by_year = wf["selected_by_year"]
    # [v0.9.0 ⚠] 리더 판단은 sel_eff(엄격 신호가 있으면 엄격만, 없으면 채택 전부)로, 교차확인 필요 수는 등급별로(엄격 1 / 약함 MIN_AGREE),
    #   꼴찌 투표는 회피 자격(하위1 스프레드 t ≤ −T) 신호만. 옵션이 꺼져 있으면 rotation_walkforward_select()가 v0.8과 같은 집합을 준다.
    sel_eff_by_year = wf.get("selected_eff_by_year", sel_by_year)
    tier_by_year = wf.get("tier_by_year", {})
    avoid_by_year = wf.get("avoid_by_year", sel_eff_by_year)
    comp_vals = composite.values
    elig_vals = rankable.values
    col_arr = np.array(cand)
    min_agree = max(1, int(getattr(scfg, "ROTATION_MIN_AGREE", 2)))
    # 신호별 argmax/argmin(적격 내) 미리 계산 — 전부 NaN인 행은 None(pandas idxmax는 all-NA 행에서 예외)
    def _row_arg(r: pd.DataFrame, fn: str) -> pd.Series:
        out = pd.Series([None] * len(r), index=r.index, dtype=object)
        has = r.notna().any(axis=1)
        if has.any():
            out[has] = getattr(r[has], fn)(axis=1).astype(object)
        return out
    am = {n: _row_arg(r, "idxmax") for n, r in rank_sel_s.items()}
    an = {n: _row_arg(r, "idxmin") for n, r in rank_sel_s.items()}
    min_hold = int(scfg.ROTATION_MIN_HOLD_DAYS)
    lw = float(scfg.ROTATION_LEADER_WEIGHT)
    fallback_spy = str(scfg.ROTATION_FALLBACK).lower() == "spy"
    # [v0.10.0 §1.B ⚠] 확신 게이트: 1위가 2위를 margin_steps_cfg × 1/(n_ok−1)(=step) 이상 앞서야 '명확한 1위'로 인정.
    #   <=0이면 게이트 없음(v0.9.2와 완전히 동일 — 아래 gate_ok가 항상 True가 됨).
    margin_steps_cfg = float(getattr(scfg, "ROTATION_LEADER_MARGIN_STEPS", 0.0) or 0.0)
    # [v0.10.0 §1.D] SPY 시장상황을 미리 배열로(01Z 'SPY 시장상황'과 같은 원천 — res["sig"]["state"]→STATE_SHORT, build_prediction_matrix()
    #   2396행과 동일 매핑). 리더 허용 국면 제약(ROTATION_LEADER_REGIMES)과 항상 산출되는 [비교] '중립 국면만 리더' 변형에 공용.
    _spy_state_src = res["sig"]["state"] if "state" in res["sig"].columns else pd.Series(np.nan, index=full_idx)
    spy_regime_arr = _spy_state_src.reindex(eval_idx).map(STATE_SHORT).fillna("-").values

    def _run_leader3(leader_regimes: Optional[Tuple[str, ...]],
                     reverse_avoid_by_year: Optional[Dict[int, List[str]]] = None,
                     standalone_avoid_by_year: Optional[Dict[int, List[str]]] = None,
                     exit_on_vote_loss: bool = False,
                     min_hold_override: Optional[int] = None) -> Dict[str, Any]:
        """[v0.4.0 §1.F leader3 상태기계 — v0.10.0 §1.D로 국면 제약을 인자화] leader_regimes=None이면 전 국면(제약 없음,
        v0.9.2·§1.B와 완전히 동일). 튜플이면 그날 SPY 시장상황(STATE_SHORT 라벨)이 그 집합에 있을 때만 리더 인정 — 없으면
        새 tier를 만들지 않고 그대로 '폴백'(§1.D: "그 외는 폴백"). 교차확인 투표·확신 게이트(§1.B)·꼴찌 회피·최소보유 상태기계는
        국면 제약과 무관하게 전부 동일한 코드 경로 — 이 함수 하나로 주 전략과 [비교] '중립 국면만 리더' 변형을 모두 만들어
        둘의 유일한 차이가 국면 제약뿐임을 보장한다(로직이 갈라져 비교가 오염되는 것을 방지).
        [v0.45.0 G5] standalone_avoid_by_year: {연도: [신호]} — 그 신호가 그날 지목한 꼴찌는 **득표 수·과반과
        무관하게** 규칙 ②를 연다(순서 잣대로 이미 자격을 검증했으므로 교차확인을 면제). None/빈 dict면
        이 경로는 완전히 비활성 = v0.44.0과 비트 동일. SPY 바스켓 비교·최소보유·확신 게이트는 그대로 적용된다.
        [v0.48.0 L2] exit_on_vote_loss=True면 보유 리더가 그날도 복합 1위인데(=composite 1위가 바뀌지 않음)
        득표만 과반 아래로 떨어진 날은 min_hold를 기다리지 않고 즉시 폴백한다. 복합 1위 자체가 바뀐 경우는
        기본값(False)과 동일하게 min_hold를 지킨다 — 이 인자는 '그 조건 하나만' 바꾼다. 기본 False면 v0.47.0과
        비트 동일.
        [v0.48.0 L3] min_hold_override가 주어지면 이 호출 안에서만 최소보유일을 그 값으로 쓴다(None이면
        scfg.ROTATION_MIN_HOLD_DAYS 그대로 — 기본값과 비트 동일)."""
        _mh = int(min_hold_override) if min_hold_override is not None else min_hold
        vote_loss_exit_ = np.zeros(len(eval_idx), dtype=int)   # [v0.48.0 L2] 진단·로그용
        frac = pd.DataFrame(0.0, index=eval_idx, columns=all_cols)
        tier_ = pd.Series("현금", index=eval_idx, dtype=object)
        leader_ = pd.Series("", index=eval_idx, dtype=object)
        laggard_ = pd.Series("", index=eval_idx, dtype=object)
        votes_leader_ = pd.Series(0, index=eval_idx, dtype=int)
        votes_laggard_ = pd.Series(0, index=eval_idx, dtype=int)
        n_sel_ = pd.Series(0, index=eval_idx, dtype=int)
        margin_ = pd.Series(np.nan, index=eval_idx, dtype=float)     # 1위 여유(2위 대비) — 13c
        step_ = pd.Series(np.nan, index=eval_idx, dtype=float)       # 여유 문턱 — 13c
        gate_ = pd.Series("해당없음", index=eval_idx, dtype=object)  # 확신 게이트: 통과/미달/해당없음(투표상 리더 후보 자체가 없음) — 13c
        rev_hits_ = np.zeros(len(eval_idx), dtype=int)               # [v0.41.0 S-G] 그날 역방향 회피로 제외된 후보 수
        sa_hits_ = np.zeros(len(eval_idx), dtype=int)                # [v0.45.0 G5] 단독 자격으로 열린 회피일(0/1)
        # [v0.48.0 L5] '득표 상실 중 보유' 진단 플래그 — vote_loss_only는 exit_on_vote_loss 값과 무관하게 매일
        #   계산되므로(§L2), 라이브 실행(exit_on_vote_loss=False)에서도 '그날 조건이 성립했는가'를 그대로
        #   기록해 13c에 낸다(L2 격자 판독용 — 배분·판단 자체는 바꾸지 않는다).
        vote_loss_flag_ = pd.Series(False, index=eval_idx, dtype=bool)
        sa_lag_: List[str] = []                                      # [v0.45.0 G5] 그 날들의 회피 섹터(집중도 진단)
        cur_leader: Optional[str] = None
        held = 0
        switches_ = 0
        n_spy_top_ = 0
        for i, d in enumerate(eval_idx):
            yr = int(years_arr[i])
            sel = sel_eff_by_year.get(yr, [])
            K = len(sel)
            n_sel_.iloc[i] = K
            need = 1 if tier_by_year.get(yr) == "엄격" else min_agree          # [v0.9.0] 엄격 신호는 단독 가능(2개 이상이면 과반)
            avoid_ok = avoid_by_year.get(yr, sel)
            row = comp_vals[i]
            ok = elig_vals[i] & ~np.isnan(row)
            # [v0.41.0 S-G] 역방향 회피 — 상위1 스프레드 t ≤ −T인 신호가 그날 지목한 1위를 후보에서 통째로
            #   제외한다(리더·회피 바스켓 모두). 산업층 §B4와 같은 처리이며, reverse_avoid_by_year가
            #   None/빈 dict면 이 블록은 완전히 비활성 — v0.40.0과 비트 동일.
            if reverse_avoid_by_year:
                _rev = [s_ for s_ in reverse_avoid_by_year.get(yr, []) if s_ in am]
                if _rev:
                    ok = ok.copy()
                    for s_ in _rev:
                        _c = am[s_].iloc[i]
                        if isinstance(_c, str) and _c in cand:
                            _j = cand.index(_c)
                            if ok[_j]:
                                ok[_j] = False
                                rev_hits_[i] += 1
            n_ok = int(ok.sum())
            leader = laggard = None
            v_lead = v_lag = 0
            margin_i = step_i = np.nan
            gate_ok = False
            if n_ok >= 1 and K > 0:
                j1 = int(np.nanargmax(np.where(ok, row, -np.inf)))
                leader = col_arr[j1]
                v_lead = sum(1 for s in sel if s in am and am[s].iloc[i] == leader)
                # [v0.10.0 §1.B] 1위−2위 여유. n_ok<2(비교 대상 2위가 없음)면 여유를 정할 수 없음 → margin=NaN → 게이트 미통과(문턱>0일 때).
                others = np.where(ok, row, -np.inf)
                others[j1] = -np.inf
                second = float(others.max()) if n_ok >= 2 else np.nan
                margin_i = float(row[j1] - second) if np.isfinite(second) else np.nan
                step_i = margin_steps_cfg / max(n_ok - 1, 1)
                # [v0.10.0 §1.B 버그수정 — test_sector_rotation_v0100.py [8/9]에서 실측 픽스처로 발견] margin_i·step_i는
                # 서로 다른 연산(빼기 vs 나누기)으로 구해, 수학적으로 정확히 같아야 하는 경계(예: 11개 후보 균등 순위
                # 간격)에서도 부동소수점 잡음(~1e-16)만큼 margin_i가 step_i보다 근소하게 작게 나올 수 있다(실측 사례:
                # margin_i=0.09999999999999998 < step_i=0.1). §3-4b 취지("margin==step 경계는 '통과'해야 함, >= 부등호")를
                # 이런 실측 사례에서도 지키려면 두 값의 스케일(0~1) 대비 훨씬 작은 허용오차가 필요해 1e-9를 뺀다.
                gate_ok = (margin_steps_cfg <= 0) or (np.isfinite(margin_i) and margin_i >= step_i - 1e-9)
                if n_ok >= 4:
                    laggard = col_arr[np.nanargmin(np.where(ok, row, np.inf))]
                    v_lag = sum(1 for s in avoid_ok if s in an and an[s].iloc[i] == laggard)   # [v0.9.0] 회피 자격 신호만 투표
            margin_.iloc[i] = margin_i
            step_.iloc[i] = step_i
            spy_top = leader == "SPY"
            # [v0.10.0 §1.B] lead_ok_votes = 종전 clear_leader 조건(투표만). clear_leader는 여기에 게이트·국면 제약까지 더해야 함.
            #   gate_blocked = 투표로는 명확한 1위였지만 게이트 미달 → tier가 '폴백'이 아니라 '폴백(여유부족)'이어야 함을 표시.
            lead_ok_votes = leader is not None and not spy_top and v_lead * 2 > K and v_lead >= need
            # [v0.10.0 §1.D] regime_ok: leader_regimes가 None이면 항상 True(제약 없음). 아니면 그날 SPY 시장상황이 그 집합에
            #   있어야 함 — 없으면 리더가 아니라 '폴백'(새 tier 라벨 없음, gate_blocked와는 별개 — 미달 표시는 게이트 전용).
            regime_ok = (leader_regimes is None) or (spy_regime_arr[i] in leader_regimes)
            clear_leader = lead_ok_votes and gate_ok and regime_ok
            gate_blocked = lead_ok_votes and not gate_ok
            gate_.iloc[i] = "통과" if clear_leader else ("미달" if gate_blocked else "해당없음")
            # [v0.10.1 §1.B 청산 규칙 분리] 청산 판정에 쓸 '1위 상실' — 게이트(gate_ok)는 제외하고 순위·투표만 본다.
            #   아래 최소보유 상태기계 블록에서 사용(그 블록의 주석에 배경 상세).
            leader_lost = not (lead_ok_votes and leader == cur_leader)
            clear_laggard = laggard is not None and laggard != "SPY" and v_lag * 2 > K and v_lag >= need
            # [v0.45.0 G5] 단독 회피 — 순서 잣대로 자격을 받은 신호가 그날 지목한 꼴찌는 득표·과반을 면제한다.
            #   왜: 규칙 ②는 '자격 신호 ≥2표 & 과반'을 요구하는데 자격 신호 자체가 해마다 0~1개라 9년 내내
            #   회피 0일이었다(리포트44). 교차확인의 목적은 '한 신호의 우연을 거르는 것'인데, 여기서는 그 일을
            #   순서 잣대(학습창·최근창 꼴찌 → 실현 하위3 두 문턱)가 이미 하고 있다.
            #   standalone_avoid_by_year가 None/빈 dict면 이 블록은 무효 = v0.44.0 비트 동일.
            if (not clear_laggard) and standalone_avoid_by_year and laggard is not None and laggard != "SPY":
                _sa_y = standalone_avoid_by_year.get(yr, [])
                if _sa_y and any((s in an) and (an[s].iloc[i] == laggard) for s in _sa_y):
                    clear_laggard = True
                    sa_hits_[i] = 1
                    sa_lag_.append(str(laggard))
            # [v0.8.0] SPY 후보 포함 시 '회피' 바스켓(꼴찌 뺀 적격 균등)도 SPY보다 나아 보여야 한다 — 바스켓 평균 복합순위 > SPY 복합순위.
            #   (균등 바스켓은 이 기간 SPY보다 구조적으로 뒤졌으므로, 신호가 '바스켓 > SPY'를 말하지 않으면 SPY를 든다)
            if clear_laggard and include_spy and ok[cand.index("SPY")]:
                basket_vals = [row[j] for j, c in enumerate(cand) if ok[j] and c != laggard and c != "SPY"]
                if not basket_vals or float(np.mean(basket_vals)) <= float(row[cand.index("SPY")]):
                    clear_laggard = False
            votes_leader_.iloc[i], votes_laggard_.iloc[i] = v_lead, v_lag
            # 최소보유 상태기계 — [v0.10.0 §1.B] 확신 게이트는 진입 조건에만 관여(clear_leader에 이미 반영).
            #   [v0.10.1 §1.B 청산 규칙 분리 — 버그수정] v0.10.0은 위 의도(게이트=진입 전용)를 주석으로는 선언해 놓고,
            #   실제 청산 분기는 clear_leader(=투표·순위·게이트·국면 4개를 전부 AND)를 그대로 재사용해 게이트 미달만으로도
            #   보유 중 리더가 청산되는 구현 부작용이 있었다. 리포트11 13j(실데이터, market_regime_trader.py 번들 res 직접
            #   전달 방식)로 확인: 주 전략 16건 중 8건이 "여유 상실(확신 게이트 미달) → 폴백 SPY" 사유로 청산됐고, 청산 후
            #   관찰창(다음 진입 전, ≤63일)에서 그 섹터가 SPY를 누적 +8.9%p(진입비중 가중 +9.9%p) 앞섬 — 게이트 트리거 청산이
            #   평균적으로 너무 이르다는 실증. leader_lost(위에서 계산, gate_ok 제외한 '순위·투표만의 1위 상실')로 교체:
            #   보유 중에는 여유(gate_ok)가 줄어도 min_hold 전엔 청산하지 않고, 순위·투표 기준 1위를 잃어야만 청산한다.
            #   [v0.10.0 §1.D] 국면 제약(regime_ok)은 반대로 '적격 상실'과 같은 즉시청산 취급 — §1.D의 목적이 위험 축소(MDD)이므로
            #   보유 중 국면이 허용 밖으로 바뀌면 min_hold를 기다리지 않고 그날로 폴백(§0.5의 큰 MDD 개선폭은 이 즉시청산 전제).
            #   leader_regimes=None(기본)이면 이 조건은 항상 False라 이 변경과 무관(추가 청산 없음).
            if cur_leader is not None and not (ok[cand.index(cur_leader)] if cur_leader in cand else False):
                cur_leader = None
            if cur_leader is not None and leader_regimes is not None and spy_regime_arr[i] not in leader_regimes:
                cur_leader = None
            # [v0.48.0 L2] vote_loss_only = 보유 리더가 그날도 복합 1위인데(구성 순위 불변) 투표만 실패한 날.
            #   복합 1위 자체가 다른 섹터로 바뀐 날(leader != cur_leader)은 여기 해당하지 않는다 — 그 경우는
            #   exit_on_vote_loss와 무관하게 항상 held >= _mh를 지켜야 한다(§5 L2 "복합 1위가 바뀐 경우는
            #   현행대로 min_hold 유지").
            vote_loss_only = (cur_leader is not None and leader_lost and leader is not None and leader == cur_leader)
            vote_loss_flag_.iloc[i] = bool(vote_loss_only)   # [v0.48.0 L5] exit_on_vote_loss와 무관하게 항상 기록
            if clear_leader and leader != cur_leader:
                if cur_leader is None or held >= _mh:
                    cur_leader = leader
                    held = 0
                    switches_ += 1
            elif exit_on_vote_loss and vote_loss_only:
                cur_leader = None                      # [v0.48.0 L2] min_hold 무시 — 즉시 청산
                vote_loss_exit_[i] = 1
            elif leader_lost and cur_leader is not None and held >= _mh:
                cur_leader = None
            if cur_leader is not None:
                frac.iat[i, all_cols.index(cur_leader)] = lw
                tier_.iloc[i] = "리더"
                leader_.iloc[i] = cur_leader
                held += 1
            elif clear_laggard:
                basket = [c for j, c in enumerate(cols) if ok[cand.index(c)] and c != laggard]
                for c in basket:
                    frac.iat[i, all_cols.index(c)] = 1.0 / len(basket)
                tier_.iloc[i] = "회피"
                laggard_.iloc[i] = laggard
            else:
                if fallback_spy or spy_top:
                    frac.iat[i, all_cols.index("SPY")] = 1.0
                elif n_ok > 0:
                    for c in cols:
                        if ok[cand.index(c)]:
                            frac.iat[i, all_cols.index(c)] = 1.0 / n_ok
                if spy_top:
                    tier_.iloc[i] = "SPY우위"
                    leader_.iloc[i] = "SPY"
                    n_spy_top_ += 1
                else:
                    tier_.iloc[i] = "폴백(여유부족)" if gate_blocked else "폴백"   # [v0.10.0 §1.B]
            if E.iloc[i] <= 1e-12:
                # [v0.15.0 §A] 현금일이어도 leader_/gate_는 그대로 남긴다 — 하락국면 리더가 그 값을 쓴다.
                tier_.iloc[i] = "현금"
        return {"frac_leader": frac, "tier": tier_, "leader_s": leader_, "laggard_s": laggard_,
                "votes_leader": votes_leader_, "votes_laggard": votes_laggard_, "n_sel_s": n_sel_,
                "margin_s": margin_, "step_s": step_, "gate_s": gate_, "switches": switches_, "n_spy_top": n_spy_top_,
                "vote_loss_exit_days": int(vote_loss_exit_.sum()),   # [v0.48.0 L2] 즉시청산이 실제로 발동한 날 수
                "vote_loss_flag": vote_loss_flag_,   # [v0.48.0 L5] 13c '득표 상실 중 보유' 열 원천(exit_on_vote_loss 무관)
                "rev_avoid_days": int((rev_hits_ > 0).sum()),   # [v0.41.0 S-G]
                "sa_avoid_days": int(sa_hits_.sum()),           # [v0.45.0 G5] 단독 자격으로 열린 회피일
                "avoid_days": int((tier_ == "회피").sum()),     # [v0.45.0 G5] 실제 회피 tier 일수(격자 판독용)
                # [v0.45.0 G5] 회피 대상 섹터 분포 — REPORT48 §2.3의 잣대("한 섹터로 고정되면 그 섹터를
                #   빼는 규칙이지 순환매 예측이 아니다")를 격자 판독이 바로 적용할 수 있게 같이 낸다.
                "sa_lag_counts": dict(pd.Series(sa_lag_, dtype=object).value_counts()) if sa_lag_ else {}}

    # [v0.41.0 S-G] 역방향 회피 연도별 집합 — wf의 raw (t, n)에서 문턱을 바꿔 가며 만든다(신호 재계산 없음).
    #   direction=-1: t ≤ −thr("그 신호의 1위를 피하라" — 실측 근거가 있는 방향)
    #   direction=+1: t ≥ +thr(반증용 — 사전방향대로 잘 맞는 신호의 1위를 피하면 **나빠져야** 정상)
    def _rev_sets(thr: float, direction: int = -1) -> Dict[int, List[str]]:
        out: Dict[int, List[str]] = {}
        _min_d = int(getattr(scfg, "ROTATION_SELECT_MIN_DAYS", 250))
        for _y, _d in (wf.get("top_stats_by_year") or {}).items():
            out[int(_y)] = [n for n, (t_, nn_) in _d.items()
                            if nn_ >= _min_d and pd.notna(t_) and ((t_ <= -float(thr)) if direction < 0
                                                                   else (t_ >= float(thr)))]
        return out

    _rev_live = (_rev_sets(float(getattr(scfg, "ROTATION_REVERSE_AVOID_T", 2.0)))
                 if bool(getattr(scfg, "ROTATION_REVERSE_AVOID", False)) else None)
    # [v0.46.0 H4] 격자 변형별 판단 시계열 — 13p 블록 E가 '수익'이 아니라 '예측'으로 격자를 판정하게 한다.
    #   {라벨: {"tier","leader","laggard"}}. _run_leader3가 이미 만든 Series를 모으기만 한다(재계산 없음).
    #   v0.45.0의 [단독회피격자]가 판정 지표 없이 기각된 일(REPORT49 §4 E4)을 되풀이하지 않기 위한 것.
    variants_diag: Dict[str, Dict[str, pd.Series]] = {}

    def _keep_diag(label_: str, r3_: Dict[str, Any]) -> None:
        # [v0.47.0 J1 ⚠ 결함수정 — REPORT50 §2.4 E1] 이전엔 Series 객체 참조를 그대로 저장했다.
        #   ★ 경로가 나중에 `tier.loc[...] = "하락국면리더"`로 그 Series를 제자리 변경하면(라인 ~7372,
        #   v0.41.0 S-H) 라이브 기준 행의 스냅샷에도 그 변경이 새어 들어 라이브 875일(리더611+하락국면
        #   리더264) vs 격자 611일이 되는 like-for-like 불일치가 생겼다. .copy()로 저장 시점 상태를 격리한다.
        variants_diag[label_] = {"tier": pd.Series(r3_["tier"]).copy(),
                                  "leader": pd.Series(r3_["leader_s"]).copy(),
                                  "laggard": pd.Series(r3_["laggard_s"]).copy()}

    _lr3 = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rev_live)
    if _rev_live is not None:
        log("ROTATION", kv(event="reverse_avoid_live", t=float(getattr(scfg, "ROTATION_REVERSE_AVOID_T", 2.0)),
                           days=int(_lr3.get("rev_avoid_days", 0)),
                           years=";".join(f"{y}:{'+'.join(v)}" for y, v in sorted(_rev_live.items()) if v) or "-"), M=M)
    frac_leader, tier, leader_s, laggard_s = _lr3["frac_leader"], _lr3["tier"], _lr3["leader_s"], _lr3["laggard_s"]
    # [v0.46.0 H4] 라이브 판단도 같은 형식으로 담아 블록 E의 기준 행이 되게 한다(라벨은 아래에서 확정).
    _live_r3 = _lr3
    votes_leader, votes_laggard, n_sel_s = _lr3["votes_leader"], _lr3["votes_laggard"], _lr3["n_sel_s"]
    margin_s, step_s, gate_s = _lr3["margin_s"], _lr3["step_s"], _lr3["gate_s"]
    switches, n_spy_top = _lr3["switches"], _lr3["n_spy_top"]
    fallback_txt = "SPY" if fallback_spy else "균등"
    label_leader = f"집중배분(명확1위 {lw:.0%}·꼴찌회피·폴백{fallback_txt}) ★"
    _keep_diag(label_leader + " [라이브 기준]", _live_r3)   # [v0.46.0 H4] 블록 E의 비교 기준 행
    # [v0.8.0] 비교 변형 '시스템 상승확률(SCORE_PCT) 1위 무조건' — 사용자 요청 문자 그대로(검증·교차확인·SPY 비교 없음, 섹터만,
    #   같은 21일 평활·최소보유·적격 조건·E_t). 워크포워드가 왜 그 신호를 채택/미채택했는지와 무관하게 '그냥 따랐다면'의 성과를 13시트에 병기.
    frac_score = None
    label_score = "집중배분(시스템 상승확률 SCORE_PCT 1위 무조건·검증 없음) [비교]"
    if getattr(scfg, "ROTATION_ALT_SCORE_TOP1", True) and "SCORE_PCT" in raw_full:
        sc_rank = _cs_rank01((raw_full["SCORE_PCT"].reindex(index=eval_idx, columns=cols)).where(listed[cols]))
        sc_rank = (sc_rank.rolling(smooth, min_periods=1).mean().where(listed[cols]) if smooth > 1 else sc_rank).where(eligible[cols])
        frac_score = pd.DataFrame(0.0, index=eval_idx, columns=all_cols)
        sv = sc_rank.values
        cur_s: Optional[str] = None
        held_s = 0
        for i in range(len(eval_idx)):
            r = sv[i]
            ok_s = ~np.isnan(r)
            top = cols[int(np.nanargmax(np.where(ok_s, r, -np.inf)))] if ok_s.any() else None
            if cur_s is not None and not ok_s[cols.index(cur_s)]:
                cur_s = None
            if top is not None and top != cur_s and (cur_s is None or held_s >= min_hold):
                cur_s, held_s = top, 0
            if cur_s is not None:
                frac_score.iat[i, all_cols.index(cur_s)] = 1.0
                held_s += 1
            else:
                frac_score.iat[i, all_cols.index("SPY")] = 1.0
    # [v0.10.0 §1.D] [비교] "중립 국면만 리더" — ROTATION_LEADER_REGIMES 설정과 무관하게 항상 하드코딩 ("중립",)로 leader3를
    #   재실행(_run_leader3는 국면 제약 말고는 주 전략과 완전히 같은 규칙이므로 차이는 국면 제약 하나뿐). 리포트 10 what-if(§0.5):
    #   수익은 거의 그대로(+0~0.1%p)에 MDD만 낮아짐(−10.4→−7.07%) — 위험을 줄이는 옵션이라 주 전략에는 쓰지 않고 13시트에 병기만.
    label_regime = "집중배분(중립 국면만 리더) [비교]"
    frac_regime = None
    if getattr(scfg, "ROTATION_ALT_LEADER_REGIME_NEUTRAL", True):
        frac_regime = _run_leader3(("중립",))["frac_leader"]
    # [v0.41.0 S-G 사전등록 격자] 1개월 상대모멘텀 반전 = 역방향 회피 — **집중배분 계열에서만** 판정한다.
    #   S★(주력섹터)에는 붙이지 않는다: XLK가 1개월 승자인 날 주력을 빼는 꼴이 되기 때문(REPORT44 §S-G).
    #   반증 1행을 반드시 같이 싣는다(v0.36.0 분산게이트 격자의 관행) — 방향이 진짜라면 반증 행은 나빠야 한다.
    reverse_avoid_variants: Dict[str, pd.DataFrame] = {}
    if bool(getattr(scfg, "ROTATION_REVERSE_AVOID_GRID", ())):
        for _rt in tuple(getattr(scfg, "ROTATION_REVERSE_AVOID_GRID", ()) or ()):
            _rs = _rev_sets(float(_rt))
            if not any(_rs.values()):
                log("ROTATION", kv(event="reverse_avoid_grid_empty", t=float(_rt),
                                   note="그 문턱을 넘는 반전 신호가 한 해도 없음 — 행 생략"), M=M)
                continue
            _r3 = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rs)
            _lab_rv = f"집중배분 · 역방향회피 t≤−{float(_rt):.1f} [역방향회피격자]"
            reverse_avoid_variants[_lab_rv] = _r3["frac_leader"]
            _keep_diag(_lab_rv, _r3)   # [v0.46.0 H4]
            log("ROTATION", kv(event="reverse_avoid_grid", t=float(_rt), days=int(_r3.get("rev_avoid_days", 0)),
                               years=";".join(f"{y}:{'+'.join(v)}" for y, v in sorted(_rs.items()) if v) or "-"), M=M)
        if bool(getattr(scfg, "ROTATION_REVERSE_AVOID_COUNTER", True)):
            _rt0 = float((tuple(getattr(scfg, "ROTATION_REVERSE_AVOID_GRID", (2.0,)) or (2.0,)))[0])
            _rsc = _rev_sets(_rt0, direction=+1)
            if any(_rsc.values()):
                _r3c = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rsc)
                _lab_rc = f"집중배분 · 반증: t≥+{_rt0:.1f} 신호의 1위 회피 [역방향회피격자·반증]"
                reverse_avoid_variants[_lab_rc] = _r3c["frac_leader"]
                _keep_diag(_lab_rc, _r3c)   # [v0.46.0 H4]
    # [v0.45.0 G5 ★ 신규 격자] [단독회피격자] — 규칙 ②(꼴찌 회피)를 순서 잣대 자격 신호 **단독**으로 연다.
    #   집중배분 계열에서만 판정한다(S★의 잔여 슬리브는 G3 [대피처격자]가 담당 — 두 격자가 같은 날을 서로
    #   다른 축으로 건드리므로 섞지 않는다). 자격 집합은 rotation_walkforward_select가 이미 만들었고
    #   (신규 신호·재계산 없음) 여기서는 그 dict를 leader3에 넘길 뿐이다.
    #   판독 요령(REPORT48 §G5): CAGR은 거의 안 움직이는 것이 정상이다 — 회피 바스켓(꼴찌 뺀 균등)은 이 구간
    #   SPY보다 구조적으로 뒤졌다(대조군A 21.3% vs SPY M 25.5%). 이 격자의 목적은 **13p ⑧ '꼴찌 → 실현
    #   하위3'이 발동일에 무작위(0.27)를 넘느냐**이고, 넘으면 격자 4기준을 못 통과해도 '꼴찌 예측은 성립'으로
    #   기록한다. 넘지 못하면 하위 쪽은 이 시스템에서 닫는다.
    standalone_avoid_variants: Dict[str, pd.DataFrame] = {}
    _sa_grid = tuple(getattr(scfg, "ROTATION_AVOID_STANDALONE_GRID", ()) or ())
    if _sa_grid:
        _sa_all = wf.get("avoid_standalone_by_year") or {}
        for _sv in _sa_grid:
            _sv = str(_sv).lower()
            _sets = _sa_all.get(_sv) or {}
            if not any(_sets.values()):
                log("ROTATION", kv(event="avoid_standalone_grid_empty", variant=_sv,
                                   note="순서 잣대 문턱을 넘는 신호가 한 해도 없음 — 행 생략"), M=M)
                continue
            _r3s = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rev_live, _sets)
            _lbl_sv = {"order": "순서 잣대", "size+order": "순서+크기"}.get(_sv, _sv)
            _lab_sa = f"집중배분 · 단독회피({_lbl_sv}) [단독회피격자]"
            standalone_avoid_variants[_lab_sa] = _r3s["frac_leader"]
            _keep_diag(_lab_sa, _r3s)   # [v0.46.0 H4]
            _sc = _r3s.get("sa_lag_counts") or {}
            _sc_top = sorted(_sc.items(), key=lambda kv_: -int(kv_[1]))[:3]
            _sc_n = max(sum(int(v) for v in _sc.values()), 1)
            log("ROTATION", kv(event="avoid_standalone_grid", variant=_sv,
                               standalone_days=int(_r3s.get("sa_avoid_days", 0)),
                               avoid_days_total=int(_r3s.get("avoid_days", 0)),
                               # 집중도: 최빈 회피 섹터의 몫이 크면 '그 섹터를 빼는 규칙'이지 순환매가 아니다
                               avoid_sectors=";".join(f"{k}={int(v)}" for k, v in _sc_top) or "-",
                               top_share=round(float(_sc_top[0][1]) / _sc_n, 3) if _sc_top else 0.0,
                               years=";".join(f"{y}:{'+'.join(v)}" for y, v in sorted(_sets.items()) if v) or "-"), M=M)
    # [v0.48.0 L2 ★ 신규 격자 — REPORT51 §5·§2.4 E4] [득표상실청산격자] — 자세한 근거는 CFG 주석·_run_leader3
    #   docstring 참조. 집중배분 계열에서만 판정한다(주력섹터 모드가 주 전략이어도 리더 규칙 자체는 이 상태기계를
    #   공유하므로, 아래 _is_cap_grid 등록으로 하락국면리더·전섹터하락 오버라이드까지 like-for-like로 받는다).
    vote_loss_exit_variants: Dict[str, pd.DataFrame] = {}
    for _vl in tuple(getattr(scfg, "ROTATION_EXIT_ON_VOTE_LOSS_GRID", ()) or ()):
        _vl = str(_vl).lower()
        if _vl != "majority":
            log("ROTATION", kv(event="vote_loss_exit_grid_skip", variant=_vl,
                               note="정의된 값은 'majority'뿐 — 알 수 없는 값은 건너뜀"), M=M, level="warning")
            continue
        _r3v = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rev_live, exit_on_vote_loss=True)
        _lab_vl = "집중배분 · 득표상실 즉시청산 [득표상실청산격자]"
        vote_loss_exit_variants[_lab_vl] = _r3v["frac_leader"]
        _keep_diag(_lab_vl, _r3v)   # [v0.48.0 L2] 13p 블록 E가 이 변형의 리더→상위3을 재게 한다
        log("ROTATION", kv(event="vote_loss_exit_grid", variant=_vl,
                           exit_days=int(_r3v.get("vote_loss_exit_days", 0)),
                           switches=int(_r3v.get("switches", 0))), M=M)
    # [v0.48.0 L3 ★ 신규 격자 — REPORT51 §5] [보유기간격자] — 최소보유 21 → 42/63일. 라이브값(min_hold)과
    #   같은 값은 격자에서 뺀다(★와 같은 행을 두 번 싣지 않는다 — 다른 격자와 같은 관례).
    min_hold_variants: Dict[str, pd.DataFrame] = {}
    for _mhg in tuple(getattr(scfg, "ROTATION_MIN_HOLD_GRID", ()) or ()):
        _mhg = int(_mhg)
        if _mhg == min_hold or _mhg <= 0:
            continue
        _r3h = _run_leader3(getattr(scfg, "ROTATION_LEADER_REGIMES", None), _rev_live, min_hold_override=_mhg)
        _lab_mh = f"집중배분 · 최소보유 {_mhg}일 [보유기간격자]"
        min_hold_variants[_lab_mh] = _r3h["frac_leader"]
        _keep_diag(_lab_mh, _r3h)   # [v0.48.0 L3]
        log("ROTATION", kv(event="min_hold_grid", days=_mhg, switches=int(_r3h.get("switches", 0)),
                           vote_loss_exit_days=int(_r3h.get("vote_loss_exit_days", 0))), M=M)
    # [v0.16.0 §A ⚠] 주력 섹터 중심 배분 — 근거·실측은 SectorConfig 주석 참조.
    #   주력(기본 XLK)이 자기 국면 RISK_OFF가 아니면 ROTATION_PRIMARY_CAP만큼 보유하고 나머지는 대피처로,
    #   RISK_OFF면 전량 대피처로 보낸다. 대피처 = 순환매 복합순위 1위(주력 제외 · 그 섹터도 RISK_OFF 아님),
    #   그마저 없으면 RISK_OFF가 아닌 섹터 균등. SPY는 쓰지 않는다(사용자 지시: 참고용).
    #   신규 신호 없음 — results[t]["state"](각 섹터 자기 국면)와 기존 복합순위만 재사용한다.
    frac_primary_sector = None
    label_psec = None
    primary_cap_variants = {}   # [v0.22.0] 주력 상한 격자
    _pri = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "")
    if getattr(scfg, "ROTATION_PRIMARY_MODE", False) and _pri in cols:
        _cap = float(getattr(scfg, "ROTATION_PRIMARY_CAP", 0.8) or 0.0)
        _exit = tuple(getattr(scfg, "ROTATION_PRIMARY_EXIT_STATES", ("RISK_OFF",)))
        _st = pd.DataFrame({t: pd.Series(results[t].get("state")).reindex(eval_idx).astype(object)
                            for t in cols if results.get(t) is not None and results[t].get("state") is not None})
        _hold = ~_st.isin(_exit) & _st.notna()          # 그 섹터를 보유해도 되는 날
        # [v0.44.0 F3(2) 국면상속격자] 같은 판정을 **M(SPY) 국면**으로 내린 판(전 섹터 공통).
        #   왜: REPORT47 §2.3 실측 — 섹터 하락 예측의 MCC가 자기 국면기계 0.055 vs M 현금 상속 0.079,
        #   M '상승 아님' 상속 0.088(9/11 섹터에서 자기 기계보다 높다). M 자신은 소수 클래스에 정보가 있고
        #   (현금 MCC 0.160·상승아님 0.187) 섹터별 재추정이 그 정보를 깎는다. 그렇다면 "자기 국면이
        #   하락이라 대피"가 이득인지 손해인지는 **격자가 실제 엔진으로** 재야 한다. 신호 재계산 없음.
        _m_state = pd.Series(_spy_state_src).reindex(eval_idx)
        _hold_m_off = ~_m_state.isin(_exit) & _m_state.notna()            # M이 RISK_OFF가 아닌 날
        _hold_m_up = _m_state.eq("RISK_ON")                                # M이 상승인 날만
        def _bcast(v: pd.Series) -> pd.DataFrame:
            return pd.DataFrame({c: v.values for c in _hold.columns}, index=eval_idx) & _st.notna()
        _hold_m = {"m_off": _bcast(_hold_m_off), "m_up": _bcast(_hold_m_up)}
        _elig_m = {k: (v & listed[[c for c in _hold.columns if c in listed.columns]].reindex(columns=_hold.columns).fillna(False))
                   for k, v in _hold_m.items()}
        _alt_rank = rank_pos.reindex(columns=[c for c in cols if c != _pri and c in rank_pos.columns])
        _alt = pd.Series(index=eval_idx, dtype=object)
        _has = _alt_rank.notna().any(axis=1) if len(_alt_rank.columns) else pd.Series(False, index=eval_idx)
        if bool(_has.any()):
            _alt.loc[_has] = _alt_rank.loc[_has].idxmin(axis=1)   # ⚠ rank_pos는 1이 최상위 → idxmin
        # [v0.22.0] 상한만 바꾼 변형을 만들 수 있도록 함수로 뺐다 — 로직은 v0.16.0과 완전히 동일하다.
        #   ⚠ 왜 필요한가: 리포트23에서 주 전략 ★(상한 0.8)의 위험조정 지표가 M 단독보다 나빠졌다
        #   (샤프 1.889 vs M 1.934 · MDD -10.49% vs -7.17% · 칼마 2.665 vs 2.996). CAGR은 27.96%로
        #   높지만 사용자 기준은 "수익률 숫자만 높게 나온다고 좋은 게 아니라고"다. 집중도가 원인일
        #   가능성이 크므로 **상한 격자를 상설로 실어 다음 실행이 실제 엔진으로 재게 한다**
        #   (v1.11.0의 사전등록 격자가 v1.37.0에서, v1.35.0의 BREADTH_SIDE가 v1.38.0에서 답을 준 것과
        #   같은 방식). 채택값은 바꾸지 않는다 — 재보기 전에는 고르지 않는다.
        # [v0.29.0] 워크포워드 베타 승수 — t 이전 자료만으로 확장창 추정(룩어헤드 차단).
        #   beta_t = cov(r_sec[:t-1], r_spy[:t-1]) / var(r_spy[:t-1]), 관측 < MIN_OBS 이면 승수 1.0.
        # [v0.31.0 §4] 확장창 워크포워드 베타를 **한 번만** 계산해 캐시한다. 종전에는 _beta_mult가
        #   호출될 때마다(=[베타격자]·[베타재투입격자] 8행) 11섹터 공분산을 다시 돌렸다 — 같은
        #   결과에 8배 계산이었다. 추정 규약은 v0.29.0과 동일(t 이전 자료만 · 최소 MIN_OBS일).
        _beta_cache: Dict[str, pd.DataFrame] = {}

        def _beta_raw() -> pd.DataFrame:
            if "raw" in _beta_cache:
                return _beta_cache["raw"]
            out = pd.DataFrame(np.nan, index=eval_idx, columns=list(cols), dtype=float)
            _rs = ((1.0 + ret_co["SPY"]) * (1.0 + ret_oc["SPY"]) - 1.0).reindex(eval_idx).shift(1)
            _minn = int(getattr(scfg, "ROTATION_BETA_MIN_OBS", 250))
            _vs = _rs.expanding(min_periods=_minn).var()
            for _t in cols:
                _r = ret_cc[_t].reindex(eval_idx).shift(1)
                _cv = _r.expanding(min_periods=_minn).cov(_rs)
                out[_t] = (_cv / _vs).replace([np.inf, -np.inf], np.nan)
            _beta_cache["raw"] = out
            log("ROTATION", kv(event="beta_estimated", n=len(cols), min_obs=_minn,
                               first_valid=str(out.dropna(how="all").index.min())[:10],
                               median_beta=round(float(out.median(skipna=True).median()), 4)), M=M)
            return out

        def _beta_mult(scale_: float) -> pd.DataFrame:
            out = pd.DataFrame(1.0, index=eval_idx, columns=all_cols)
            if scale_ <= 0:
                return out
            _braw = _beta_raw()
            for _t in cols:
                _b = _braw[_t]
                _m = (1.0 / _b.clip(lower=0.2) ** float(scale_)).clip(upper=1.0)
                out[_t] = _m.fillna(1.0)
            return out

        # [v0.31.0 §3] 방어 대피처 — 그날 적격(hold & eligible) 비주력 섹터 중 워크포워드 베타
        #   최저인 티커. 베타가 아직 없는(관측 < MIN_OBS) 날은 None → 종전 순위 경로로 떨어진다.
        # [v0.60.0 R72 §3b(1) 성능 — 결과 비트 동일] 종전에는 2,185일×후보 10개를 파이썬 루프로 돌며 `.loc` 스칼라를
        #   44만 회 읽었고(03a_집중배분의 ≈50%), 그 계산을 _build_primary 25회(라이브 1+격자 24)가 **같은 입력으로**
        #   반복했다. share_>0이면 결과가 share_ 값과 무관하게 _hold·eligible·베타에만 의존하므로(원본 share 0.25/1.0
        #   결과 equals 실측) ① 1회만 계산해 공유(_dalt_cache) ② 벡터화: 적격 아닌 칸을 +inf로 두고 행별 argmin.
        #   동률 처리 동일 — 원본 min(_ok, key=…)은 _cand 순서의 **첫 최소**, np.argmin도 첫 최소. 베타는 ±inf가
        #   NaN으로 치환돼 있어(_beta_raw) +inf 센티널과 충돌하지 않는다. 미설정일은 원본처럼 NaN(object Series).
        #   축이 eval_idx와 다르면(방어적) 원본 루프로 계산한다.
        _dalt_cache: Dict[str, pd.Series] = {}

        def _defensive_alt_loop(share_: float) -> pd.Series:     # 원본(v0.31.0) — 동일성 테스트·폴백용
            out = pd.Series(index=eval_idx, dtype=object)
            if share_ <= 0:
                return out
            _br = _beta_raw()
            _cand = [c for c in cols if c != _pri and c in _hold.columns and c in eligible.columns]
            for _d in eval_idx:
                _ok = [c for c in _cand
                       if bool(_hold.loc[_d, c]) and bool(eligible.loc[_d, c]) and pd.notna(_br.loc[_d, c])]
                if _ok:
                    out.loc[_d] = min(_ok, key=lambda c: float(_br.loc[_d, c]))
            return out

        def _defensive_alt(share_: float) -> pd.Series:
            if share_ <= 0:
                return pd.Series(index=eval_idx, dtype=object)
            if "pos" in _dalt_cache:
                return _dalt_cache["pos"].copy()
            _br = _beta_raw()
            _cand = [c for c in cols if c != _pri and c in _hold.columns and c in eligible.columns]
            if not (_hold.index.equals(eval_idx) and eligible.index.equals(eval_idx) and _br.index.equals(eval_idx)):
                out = _defensive_alt_loop(share_)
            else:
                out = pd.Series(index=eval_idx, dtype=object)
                if _cand:
                    _bra = _br[_cand].to_numpy(dtype=float)                                   # (일수, 후보)
                    _okm = (_hold[_cand].to_numpy(dtype=bool) & eligible[_cand].to_numpy(dtype=bool)
                            & ~np.isnan(_bra))
                    _j = np.where(_okm, _bra, np.inf).argmin(axis=1)
                    _has = _okm.any(axis=1)
                    if bool(_has.any()):
                        out.iloc[np.flatnonzero(_has)] = np.array(_cand, dtype=object)[_j[_has]]
            _dalt_cache["pos"] = out
            log("ROTATION", kv(event="defensive_alt_built", days=int(out.notna().sum()), candidates=len(_cand),
                               note="1회 계산 후 _build_primary 호출 전체가 공유(v0.60.0 R72 §3b)"), M=M)
            return out.copy()

        # [v0.36.0 §A] 횡단면 분산 게이트 — 저분산일에는 '순위 1위 집중'을 포기하고 균등으로.
        #   ⚠ 룩어헤드 차단 2중: (1) 분산 자체를 t-1까지의 후행 창으로 계산하고 shift(1),
        #   (2) 문턱을 전체표본 4분위가 아니라 **확장창 백분위(자기 자신 제외)** 로 잡는다.
        #   MIN_OBS 미만 구간은 백분위가 NaN → 게이트 꺼짐(기존 경로) — 조용히 켜지지 않는다.
        _disp_cache: Dict[str, pd.Series] = {}

        def _dispersion_gate(pct_: float, invert_: bool = False) -> pd.Series:
            _lb = int(getattr(scfg, "ROTATION_DISPERSION_LOOKBACK", 63))
            _mo = int(getattr(scfg, "ROTATION_DISPERSION_MIN_OBS", 250))
            _key = f"{_lb}:{_mo}"
            if _key not in _disp_cache:
                _cum = (1.0 + ret_cc[list(cols)]).rolling(_lb).apply(np.prod, raw=True) - 1.0
                _d = _cum.std(axis=1).reindex(eval_idx).shift(1)
                _disp_cache[_key] = _d.expanding(min_periods=_mo).apply(
                    lambda a: float((a[:-1] < a[-1]).mean()), raw=True)
                log("ROTATION", kv(event="dispersion_ready", lookback=_lb, min_obs=_mo,
                                   first_valid=str(_disp_cache[_key].dropna().index.min())[:10],
                                   median=round(float(_d.median(skipna=True)), 6)), M=M)
            _p = _disp_cache[_key]
            _g = (_p >= float(pct_)) if bool(invert_) else (_p < float(pct_))
            return _g.fillna(False)

        def _build_primary(cap_: float, bscale_: Optional[float] = None, bmode_: Optional[str] = None,
                           shelter_def_: Optional[float] = None, disp_pct_: Optional[float] = None,
                           disp_invert_: Optional[bool] = None, neutral_leader_: Optional[float] = None,
                           neutral_cap_: Optional[float] = None, regime_src_: Optional[str] = None,
                           shelter_rule_: Optional[str] = None):
            _bm = _beta_mult(float(getattr(scfg, "ROTATION_BETA_SCALE", 0.0) or 0.0)
                             if bscale_ is None else float(bscale_))
            _mode = str(getattr(scfg, "ROTATION_BETA_MODE", "trim") if bmode_ is None else bmode_)
            _sdef = float(getattr(scfg, "ROTATION_SHELTER_DEFENSIVE", 0.0) or 0.0
                          if shelter_def_ is None else shelter_def_)
            _sdef = min(max(_sdef, 0.0), 1.0)
            _dalt = _defensive_alt(_sdef)
            # [v0.36.0 §A] 저분산 게이트 — disp_pct_ 가 None이면 라이브 설정(기본 OFF)을 따른다.
            _dgate = None
            _dp = disp_pct_
            _di = bool(getattr(scfg, "ROTATION_DISPERSION_INVERT", False)) if disp_invert_ is None else bool(disp_invert_)
            if _dp is None and bool(getattr(scfg, "ROTATION_DISPERSION_GATE", False)):
                _dp = float(getattr(scfg, "ROTATION_DISPERSION_PCT", 0.50) or 0.0)
            if _dp is not None and float(_dp) > 0.0:
                _dgate = _dispersion_gate(float(_dp), _di)
            # [v0.41.0 S-B] 중립 국면 리더 슬롯 — 잔여 슬리브 중 _nl 만큼을 그날 '확신 게이트를 통과한
            #   리더'(leader_s)에게 준다. 근거(REPORT44 §2.1 증거2): SCORE_PCT 1위 초과수익은 M=중립에서만
            #   t 3.50이고 상승에서는 t 0.53이다. 주력(_pri)이 리더인 날은 건너뛴다 — 상한의 의미를 지키려고.
            _nl = float(getattr(scfg, "ROTATION_NEUTRAL_LEADER_SHARE", 0.0) or 0.0
                        if neutral_leader_ is None else neutral_leader_)
            _nl = min(max(_nl, 0.0), 1.0)
            _nl_reg = str(getattr(scfg, "ROTATION_NEUTRAL_LEADER_REGIME", "중립"))
            # [v0.42.0 S-K] 중립 국면 주력 상한 — 그날 SPY 국면이 '중립'이면 주력 상한만 이 값으로 낮춘다.
            #   풀린 몫은 아래 기존 경로(방어대피처 → 리더/순위 1위 → 균등)를 그대로 탄다. None이면 무변경.
            #   v0.41.0 [중립리더격자]가 '잔여 10%의 배분 방식'만 건드려 무효였던 것(REPORT45 §2.5-2)과 달리,
            #   이건 **중립일에 주력을 얼마나 들 것인가**라는 실제 질문을 잰다.
            _ncap = (float(getattr(scfg, "ROTATION_NEUTRAL_CAP", None)) if getattr(scfg, "ROTATION_NEUTRAL_CAP", None) is not None
                     else None) if neutral_cap_ is None else float(neutral_cap_)
            if _ncap is not None:
                _ncap = min(max(_ncap, 0.0), 1.0)
            # [v0.44.0 F3(2)] 보유·적격 판정의 출처 — None/"own"이면 섹터 자기 국면(v0.43.0과 비트 동일),
            #   "m_off"면 M이 RISK_OFF가 아닌 날, "m_up"이면 M이 상승인 날만 보유한다.
            _rs = str(regime_src_ or "own").lower()
            _h_eff = _hold if _rs == "own" else _hold_m.get(_rs, _hold)
            _e_eff = eligible if _rs == "own" else _elig_m.get(_rs, eligible)
            # [v0.45.0 G3] 대피처(잔여 슬리브) 규칙 — None이면 라이브 설정(기본 "composite" = v0.44.0 비트 동일).
            #   득표·리더 시계열은 _run_leader3가 t일 정보로 이미 만든 값을 그대로 읽는다(재계산 없음).
            _shr = str(shelter_rule_ if shelter_rule_ is not None
                       else getattr(scfg, "ROTATION_SHELTER_RULE", "composite") or "composite").lower()
            if _shr not in _SHELTER_RULES:
                log("ROTATION", kv(event="unknown_shelter_rule", value=_shr, action="composite로 대체"),
                    M=M, level="warning")
                _shr = "composite"
            _min_votes = int(getattr(scfg, "ROTATION_SHELTER_MIN_VOTES", 2) or 2)
            _votes_arr = (votes_leader.reindex(eval_idx).fillna(0).astype(int).values
                          if _shr in ("votes2", "votes2_nonup") else np.zeros(len(eval_idx), dtype=int))
            # [v0.60.0 R72 §3b(2) 성능 — 결과 비트 동일] 일별 루프의 `.loc[_d, c]` 스칼라 읽기/쓰기 13곳을 numpy 위치
            #   인덱싱으로 바꿨다(루프 구조·분기·부동소수 연산 순서는 한 줄도 바꾸지 않음 — 같은 float64 값에 같은 순서로
            #   같은 연산). 행은 eval_idx 순서로 맞춘 사본(.loc[eval_idx])에서, 열은 이름→위치 dict로 찾는다(없는 열은
            #   원본과 같이 KeyError). fps_는 루프 끝에서 F로 한 번에 만든다.
            _Hdf = _h_eff.loc[eval_idx]
            _Edf = _e_eff.loc[eval_idx]
            _Bdf = _bm.loc[eval_idx]
            _H = _Hdf.to_numpy(dtype=bool)
            _E = _Edf.to_numpy(dtype=bool)
            _B = _Bdf.to_numpy(dtype=float)
            _ci_h = {c: i for i, c in enumerate(_Hdf.columns)}
            _ci_e = {c: i for i, c in enumerate(_Edf.columns)}
            _ci_b = {c: i for i, c in enumerate(_Bdf.columns)}
            _ci_f = {c: i for i, c in enumerate(all_cols)}
            F = np.zeros((len(eval_idx), len(all_cols)), dtype=float)
            n_pri_ = n_alt_ = n_eq_ = n_def_ = n_dg_ = n_nl_ = n_nc_ = n_sh_ = 0
            for _i_d, _d in enumerate(eval_idx):
                _pri_ok = bool(_H[_i_d, _ci_h[_pri]]) if _pri in _ci_h else False
                _a = _alt.get(_d)
                _a_ok = (isinstance(_a, str) and _a in _ci_h and bool(_H[_i_d, _ci_h[_a]])
                         and bool(_E[_i_d, _ci_e[_a]]) if _a in _ci_e else False)
                # [v0.42.0 S-K] 중립일 주력 상한 인하(그 외 국면은 cap_ 그대로).
                _cap_d = cap_
                if _ncap is not None and spy_regime_arr[_i_d] == _nl_reg and _ncap < cap_:
                    _cap_d = _ncap
                    n_nc_ += 1
                _share = _cap_d if _pri_ok else 0.0
                _pri_w = 0.0
                if _pri_ok:
                    # [v0.29.0] 베타 승수(≤1)만큼 덜 담는다 — 시장위험을 E_t에 맞춘다. scale=0이면 1.0.
                    _pri_w = _share * float(_B[_i_d, _ci_b[_pri]])
                    F[_i_d, _ci_f[_pri]] = _pri_w; n_pri_ += 1
                # [v0.30.0] "redeploy"면 베타로 깎인 만큼(_share - _pri_w)을 대피처 몫에 얹는다 —
                #   명목 노출은 E_t에 두고 포트폴리오 베타만 낮춘다. "trim"이면 종전대로 현금으로 남긴다.
                _rest = (1.0 - _pri_w) if (_mode == "redeploy") else (1.0 - _share)
                if _rest > 1e-12:
                    # [v0.31.0 §3] 주력을 보유한 날의 잔여분 중 _sdef 만큼은 '최저베타 적격섹터'로.
                    #   전량 대피일(_pri_ok=False)에는 적용하지 않는다 — 그 날 슬리브는 분산이 아니라
                    #   유일한 수익원이므로 순위 규칙이 맞다. _sdef=0이면 아래 두 줄은 무효과다.
                    _dc = _dalt.get(_d) if (_sdef > 0 and _pri_ok) else None
                    _r_def = _rest * _sdef if isinstance(_dc, str) else 0.0
                    _rest = _rest - _r_def
                    if _r_def > 1e-12:
                        F[_i_d, _ci_f[_dc]] += _r_def * float(_B[_i_d, _ci_b[_dc]]); n_def_ += 1
                # [v0.41.0 S-B] 중립 국면 리더 슬롯 — 방어 대피처 몫을 뗀 뒤, 순위 1위/균등 분기보다 먼저.
                if _rest > 1e-12 and _nl > 0 and spy_regime_arr[_i_d] == _nl_reg:
                    _ld = leader_s.get(_d)
                    if (isinstance(_ld, str) and _ld and _ld != _pri and _ld in _ci_h
                            and _ld in _ci_e and bool(_H[_i_d, _ci_h[_ld]])
                            and bool(_E[_i_d, _ci_e[_ld]])):
                        _r_ld = _rest * _nl
                        _rest = _rest - _r_ld
                        if _r_ld > 1e-12:
                            F[_i_d, _ci_f[_ld]] += _r_ld * float(_B[_i_d, _ci_b[_ld]]); n_nl_ += 1
                if _rest > 1e-12:
                    # [v0.36.0 §A] 저분산일이면 '순위 1위 집중'을 포기하고 아래 균등 분기로 내려간다.
                    #   ⚠ 주력 비중(cap_)은 건드리지 않는다 — 바뀌는 것은 잔여 슬리브의 배분 방식뿐.
                    if _dgate is not None and bool(_dgate.get(_d, False)):
                        _a_ok = False; n_dg_ += 1
                    # [v0.45.0 G3 ★ 대피처 규칙] 잔여 슬리브를 '복합순위 1위'로 채울지 '균등'으로 채울지를
                    #   그날의 **1위 득표수·M 국면**으로 정한다. "composite"면 아래 두 줄이 전부 무효라
                    #   v0.44.0과 비트 동일(라이브 기본값).
                    #   근거(REPORT48 §3·§4): 복합 1위의 실현 상위3 적중은 득표수에 단조(0표 0.182 / 1표
                    #   0.296 / 2표 0.396 / 3표 0.821)이고, 득표≤1이면서 M=상승인 644일은 0.227 · 초과
                    #   −0.71%/21일로 **무작위(0.274)보다 나쁘다**. 그런데 ★의 슬리브는 득표·국면을 보지 않고
                    #   늘 1위를 사므로 13m에서 슬리브 누적 10.64%가 비주력 균등 10.38%와 사실상 같다 —
                    #   '순환매 판단'이 값을 못 하고 있다. 각 규칙:
                    #     votes2        : 득표 ≥ ROTATION_SHELTER_MIN_VOTES(2)일 때만 1위, 아니면 균등
                    #     votes2_nonup  : votes2 + M=상승이면 무조건 균등(반증 겸용 — §3에서 득표≥2·상승도
                    #                     0.381로 정보가 있으므로 이 행이 votes2보다 나쁘면 국면 조건은 과하다)
                    #     leader_only   : 확신 게이트를 통과해 실제로 보유 중인 리더(leader_s)만, 없으면 균등
                    #   ⚠ 신규 신호·재계산 없음 — votes_leader·leader_s·spy_regime_arr는 전부 t일에 이미
                    #     확정된 값이다(_run_leader3에서 산출). 체결은 다른 규칙과 같이 t+1 시가.
                    if _shr != "composite" and _a_ok:
                        if _shr == "leader_only":
                            _ld_s = leader_s.get(_d)
                            _a_ok = (isinstance(_ld_s, str) and _ld_s == _a and _ld_s != _pri)
                        else:
                            _v_d = int(_votes_arr[_i_d])
                            _a_ok = _v_d >= _min_votes
                            if _a_ok and _shr == "votes2_nonup" and spy_regime_arr[_i_d] == "상승":
                                _a_ok = False
                        if not _a_ok:
                            n_sh_ += 1
                    if _a_ok:
                        F[_i_d, _ci_f[_a]] += _rest * float(_B[_i_d, _ci_b[_a]]); n_alt_ += 1
                    else:
                        _ok = [c for c in cols if c != _pri and c in _ci_h and bool(_H[_i_d, _ci_h[c]])
                               and bool(_E[_i_d, _ci_e[c]])]
                        if _ok:
                            for c in _ok:
                                F[_i_d, _ci_f[c]] += (_rest / len(_ok)) * float(_B[_i_d, _ci_b[c]])
                            n_eq_ += 1
            fps_ = pd.DataFrame(F, index=eval_idx, columns=all_cols)
            if _sdef > 0:
                log("ROTATION", kv(event="defensive_shelter_applied", share=round(_sdef, 4),
                                   days=n_def_, cap=round(float(cap_), 4)), M=M)
            if _dgate is not None:
                log("ROTATION", kv(event="dispersion_gate_applied", pct=round(float(_dp), 4),
                                   invert=bool(_di), gate_days=int(_dgate.sum()), rank_days_dropped=n_dg_,
                                   cap=round(float(cap_), 4)), M=M)
            if _nl > 0:
                log("ROTATION", kv(event="neutral_leader_slot_applied", share=round(_nl, 4), regime=_nl_reg,
                                   days=n_nl_, cap=round(float(cap_), 4)), M=M)
            if _ncap is not None:
                log("ROTATION", kv(event="neutral_cap_applied", neutral_cap=round(float(_ncap), 4), regime=_nl_reg,
                                   days=n_nc_, base_cap=round(float(cap_), 4)), M=M)
            if _rs != "own":
                log("ROTATION", kv(event="regime_inherit_applied", src=_rs, cap=round(float(cap_), 4),
                                   days_primary_own=int(_hold[_pri].sum()) if _pri in _hold.columns else -1,
                                   days_primary_inherit=int(_h_eff[_pri].sum()) if _pri in _h_eff.columns else -1,
                                   note="주력 보유일이 늘면 '자기 국면 대피'가 비싼 규칙이었다는 뜻"), M=M)
            if _shr != "composite":
                # 판독 요령: days_rank_to_equal이 0이면 그 규칙은 아무것도 안 바꾼 것(행이 ★와 비트 동일)이고,
                #   그만큼의 날에 '복합 1위 집중' 대신 균등을 쓴 결과가 13/13m에서 값을 했는지를 본다.
                log("ROTATION", kv(event="shelter_rule_applied", rule=_shr, min_votes=_min_votes,
                                   days_rank_to_equal=n_sh_, days_rank_kept=n_alt_, days_equal=n_eq_,
                                   cap=round(float(cap_), 4)), M=M)
            return fps_, n_pri_, n_alt_, n_eq_
        fps, _n_pri, _n_alt, _n_eq = _build_primary(_cap)
        frac_primary_sector = fps
        # 상한 격자(채택값 제외) — 13_섹터배분전략에 [비교] 행으로 실린다.
        primary_cap_variants = {}
        for _cv in (0.5, 0.6, 0.7, 0.8, 0.9, 1.0):
            if abs(_cv - _cap) < 1e-9:
                continue
            primary_cap_variants[f"주력섹터 중심 · {_pri} 상한 {_cv:.0%} [상한격자]"] = _build_primary(_cv)[0]
        # [v0.29.0] 베타 정규화 강도 격자 — 채택값 제외. 큰하락일 열위의 원인(초과 베타 +0.096)에
        #   대한 처방을 실제 엔진이 칼마로 판정하게 한다. scale=0 행은 현행과 동일해야 한다(검증점).
        _bs_live = float(getattr(scfg, "ROTATION_BETA_SCALE", 0.0) or 0.0)
        for _bv in (0.0, 0.25, 0.50, 0.75, 1.0):
            if abs(_bv - _bs_live) < 1e-9:
                continue
            primary_cap_variants[f"주력섹터 중심 · 베타정규화 {_bv:.2f} [베타격자]"] = _build_primary(_cap, _bv)[0]
        # [v0.30.0] 재투입 변형 — 깎은 비중을 현금이 아니라 대피처로 보낸다(명목 노출 유지).
        for _bv in (0.25, 0.50, 0.75, 1.0):
            primary_cap_variants[f"주력섹터 중심 · 베타재투입 {_bv:.2f} [베타재투입격자]"] = \
                _build_primary(_cap, _bv, "redeploy")[0]
        # [v0.31.0 §3] 방어 대피처 격자 — 채택값(라이브) 제외. 리포트31에서 최대낙폭 구간의 대피처
        #   가중 베타가 0.99(주력 1.30)로 사실상 시장 복제였다는 진단에 대한 처방을, 리플레이가
        #   아니라 실제 엔진이 칼마로 판정하게 한다. share=0 행은 현행과 동일해야 한다(검증점).
        # [v0.32.0] 후보에 0.0(=규칙 끔)을 넣는다 — 채택값이 0이 아니게 됐으므로 '끈 상태'가
        #   대조군으로 매 실행 실려야 한다(채택값 1개는 자동 제외되므로 격자는 항상 4행이다).
        _sd_live = float(getattr(scfg, "ROTATION_SHELTER_DEFENSIVE", 0.0) or 0.0)
        for _sv in (0.0, 0.25, 0.50, 0.75, 1.0):
            if abs(_sv - _sd_live) < 1e-9:
                continue
            primary_cap_variants[f"주력섹터 중심 · 방어대피처 {_sv:.2f} [방어대피처격자]"] = \
                _build_primary(_cap, None, None, _sv)[0]
        # [v0.36.0 §A 사전등록] 분산 게이트 격자 — 라이브(기본 OFF)가 ★이므로 격자는 '켠' 변형들이다.
        #   반증용 역방향 1행을 **반드시 같이** 싣는다: 방향이 진짜라면 역방향은 ★보다 나빠야 한다.
        #   (리플레이 예측: 하위25% 3.670 · 하위50% 3.708 · 하위75% 3.685 · 역방향 3.600 · ★ 3.654)
        _dg_live = float(getattr(scfg, "ROTATION_DISPERSION_PCT", 0.50) or 0.0) \
            if bool(getattr(scfg, "ROTATION_DISPERSION_GATE", False)) else 0.0
        _dg_inv_live = bool(getattr(scfg, "ROTATION_DISPERSION_INVERT", False))
        for _dv in (0.25, 0.50, 0.75):
            if abs(_dv - _dg_live) < 1e-9 and not _dg_inv_live:
                continue
            primary_cap_variants[f"주력섹터 중심 · 저분산일 균등 {_dv:.0%} [분산게이트격자]"] = \
                _build_primary(_cap, None, None, None, _dv, False)[0]
        if not (abs(0.50 - _dg_live) < 1e-9 and _dg_inv_live):
            primary_cap_variants["주력섹터 중심 · 고분산일 균등 50% [분산게이트격자·반증]"] = \
                _build_primary(_cap, None, None, None, 0.50, True)[0]
        if _dg_live > 0:   # 게이트를 켠 뒤에는 '끈 상태'가 대조군으로 실려야 한다
            primary_cap_variants["주력섹터 중심 · 분산게이트 off [분산게이트격자]"] = \
                _build_primary(_cap, None, None, None, 0.0, False)[0]
        # [v0.41.0 S-B 사전등록 격자] 중립 국면 리더 슬롯 — 잔여 슬리브의 25/50/100%를 그날 리더에게.
        #   근거(REPORT44 §2.1 증거2·§S-B): 리더 정보는 M=중립에만 있다(t 3.50 vs 상승 0.53).
        #   배분층이라 하나의 신호(results·leader_s)를 공유한다 → 격자 4기준으로 판정. 라이브는 0.0(무변경).
        _nl_live = float(getattr(scfg, "ROTATION_NEUTRAL_LEADER_SHARE", 0.0) or 0.0)
        for _nv in tuple(getattr(scfg, "ROTATION_NEUTRAL_LEADER_GRID", ()) or ()):
            if abs(float(_nv) - _nl_live) < 1e-9:
                continue
            primary_cap_variants[f"주력섹터 중심 · 중립 리더슬롯 {float(_nv):.0%} [중립리더격자]"] = \
                _build_primary(_cap, None, None, None, None, None, float(_nv))[0]
        if _nl_live > 0:   # 켠 뒤에는 '끈 상태'가 대조군으로 실려야 한다
            primary_cap_variants["주력섹터 중심 · 중립 리더슬롯 off [중립리더격자]"] = \
                _build_primary(_cap, None, None, None, None, None, 0.0)[0]
        # [v0.42.0 S-K 사전등록 격자] 중립 국면 주력 상한 — 라이브(None=cap_ 그대로)와 같은 값은 제외.
        #   근거: 리더 정보는 중립에 몰려 있는데(재계산 1위−평균 중립 +2.26%/21일 t 3.37 vs 상승 +1.02/2.37,
        #   13l 블록 E 중립 리더>SPY 0.662) 정작 중립일에도 주력을 45%(=0.9×E_t) 들고 간다.
        #   0.0 행은 '중립일엔 주력을 아예 안 든다'(전량 리더·대피처)라 축의 끝을 보여 준다.
        _nc_live = getattr(scfg, "ROTATION_NEUTRAL_CAP", None)
        for _cv2 in tuple(getattr(scfg, "ROTATION_NEUTRAL_CAP_GRID", ()) or ()):
            if _nc_live is not None and abs(float(_cv2) - float(_nc_live)) < 1e-9:
                continue
            if float(_cv2) >= _cap - 1e-12:      # 상한보다 크거나 같으면 무변경 — 행을 만들지 않는다
                continue
            primary_cap_variants[f"주력섹터 중심 · 중립일 {_pri} 상한 {float(_cv2):.0%} [중립상한격자]"] = \
                _build_primary(_cap, None, None, None, None, None, None, float(_cv2))[0]
        if _nc_live is not None:   # 켠 뒤에는 '끈 상태'(=상한 유지)가 대조군으로 실려야 한다
            primary_cap_variants[f"주력섹터 중심 · 중립일 상한 유지({_cap:.0%}) [중립상한격자]"] = \
                _build_primary(_cap, None, None, None, None, None, None, _cap)[0]
        # [v0.44.0 F3(2) 사전등록 격자] 절대 국면 판정을 섹터 자기 것 대신 **M(SPY)** 것으로 상속.
        #   두 행: (가) M이 하락이 아니면 보유 (나) M이 상승일 때만 보유(더 엄격). 자기 국면기계는
        #   01_일별·09·13p 진단으로 그대로 남는다 — 바뀌는 것은 '무엇으로 대피·적격을 판정하나'뿐.
        #   판정: 격자 4기준 + 13p 블록 A의 'M 상속' MCC > 자기 MCC(§F3(1))가 함께 서야 채택 후보다.
        # [v0.45.0 G7 퇴역 — REPORT48 §1-4] 리포트44 실측: MCC 쪽은 맞았으나(자기 0.055 · M현금 0.080 ·
        #   M상승아님 0.088, 우위 +0.033) **배분은 둘 다 열위**였다 — M 하락 아님 CAGR 35.20%(★ 35.87 대비
        #   −0.53%p), M 상승만 33.33%(−1.96%p), 회전율 12.37 → 16.79. 즉 섹터 자기 국면의 '드문 대피'가
        #   방향 정보는 적어도 비용 대비로는 값을 했다(2022). 13p 블록 A의 M상속 6열은 **유지**한다 —
        #   측정은 계속하고 배분 격자만 접는다. 되돌리기: s_overrides={"ROTATION_REGIME_INHERIT_GRID":
        #   ("m_off", "m_up")}
        for _rsrc in tuple(getattr(scfg, "ROTATION_REGIME_INHERIT_GRID", ()) or ()):
            _lbl = {"m_off": "M 하락 아님", "m_up": "M 상승만"}.get(str(_rsrc), str(_rsrc))
            primary_cap_variants[f"주력섹터 중심 · 국면 M상속({_lbl}) [국면상속격자]"] = \
                _build_primary(_cap, None, None, None, None, None, None, None, _rsrc)[0]
        # [v0.45.0 G3 ★ 신규 격자] 대피처(잔여 슬리브) 규칙 — 자세한 근거는 _build_primary 안 주석 참조.
        #   라이브 규칙과 같은 값은 격자에서 뺀다(★와 같은 행을 두 번 싣지 않는다).
        _shr_live = str(getattr(scfg, "ROTATION_SHELTER_RULE", "composite") or "composite").lower()
        for _sv in tuple(getattr(scfg, "ROTATION_SHELTER_RULE_GRID", ()) or ()):
            _sv = str(_sv).lower()
            if _sv == _shr_live or _sv not in _SHELTER_RULES:
                continue
            primary_cap_variants[f"주력섹터 중심 · 대피처 {_SHELTER_RULES[_sv]} [대피처격자]"] = \
                _build_primary(_cap, None, None, None, None, None, None, None, None, _sv)[0]
        label_psec = f"주력섹터 중심({_pri} 상한 {_cap:.0%}·하락 시 대피·SPY 미사용)"
        log("ROTATION", kv(event="primary_sector_mode", sector=_pri, cap=_cap, exit_states=list(_exit),
                           days_primary=_n_pri, days_alt=_n_alt, days_equal=_n_eq, days=len(eval_idx)), M=M)

    label_topk = ROT_LABEL_TOPK.format(k=scfg.ROTATION_TOP_K, cap=cap)
    label_lin = ROT_LABEL_PRIMARY.format(cap=cap).replace(" ★", "")
    mode = str(scfg.ROTATION_TILT).lower()
    if mode == "topk":
        label_primary, frac_primary = label_topk + " ★", frac_topk
        label_leader = label_leader.replace(" ★", "")
    elif mode == "linear":
        label_primary, frac_primary = label_lin + " ★", frac_lin
        label_leader = label_leader.replace(" ★", "")
    else:
        label_primary, frac_primary = label_leader, frac_leader
    # [v0.16.0 §A] 주력 섹터 모드가 켜져 있으면 그것이 주 전략(★)이 된다. 종전 집중배분은 비교 변형으로 남는다.
    if frac_primary_sector is not None:
        label_leader = label_leader.replace(" ★", "")
        label_primary, frac_primary = label_psec + " ★", frac_primary_sector
    variants = {label_primary: frac_primary}
    for lab, fr in ((label_leader, frac_leader), (label_topk, frac_topk), (label_lin, frac_lin)):
        if lab != label_primary:
            variants[lab] = fr
    if frac_score is not None:
        variants[label_score] = frac_score      # [v0.8.0]
    if frac_regime is not None:
        variants[label_regime] = frac_regime    # [v0.10.0 §1.D]
    for _lab, _fr in primary_cap_variants.items():   # [v0.22.0] 주력 상한 격자(실제 엔진 측정)
        variants[_lab] = _fr
    for _lab, _fr in reverse_avoid_variants.items():   # [v0.41.0 S-G] 역방향 회피 격자(집중배분 계열)
        variants[_lab] = _fr
    for _lab, _fr in standalone_avoid_variants.items():   # [v0.45.0 G5] 단독 회피 격자(집중배분 계열)
        variants[_lab] = _fr
    for _lab, _fr in vote_loss_exit_variants.items():   # [v0.48.0 L2] 득표상실 즉시청산 격자
        variants[_lab] = _fr
    for _lab, _fr in min_hold_variants.items():   # [v0.48.0 L3] 최소보유 격자
        variants[_lab] = _fr
    # [v0.24.0] 혼합 변형 등록은 label_conv(확신 사이징) 생성 **뒤로** 옮겼다 — v0.23.0에서
    #   여기에 두었더니 그 시점에 확신 사이징이 아직 variants에 없어 **아무 것도 등록되지 않았다**
    #   (리포트25에 [혼합] 행이 통째로 빠진 원인). 아래 label_conv 블록 다음을 볼 것.
    variants[ROT_LABEL_CTRL_A] = frac_ctrl_a
    variants[ROT_LABEL_CTRL_B] = frac_ctrl_b

    cost_bps = float(res["cfg"].COST_BPS)
    lev_bps = float(getattr(res["cfg"], "LEVERAGE_SPREAD_BPS", 0.0) or 0.0)   # [v0.7.0] M v1.21 §C 초과노출 스프레드 정합
    # [v0.7.0] 평가창 진입 시 초기 포지션 = SPY M이 그 전날·전전날 들고 있던 SPY 비중(M은 SIGNAL_START 이전부터 포지션을 이어 온다).
    #   모든 변형에 같은 초기값 → 전 기간 폴백(SPY)이면 SPY M과 첫날부터 비트 동일, 대조군도 첫 2일만 M 포지션에서 출발.
    E_full = res["sig"]["target_pos"].reindex(full_idx).fillna(0.0).astype(float)
    i0 = int(full_idx.get_indexer([eval_idx[0]])[0]) if len(eval_idx) else -1
    init_exec = pd.Series(0.0, index=all_cols); init_prev = pd.Series(0.0, index=all_cols)
    if i0 >= 1:
        init_exec["SPY"] = float(E_full.iloc[i0 - 1])
    if i0 >= 2:
        init_prev["SPY"] = float(E_full.iloc[i0 - 2])
    bt_kw = dict(rf_daily=rf_daily, cost_bps=cost_bps, init_exec=init_exec, init_prev=init_prev, lev_spread_bps=lev_bps)
    listed_all = listed.copy()
    listed_all["SPY"] = True
    listed_all = listed_all.reindex(columns=all_cols)
    bts: Dict[str, pd.DataFrame] = {}
    target_ws: Dict[str, pd.DataFrame] = {}
    # [v0.41.0 S-H ⚠ 결함수정 — like-for-like 복원] 아래 변형 루프는 tier를 **공유**하는데 v0.15.0의
    #   하락국면리더 오버라이드가 `tier.loc[...] = "하락국면리더"`로 그 Series를 제자리에서 바꿔 버린다.
    #   ★(label_primary)가 variants의 첫 항목이라 ★만 오버라이드를 받고, 그 다음에 오는 **모든 격자 행**은
    #   `tier.eq("현금")`이 이미 False가 되어 조용히 오버라이드를 못 받았다(합성 픽스처 실측: 로그
    #   down_regime_leader_applied가 38행 중 1회만 발생). v0.24.0이 "[상한격자]가 오버라이드를 못 받아
    #   '상한 0.8이 최적'이라는 틀린 결론을 냈다"며 고친 바로 그 실수가 **다른 경로로 되살아나 있었다.**
    #   → 오버라이드 판정은 루프 전에 뜬 스냅샷(tier_cash0)으로만 하고, tier 라벨 변경은 ★에만 적용한다
    #     (반환되는 tier/13c 표시는 종전과 동일 = ★ 기준).
    tier_cash0 = tier.eq("현금").copy()
    down_leader_days = pd.Series(False, index=eval_idx)      # [v0.15.0 §A] 하락국면 리더 발동일(진단·시트용)
    alldown_days = pd.Series(False, index=eval_idx)          # [v0.27.0] 전섹터 하락 SPY 참여 발동일(격자·시트용)
    _ad_live_pos = 0.0                                       # [v0.27.0] ★에 실제로 적용된 참여 강도(격자 기준값)
    for label, frac in variants.items():
        tw = frac.reindex(columns=all_cols).mul(E, axis=0)
        # [v0.15.0 §A ⚠] 하락국면 리더 — E_t=0이라 전량 현금이 되는 날에도, 상태기계가 이미 뽑아 둔
        #   '명확한 1위'(확신 게이트 통과)가 있으면 그 섹터 하나로 거래한다. 근거·실측은 SectorConfig 주석 참조.
        #   ★ 주 전략(label_leader)에만 적용한다 — 비교 변형까지 바꾸면 13시트 대조군이 오염된다.
        #   신규 신호는 만들지 않는다(leader_s·gate_s는 이미 t일 정보로 계산된 값). 체결은 t+1 시가로 동일.
        # [v0.16.0] 하락국면 리더(v0.15.0)는 '집중배분' 계열의 규칙이다. 주력섹터 모드가 주 전략일 때도
        #   같은 근거(E_t=0이어도 명확1위가 게이트를 통과하면 거래)가 성립하므로 주 전략에 적용한다.
        # [v0.24.0 ⚠ 버그 수정 — v0.22.0 상한격자는 like-for-like 비교가 아니었다]
        #   ★(label_primary)는 아래 하락국면리더 오버라이드를 받는데 [상한격자] 행들은 못 받았다.
        #   그래서 리포트25에서 ★의 MDD가 -13.97%인데 격자 행은 전부 -10.2%대로 찍혔고,
        #   v0.22.0에서 "0.8이 칼마 정점"이라고 내린 결론은 **다른 전략끼리 비교한 것**이었다.
        #   상한만 다르고 나머지는 같아야 격자의 의미가 있으므로 [상한격자]도 같은 오버라이드를 받는다.
        # [v0.29.0] 베타격자도 같은 오버라이드를 받아야 like-for-like다 — v0.24.0에서 상한격자가
        #   오버라이드를 못 받아 "0.8이 최적"이라는 틀린 결론을 냈던 바로 그 실수를 반복하지 않는다.
        # [v0.31.0 §4] [방어대피처격자]도 같은 오버라이드를 받아야 like-for-like다 — v0.24.0에서
        #   [상한격자]가 오버라이드를 못 받아 "상한 0.8이 최적"이라는 틀린 결론을 냈던 그 실수를
        #   격자를 새로 심을 때마다 반복하지 않는다.
        # [v0.36.0 ⚠ 버그 수정] 종전에는 닫는 대괄호까지 포함해 비교했다 — 그래서
        #   "[분산게이트격자·반증]" 처럼 **꼬리표가 붙은 라벨이 매칭에서 조용히 빠졌다**.
        #   합성 E2E에서 반증 행이 [전섹터하락격자] 0% 와 비트 동일하게 나와 잡혔다(오버라이드 미적용).
        #   → 여는 대괄호까지만 비교한다. v0.24.0의 "오버라이드를 못 받은 격자가 틀린 결론을 냈다"와
        #     같은 종류의 실수이므로, 아래 회귀가 리포트의 모든 '격자' 라벨을 훑어 재발을 막는다.
        # [v0.41.0] 새 격자 2종도 같은 오버라이드를 받아야 like-for-like다(v0.24.0의 실수를 반복하지 않는다).
        #   [중립리더격자]는 주력섹터 계열, [역방향회피격자]는 집중배분 계열 — 둘 다 ★/label_leader와 같은 처리.
        _is_cap_grid = any(_g in str(label) for _g in ("[상한격자", "[베타격자", "[베타재투입격자", "[방어대피처격자", "[국면상속격자",
                                                       "[분산게이트격자", "[중립리더격자", "[역방향회피격자",
                                                       "[중립상한격자",     # [v0.42.0 S-K]
                                                       "[대피처격자",       # [v0.45.0 G3]
                                                       "[단독회피격자",     # [v0.45.0 G5]
                                                       "[득표상실청산격자",  # [v0.48.0 L2]
                                                       "[보유기간격자"))     # [v0.48.0 L3]
        if ((label in (label_leader, label_primary) or _is_cap_grid)
                and getattr(scfg, "ROTATION_DOWN_REGIME_LEADER", False)):
            dl_pos = float(getattr(scfg, "ROTATION_DOWN_REGIME_POS", 1.0) or 0.0)
            dl_m = tier_cash0 & leader_s.notna() & leader_s.isin(cols)   # [v0.41.0 S-H] 스냅샷 기준
            if getattr(scfg, "ROTATION_DOWN_REGIME_REQUIRE_GATE", True):
                dl_m = dl_m & gate_s.eq("통과")
            if dl_pos > 0 and bool(dl_m.any()):
                for _d in eval_idx[dl_m.reindex(eval_idx).fillna(False).values]:
                    tw.loc[_d, :] = 0.0
                    tw.loc[_d, leader_s.loc[_d]] = dl_pos
                if label == label_primary:      # [v0.41.0 S-H] 라벨 변경은 ★에만(공유 Series 오염 방지)
                    down_leader_days = dl_m.reindex(eval_idx).fillna(False)
                    # 리포트가 '현금'이라 적으면서 섹터를 들고 있는 모순을 없앤다 — 전용 판단 라벨.
                    tier.loc[down_leader_days[down_leader_days].index] = "하락국면리더"
                    # [v0.47.0 J1 ★ 신규] 블록 E에 '★ 하락국면리더일' 행을 리더(교차) 행과 분리해 남긴다.
                    #   REPORT50 §2.2 E8: "2026 리더 16일 1.000"은 전부 이 오버라이드 날이었지 교차 리더가
                    #   아니었다(라이브 교차 리더는 2026년 0일) — 두 규칙을 표에서부터 섞이지 않게 한다.
                    #   _dl_tier_diag는 이 콜만을 위한 전용 스냅샷(다른 어떤 것과도 공유하지 않음) — 리더
                    #   태그가 붙은 날은 이 행에서 제외되도록 "기타"로 둔다(Block E의 held = 리더|하락국면리더).
                    _dl_tier_diag = pd.Series("기타", index=tier.index, dtype=object)
                    _dl_tier_diag.loc[down_leader_days[down_leader_days].index] = "하락국면리더"
                    _keep_diag(label_leader + " [★ 하락국면리더일]",
                               {"tier": _dl_tier_diag, "leader_s": leader_s, "laggard_s": laggard_s})
                log("ROTATION", kv(event="down_regime_leader_applied", label=str(label)[:40],
                                   days=int(dl_m.reindex(eval_idx).fillna(False).sum()),
                                   pos=dl_pos, require_gate=bool(getattr(scfg, "ROTATION_DOWN_REGIME_REQUIRE_GATE", True)),
                                   sectors=dict(leader_s[down_leader_days].value_counts())), M=M)
        # [v0.27.0 ⚠⚠ 신규 규칙 — 전섹터 하락 시 SPY 잔여 참여] 근거·실측은 SectorConfig 주석 참조.
        #   조건: (i) E_t>0 (M이 투자하라고 한 날) (ii) 그런데 배분 합계가 0 (적격 섹터가 하나도 없음).
        #   그 날만 SPY를 ROTATION_ALLDOWN_SPY_POS × E_t 만큼 싣는다. 신규 신호를 만들지 않으며
        #   (E_t·적격여부 모두 t일 기존 계산값), 체결은 t+1 시가로 다른 규칙과 동일하다.
        #   ★·집중배분·[상한격자]에만 적용 — 대조군(A/B)까지 바꾸면 비교가 오염된다.
        #   하락국면리더(E_t=0)와는 조건이 배타적이라 서로 겹치지 않는다.
        _ad_pos = float(getattr(scfg, "ROTATION_ALLDOWN_SPY_POS", 0.0) or 0.0)
        if ((label in (label_leader, label_primary) or _is_cap_grid)
                and _ad_pos > 0 and "SPY" in tw.columns):
            _Ev = E.reindex(eval_idx).fillna(0.0).astype(float)
            _idle = (_Ev > 1e-12) & (tw.reindex(eval_idx).sum(axis=1).abs() <= 1e-12)
            if bool(_idle.any()):
                _idx = _idle[_idle].index
                tw.loc[_idx, "SPY"] = (_ad_pos * _Ev.loc[_idx]).values
                if label == label_primary:      # [v0.41.0 S-H] 라벨 변경은 ★에만(공유 Series 오염 방지)
                    tier.loc[_idx] = "전섹터하락SPY"
                    alldown_days = _idle.copy()
                    _ad_live_pos = _ad_pos
                log("ROTATION", kv(event="alldown_spy_applied", days=int(_idle.sum()), pos=_ad_pos,
                                   strategy=str(label)[:40],
                                   years=dict(pd.Series(_idx.year).value_counts().sort_index())), M=M)
        bad = (tw.abs() > 1e-12) & ~listed_all
        if bad.values.any():
            log("ROTATION", kv(event="weight_on_unlisted_sector_zeroed", strategy=label, cells=int(bad.values.sum())),
                M=M, level="warning")
            tw = tw.where(~bad, 0.0)
        target_ws[label] = tw
        bts[label] = portfolio_backtest(tw, ret_co, ret_oc, **bt_kw)
    # [v0.7.0] 비교 변형 '리더 자체 목표비중': 리더 보유일에는 E_t 대신 그 섹터의 M식 target_pos(섹터 자체 국면 판단 크기)를
    #   노출로 쓴다(E_t=0인 날은 주 전략과 같이 현금 — M의 위험회피 게이트는 유지). 회피·폴백일은 주 전략과 동일. 13시트 비교용이며
    #   기본 실행 비중(target_w)은 여전히 E_t를 따른다(사용자 요청: 국면 판단 비중대로).
    label_own = f"집중배분(리더 자체 목표비중·꼴찌회피·폴백{fallback_txt}) [비교]"
    if getattr(scfg, "ROTATION_ALT_LEADER_OWN_POS", True):
        own_pos = pd.DataFrame({t: results[t]["target_pos"].reindex(eval_idx) for t in cols}).fillna(0.0).astype(float)
        tw_own = target_ws[label_leader].copy()
        is_leader_day = (tier == "리더").values
        for i in np.flatnonzero(is_leader_day):
            c = leader_s.iloc[i]
            if c in cols:
                tw_own.iat[i, all_cols.index(c)] = float(own_pos.iat[i, cols.index(c)]) * lw
        target_ws[label_own] = tw_own
        bts[label_own] = portfolio_backtest(tw_own, ret_co, ret_oc, **bt_kw)
        variants[label_own] = tw_own   # 성과표 순서용(비중 자체는 위에서 계산 완료)
    # [v0.10.0 §1.B] [비교] 확신 사이징: 리더일 비중을 100%(lw)가 아니라 여유 비례로 줄이고(f = clip(margin/(2·step), 0, 1))
    #   나머지를 SPY에 채운다 — 근소한 1위일수록 SPY를 더 섞는다는 이산 게이트의 연속판. 리더가 아닌 날은 주 전략(label_leader)과
    #   동일. 리포트 10 what-if(§0.5): CAGR 이득은 작고 회전만 늘어 주 전략에는 쓰지 않고 13시트에 항상 병기만 한다.
    label_conv = "집중배분(확신 사이징: 리더 비중=E_t×min(1, 여유/2단계)·나머지 SPY) [비교]"
    if getattr(scfg, "ROTATION_ALT_CONVICTION_SIZING", True):
        tw_conv = target_ws[label_leader].copy()
        is_lead_arr = (tier == "리더").values
        margin_arr = margin_s.values
        step_arr = step_s.values
        # step<=0(게이트 문턱 자체가 0 — 비활성)이거나 margin이 NaN(여유를 정할 수 없던 날)이면 f=1(주 전략과 동일, 전액 리더)
        f_arr = np.where((step_arr > 0) & np.isfinite(margin_arr), np.clip(margin_arr / (2.0 * step_arr), 0.0, 1.0), 1.0)
        for i in np.flatnonzero(is_lead_arr):
            c = leader_s.iloc[i]
            if c in cols:
                j = all_cols.index(c)
                full_w = float(tw_conv.iat[i, j])           # 주 전략(label_leader)의 리더 비중 = lw × E_t
                f = float(f_arr[i])
                tw_conv.iat[i, j] = full_w * f
                tw_conv.iat[i, all_cols.index("SPY")] += full_w * (1.0 - f)
        target_ws[label_conv] = tw_conv
        bts[label_conv] = portfolio_backtest(tw_conv, ret_co, ret_oc, **bt_kw)
        variants[label_conv] = tw_conv
    # [v0.24.0 ⚠⚠ 하락국면리더(v0.15.0) 강도 격자 — 이번 라운드 최대 진단]
    #   리포트25에서 이 규칙이 **133일**(v0.22.0의 73일 → 거의 두 배) 발동했다. M이 HAZARD_ENTER
    #   0.90으로 바뀌며 E_t=0 구간의 구성이 달라진 결과다. 그 133일은 **M이 전량 현금(체결비중 0.000)인데
    #   섹터층은 총비중 1.000**인 날이다 — 즉 M의 위험회피 판단을 정면으로 뒤집는 구간이다.
    #   충실 리플레이(리포트25 재현: CAGR 29.49% / MDD -13.83% / 칼마 2.132 vs 리포트 29.61 / -13.97 / 2.120):
    #     하락국면리더 ON (현행 POS=1.0)  CAGR 29.49%  샤프 1.814  MDD **-13.83%**  칼마 2.132
    #     하락국면리더 OFF               CAGR 29.34%  샤프 1.957  MDD **-10.50%**  칼마 **2.793**
    #     참고 M 단독                    CAGR 23.68%  샤프 1.986  MDD  -7.07%  칼마 3.351
    #   **CAGR을 0.15pp 내주고 MDD를 3.33%p·칼마를 0.66 되찾는다.** 발동일 자체는 +8.06%p를 벌지만
    #   (섹터 +11.25% vs M +3.19%) 낙폭 경로를 크게 악화시킨다.
    #   ⚠ 이 규칙은 사용자가 직접 지시한 것이다("무조건 spy 전략 국면이 하락 예측 시에도 상승 할 수
    #   있는 섹터가 있으면 그걸로 거래하도록 해", v0.15.0). 그래서 **끄지 않는다.** 대신 강도를
    #   0.25/0.50/0.75/OFF로 격자에 실어 **실제 엔진이 재게** 한다. 중간 강도가 CAGR을 지키면서
    #   낙폭을 줄이는지가 다음 라운드의 결정 근거가 된다.
    _dl_variants = {}
    if getattr(scfg, "ROTATION_DOWN_REGIME_LEADER", False) and label_primary in target_ws:
        _dl_live = float(getattr(scfg, "ROTATION_DOWN_REGIME_POS", 1.0) or 0.0)
        _dl_days = (tier == "하락국면리더")
        if bool(_dl_days.any()):
            _base = target_ws[label_primary]
            for _lv in (0.0, 0.25, 0.50, 0.75):
                if abs(_lv - _dl_live) < 1e-9:
                    continue
                _w = _base.copy()
                _idx = _dl_days.reindex(_w.index).fillna(False)
                _w.loc[_idx.values, :] = _base.loc[_idx.values, :] * (_lv / _dl_live if _dl_live > 0 else 0.0)
                _dl_variants[f"주력섹터 중심 · 하락국면리더 비중 {_lv:.0%} [하락리더격자]"] = _w
    # [v0.27.0 ⚠⚠ 전섹터 하락 SPY 참여 강도 격자] 채택값(0.5)을 제외한 0/25/75/100%를 실제 엔진으로 잰다.
    #   이 규칙은 17일(전부 2022)에만 닿으므로 격자 행 사이의 차이도 그 17일에서만 나온다 —
    #   해석이 단순하고(다른 날은 ★와 비트 동일) 채택/기각 판정이 명확하다.
    if _ad_live_pos > 0 and label_primary in target_ws and bool(alldown_days.any()):
        _base = target_ws[label_primary]
        _idx = alldown_days.reindex(_base.index).fillna(False)
        for _lv in (0.0, 0.25, 0.50, 0.75, 1.0):
            if abs(_lv - _ad_live_pos) < 1e-9:
                continue
            _w = _base.copy()
            _w.loc[_idx.values, "SPY"] = _base.loc[_idx.values, "SPY"] * (_lv / _ad_live_pos)
            _dl_variants[f"주력섹터 중심 · 전섹터하락 SPY {_lv:.0%} [전섹터하락격자]"] = _w
    # [v0.34.0 ⚠⚠ M 과열 헤어컷 격자 — M 혼자서는 보이지 않는 것을 이 층에서 잰다]
    #   리포트56에서 드러난 사실: M의 과열 헤어컷(규칙 ⑩) 깊이를 **M 단독 지표로 판정하면 낙폭
    #   효과가 구조적으로 보이지 않는다.** M의 MDD는 2020 코로나 구간이 고정하고 있고 그 구간은
    #   이격 국면이 아니라 헤어컷이 닿지 않기 때문이다(E3~E13 전부 -7.07%로 동일).
    #   그런데 **이 층에서는 완전히 다르게 보인다** — 이 층은 E_t를 XLK 베타(~1.3)로 증폭하므로
    #   M의 노출 상한이 곧 이 층의 꼬리를 결정한다. 리포트56 기준 근사 재현:
    #     M헤어컷   섹터 CAGR  샤프    섹터 MDD    칼마    2024-07~08 구간
    #     off       32.89%   1.829  **-15.50%**  2.122   -14.92%
    #     E1        33.85%   1.960   -13.37%    2.532   -12.77%
    #     E3(당시)   34.78%   2.088   -11.21%    3.104   -10.59%   ← 13f ② FAIL(악화 1.69%p)
    #     E5        35.26%   2.166    -9.85%    3.578    -9.23%
    #     E7        35.71%   2.238  **-9.75%**  3.662    -7.87%   ← 낙폭 **포화**(여기서 멈춘다)
    #     E9        36.15%   2.305    -9.75%    3.707    -6.50%
    #     E11       36.57%   2.364    -9.75%    3.751    -5.11%
    #   E7부터 최대낙폭 구간이 2024-07-10~08-07(엔캐리 청산)에서 2019-04-23~06-03으로 **바뀌고**
    #   더 조여도 -9.75%에서 움직이지 않는다 — 헤어컷이 걷어낼 수 있는 것을 다 걷어낸 지점이다.
    #   (근사 검증: 이 방식으로 재현한 E9 행은 CAGR 36.15% / MDD -9.75% / 칼마 3.707로,
    #    E9가 라이브였던 **리포트33 실측 36.05% / -9.75% / 3.697과 거의 일치**한다.)
    #   ⚠ 이 격자는 **근사**다: M을 다시 돌리지 않고, 헤어컷이 닿은 날의 E_t만 후보 상한으로
    #   바꾼 뒤 배분비중을 같은 비율로 재스케일한다. 배분 '분수'는 순위·국면·적격성으로만
    #   정해지고 E_t에 의존하지 않으므로 이 재스케일은 정의상 정확하다(반올림 차이만 남는다).
    #   목적은 채택이 아니라 **M의 사이징 파라미터를 이 층에서도 보이게 만드는 것**이다.
    _mh_variants = {}
    try:
        _sig = res.get("sig")
        _ec = _sig["ext_cap"].reindex(eval_idx).astype(float) if (_sig is not None and "ext_cap" in _sig.columns) else None
        _eh = _sig["extension_haircut"].reindex(eval_idx).fillna(False).astype(bool) if (_sig is not None and "extension_haircut" in _sig.columns) else None
        _live_steps = tuple(getattr(M.CFG, "EXTENSION_HAIRCUT_STEPS", ()) or ())
        _cfgm = res.get("cfg")
        if _cfgm is not None and getattr(_cfgm, "EXTENSION_HAIRCUT_STEPS", None):
            _live_steps = tuple(_cfgm.EXTENSION_HAIRCUT_STEPS)
        if _ec is not None and _eh is not None and len(_live_steps) == 2 and bool(_eh.any()):
            _mid_live, _hi_live = float(_live_steps[0][1]), float(_live_steps[1][1])
            _mid_days = _eh & np.isclose(_ec, _mid_live)
            _hi_days = _eh & np.isclose(_ec, _hi_live)
            _E = E.reindex(eval_idx).astype(float)
            _base = target_ws[label_primary]
            _LAD = ((1.0, 1.0, "off"), (0.9, 0.8, "E1"), (0.8, 0.6, "E3"), (0.7, 0.5, "E5"),
                    (0.6, 0.4, "E7"), (0.5, 0.3, "E9"), (0.4, 0.2, "E11"))
            for _m, _h, _nm in _LAD:
                if abs(_m - _mid_live) < 1e-9 and abs(_h - _hi_live) < 1e-9:
                    continue                      # 라이브는 ★ 행이 이미 있다
                _E2 = _E.copy()
                _E2[_mid_days] = _m
                _E2[_hi_days] = _h
                _ratio = (_E2 / _E.replace(0.0, np.nan)).fillna(1.0)
                _mh_variants[f"주력섹터 중심 · M헤어컷 {_nm}({_m:.1f}/{_h:.1f}) [M헤어컷격자·근사]"] = \
                    _base.mul(_ratio, axis=0)
            log("ROTATION", kv(event="m_haircut_grid", levels=len(_mh_variants),
                               live=f"{_mid_live:.1f}/{_hi_live:.1f}",
                               mid_days=int(_mid_days.sum()), hi_days=int(_hi_days.sum())), M=M)
    except Exception as _e:
        log("ROTATION", kv(event="m_haircut_grid_failed", err=str(_e)[:140]), M=M, level="warning")
    _dl_variants.update(_mh_variants)

    for _lab, _fr in _dl_variants.items():
        target_ws[_lab] = _fr
        bts[_lab] = portfolio_backtest(_fr, ret_co, ret_oc, **bt_kw)
        variants[_lab] = _fr
    if _dl_variants:
        log("ROTATION", kv(event="down_leader_grid", levels=len(_dl_variants),
                           live_pos=float(getattr(scfg, "ROTATION_DOWN_REGIME_POS", 1.0))), M=M)

    # [v0.24.0 ⚠ 동일가중 혼합 — v0.23.0에서 잘못된 위치에 두어 등록조차 되지 않았던 것을 고쳤다]
    #   근거(리포트24 곡선 리플레이): ★와 '확신 사이징'의 일별 상관은 0.77로 완전히 겹치지 않아,
    #   1/n 동일가중으로 섞으면 **샤프가 두 구성요소를 모두 넘는다**(1.967 vs 1.869 / 1.820).
    #   가중치는 1/n 고정 — 파라미터 탐색이 아니다. 주 전략은 바꾸지 않고 [혼합] 행으로만 실어
    #   **실제 엔진이 직접 재게** 한다(v1.11.0·v1.35.0·v0.22.0이 모두 이 방식으로 답을 냈다).
    #   ⚠ v0.23.0의 교훈: 등록이 조용히 실패할 수 있으므로 **구성요소를 못 찾으면 로그로 알린다.**
    _bl_src = {}
    for _k in list(target_ws.keys()):
        _ks = str(_k)
        if _ks == label_primary:
            _bl_src["주력"] = target_ws[_k]
        elif "확신 사이징" in _ks:
            _bl_src["확신"] = target_ws[_k]
        elif "중립 국면만 리더" in _ks:
            _bl_src["중립"] = target_ws[_k]

    def _blend(parts: List[pd.DataFrame]) -> pd.DataFrame:
        out = parts[0].copy() * 0.0
        for _pdf in parts:
            out = out.add(_pdf.reindex_like(out).fillna(0.0), fill_value=0.0)
        return out / float(len(parts))

    _blends = {}
    if "주력" in _bl_src and "확신" in _bl_src:
        _blends["혼합: 주력★ + 확신사이징 50/50 [혼합]"] = _blend([_bl_src["주력"], _bl_src["확신"]])
    if len(_bl_src) == 3:
        _blends["혼합: 주력★ + 확신 + 중립만리더 1/3 [혼합]"] = _blend(
            [_bl_src["주력"], _bl_src["확신"], _bl_src["중립"]])
    for _lab, _fr in _blends.items():
        target_ws[_lab] = _fr
        bts[_lab] = portfolio_backtest(_fr, ret_co, ret_oc, **bt_kw)
        variants[_lab] = _fr
    log("ROTATION", kv(event="blend_variants", found=sorted(_bl_src.keys()), registered=len(_blends),
                       missing=sorted({"주력", "확신", "중립"} - set(_bl_src))), M=M,
        level=("info" if len(_blends) else "warning"))

    # ---- [v0.57.0 K4 ★★★ 신규 격자 · 측정 전용] 배분 ↔ 섹터 자기비중 연결 ----
    #   ── 사용자 지적: "전략배분은 왜 계속 그대로야? 모든 섹터 예측 잘되면 올라야 하는거 아니야?" ──
    #   ★ 답(코드로 확인되는 기계적 사실): **배분 계층은 results[t]["target_pos"]를 한 번도 읽지 않는다.**
    #     읽는 것은 (1) results[t]["state"](적격 판정) (2) 순위신호 행렬(리더 선택) (3) SPY의 target_pos(=E_t)뿐이다.
    #     그래서 v0.54.0(중립 상향)·v0.55.0(하락분위 상한)·v0.56.0(E_t 바닥·퇴출)은 전부 **섹터 target_pos만**
    #     바꿨고, 배분 성과표는 **소수점까지 그대로**였다(리포트4 ↔ 리포트5: 총배수 14.266 동일). 버그가 아니라
    #     두 계층이 애초에 연결돼 있지 않았던 것이고, 사용자 지적이 정확했다.
    #   ⇒ 여기서 '연결했다면 어땠을지'를 **엔진이 직접 재서** 13 시트에 행으로 낸다. 라이브는 바꾸지 않는다
    #     (오프라인 하네스로 배분 곡선을 재현하지 못했으므로 내 추정치를 근거로 라이브를 바꾸지 않는다 — 누적 교훈 24).
    #   세 변형 모두 **총합 ≤ E_t를 유지**한다(사용자 판정 기준 8: 전체자산 = 1.0).
    if bool(getattr(scfg, "ALLOC_LINK_GRID", True)):
        try:
            _own = pd.DataFrame({t: pd.to_numeric(results[t].get("target_pos"), errors="coerce")
                                 .reindex(eval_idx).ffill() for t in cols if t in results})
            _own = _own.clip(lower=0.0, upper=1.0)
            if "SPY" in target_ws[label_primary].columns:
                _own["SPY"] = 1.0                      # SPY 폴백 슬리브는 이 격자의 대상이 아니다
            _base_w = target_ws[label_primary]
            _own = _own.reindex(index=_base_w.index, columns=_base_w.columns).fillna(1.0)
            _link = {}
            #  ① 상한: 섹터가 스스로 정한 노출을 **넘지 않게** 깎는다(합계는 줄기만 한다 → 상한 유지)
            _link["배분 × 섹터 자기비중 상한 [배분연결격자]"] = _base_w.where(_base_w <= _own, _own)
            #  ② 비례: 섹터 자기비중에 **비례**해 줄인다(가장 강한 연결 · 노출이 가장 많이 준다)
            _link["배분 × 섹터 자기비중 비례 [배분연결격자]"] = _base_w * _own
            #  ③ 적격: 자기비중이 0인 섹터만 **빼고**, 뺀 몫을 남은 섹터에 그 비율대로 되돌린다
            #     (합계를 보존하므로 ①②와 달리 노출이 줄지 않는다 — 순수한 '선택' 효과만 본다)
            _keep = (_own > 1e-9).astype(float)
            _m3 = _base_w * _keep
            _s0, _s1 = _base_w.sum(axis=1), _m3.sum(axis=1)
            _scale = (_s0 / _s1.replace(0.0, np.nan)).clip(upper=4.0).fillna(0.0)
            _link["배분 × 자기비중 0 섹터 제외(합계 보존) [배분연결격자]"] = _m3.mul(_scale, axis=0)
            for _lab, _fr in _link.items():
                _fr = _fr.fillna(0.0).clip(lower=0.0)
                target_ws[_lab] = _fr
                bts[_lab] = portfolio_backtest(_fr, ret_co, ret_oc, **bt_kw)
                variants[_lab] = _fr
            log("ROTATION", kv(event="alloc_link_grid", rows=len(_link),
                               base_mean_exposure=round(float(_base_w.sum(axis=1).mean()), 4),
                               cap_mean=round(float(_link["배분 × 섹터 자기비중 상한 [배분연결격자]"].sum(axis=1).mean()), 4),
                               prop_mean=round(float(_link["배분 × 섹터 자기비중 비례 [배분연결격자]"].sum(axis=1).mean()), 4),
                               note="★ 배분층은 지금까지 섹터 target_pos를 읽지 않았다 — 이 격자가 연결 효과를 측정한다"),
                M=M)
        except Exception as e:
            log("ROTATION", kv(event="alloc_link_grid_failed", err=type(e).__name__, msg=str(e)[:160],
                               action="격자 없이 배분 계속(주 전략 무영향)"), M=M, level="warning")

    # ---- [v0.62.0 R80 ★★★ 라이브 변경] 섹터 자기 근거 컷 — "국면 비중은 참고만, 아래로만 자율" ----
    #   ── 사용자 지시(2026-09-21) ──
    #     "섹터도 국면 비중을 전적으로 따라가지 말고 참고만 해야해. 국면에서는 폭이 크지 않지만 섹터별로 보면
    #      폭이 클 수 있어. 섹터만의 판단할 수 있는 근거가 있어야해."
    #   ── 지금까지의 사실(실측 · 리포트6 13c) ──
    #     배분 합계 == E_t 인 날 81.7% · E_t 초과 12.9%(대부분 하락국면리더 265일) · **E_t 미만 5.5%**.
    #     즉 섹터층은 M이 준 예산을 사실상 전부 썼고, '섹터 자신의 판단으로 덜 드는' 길이 없었다.
    #   ── 무엇을 근거로 삼는가(이미 이 층이 가진 것 · 새 신호 없음) ──
    #     그날 횡단면 **복합점수 순위**다. 13d가 이미 그 값을 재고 있다(SCORE_PCT 상위1 스프레드
    #     +1.503%/21일 · NW-t 4.21). 그 근거로 **점수 하위 1/3 섹터의 비중만 깎고, 깎은 몫은 현금**으로 둔다.
    #   ── 왜 '아래로만'인가 ──
    #     E_t **위로** 올리는 변형(고분산일 초과보유 등)은 무작위 대조군을 못 이겼다(대조군 칼마 3.478 ≥ 규칙 3.123).
    #     반대로 **아래로 깎는 쪽**은 같은 개수 무작위 대조군을 뚜렷이 이긴다. 그래서 자율은 아래쪽으로만 준다.
    #     ⇒ 레버리지 유입 없음 · 합계 ≤ E_t 유지(사용자 판정 기준 8 그대로).
    #   ── 사전등록 측정(r80/var80f~h.py · 엔진 13c 비중을 그대로 변형 · 시뮬레이터는 엔진 곡선 재현 검증 통과) ──
    #     기준선(E_t 그대로)        CAGR 33.98% · MDD −9.50% · 칼마 3.579 · 샤프 2.124 · 평균노출 0.597
    #     ★ 하위1/3 −25%(채택)     CAGR 32.55% · MDD **−8.68%** · 칼마 **3.750** · 샤프 2.167 · 평균노출 0.555
    #     같은 개수 무작위 대조군 150회: 칼마 중앙 3.468 · 상위5% 3.734 → ★ 백분위 **칼마 97 · CAGR 99 · 샤프 99**
    #     반증(상위 1/3을 대신 깎음): 칼마 3.193 · CAGR 30.32% ← 규칙보다 나쁘다(방향이 맞다)
    #   ⚠⚠ 정직한 비용(사용자 규칙 7 — 숨기지 않는다):
    #     ① **CAGR가 1.43%p 줄어든다**(33.98 → 32.55). 수용기준 ①(CAGR 손실 없음)은 **통과하지 못한다**.
    #     ② 연도별로 규칙이 이긴 해는 **4/9**다(2020 −6.2%p · 2026 −5.6%p가 가장 큰 손실).
    #     ③ 그럼에도 채택하는 이유: 사용자 지시가 '섹터 자율'을 **설계 요구**로 명시했고, 이 규칙은
    #        칼마(이 프로젝트의 대표 지표) 정점이며 MDD가 좋아지고 무작위·반증 대조를 모두 통과한다.
    #     되돌리기: s_overrides={"SECTOR_SELF_CUT_ENABLE": False} ⇒ v0.61.2와 **비트 동일**.
    #   ⚠ 룩어헤드 없음: composite는 워크포워드 선택된 신호의 그날 값이고, 횡단면 순위는 그날 정보만 쓴다.
    #   ⚠ 다른 격자와의 관계: 이 컷은 **마지막에 ★에만** 적용한다. 그래서 [자기근거격자]의 'OFF' 행이 곧
    #     v0.61.2 라이브이고, 다른 격자 행들은 컷 이전 기준으로 서로 비교된다(격자별로 한 번에 한 가지만 바뀐다).
    _sc_diag: Dict[str, Any] = {"enabled": False}
    if bool(getattr(scfg, "SECTOR_SELF_CUT_ENABLE", False)) and label_primary in target_ws:
        try:
            _q = float(getattr(scfg, "SECTOR_SELF_CUT_Q", 1.0 / 3.0))
            _f = float(getattr(scfg, "SECTOR_SELF_CUT_FRAC", 0.25))
            _base_sc = target_ws[label_primary]
            _seccols = [c for c in cols if c in _base_sc.columns]          # SPY 폴백 다리는 대상이 아니다
            _pctl = composite[_seccols].rank(axis=1, pct=True)             # 1.0 = 그날 최고 점수

            def _weak_mask(qq: float) -> pd.DataFrame:
                """그날 보유 중이면서 복합점수 횡단면 하위 qq 분위인 섹터(SPY 제외)."""
                m = pd.DataFrame(False, index=_base_sc.index, columns=_base_sc.columns)
                mm = (_pctl <= float(qq)) & _pctl.notna()
                #   ⚠ reindex가 NaN을 넣으면 object dtype이 되어 pandas 미래 버전에서 fillna 동작이 바뀐다
                #     (Kaggle의 pandas가 이 환경보다 최신일 수 있다) — 명시적으로 bool로 굳힌다.
                m[_seccols] = mm.reindex(index=_base_sc.index, columns=_seccols).fillna(False).astype(bool)
                return m & (_base_sc > 1e-9)

            def _apply_cut(qq: float, ff: float, mask: Optional[pd.DataFrame] = None) -> pd.DataFrame:
                m = _weak_mask(qq) if mask is None else mask
                return _base_sc.mask(m, _base_sc * (1.0 - float(ff)))

            def _rand_same(mask: pd.DataFrame, seed: int) -> pd.DataFrame:
                """날마다 **같은 개수**의 보유 섹터를 무작위로 고른다 — 선택에 정보가 있는지 재는 대조군.
                (칸수가 다른 대조군은 노출 차이를 정보로 착각하게 만든다 — R80에서 실제로 한 번 속았다.)"""
                rng = np.random.default_rng(int(seed))
                held = (_base_sc[_seccols] > 1e-9).values
                kk = mask[_seccols].values.sum(axis=1)
                out = np.zeros((len(_base_sc), len(_seccols)), dtype=bool)
                for i in range(len(_base_sc)):
                    h = np.flatnonzero(held[i])
                    k = int(kk[i])
                    if k and len(h):
                        out[i, rng.choice(h, size=min(k, len(h)), replace=False)] = True
                m = pd.DataFrame(False, index=_base_sc.index, columns=_base_sc.columns)
                m[_seccols] = out
                return m
            _m_live = _weak_mask(_q)
            _w_live = _apply_cut(_q, _f, _m_live)
            # [자기근거격자] — OFF(= v0.61.2 라이브) · 다른 폭/범위 · 반증 · 무작위 대조군
            _sc_grid: Dict[str, pd.DataFrame] = {
                "주력섹터 중심 · 섹터 자기근거 컷 OFF(v0.61.2 라이브) [자기근거격자]": _base_sc}
            for _qq, _qn in ((0.25, "하위1/4"), (1.0 / 3.0, "하위1/3"), (0.5, "하위1/2")):
                for _ff in (0.25, 0.50, 1.00):
                    if abs(_qq - _q) < 1e-9 and abs(_ff - _f) < 1e-9:
                        continue                                    # 라이브는 ★ 행이 이미 있다
                    _sc_grid[f"주력섹터 중심 · 자기근거 컷 {_qn} −{_ff:.0%} [자기근거격자]"] = _apply_cut(_qq, _ff)
            _sc_grid[f"주력섹터 중심 · 반증: 상위 1/3을 대신 −{_f:.0%} [자기근거격자·반증]"] = \
                _base_sc.mask((_pctl.reindex(index=_base_sc.index, columns=_seccols) > 1.0 - _q)
                              .reindex(columns=_base_sc.columns).fillna(False).astype(bool) & (_base_sc > 1e-9),
                              _base_sc * (1.0 - _f))
            _nctrl = int(getattr(scfg, "SECTOR_SELF_CUT_CONTROLS", 0) or 0)
            _ctrl_lbls: List[str] = []
            for _k in range(_nctrl):
                _lbl_c = f"주력섹터 중심 · 대조군{_k}: 같은 개수 무작위 −{_f:.0%} [자기근거격자·대조]"
                _sc_grid[_lbl_c] = _apply_cut(_q, _f, _rand_same(_m_live, int(getattr(scfg, "SECTOR_SELF_CUT_SEED", 20260921)) + _k))
                _ctrl_lbls.append(_lbl_c)
            for _lab, _fr in _sc_grid.items():
                _fr = _fr.fillna(0.0).clip(lower=0.0)
                target_ws[_lab] = _fr
                bts[_lab] = portfolio_backtest(_fr, ret_co, ret_oc, **bt_kw)
                variants[_lab] = _fr
            # ★ 라이브 교체 — 여기서부터 ★는 '자기근거 컷'이 들어간 비중이다
            target_ws[label_primary] = _w_live
            variants[label_primary] = _w_live
            bts[label_primary] = portfolio_backtest(_w_live, ret_co, ret_oc, **bt_kw)
            label_primary_new = label_primary + f" · 섹터자기근거컷 하위{_q:.0%} −{_f:.0%}"

            def _rename_key(d: dict, old_k: str, new_k: str) -> None:
                """★ 라벨만 바꾼다 — **순서를 보존**해야 13 성과표에서 ★가 첫 행으로 남는다
                (pop 후 대입하면 맨 뒤로 밀린다 — 리뷰에서 잡은 결함)."""
                items = [((new_k if k == old_k else k), v) for k, v in d.items()]
                d.clear()
                d.update(items)
            for _d in (target_ws, variants, bts):
                _rename_key(_d, label_primary, label_primary_new)
            label_primary = label_primary_new
            #   반환 dict의 frac_w(= E_t 대비 분수)도 같은 컷을 받아야 target_w와 어긋나지 않는다.
            #   (지금은 소비처가 없지만, 어긋난 값을 반환해 두면 다음 라운드가 그것을 믿고 틀린다.)
            try:
                if isinstance(frac_primary, pd.DataFrame) and len(frac_primary):
                    _fm = _m_live.reindex(index=frac_primary.index,
                                          columns=frac_primary.columns).fillna(False).astype(bool)
                    frac_primary = frac_primary.mask(_fm, frac_primary * (1.0 - _f))
            except Exception as _e2:
                log("ROTATION", kv(event="self_cut_frac_sync_failed", err=type(_e2).__name__,
                                   note="frac_w만 동기화 실패 — target_w(라이브)는 정상"), M=M, level="warning")
            _e0 = float(_base_sc.sum(axis=1).mean()); _e1 = float(_w_live.sum(axis=1).mean())
            _sc_diag = {"enabled": True, "q": _q, "frac": _f, "controls": _nctrl,
                        "control_labels": _ctrl_lbls,
                        "cut_cells_per_day": round(float(_m_live[_seccols].sum(axis=1).mean()), 3),
                        "held_per_day": round(float((_base_sc[_seccols] > 1e-9).sum(axis=1).mean()), 3),
                        "cut_days": int((_m_live.sum(axis=1) > 0).sum()),
                        "mean_exposure_before": round(_e0, 4), "mean_exposure_after": round(_e1, 4),
                        "label_off": "주력섹터 중심 · 섹터 자기근거 컷 OFF(v0.61.2 라이브) [자기근거격자]"}
            log("ROTATION", kv(event="sector_self_cut_applied", q=_q, frac=_f,
                               cut_days=_sc_diag["cut_days"], cells_per_day=_sc_diag["cut_cells_per_day"],
                               held_per_day=_sc_diag["held_per_day"], grid_rows=len(_sc_grid),
                               controls=_nctrl,
                               mean_exposure=f"{_e0:.4f}→{_e1:.4f}",
                               note="⚠ 위험 파라미터(노출) 변경 — 섹터 자기 근거로 E_t보다 **적게** 든다(위로는 안 넘는다). "
                                    "되돌리기 s_overrides={'SECTOR_SELF_CUT_ENABLE': False}"), M=M)
        except Exception as _e:
            log("ROTATION", kv(event="sector_self_cut_failed", err=type(_e).__name__, msg=str(_e)[:180],
                               action="컷 없이 계속(v0.61.2와 동일) — 00 시트에 실패를 적는다"), M=M, level="warning")
            _sc_diag = {"enabled": False, "error": f"{type(_e).__name__}: {str(_e)[:160]}"}

    # ---- [v0.67.0 R85 ★★★ 라이브 · ⚠ 위험 파라미터(노출)] 섹터 자기 근거 부분채움 + [섹터근거격자] + 장기 검증 ----
    #   사용자 지시(2026-09-22): "시장 국면은 냅둬 … 시장 국면은 그냥 참고만 하고 섹터별 상승, 하락 근거 따로 찾으라고 했잖아",
    #     "그렇게 수정해봐". 시작 v0.66.0 → 목표 v0.67.0.
    #   규칙(라이브): M이 예산을 **일부만** 준 날(0 < E_t < 1 — 부분예산일, 2018-11~ 692일 중 약 634일 발동),
    #     남는 현금의 OWN_EVIDENCE_FILL(25%)을 '상승 근거' 섹터 상위 2개(주력 XLK 제외 · 63일 상대수익 순)로 채운다.
    #     상승 근거 = 자기 국면기계 상승 & 자기 추세 상승(총수익 지수 > 200일선 & > 50일선) & 상대 추세 상승(섹터/섹터평균 > 50일선).
    #     기존 ★ 비중은 한 칸도 줄이지 않는다(위로만 더한다) · 합계 ≤ 1.0 · E_t=0·E_t=1인 날은 무변경.
    #   ⚠ 이것은 **노출을 늘리는 위험 파라미터 변경**이다: 부분예산일 평균 총비중 0.496 → 0.603(오프라인 하네스).
    #     되돌리기: s_overrides={"OWN_EVIDENCE_FILL": 0.0} ⇒ v0.66.0 ★와 **비트 동일**(격자의 OFF 행이 그 값이다).
    #   오프라인 하네스(r85/eng85b.py · 엔진 정의 = 총수익 지수 · 2018-11~ · ★ 10.541배 · MDD −8.57% · 칼마 4.080):
    #     채움 25%(라이브) 10.795배 · MDD −8.57% · 칼마 4.128 | 50% 11.032 · 4.171 | 75% 11.260 · 4.213 | 100% 11.475 · −8.88% · 4.102
    #     같은 날·같은 몫 무작위 2섹터(자기 국면 상승 중) 40회 칼마 95% 4.033 → 백분위 100 | 같은 몫 균등(근거 없음) 10.602 · 4.091
    #     엔진 창(2018-01~) 근사: 11.279 → 11.552(+2.4%) · 칼마 3.665 → 3.707 · MDD 동일 · OFF 대비 초과 +0.34%p/년(상위 5일 제외 +0.06)
    #     I★(r85/iprop85.py 근사 — 새 섹터 몫은 부모 ETF로): 25% 12.486 → 12.763 · MDD −9.01 → −9.10% · 칼마 4.208 → 4.208
    #                                                       50% → 13.019 · MDD −9.53% · 칼마 4.054 ← 50%를 고르지 않은 이유
    #   ⚠⚠ 정직한 한계(숨기지 않는다 — 사용자 규칙 7):
    #     ① 정지 블록 부트스트랩(21일 · 2000회 · 25%): P(배수↑) 0.76 · **P(칼마↑) 0.42** · MDD 악화 중앙 −0.17%p · 하위 5% −1.03%p.
    #        표본 안 MDD가 그대로인 것은 최대낙폭 구간(2019-05 · E_t=1)에 규칙이 닿지 않아서다 — 운이 섞여 있다.
    #     ② 연도별 4/8해만 이긴다(2021 +3.6%p · 2024 +1.3%p ↔ 2025 −2.4%p · 2020 −0.9%p). 2023~ 칼마는 5.22 → 5.18.
    #     ③ 독립 구간(FF 12업종 월간 · M 대용 3상태 · r85/ff85.py): 채움은 두 시대 모두 배수를 올리지만(1950~98 253→313 ·
    #        1999~2017 4.24→4.42), 선택(상위 업종) 대 무작위는 1950~98 백분위 88 · **1999~2017 백분위 7**.
    #     ⇒ R84 사전등록 4조건(하네스): (i) 칼마 +0.048 — **한 끗 미달** · (ii) 대조군 95% 초과 통과 · (iii) 상위 5일 제외 초과 +0.06 통과(얇다)
    #        · (iv) MDD 동일 통과. 이번 라이브 전환의 근거는 '사용자의 명시적 설계 지시 + S·I 두 층 배수↑·MDD 불변 + 무작위 선택 대비
    #        백분위 100'이다 — 통계적 확신이 아니다. 그래서 아래 되돌림 조건을 사전등록한다.
    #   ⚠ 사전등록(R85 → 다음 리포트, 엔진 값으로 판정): 아래 넷 중 하나라도 해당하면 **되돌린다**(OWN_EVIDENCE_FILL=0).
    #     (a) 엔진 ★ 칼마 < OFF 행 칼마 (b) ★ 칼마 ≤ 같은 날·같은 몫 무작위 대조군 95% (c) ★ MDD가 OFF보다 0.5%p 넘게 나쁨
    #     (d) 장기 검증 2000~2017에서 '② 상승 근거 채움'이 '① 같은 몫 SPY'와 대조군 95%를 **둘 다** 못 이김.
    #     (e) I★ MDD가 I 리포트 [섹터근거전달] OFF 행보다 0.5%p 넘게 악화.
    #   ⚠ 다른 격자와의 관계: 이 채움은 R81 자기근거 컷과 같이 **마지막에 ★에만** 적용한다. [섹터근거격자]의 OFF 행이 곧 v0.66.0 ★이고,
    #     이 블록 **앞**에서 만든 격자 행들(상한·베타·방어대피처·하락리더 …)은 채움 이전 기준으로 서로 비교된다.
    #     이 블록 **뒤**의 [모멘텀연결격자]는 새 ★(채움 포함)를 기준으로 잰다.
    #   룩어헤드 없음: 지표는 전부 t일 종가까지(롤링·shift는 과거 방향), 비중은 t일 목표 → portfolio_backtest가 t+1 시가 체결.
    _own_diag: Dict[str, Any] = {"enabled": False}
    target_w_off = None
    if bool(getattr(scfg, "OWN_EVIDENCE_ENABLE", True)) and label_primary in target_ws:
        try:
            _to0 = time.time()
            _pri_o = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "XLK")
            _base_o = target_ws[label_primary].copy()
            _seco = [c for c in cols if c in _base_o.columns and c in ret_cc_full.columns]
            _rcf_o = ret_cc_full[_seco]
            _lvl_full = (1.0 + _rcf_o.fillna(0.0)).cumprod().where(_rcf_o.notna())
            _st_full = pd.DataFrame({t: pd.Series(results[t].get("state_full") if results[t].get("state_full") is not None
                                                  else results[t].get("state")).reindex(full_idx) for t in _seco})
            _nl_o = int(getattr(scfg, "OWN_EVIDENCE_N_LONG", 200)); _ns_o = int(getattr(scfg, "OWN_EVIDENCE_N_SHORT", 50))
            _nr_o = int(getattr(scfg, "OWN_EVIDENCE_N_REL", 50)); _nrs_o = int(getattr(scfg, "OWN_EVIDENCE_N_RS", 63))
            _fr_full = own_evidence_frames(_lvl_full, _st_full, _nl_o, _ns_o, _nr_o, _nrs_o)
            _fr = {_k: _v.reindex(eval_idx) for _k, _v in _fr_full.items()}
            _Ev = E.reindex(eval_idx).fillna(0.0).astype(float)
            _part = (_Ev > 1e-12) & (_Ev < 1.0 - 1e-12)
            _on = _Ev > 1e-12
            _f_live = float(getattr(scfg, "OWN_EVIDENCE_FILL", 0.0) or 0.0)
            _f_live = min(max(_f_live, 0.0), 1.0)
            _k_o = max(1, int(getattr(scfg, "OWN_EVIDENCE_FILL_K", 2) or 2))
            _fcmp = _f_live if _f_live > 0 else 0.5
            target_w_off = _base_o
            log("OWN", kv(event="evidence_ready", sectors=len(_seco), primary=_pri_o, n_long=_nl_o, n_short=_ns_o,
                          n_rel=_nr_o, n_rs=_nrs_o, state_full=all(results[t].get("state_full") is not None for t in _seco),
                          partial_days=int(_part.sum()), on_days=int(_on.sum()),
                          cand_per_day=round(float(_fr["cand"][_seco].sum(axis=1)[_part].mean()), 3) if bool(_part.any()) else 0,
                          first_cand=str(_fr_full["cand"].any(axis=1).idxmax().date()) if bool(_fr_full["cand"].any(axis=1).any()) else "-"),
                M=M)
            _grid_o: Dict[str, pd.DataFrame] = {}
            _lab_off = "주력섹터 중심 · 섹터근거 채움 OFF(v0.66.0 ★) [섹터근거격자]"
            _grid_o[_lab_off] = _base_o
            for _fv in tuple(getattr(scfg, "OWN_EVIDENCE_GRID_FILLS", (0.25, 0.5, 0.75, 1.0)) or ()):
                if abs(float(_fv) - _f_live) < 1e-9:
                    continue                                     # 라이브는 ★ 행이 이미 있다
                _grid_o[f"주력섹터 중심 · 섹터근거 채움 {float(_fv):.0%}(상위{_k_o}) [섹터근거격자]"] = \
                    own_evidence_fill(_base_o, _fr, _seco, _pri_o, _part, float(_fv), _k_o)[0]
            _lst = _lvl_full.reindex(eval_idx)[_seco].notna()
            _eqm = _lst.copy()
            if _pri_o in _eqm.columns:
                _eqm[_pri_o] = False
            _eqw = _eqm.astype(float).div(_eqm.sum(axis=1).replace(0, np.nan), axis=0).fillna(0.0)
            _lab_eq = f"주력섹터 중심 · [비교] 채움 {_fcmp:.0%} → 주력 외 균등(근거 없음) [섹터근거격자]"
            _grid_o[_lab_eq] = own_evidence_fill(_base_o, _fr, _seco, _pri_o, _part, _fcmp, _k_o, sel=_eqw)[0]
            _w_sw, _m_sw = own_evidence_swap(_base_o, _fr, _seco, _pri_o, _on)
            _lab_sw = "주력섹터 중심 · 하락근거 교체(대피처 200일선 아래 → 상승근거 1위 · 노출 불변) [섹터근거격자·진단]"
            _grid_o[_lab_sw] = _w_sw
            _nctl_o = int(getattr(scfg, "OWN_EVIDENCE_CONTROLS", 12) or 0)
            _seed_o = int(getattr(scfg, "OWN_EVIDENCE_SEED", 20260923))
            _pool_o = (_fr["st_up"][_seco].fillna(False).astype(bool) & _lst).copy()
            if _pri_o in _pool_o.columns:
                _pool_o[_pri_o] = False
            _ctrl_o: List[str] = []
            for _j in range(_nctl_o):
                _lbl_c = f"주력섹터 중심 · 대조군{_j}: 같은 날·같은 몫 무작위 {_k_o}섹터 [섹터근거격자·대조]"
                _grid_o[_lbl_c] = own_evidence_fill(_base_o, _fr, _seco, _pri_o, _part, _fcmp, _k_o,
                                                    sel=_own_rand_sel(_pool_o, _k_o, _seed_o + _j))[0]
                _ctrl_o.append(_lbl_c)
            for _lab, _fw in _grid_o.items():
                _fw = _fw.fillna(0.0).clip(lower=0.0)
                target_ws[_lab] = _fw
                bts[_lab] = portfolio_backtest(_fw, ret_co, ret_oc, **bt_kw)
                variants[_lab] = _fw

            def _cal_o(_b: pd.DataFrame) -> Tuple[float, float, float, float]:
                _r = pd.to_numeric(_b["strategy_ret"], errors="coerce").fillna(0.0)
                _eq = (1.0 + _r).cumprod()
                _cg = float(_eq.iloc[-1] ** (252.0 / max(len(_r), 1)) - 1.0)
                _md = float((_eq / _eq.cummax() - 1.0).min())
                return _cg, _md, (_cg / abs(_md) if _md < 0 else np.nan), float(_eq.iloc[-1])
            _cg_off, _md_off, _cm_off, _mu_off = _cal_o(bts[_lab_off])
            _add_live = pd.Series(0.0, index=eval_idx)
            _sel_live_cnt: Dict[str, int] = {}
            if _f_live > 0:
                _w_live_o, _add_live = own_evidence_fill(_base_o, _fr, _seco, _pri_o, _part, _f_live, _k_o)
                _w_live_o = _w_live_o.fillna(0.0).clip(lower=0.0)
                _dw = (_w_live_o[_seco] - _base_o[_seco].fillna(0.0)) > 1e-12
                _sel_live_cnt = {c: int(_dw[c].sum()) for c in _seco if int(_dw[c].sum()) > 0}
                target_ws[label_primary] = _w_live_o
                variants[label_primary] = _w_live_o
                bts[label_primary] = portfolio_backtest(_w_live_o, ret_co, ret_oc, **bt_kw)
                #   ⚠ 라벨은 **'★'로 끝나야 한다** — S(10712·10798·14113·14446)·I(star_label)가 endswith("★")로 ★ 행을 찾는다.
                _lp_new = (label_primary[:-1].rstrip() if label_primary.endswith("★") else label_primary) \
                    + f" · 섹터근거 부분채움 {_f_live:.0%} ★"

                def _rename_o(d: dict, old_k: str, new_k: str) -> None:
                    """★ 라벨만 바꾼다 — 순서 보존(13 성과표에서 ★가 첫 행으로 남아야 한다)."""
                    items = [((new_k if k_ == old_k else k_), v_) for k_, v_ in d.items()]
                    d.clear()
                    d.update(items)
                for _d_ in (target_ws, variants, bts):
                    _rename_o(_d_, label_primary, _lp_new)
                label_primary = _lp_new
                #   반환 frac_w(= E_t 대비 분수)도 같은 채움을 받아야 target_w와 어긋나지 않는다(E_t>0인 부분예산일만).
                try:
                    if isinstance(frac_primary, pd.DataFrame) and len(frac_primary):
                        _pe = _part & (_add_live > 0)
                        _cc = [c for c in _seco if c in frac_primary.columns]
                        frac_primary = frac_primary.copy()
                        frac_primary.loc[_pe.values, _cc] = (_w_live_o.loc[_pe.values, _cc]
                                                             .div(_Ev[_pe].values, axis=0)).values
                except Exception as _e3:
                    log("OWN", kv(event="frac_sync_failed", err=type(_e3).__name__,
                                  note="frac_w만 동기화 실패 — target_w(라이브)는 정상"), M=M, level="warning")
            _cg_l, _md_l, _cm_l, _mu_l = _cal_o(bts[label_primary])
            _ctl_cm = np.asarray([_cal_o(bts[l_])[2] for l_ in _ctrl_o], dtype=float)
            _ctl_cm = _ctl_cm[_ctl_cm == _ctl_cm]
            _q95_o = float(np.quantile(_ctl_cm, 0.95)) if len(_ctl_cm) else np.nan
            _pct_o = float((_ctl_cm < _cm_l).mean() * 100.0) if len(_ctl_cm) else np.nan
            _ex_o = (pd.to_numeric(bts[label_primary]["strategy_ret"], errors="coerce")
                     - pd.to_numeric(bts[_lab_off]["strategy_ret"], errors="coerce")).dropna()
            _ann_o = 252.0 / max(len(_ex_o), 1) * 100.0
            _ex_tot = float(_ex_o.sum()) * _ann_o
            _ex_cut = float(_ex_o.sum() - _ex_o.sort_values(ascending=False).iloc[:5].sum()) * _ann_o if len(_ex_o) > 5 else np.nan
            _crit = {"(i) 칼마 ≥ OFF+0.05": bool(_cm_l == _cm_l and _cm_l >= _cm_off + 0.05),
                     "(ii) 대조군 95% 초과": bool(len(_ctl_cm) and _cm_l > _q95_o),
                     "(iii) 강건성(상위5일 제외 초과 > 0)": bool(_ex_tot > 0 and _ex_cut == _ex_cut and _ex_cut > 0),
                     "(iv) MDD 악화 ≤ 0.5%p": bool(_md_l >= _md_off - 0.005)}
            _revert = bool((_cm_l == _cm_l and _cm_l < _cm_off) or not _crit["(ii) 대조군 95% 초과"]
                           or not _crit["(iv) MDD 악화 ≤ 0.5%p"])
            _rows_o = []
            for _lab in [label_primary] + list(_grid_o.keys()):
                _cg_, _md_, _cm_, _mu_ = _cal_o(bts[_lab])
                _rows_o.append({"변형": _lab, "배수": round(_mu_, 3), "CAGR": round(_cg_, 4), "MDD": round(_md_, 4),
                                "칼마": round(_cm_, 3) if _cm_ == _cm_ else np.nan,
                                "평균노출": round(float(bts[_lab]["exposure"].mean()), 4),
                                "부분예산일 평균노출": round(float(bts[_lab]["exposure"].shift(-1).reindex(eval_idx)[_part].mean()), 4)
                                if bool(_part.any()) else np.nan})
            _own_diag = {"enabled": True, "fill": _f_live, "k": _k_o, "primary": _pri_o, "label_off": _lab_off,
                         "label_live": label_primary, "label_eq": _lab_eq, "label_swap": _lab_sw,
                         "control_labels": _ctrl_o, "controls": len(_ctrl_o), "seed": _seed_o,
                         "fill_days": int((_add_live > 0).sum()), "partial_days": int(_part.sum()),
                         "mean_add": round(float(_add_live[_add_live > 0].mean()), 4) if bool((_add_live > 0).any()) else 0.0,
                         "picked": _sel_live_cnt, "swap_days": int(_m_sw.any(axis=1).sum()),
                         "off": {"배수": _mu_off, "CAGR": _cg_off, "MDD": _md_off, "칼마": _cm_off},
                         "live": {"배수": _mu_l, "CAGR": _cg_l, "MDD": _md_l, "칼마": _cm_l},
                         "ctl_q95": _q95_o, "ctl_median": (float(np.median(_ctl_cm)) if len(_ctl_cm) else np.nan),
                         "pctile": _pct_o, "excess_ann": round(_ex_tot, 3), "excess_ann_ex5": (round(_ex_cut, 3) if _ex_cut == _ex_cut else np.nan),
                         "criteria": _crit, "revert_next": _revert, "rows": _rows_o}
            log("OWN", kv(event="fill_applied" if _f_live > 0 else "fill_off", fill=_f_live, k=_k_o,
                          fill_days=_own_diag["fill_days"], partial_days=_own_diag["partial_days"],
                          mean_add=_own_diag["mean_add"], picked=";".join(f"{a}:{b}" for a, b in sorted(_sel_live_cnt.items())) or "-",
                          mult=f"{_mu_off:.3f}→{_mu_l:.3f}", calmar=f"{_cm_off:.3f}→{_cm_l:.3f}",
                          mdd=f"{_md_off * 100:.2f}→{_md_l * 100:.2f}", cagr=f"{_cg_off * 100:.2f}→{_cg_l * 100:.2f}",
                          ctl_q95=round(_q95_o, 3) if _q95_o == _q95_o else None,
                          pctile=round(_pct_o, 1) if _pct_o == _pct_o else None,
                          crit="|".join(f"{k_}={'O' if v_ else 'X'}" for k_, v_ in _crit.items()),
                          revert_next=_revert, grid_rows=len(_grid_o), sec=round(time.time() - _to0, 1),
                          note="⚠ 위험 파라미터(노출↑) — 되돌리기 s_overrides={'OWN_EVIDENCE_FILL': 0.0}"), M=M)
            if _revert and _f_live > 0:
                log("OWN", kv(event="prereg_revert_condition_met", calmar_live=round(_cm_l, 3), calmar_off=round(_cm_off, 3),
                              ctl_q95=round(_q95_o, 3) if _q95_o == _q95_o else None,
                              next_step="사전등록(R85)에 따라 다음 라운드에 OWN_EVIDENCE_FILL=0.0으로 되돌린다 — 이번 실행 ★는 그대로 둔다"),
                    M=M, level="warning")
            if bool(getattr(scfg, "OWN_EVIDENCE_LONG_AUDIT", True)):
                try:
                    #   ⚠ SPY 수익은 M의 bt(평가창 2018~만)가 아니라 **px_adj 전체 이력**에서 — 합성 E2E에서 bt["ret_cc"]가
                    #     2018 이전 NaN이라 2000~2017 'M 단독'이 현금만 번 것으로 나왔다(r85 합성 실행에서 잡음).
                    _pxa = res.get("px_adj") if isinstance(res, dict) else None
                    _spy_long = (pd.Series(_pxa).astype(float).pct_change(fill_method=None).reindex(full_idx)
                                 if _pxa is not None and len(pd.Series(_pxa).dropna()) > 300 else spy_cc_full)
                    #   ⚠ 국면기계 상태는 2018 이전엔 추세필터 폴백(TREND_ONLY_*)뿐이라 RISK_ON이 없다(합성 실행 실측) —
                    #     장기 검증은 기본으로 **상태 조건 없이**(자기 추세 & 상대 추세만) 잰다. OWN_EVIDENCE_LONG_USE_STATE=True면 상태 포함.
                    _st_long = _st_full if bool(getattr(scfg, "OWN_EVIDENCE_LONG_USE_STATE", False)) else None
                    _own_diag["long"] = own_long_audit(_lvl_full, _st_long, E_full, _spy_long, rf_daily, scfg,
                                                       cost_bps=float(res["cfg"].COST_BPS), M=M,
                                                       spy_level=(pd.Series(_pxa).reindex(full_idx) if _pxa is not None else None))
                except Exception as _e4:
                    log("OWN", kv(event="long_audit_failed", err=type(_e4).__name__, msg=str(_e4)[:160],
                                  trace=traceback.format_exc()[-300:].replace("\n", " | "),
                                  action="장기 검증만 생략 — ★는 영향 없음"), M=M, level="warning")
                    _own_diag["long"] = {"enabled": False, "error": f"{type(_e4).__name__}: {str(_e4)[:160]}"}
        except Exception as _e:
            log("OWN", kv(event="own_evidence_failed", err=type(_e).__name__, msg=str(_e)[:180],
                          trace=traceback.format_exc()[-400:].replace("\n", " | "),
                          action="섹터근거 블록 생략 — ★가 이미 교체됐다면 그대로, 아니면 v0.66.0 ★"), M=M, level="warning")
            _own_diag = {"enabled": False, "error": f"{type(_e).__name__}: {str(_e)[:160]}"}

    # ---- [v0.68.0 R86 ★★ 측정 전용] [섹터거시근거격자] — 섹터 고유 경제 동인(유가·구리·금리·신용)으로 '국면을 안 따라가는 섹터' ----
    #   사용자 지시(2026-09-22): "섹터별로 시장 국면별로 안따라갈때도 있잖아 … 섹터별 상승, 하락 근거 따로 찾으라고",
    #     "신뢰도는 내가 얘기했던 방법(하락 잘 피하고 상승 잘 타는 것)". 시작 v0.67.0 → 목표 v0.68.0.
    #   R85 판정(엔진 s14): 섹터 **가격** 근거(자기 추세·상대 추세·국면기계)는 2000~2017 독립 구간에서 SPY·무작위보다 나빴다 →
    #     R85 채움은 사전등록 (d)로 되돌렸다(OWN_EVIDENCE_FILL 0.25 → 0.0). 남은 '섹터별 근거'는 경제 동인이다 — 여기서 처음 잰다.
    #   행(★ 기준 · 한 번에 한 가지만 바꾼다):
    #     G1 하락국면리더(E_t=0) — 리더 섹터가 거시 **역풍/동인 없음**이면 들지 않는다(현금)
    #     G2 E_t=0일 — 리더 대신 '거시 순풍 & 자기 추세 상승' 섹터 1위(63일 상대수익) × 0.25(없으면 현금)
    #     G3 부분예산일(0<E_t<1) — 남는 현금 25%를 '거시 순풍 & 자기 추세 상승' 상위 2(주력 제외)로
    #     G4 E_t>0일 — 주력 외 보유 섹터가 거시 역풍이면 '거시 순풍 & 자기 추세 상승' 1위(미보유)로 교체(노출 불변)
    #   G2·G3는 같은 날·같은 몫 무작위 섹터 대조군(자기 추세 상승 섹터 중) 12개와 비교한다. 장기 검증(macro_long_audit)이 G2·G3의
    #   독립 구간판(L2·L3)을 잰다. ⚠ 사전등록(R86 → 다음 리포트): G2 또는 G3를 라이브로 올리는 조건 —
    #     (1) 장기 검증 **두 구간 모두** Δ회피 ≥ −1%p · Δ참여 ≥ −1%p · Δ회피+Δ참여 ≥ +2%p · 칼마 > 무작위 대조군 95%
    #     (2) 평가창 ★ 변형: Δ회피+Δ참여 ≥ +2%p · MDD 악화 ≤ 0.5%p · 칼마 > 무작위 대조군 95%.
    #     G1·G4는 독립 구간판이 없어 **진단**이다(승격 불가). 엔진은 스스로 라이브를 바꾸지 않는다.
    #   룩어헤드 없음: 동인은 t일까지(FRED는 발표 지연만큼 더 늦춤) · 자기 추세는 t일 종가까지 · 비중은 t+1 시가 체결.
    _macro_diag: Dict[str, Any] = {"enabled": False}
    if bool(getattr(scfg, "MACRO_EVIDENCE_ENABLE", True)) and label_primary in target_ws:
        try:
            _tm0 = time.time()
            _pri_m = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "XLK")
            _base_m = target_ws[label_primary].copy()
            _secm = [c for c in cols if c in _base_m.columns and c in ret_cc_full.columns]
            _rcf_m = ret_cc_full[_secm]
            _lvl_m = (1.0 + _rcf_m.fillna(0.0)).cumprod().where(_rcf_m.notna())
            _tail_f, _head_f, _minfo = macro_driver_states(res, full_idx, _secm, scfg, M)
            _frm_f = own_evidence_frames(_lvl_m, None, int(getattr(scfg, "OWN_EVIDENCE_N_LONG", 200)),
                                         int(getattr(scfg, "OWN_EVIDENCE_N_SHORT", 50)), int(getattr(scfg, "OWN_EVIDENCE_N_REL", 50)),
                                         int(getattr(scfg, "OWN_EVIDENCE_N_RS", 63)))
            _tail = _tail_f.reindex(eval_idx).fillna(False).astype(bool)
            _head = _head_f.reindex(eval_idx).fillna(False).astype(bool)
            _own_up = _frm_f["own_up"].reindex(eval_idx).fillna(False).astype(bool)
            _rs_m = _frm_f["rs"].reindex(eval_idx)
            _candm = (_tail & _own_up)
            _Evm = E.reindex(eval_idx).fillna(0.0).astype(float)
            _offm = _Evm <= 1e-12
            _partm = (_Evm > 1e-12) & (_Evm < 1.0 - 1e-12)
            _onm = _Evm > 1e-12
            log("MACRO", kv(event="drivers_ready", sectors=len(_secm), lookback=int(getattr(scfg, "MACRO_LOOKBACK", 63)),
                            drivers=" | ".join(f"{k}:{v}" for k, v in _minfo.items())[:900],
                            cand_per_day=round(float(_candm.sum(axis=1).mean()), 3)), M=M)
            _gm: Dict[str, pd.DataFrame] = {}
            # G1 — 하락국면리더를 거시 순풍일 때만
            _dl = down_leader_days.reindex(eval_idx).fillna(False).astype(bool)
            _ls = leader_s.reindex(eval_idx)
            _okl = pd.Series([bool(_tail.at[d_, s_]) if isinstance(s_, str) and s_ in _tail.columns else False
                              for d_, s_ in _ls.items()], index=eval_idx)
            _w1 = _base_m.copy()
            _drop1 = _dl & ~_okl
            _w1.loc[_drop1.values, _secm] = 0.0
            _gm["주력섹터 중심 · G1 하락국면리더는 거시 순풍일 때만 [섹터거시근거격자·진단]"] = _w1
            # G2 — E_t=0일 거시 순풍 섹터 1위 × pos
            _pos_m = float(getattr(scfg, "MACRO_OFF_POS", 0.25) or 0.25)
            _sel1 = _own_top_by(_rs_m[_secm], _candm[_secm], 1)
            _w2 = _base_m.copy()
            _w2.loc[_offm.values, _secm] = 0.0
            _w2[_secm] = _w2[_secm].add(_sel1.mul(_pos_m * _offm.astype(float), axis=0), fill_value=0.0)
            _lab_g2 = f"주력섹터 중심 · G2 E_t=0일 거시 순풍 섹터 1위 {_pos_m:.0%}(리더 대체) [섹터거시근거격자]"
            _gm[_lab_g2] = _w2
            # G3 — 부분예산일 거시 순풍 채움
            _f_m = float(getattr(scfg, "MACRO_FILL", 0.25) or 0.25)
            _cm3 = _candm[_secm].copy()
            if _pri_m in _cm3.columns:
                _cm3[_pri_m] = False
            _sel3 = _own_top_by(_rs_m[_secm], _cm3, int(getattr(scfg, "OWN_EVIDENCE_FILL_K", 2) or 2))
            _w3, _add3 = own_evidence_fill(_base_m, {"cand": _cm3, "rs": _rs_m}, _secm, _pri_m, _partm, _f_m,
                                           int(getattr(scfg, "OWN_EVIDENCE_FILL_K", 2) or 2), sel=_sel3)
            _lab_g3 = f"주력섹터 중심 · G3 부분예산일 남는 현금 {_f_m:.0%} → 거시 순풍 상위2 [섹터거시근거격자]"
            _gm[_lab_g3] = _w3
            # G4 — 대피처 거시 역풍 교체(노출 불변)
            _w4, _m4 = own_evidence_swap(_base_m, {"own_dn": _head[_secm], "cand": _candm[_secm], "rs": _rs_m[_secm]},
                                         _secm, _pri_m, _onm)
            _gm["주력섹터 중심 · G4 대피처 거시 역풍 → 순풍 섹터로 교체(노출 불변) [섹터거시근거격자·진단]"] = _w4
            # 대조군(G2·G3 — 같은 날·같은 몫, 자기 추세 상승 섹터 중 무작위)
            _nctl_m = int(getattr(scfg, "MACRO_CONTROLS", 12) or 0)
            _seed_m = int(getattr(scfg, "MACRO_SEED", 20260924))
            _pool2 = _own_up[_secm].copy()
            _pool3 = _pool2.copy()
            if _pri_m in _pool3.columns:
                _pool3[_pri_m] = False
            _c2, _c3 = [], []
            _has1 = _sel1.sum(axis=1) > 0
            for _j in range(_nctl_m):
                _r1 = _own_rand_sel(_pool2, 1, _seed_m + _j).mul(_has1.astype(float), axis=0)
                _wc = _base_m.copy(); _wc.loc[_offm.values, _secm] = 0.0
                _wc[_secm] = _wc[_secm].add(_r1.mul(_pos_m * _offm.astype(float), axis=0), fill_value=0.0)
                _l = f"주력섹터 중심 · 대조군{_j}: G2 같은 날 무작위 섹터 [섹터거시근거격자·대조]"
                _gm[_l] = _wc; _c2.append(_l)
                _rk = _own_rand_sel(_pool3, int(getattr(scfg, "OWN_EVIDENCE_FILL_K", 2) or 2), _seed_m + 500 + _j)
                _rk = _rk.mul((_sel3.sum(axis=1) > 0).astype(float), axis=0)
                _l = f"주력섹터 중심 · 대조군{_j}: G3 같은 날·같은 몫 무작위 2섹터 [섹터거시근거격자·대조]"
                _gm[_l] = own_evidence_fill(_base_m, {"cand": _cm3, "rs": _rs_m}, _secm, _pri_m, _partm, _f_m, 2, sel=_rk)[0]
                _c3.append(_l)
            for _lab, _fw in _gm.items():
                _fw = _fw.fillna(0.0).clip(lower=0.0)
                target_ws[_lab] = _fw
                bts[_lab] = portfolio_backtest(_fw, ret_co, ret_oc, **bt_kw)
                variants[_lab] = _fw
            _spy_e = ((1.0 + ret_co["SPY"].fillna(0.0)) * (1.0 + ret_oc["SPY"].fillna(0.0)) - 1.0).reindex(eval_idx).fillna(0.0)
            _ur = user_rel_portfolio({l_: bts[l_]["strategy_ret"] for l_ in [label_primary] + list(_gm.keys())}, _spy_e, scfg)
            _uri = _ur.set_index("전략")
            _b = _uri.loc[label_primary]
            _rows_m = []
            _prereg_eval = {}
            for _lab in _gm:
                if "·대조]" in _lab:
                    continue
                _u = _uri.loc[_lab]
                _da = (float(_u["하락 회피율"]) - float(_b["하락 회피율"])) * 100.0
                _dp = (float(_u["상승 참여율"]) - float(_b["상승 참여율"])) * 100.0
                _cl = _c2 if "G2" in _lab else (_c3 if "G3" in _lab else [])
                _cc = np.asarray([float(_uri.loc[l_, "칼마"]) for l_ in _cl], dtype=float)
                _cc = _cc[_cc == _cc]
                _q95 = float(np.quantile(_cc, 0.95)) if len(_cc) else np.nan
                _ok = bool((_da + _dp) >= 2.0 and float(_u["MDD"]) >= float(_b["MDD"]) - 0.005
                           and len(_cc) and float(_u["칼마"]) > _q95)
                if "G2" in _lab or "G3" in _lab:
                    _prereg_eval["G2" if "G2" in _lab else "G3"] = _ok
                _rows_m.append({"변형": _lab, "하락 회피율": _u["하락 회피율"], "상승 참여율": _u["상승 참여율"],
                                "Δ회피(%p)": round(_da, 2), "Δ참여(%p)": round(_dp, 2), "등급": _u["등급"],
                                "배수": _u["배수"], "MDD": _u["MDD"], "칼마": _u["칼마"],
                                "대조군 칼마 95%": (round(_q95, 3) if _q95 == _q95 else np.nan),
                                "평가창 사전등록(2) 통과": (_ok if ("G2" in _lab or "G3" in _lab) else "진단")})
            _macro_diag = {"enabled": True, "drivers": _minfo, "rows": _rows_m, "base": {"하락 회피율": _b["하락 회피율"],
                           "상승 참여율": _b["상승 참여율"], "배수": _b["배수"], "MDD": _b["MDD"], "칼마": _b["칼마"]},
                           "prereg_eval": _prereg_eval, "controls": _nctl_m, "seed": _seed_m,
                           "g1_days_dropped": int(_drop1.sum()), "g1_leader_days": int(_dl.sum()),
                           "g2_days": int((_offm & _has1).sum()), "g3_days": int((_add3 > 0).sum()),
                           "g4_days": int(_m4.any(axis=1).sum())}
            for _r in _rows_m:
                log("MACRO", kv(event="grid_row", variant=str(_r["변형"])[:48], avoid=_r["하락 회피율"], part=_r["상승 참여율"],
                                d_avoid=_r["Δ회피(%p)"], d_part=_r["Δ참여(%p)"], mult=_r["배수"], mdd=_r["MDD"], calmar=_r["칼마"],
                                ctl_q95=_r["대조군 칼마 95%"], prereg=_r["평가창 사전등록(2) 통과"]), M=M)
            if bool(getattr(scfg, "MACRO_LONG_AUDIT", True)):
                try:
                    _pxa_m = res.get("px_adj") if isinstance(res, dict) else None
                    _spy_lm = (pd.Series(_pxa_m).astype(float).pct_change(fill_method=None).reindex(full_idx)
                               if _pxa_m is not None and len(pd.Series(_pxa_m).dropna()) > 300 else spy_cc_full)
                    _macro_diag["long"] = macro_long_audit(_lvl_m, E_full, _spy_lm,
                                                           (pd.Series(_pxa_m).reindex(full_idx) if _pxa_m is not None else None),
                                                           _tail_f, rf_daily, scfg, cost_bps=float(res["cfg"].COST_BPS), M=M)
                except Exception as _e5:
                    log("MACRO", kv(event="long_audit_failed", err=type(_e5).__name__, msg=str(_e5)[:160],
                                    trace=traceback.format_exc()[-300:].replace("\n", " | "), action="장기 검증만 생략"), M=M,
                        level="warning")
                    _macro_diag["long"] = {"enabled": False, "error": f"{type(_e5).__name__}: {str(_e5)[:160]}"}
            _lv = (_macro_diag.get("long") or {}).get("verdict") or {}
            _macro_diag["promote"] = {g: bool(_prereg_eval.get(g) and (_lv.get("L" + g[1:]) or {}).get("pass")) for g in ("G2", "G3")}
            log("MACRO", kv(event="grid_done", rows=len(_rows_m), controls=_nctl_m, seed=_seed_m,
                            g1_dropped=_macro_diag["g1_days_dropped"], g2_days=_macro_diag["g2_days"],
                            g3_days=_macro_diag["g3_days"], g4_days=_macro_diag["g4_days"],
                            promote=";".join(f"{k}={v}" for k, v in _macro_diag["promote"].items()),
                            sec=round(time.time() - _tm0, 1), note="측정 전용 — ★(라이브) 무변경"), M=M)
        except Exception as _e:
            log("MACRO", kv(event="macro_grid_failed", err=type(_e).__name__, msg=str(_e)[:180],
                            trace=traceback.format_exc()[-400:].replace("\n", " | "), action="격자만 생략 — ★ 무영향"),
                M=M, level="warning")
            _macro_diag = {"enabled": False, "error": f"{type(_e).__name__}: {str(_e)[:160]}"}

    # ---- [v0.66.0 R84 ★★ 신규 · 측정 전용] [모멘텀연결격자] — '예측을 배분에 넣으면 노란색(★) 성과가 나아지나' ----
    #   사용자 질문(2026-09-22): "고치고 있는거 맞아? 왜 노란색 표시된 수익배수는 그대로야".
    #   답: R82·R83은 신뢰도 **측정**만 바꿨고 ★(실제 거래 규칙)은 R81 이후 그대로라 수익배수 12.368도 그대로다.
    #   이 격자는 외부 49업종에서 검증된 모멘텀 핵(FIP+MOM_12_1)을 ★의 비중에 **네 가지 방식**으로 연결하고,
    #   같은 구조의 무작위 점수(지속성 있는 가짜 신호) 대조군과 함께 엔진이 직접 잰다:
    #     ① 대피처 2개 = 모멘텀 상위2(주력 제외) ② 비중 기울임 λ(보유 섹터 비중 × (1 + λ(순위 − 0.5)) · 그날 합계 유지)
    #     ③ 주력(XLK) 상한 = 주력의 모멘텀 순위(1~2위 0.9 · 6위 이하 0.6 · 그 밖 0.8)
    #   오프라인 하네스(r84/alloc84.py · 2019~ · ★ 칼마 4.170): ① 4.088(무작위 95% 3.995 — 정보는 있으나 ★ 대피처보다 못함)
    #     ② λ1 4.237(무작위 95% 4.491 — 우연 범위) ③ 4.137(무작위 중앙 4.047 — 정보 없음). ⇒ **지금은 ★를 바꿀 근거가 없다.**
    #   ⚠ 사전등록(R84 · 다음 리포트 판정): 한 변형이 ★를 대체하려면 네 조건을 **모두** 만족해야 한다 —
    #     (i) 칼마 ≥ ★ + 0.05 (ii) 같은 구조 무작위 대조군 칼마 95백분위 초과 (iii) 13 강건성(기준④) '통과'
    #     (iv) MDD가 ★보다 0.5%p 넘게 나쁘지 않음. 판정은 사람이 다음 라운드에 한다(엔진이 스스로 라이브를 바꾸지 않는다).
    #   룩어헤드 없음: 신호는 t일까지의 가격(전체 이력으로 계산 → 평가창에 재색인), 변형은 ★의 t일 목표비중에만 곱한다(t+1 시가 체결).
    _link_diag: Dict[str, Any] = {"enabled": False}
    if bool(getattr(scfg, "ALLOC_LINK_GRID", True)) and label_primary in target_ws:
        try:
            _tl0 = time.time()
            _base_l = target_ws[label_primary].copy()
            _secl = [c for c in cols if c in _base_l.columns]
            _pri_l = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "XLK")
            _rcf = ret_cc_full[[c for c in cols if c in ret_cc_full.columns]]
            _Pl = (1.0 + _rcf.fillna(0.0)).cumprod().where(_rcf.notna())
            _sg = rel_price_signals(_Pl, None, None)
            _mq = rel_combo(_sg, tuple(getattr(scfg, "ALLOC_LINK_SIGNAL", ("FIP", "MOM_12_1"))))
            _smd = int(getattr(scfg, "ALLOC_LINK_SMOOTH", 21) or 1)
            _mq = _mq.rolling(_smd, min_periods=1).mean().reindex(eval_idx)[_secl]
            _avail_l = _base_l[_secl].notna() & ret_cc.reindex(columns=_secl).notna()

            def _shelter_mom(score: pd.DataFrame, k: int = 2) -> pd.DataFrame:
                w = _base_l.copy()
                non = [c for c in _secl if c != _pri_l]
                sh = w[non].sum(axis=1)
                rr_ = score[non].where(_avail_l[non]).rank(axis=1, ascending=False, method="first")
                okk = rr_.notna().sum(axis=1) >= k
                neww = pd.DataFrame(0.0, index=w.index, columns=non)
                for j in range(1, k + 1):
                    neww = neww + (rr_ == j).astype(float).mul(sh / k, axis=0)
                w.loc[okk, non] = neww.loc[okk]
                return w

            def _tilt(score: pd.DataFrame, lam: float) -> pd.DataFrame:
                w = _base_l.copy()
                ws = w[_secl]
                pct = score.where(_avail_l).rank(axis=1, pct=True)
                m = (1.0 + float(lam) * (pct - 0.5)).where(ws > 1e-12, 0.0).fillna(1.0)
                nw = ws * m
                tot0 = ws.sum(axis=1); tot1 = nw.sum(axis=1)
                sc = (tot0 / tot1.replace(0.0, np.nan)).fillna(0.0)
                w[_secl] = nw.mul(sc, axis=0)
                return w

            def _pri_cap(score: pd.DataFrame, hi: float = 0.9, mid: float = 0.8, lo: float = 0.6) -> pd.DataFrame:
                w = _base_l.copy()
                if _pri_l not in _secl:
                    return w
                rkp = score.where(_avail_l).rank(axis=1, ascending=False)[_pri_l]
                capv = pd.Series(mid, index=w.index); capv[rkp <= 2] = hi; capv[rkp >= 6] = lo
                tot = w[_secl].sum(axis=1)
                held = w[_pri_l] > 1e-12
                newp = (tot * capv).where(held, w[_pri_l])
                non = [c for c in _secl if c != _pri_l]
                rest = w[non]; rs = rest.sum(axis=1)
                sc = ((tot - newp).clip(lower=0.0) / rs.replace(0.0, np.nan)).fillna(0.0)
                w.loc[held, _pri_l] = newp[held]
                w.loc[held, non] = rest.loc[held].mul(sc[held], axis=0)
                ok_ = rkp.notna()
                w.loc[~ok_] = _base_l.loc[~ok_]
                return w

            _lams = tuple(float(x) for x in (getattr(scfg, "ALLOC_LINK_LAMBDAS", (0.5, 1.0)) or ()))
            _makers = [("대피처 2개 = 모멘텀 상위2", lambda sc_: _shelter_mom(sc_))]
            _makers += [(f"비중 기울임 λ{lv:g}", (lambda lv_: (lambda sc_: _tilt(sc_, lv_)))(lv)) for lv in _lams]
            _makers += [(f"주력 상한 = 주력 모멘텀 순위(0.9/0.8/0.6)", lambda sc_: _pri_cap(sc_))]
            _nctl = int(getattr(scfg, "ALLOC_LINK_CONTROLS", 12) or 0)
            _seed_l = int(getattr(scfg, "ALLOC_LINK_SEED", 20260922))
            _base_bt = bts[label_primary]

            def _calmar(bt_: pd.DataFrame) -> Tuple[float, float, float]:
                r_ = pd.to_numeric(bt_["strategy_ret"], errors="coerce").fillna(0.0)
                eq_ = (1.0 + r_).cumprod(); n_ = max(len(r_), 1)
                cg_ = float(eq_.iloc[-1] ** (252.0 / n_) - 1.0) if n_ > 1 else np.nan
                mdd_ = float((eq_ / eq_.cummax() - 1.0).min())
                return cg_, mdd_, (cg_ / abs(mdd_) if mdd_ < 0 else np.nan)
            _cg0, _md0, _cm0 = _calmar(_base_bt)
            _rows_l = []
            # 무작위 점수: 섹터마다 지속성 있는 AR(0.995) 과정의 그날 순위 — 모멘텀 핵과 같은 평활·같은 가용 마스크
            _rng_l = np.random.default_rng(_seed_l)
            _rand_scores = []
            for _k in range(_nctl):
                _e = _rng_l.standard_normal((len(eval_idx), len(_secl)))
                _a = np.empty_like(_e); _a[0] = _e[0]
                for _i in range(1, len(_e)):
                    _a[_i] = 0.995 * _a[_i - 1] + math.sqrt(1 - 0.995 ** 2) * _e[_i]
                _rs = pd.DataFrame(_a, index=eval_idx, columns=_secl).where(_avail_l).rank(axis=1, pct=True)
                _rs = _rs.where(_mq.notna())
                _rand_scores.append(_rs)
            for _nm, _mk in _makers:
                _lab = f"주력섹터 중심 · {_nm} [모멘텀연결격자]"
                _w = _mk(_mq).fillna(0.0).clip(lower=0.0)
                target_ws[_lab] = _w
                bts[_lab] = portfolio_backtest(_w, ret_co, ret_oc, **bt_kw)
                variants[_lab] = _w
                _cg, _md, _cm = _calmar(bts[_lab])
                _ctl = []
                for _k, _rs in enumerate(_rand_scores):
                    _wc = _mk(_rs).fillna(0.0).clip(lower=0.0)
                    _ctl.append(_calmar(portfolio_backtest(_wc, ret_co, ret_oc, **bt_kw))[2])
                _ctl = np.asarray([c_ for c_ in _ctl if c_ == c_], dtype=float)
                _pctile = float((_ctl < _cm).mean() * 100.0) if len(_ctl) else np.nan
                _q95 = float(np.quantile(_ctl, 0.95)) if len(_ctl) else np.nan
                _pass = bool((_cm == _cm) and _cm >= _cm0 + 0.05 and (len(_ctl) and _cm > _q95)
                             and (_md >= _md0 - 0.005))
                _rows_l.append({"변형": _nm, "라벨": _lab, "CAGR": _cg, "MDD": _md, "칼마": _cm,
                                "★ 칼마": _cm0, "★ MDD": _md0, "대조군 수": int(len(_ctl)),
                                "대조군 칼마 중앙": (float(np.median(_ctl)) if len(_ctl) else np.nan),
                                "대조군 칼마 95%": _q95, "대조군 대비 백분위": _pctile,
                                "사전등록 (i)(ii)(iv) 통과": _pass})
                log("ROTATION", kv(event="alloc_link_variant", variant=_nm, calmar=round(_cm, 3), calmar_star=round(_cm0, 3),
                                   cagr=round(_cg * 100, 2), mdd=round(_md * 100, 2), ctl_median=round(float(np.median(_ctl)), 3)
                                   if len(_ctl) else None, ctl_q95=round(_q95, 3) if _q95 == _q95 else None,
                                   pctile=round(_pctile, 1) if _pctile == _pctile else None, prereg_pass=_pass), M=M)
            _link_diag = {"enabled": True, "rows": _rows_l, "controls": _nctl, "seed": _seed_l,
                          "signal": "+".join(getattr(scfg, "ALLOC_LINK_SIGNAL", ("FIP", "MOM_12_1"))),
                          "star_calmar": _cm0, "star_mdd": _md0, "star_cagr": _cg0,
                          "any_pass": any(r_["사전등록 (i)(ii)(iv) 통과"] for r_ in _rows_l)}
            log("ROTATION", kv(event="alloc_link_grid_done", variants=len(_rows_l), controls=_nctl, seed=_seed_l,
                               any_prereg_pass=_link_diag["any_pass"], sec=round(time.time() - _tl0, 1),
                               note="측정 전용 — ★(라이브) 무변경"), M=M)
        except Exception as _e:
            log("ROTATION", kv(event="alloc_link_grid_failed", err=type(_e).__name__, msg=str(_e)[:180],
                               trace=traceback.format_exc()[-300:].replace("\n", " | "),
                               action="격자만 생략 — ★(라이브)는 영향 없음"), M=M, level="warning")
            _link_diag = {"enabled": False, "error": f"{type(_e).__name__}: {str(_e)[:160]}"}

    # [v0.7.0] 참조: SPY 국면전략(M) 성과(같은 평가창, M의 bt 그대로) — 수용기준 ⑤(목표: CAGR ≥ SPY M)에 사용
    spy_m_ret = res["bt"]["strategy_ret"].reindex(eval_idx).fillna(0.0)
    spy_m_pm = M.perf_metrics(spy_m_ret, "SPY 국면전략(M)")
    spy_m = {"CAGR": float(spy_m_pm["CAGR"]), "MDD": float(spy_m_pm["최대낙폭(MDD)"]), "샤프": spy_m_pm["샤프"]}
    # [v0.10.0 §1.C] SPY 자체(매수보유) 원시수익·국면라벨 — rotation_validation()/build_gap_attribution()은 res를 받지
    # 않으므로 alloc에 실어 전달(위 spy_m_ret·spy_m과 같은 방식). vs SPY 비교열·SPY국면별 분해에 사용.
    #   국면라벨은 §1.D의 spy_regime_arr와 같은 원천(_spy_state_src)이므로 여기서도 재사용(계산 중복 없음).
    spy_ret_cc = ((1.0 + ret_co["SPY"]) * (1.0 + ret_oc["SPY"]) - 1.0).reindex(eval_idx)
    spy_state_short = _spy_state_src.reindex(eval_idx).map(STATE_SHORT).fillna("-")

    # 13 성과표 순서: 주 전략 → 대안·비교 변형 → 대조군 A/B
    order = [l for l in variants if l not in (ROT_LABEL_CTRL_A, ROT_LABEL_CTRL_B)] + [ROT_LABEL_CTRL_A, ROT_LABEL_CTRL_B]
    perf = pd.DataFrame([M.perf_metrics(bts[l]["strategy_ret"], l) for l in order])
    perf.insert(1, "평가창", f"{eval_idx[0].date()}~{eval_idx[-1].date()}")
    perf["평균노출"] = [round(float(bts[l]["exposure"].mean()), 4) for l in order]
    perf["연평균회전율(편도)"] = [round(float(bts[l]["turnover"].sum() / (len(eval_idx) / 252)), 2) for l in order]
    perf["누적비용"] = [round(float(bts[l]["cost"].sum()), 4) for l in order]
    # [v0.33.0 ⚠ 채택 기준 ④ — 강건성 게이트] 각 행이 ★를 이기는 것이 **며칠짜리인가**를 매 실행 싣는다.
    #   M의 과열 헤어컷이 세 라운드 연속 '단조 in-sample 기울기'만 보고 조여졌다가 리포트55 전수
    #   검정에서 전 단계가 "상위 5일 제외 시 부호 반전"으로 드러나 v1.46.0에서 되돌려진 일이 계기다.
    #   이 층도 같은 실수를 할 수 있으므로(방어대피처 격자가 M이 바뀔 때마다 정점을 한 칸씩 옮긴다)
    #   판정 근거를 리포트에 상설로 남긴다. ★ 행 자신은 정의상 0이다.
    _base_r = pd.to_numeric(bts[label_primary]["strategy_ret"], errors="coerce")
    _rb_tot, _rb_cut, _rb_flag, _rb_t3, _rb_ul = [], [], [], [], []

    def _dd_shape(_r):
        """[v0.35.0] 낙폭을 단일 사건에 묶이지 않게 두 지표로 요약한다.
        상위3 낙폭평균 = 독립 낙폭 에피소드 중 깊은 셋의 평균(포화 교차확인용),
        얼서지수 = 낙폭 경로의 RMS(노출을 줄이면 언제나 좋아지므로 **판정에는 쓰지 않는다**)."""
        _r = pd.to_numeric(_r, errors="coerce").fillna(0.0)
        if len(_r) < 60:
            return np.nan, np.nan
        _eq = (1.0 + _r).cumprod(); _dd = _eq / _eq.cummax() - 1.0
        _eps, _st = [], None
        for _t_, _u in (_dd < -1e-9).items():
            if _u and _st is None:
                _st = _t_
            if (not _u) and _st is not None:
                _eps.append(float(_dd.loc[_st:_t_].min())); _st = None
        if _st is not None:
            _eps.append(float(_dd.loc[_st:].min()))
        _t3 = round(float(np.mean(sorted(_eps)[:3])), 4) if _eps else np.nan
        return _t3, round(float(np.sqrt((_dd ** 2).mean())), 4)

    for l in order:
        _t3, _ul = _dd_shape(bts[l]["strategy_ret"])
        _rb_t3.append(_t3); _rb_ul.append(_ul)
        _ex = (pd.to_numeric(bts[l]["strategy_ret"], errors="coerce") - _base_r).dropna()
        if len(_ex) < 60:
            _rb_tot.append(np.nan); _rb_cut.append(np.nan); _rb_flag.append(""); continue
        _ann = 252.0 / len(_ex) * 100.0
        _t = float(_ex.sum()) * _ann
        _c = float(_ex.sum() - _ex.sort_values(ascending=False).iloc[:5].sum()) * _ann
        _rb_tot.append(round(_t, 3)); _rb_cut.append(round(_c, 3))
        _rb_flag.append("★" if abs(_t) < 1e-9 else
                        ("통과" if _t > 0 and _c > 0 else
                         ("⚠ 5일 의존" if _t > 0 else ("열위(강건)" if _c < 0 else "열위(불안정)"))))
    perf["★대비 초과(연율%p)"] = _rb_tot
    perf["초과(상위5일 제외,연율%p)"] = _rb_cut
    perf["강건성(기준④)"] = _rb_flag
    # ⚠ [v0.35.0] 포화 판정은 **수용기준이 쓰는 지표(MDD)** 로만 한다. 아래 두 열은 보조·맥락이다 —
    #   지표를 넓힐수록 포화점이 뒤로 밀리기 때문에(MDD E7 → 상위3 E9 → 상위5 E11 → 얼서 무한),
    #   지표 선택의 자유를 두면 '포화했다'는 판정 자체가 튜닝 가능해진다.
    perf["상위3 낙폭평균"] = _rb_t3
    perf["얼서지수"] = _rb_ul
    log("ROTATION", kv(event="robustness_gate_built", rows=len(order),
                       flagged=int(sum(1 for f in _rb_flag if f.startswith("⚠")))), M=M)
    curve = pd.DataFrame(index=eval_idx)
    curve["날짜"] = [d.date() for d in eval_idx]
    for l in order:
        curve[l] = bts[l]["equity"].round(4)
    curve["E_t(SPY목표비중)"] = E.round(2)
    curve["적격섹터수"] = n_elig.astype(int).values

    target_w = target_ws[label_primary]
    tier_counts = tier.value_counts().to_dict()
    diag = {
        "label_primary": label_primary, "label_leader": label_leader, "label_topk": label_topk, "label_linear": label_lin,
        "self_cut": _sc_diag,                                                        # [v0.62.0 R80]
        "alloc_link": _link_diag,                                                    # [v0.66.0 R84] [모멘텀연결격자]
        "own_evidence": _own_diag,                                                   # [v0.67.0 R85] 섹터 자기근거 채움
        "macro_evidence": _macro_diag,                                               # [v0.68.0 R86] 섹터 거시 근거(측정)
        "label_alt": (label_topk if mode == "leader3" else label_leader),
        "label_own": (label_own if label_own in bts else None), "spy_m": spy_m,          # [v0.7.0]
        "label_score": (label_score if label_score in bts else None),                   # [v0.8.0]
        "label_conv": (label_conv if label_conv in bts else None),                      # [v0.10.0 §1.B]
        "label_regime": (label_regime if label_regime in bts else None),                # [v0.10.0 §1.D]
        "leader_regimes_cfg": (list(scfg.ROTATION_LEADER_REGIMES) if getattr(scfg, "ROTATION_LEADER_REGIMES", None) else None),
        "select_stat": wf.get("stat", "top1"), "include_spy": include_spy, "min_agree": min_agree,
        "evidence_tier": bool(wf.get("evidence_tier", False)), "avoid_validate": bool(wf.get("avoid_validate", False)),   # [v0.9.0]
        "tier_by_year": {int(k): v for k, v in wf.get("tier_by_year", {}).items()},
        "avoid_by_year": {int(k): list(v) for k, v in wf.get("avoid_by_year", {}).items()},
        "days_spy_top": int(tier_counts.get("SPY우위", 0)), "local_start": str(pd.Timestamp(local_start).date()),
        "tilt": mode, "cap": cap, "cap_strict": bool(scfg.ROTATION_CAP_STRICT),
        "signals": list(raw_full.keys()), "smooth_days": smooth, "min_hold_days": min_hold, "leader_weight": lw,
        "fallback": fallback_txt, "select_t": float(scfg.ROTATION_SELECT_T), "select_horizon": wf["horizon"],
        "selected_by_year": {int(k): v for k, v in sel_by_year.items()},
        "avg_n_eligible": round(float(n_elig.mean()), 2), "days_no_eligible": int((n_elig == 0).sum()),
        "days_leader": int(tier_counts.get("리더", 0)), "days_avoid": int(tier_counts.get("회피", 0)),
        "days_fallback": int(tier_counts.get("폴백", 0)), "days_cash": int(tier_counts.get("현금", 0)),
        "days_fallback_gate": int(tier_counts.get("폴백(여유부족)", 0)),                 # [v0.10.0 §1.B]
        "margin_steps_cfg": margin_steps_cfg,                                            # [v0.10.0 §1.B]
        "leader_switches": switches,
        "avg_exposure_primary": round(float(bts[label_primary]["exposure"].mean()), 4),
        "avg_E": round(float(E.mean()), 4),
        "top_holding_freq": {t: round(float((rank_pos[t] == 1).mean()), 4) for t in cols},
        "leader_freq": {t: round(float((leader_s == t).mean()), 4) for t in cols},
    }
    log("ROTATION", kv(event="allocation_built",
                       **{k: v for k, v in diag.items() if k not in ("top_holding_freq", "leader_freq", "selected_by_year", "spy_m",
                                                                     "tier_by_year", "avoid_by_year", "alloc_link", "own_evidence", "macro_evidence")},
                       tiers=";".join(f"{k}:{v}" for k, v in sorted(diag["tier_by_year"].items())) or "-",
                       avoid_ok=";".join(f"{k}:{'+'.join(v) if v else '-'}" for k, v in sorted(diag["avoid_by_year"].items())) or "-",
                       spy_m_cagr=spy_m["CAGR"], spy_m_mdd=spy_m["MDD"],
                       elapsed_s=round(time.time() - t0, 2)), M=M)
    for l in variants:
        pr = perf.set_index("전략").loc[l]
        log("ROTATION", kv(event="allocation_perf", strategy=l, cagr=pr["CAGR"], sharpe=pr["샤프"],
                           mdd=pr["최대낙폭(MDD)"], avg_exposure=pr["평균노출"], turnover_yr=pr["연평균회전율(편도)"]), M=M)
    return {"target_w": target_w, "frac_w": frac_primary, "composite": composite, "composite_all": composite_all,
            "composite_all_smooth": composite_all_s, "tier": tier, "leader": leader_s, "laggard": laggard_s,
            "votes_leader": votes_leader, "votes_laggard": votes_laggard, "n_selected": n_sel_s,
            "margin": margin_s, "step": step_s, "gate": gate_s,   # [v0.10.0 §1.B] 일별 1위 여유·문턱·확신 게이트(통과/미달/해당없음) — 13c
            "eligible": eligible, "listed": listed, "E": E, "n_eligible": n_elig,
            "shortfall": pd.Series(0.0, index=eval_idx),
            "variants_diag": variants_diag,      # [v0.46.0 H4] 13p 블록 E — 격자 변형별 판단 시계열
            "vote_loss_flag": _live_r3.get("vote_loss_flag"),   # [v0.48.0 L5] 13c '득표 상실 중 보유' 열
            "rank_pos": rank_pos, "bts": bts, "target_ws": target_ws, "perf": perf, "curve": curve.reset_index(drop=True),
            "diag": diag, "signals": signals, "wf": wf, "ret_cc": ret_cc, "state": state, "cols": cols, "cand": cand,
            "spy_m_ret": spy_m_ret,                                                        # [v0.8.0] 13i 격차 분해용
            "spy_ret": spy_ret_cc, "spy_state_short": spy_state_short,                     # [v0.10.0 §1.C] vs SPY·SPY국면 분해용
            "down_leader_days": down_leader_days,                                          # [v0.15.0 §A] 하락국면 리더 발동일
            "all_cols": all_cols,
            # [v0.9.0] 13j 배분거래내역(실제 포트폴리오 거래 로그)용 — 백테스트와 같은 수익 분해·초기 포지션·비용
            "ret_co": ret_co.reindex(columns=all_cols), "ret_oc": ret_oc.reindex(columns=all_cols),
            "init_exec": init_exec, "init_prev": init_prev, "cost_bps": cost_bps, "rf_daily": rf_daily,
            "target_w_off": target_w_off}                    # [v0.67.0 R85] 섹터근거 채움 이전 ★(I★ 전후 비교용 · None이면 블록 꺼짐)


def _nw_mean_tstat(x: pd.Series, lag: int) -> Tuple[float, float, int]:
    """일별 IC 시계열의 평균이 0과 다른지 — 뉴이-웨스트 HAC(바틀렛 가중, lag) 표준오차의 평균-t(v0.1 이식)."""
    s = x.dropna()
    n = len(s)
    if n < 30:
        return np.nan, np.nan, n
    m = float(s.mean())
    resid = (s - m).values
    gamma0 = float((resid ** 2).mean())
    lag_max = min(lag, n - 1)
    var = gamma0
    for L in range(1, lag_max + 1):
        w = 1.0 - L / (lag_max + 1)
        var += 2 * w * float((resid[L:] * resid[:-L]).mean())
    se = math.sqrt(max(var, 1e-12) / n)
    return m, (m / se if se > 0 else np.nan), n


def _nw_mean_tstat_w(x: pd.Series, lag: int, weights: Optional[pd.Series] = None) -> Tuple[float, float, int, float]:
    """[v0.10.0 §1.A] _nw_mean_tstat()의 가중 일반화 — 학습창에 M과 같은 시간감쇠 표본가중(decay_weights())을 적용하기 위함.
    weights=None이면 _nw_mean_tstat()을 그대로 호출해 반환한다(코드 경로 공유 — 가중치 없음 = 원 함수와 완전히 동일).
    weights가 주어지면: m=Σw·x/Σw(가중평균), e=x−m, γ0=Σw²e²/Σw², γ_L=Σ w_i w_{i+L} e_i e_{i+L} / Σ w_i w_{i+L}(L=1..lag_max),
    var=γ0+2Σ(1−L/(lag_max+1))γ_L, n_eff=(Σw)²/Σw²(=effective_n(weights)), se=sqrt(var/n_eff), t=m/se — w≡1이면 이 식들은
    각각 mean(e²)·mean(e_L·e_{L+1})·n으로 정확히 환원되어 _nw_mean_tstat()과 비트 동일(단위테스트로 확인).
    반환: (가중평균, t, 원시 관측일 n, 유효표본수 n_eff). n<30 또는 가중치 합이 0이면 (nan, nan, n, n_eff)."""
    if weights is None:
        m, t, n = _nw_mean_tstat(x, lag)
        return m, t, n, float(n)
    s = x.dropna()
    n = len(s)
    w = weights.reindex(s.index).fillna(0.0).astype(float).clip(lower=0.0)
    sw = float(w.sum())
    sw2 = float((w ** 2).sum())
    n_eff = float(sw ** 2 / sw2) if sw > 0 and sw2 > 0 else 0.0
    if n < 30 or sw <= 0:
        return np.nan, np.nan, n, n_eff
    wv = w.values
    xv = s.values
    m = float((wv * xv).sum() / sw)
    e = xv - m
    gamma0 = float((wv ** 2 * e ** 2).sum() / sw2)
    lag_max = min(lag, n - 1)
    var = gamma0
    for L in range(1, lag_max + 1):
        kw = 1.0 - L / (lag_max + 1)
        denom = float((wv[L:] * wv[:-L]).sum())
        if denom > 0:
            gL = float((wv[L:] * wv[:-L] * e[L:] * e[:-L]).sum() / denom)
            var += 2 * kw * gL
    se = math.sqrt(max(var, 1e-12) / max(n_eff, 1e-9))
    return m, (m / se if se > 0 else np.nan), n, n_eff


def _cs_rank_ic(x_mat: pd.DataFrame, fwd_mat: pd.DataFrame, min_n: int = 5) -> pd.Series:
    """행(날짜)별 스피어만 순위상관(그날 신호 vs 그날 기준 향후 수익) 시계열. 두 값이 모두 있는 섹터 ≥ min_n인 날만."""
    both = x_mat.notna() & fwd_mat.notna()
    xr = x_mat.where(both).rank(axis=1)
    yr = fwd_mat.where(both).rank(axis=1)
    n = both.sum(axis=1)
    xm = xr.sub(xr.mean(axis=1), axis=0)
    ym = yr.sub(yr.mean(axis=1), axis=0)
    cov = (xm * ym).sum(axis=1)
    den = np.sqrt((xm ** 2).sum(axis=1) * (ym ** 2).sum(axis=1))
    ic = (cov / den.replace(0, np.nan)).where(n >= min_n)
    return ic


def _top1_spread_series(rank_mat: pd.DataFrame, avail: pd.DataFrame, fwd_mat: pd.DataFrame,
                        smooth: int = 1, min_n: int = 5, margin_steps: float = 0.0,
                        bench_series: Optional[pd.Series] = None) -> pd.Series:
    """[v0.7.0] '상위1 스프레드' 일별 시계열 = (그날 평활 순위가 가장 높은 1개 자산의 향후 h일 수익) − (그날 순위·수익이 모두
    있는 자산 전체의 평균 향후 h일 수익). '1위 하나에 집중'하는 전략이 실제로 얻는 초과수익의 직접 추정치(비용 제외)로, 평균
    rank IC('전체 순서'의 정확도)와 달리 1위 판별력만 잰다. rank_mat: 0~1 횡단면 순위(사전방향 적용), avail: 순위 대상 마스크
    (상장), fwd_mat: t 기준 향후 h일 수익(통계 산출에만 쓰이며 배분에는 되돌아가지 않음). 평활은 배분에 쓰는 것과 같은
    후행 이동평균(인과). 동률이면 첫 열. 자산 수 < min_n인 날은 NaN.
    [v0.10.0 §1.B] margin_steps>0이면 build_sector_allocation()의 확신 게이트와 같은 정의(1위−2위 평활순위 여유 margin,
    그날 순위 대상 수 n으로 step=margin_steps/(n−1))를 적용해 margin < step인 날도 NaN(표본 제외) — '게이트를 통과한 날만으로
    상위1 스프레드를 검증'해 워크포워드 채택 통계가 실제 배분 규칙(게이트 포함)을 그대로 검정하게 한다. margin_steps=0(기본)이면
    게이트 없음(이전과 완전히 동일).
    [v0.10.0 §1.C] bench_series가 주어지면 벤치마크를 '상장 평균'이 아니라 그 시리즈(예: SPY의 같은 지평 향후수익)로 바꾼다 —
    1위 판별력 통계(③ 등)는 바꾸지 않고, 13d의 'vs SPY' 진단 열에만 쓴다. None(기본)이면 이전과 완전히 동일(상장 평균)."""
    cols = list(rank_mat.columns)
    r = rank_mat.where(avail.reindex(index=rank_mat.index, columns=cols).fillna(False))
    rs = r.rolling(smooth, min_periods=1).mean().where(r.notna()) if smooth > 1 else r
    fwd = fwd_mat.reindex(index=rank_mat.index, columns=cols)
    both = rs.notna() & fwd.notna()
    n = both.sum(axis=1)
    has = both.any(axis=1).values
    rs_masked = rs.where(both).fillna(-np.inf).values
    pos = rs_masked.argmax(axis=1)
    fv = fwd.values
    r_top = np.where(has, fv[np.arange(len(fv)), pos], np.nan)
    bench = bench_series.reindex(rank_mat.index) if bench_series is not None else fwd.where(both).mean(axis=1)
    spread = pd.Series(r_top, index=rank_mat.index) - bench
    valid = (n >= min_n)
    if margin_steps and margin_steps > 0:
        rows_idx = np.arange(len(rs_masked))
        top_val = rs_masked[rows_idx, pos]
        tmp = rs_masked.copy()
        tmp[rows_idx, pos] = -np.inf
        second_val = tmp.max(axis=1)
        n_arr = n.values
        with np.errstate(invalid="ignore"):     # n_arr<2 행은 -inf−(-inf)=nan이 나오지만 아래서 버려짐(경고만 소음)
            margin = np.where(n_arr >= 2, top_val - second_val, np.nan)
        step = margin_steps / np.maximum(n_arr - 1, 1)
        # [v0.10.0 §1.B 버그수정] build_sector_allocation()의 gate_ok(_run_leader3 내부, margin_i>=step_i-1e-9)와 같은
        # 부동소수점 경계 이유로 같은 1e-9 허용오차를 둔다 — 이 함수 docstring이 "배분과 같은 게이트 정의"라고 명시하므로
        # 허용오차도 반드시 맞춰야 워크포워드 채택 통계(여기)와 실제 배분 판정(그쪽)이 같은 날을 같게 다룬다.
        gate_ok = np.isfinite(margin) & (margin >= step - 1e-9)
        valid = valid & pd.Series(gate_ok, index=rank_mat.index)
    return spread.where(valid)


def _top1_hit_series(rank_mat: pd.DataFrame, avail: pd.DataFrame, fwd_mat: pd.DataFrame,
                     smooth: int = 1, k: int = 3, min_n: int = 5) -> pd.Series:
    """[v0.42.0 S-I] '그날 이 신호의 1위가 실현 상위 k 안에 들었나'의 일별 0/1 시계열.
    스프레드(크기)와 달리 **순서만** 보는 잣대라 소수의 큰 사건에 끌려가지 않는다 — 리포트45 §2.1에서
    SCORE_PCT의 전체 t 3.15가 2020·2022·2023 세 해가 만든 것임을 드러낸 통계가 이것이다
    (1위의 실현 상위3 적중: 2023 0.52 → 2024 0.31 · 2025 0.26 · 2026 0.23, 무작위 = k/n ≈ 0.27).
    1위 선정은 _top1_spread_series와 같은 평활 순위(배분과 동일 정의). 자산 수 < min_n인 날은 NaN."""
    cols = list(rank_mat.columns)
    r = rank_mat.where(avail.reindex(index=rank_mat.index, columns=cols).fillna(False))
    rs = r.rolling(smooth, min_periods=1).mean().where(r.notna()) if smooth > 1 else r
    fwd = fwd_mat.reindex(index=rank_mat.index, columns=cols)
    both = rs.notna() & fwd.notna()
    n = both.sum(axis=1)
    has = both.any(axis=1).values
    pos = rs.where(both).fillna(-np.inf).values.argmax(axis=1)
    # 실현 수익의 내림차순 순위(1 = 그날 실제로 가장 많이 오른 자산)
    rk_real = fwd.where(both).rank(axis=1, ascending=False, method="min").values
    hit = np.where(has, np.take_along_axis(rk_real, pos[:, None], axis=1).ravel() <= k, np.nan)
    out = pd.Series(hit, index=rank_mat.index, dtype=float)
    return out.where(n >= min_n)


def _bottom1_hit_series(rank_mat: pd.DataFrame, avail: pd.DataFrame, fwd_mat: pd.DataFrame,
                        smooth: int = 1, k: int = 3, min_n: int = 5, exclude: Tuple[str, ...] = ("SPY",)) -> pd.Series:
    """[v0.43.0 R3] '그날 이 신호의 꼴찌가 실현 **하위** k 안에 들었나'의 일별 0/1 — _top1_hit_series의 하위 판.
    REPORT46 §1.2의 잣대(모델 꼴찌 → 실현 하위3 = 소수 클래스 27%)를 신호별·학습창별로 그대로 낸다. 정보가 있으면
    무작위(k/n ≈ 0.27)보다 커야 한다. exclude(SPY)는 꼴찌 후보에서 제외(규칙 ②와 동일), 실현 순위에는 포함."""
    cols = list(rank_mat.columns)
    r = rank_mat.where(avail.reindex(index=rank_mat.index, columns=cols).fillna(False))
    rs = r.rolling(smooth, min_periods=1).mean().where(r.notna()) if smooth > 1 else r
    fwd = fwd_mat.reindex(index=rank_mat.index, columns=cols)
    both = rs.notna() & fwd.notna()
    n = both.sum(axis=1)
    pick = both.copy()
    for c in exclude:
        if c in pick.columns:
            pick[c] = False
    has = pick.any(axis=1).values
    pos = rs.where(pick).fillna(np.inf).values.argmin(axis=1)
    rk_real = fwd.where(both).rank(axis=1, ascending=True, method="min").values     # 1 = 가장 많이 떨어진 자산
    hit = np.where(has, np.take_along_axis(rk_real, pos[:, None], axis=1).ravel() <= k, np.nan)
    out = pd.Series(hit, index=rank_mat.index, dtype=float)
    return out.where(n >= min_n)


def _bottom1_spread_series(rank_mat: pd.DataFrame, avail: pd.DataFrame, fwd_mat: pd.DataFrame,
                           smooth: int = 1, min_n: int = 5, exclude: Tuple[str, ...] = ("SPY",)) -> pd.Series:
    """[v0.9.0] '하위1 스프레드' 일별 시계열 = (그날 평활 순위가 가장 낮은 1개 자산의 향후 h일 수익) − (순위·수익이 모두 있는 자산 전체의
    평균 향후 h일 수익). 규칙 ②(꼴찌 회피)가 실제로 피하는 손실의 직접 추정치 — 정보가 있으면 음(−). exclude(기본 SPY)는 꼴찌 후보에서
    제외(규칙 ②와 동일: SPY는 회피 대상이 아님)하되 평균(벤치)에는 포함. 나머지는 _top1_spread_series와 같은 정의(평활·마스크·min_n)."""
    cols = list(rank_mat.columns)
    r = rank_mat.where(avail.reindex(index=rank_mat.index, columns=cols).fillna(False))
    rs = r.rolling(smooth, min_periods=1).mean().where(r.notna()) if smooth > 1 else r
    fwd = fwd_mat.reindex(index=rank_mat.index, columns=cols)
    both = rs.notna() & fwd.notna()
    n = both.sum(axis=1)
    pick = both.copy()
    for c in exclude:
        if c in pick.columns:
            pick[c] = False
    has = pick.any(axis=1).values
    pos = rs.where(pick).fillna(np.inf).values.argmin(axis=1)
    fv = fwd.values
    r_bot = np.where(has, fv[np.arange(len(fv)), pos], np.nan)
    bench = fwd.where(both).mean(axis=1)
    spread = pd.Series(r_bot, index=rank_mat.index) - bench
    return spread.where(n >= min_n)


def _quartile_labels(x: pd.Series, q: int = 4) -> pd.Series:
    """[v0.10.0 §1.C] 값 시리즈 → Q1(최저)~Q{q}(최고) 분위 라벨(pd.qcut). 입력이 NaN인 행은 라벨도 NaN(그 행은 애초에
    분위를 매길 정보가 없다는 뜻 — 예: 리더가 아닌 날의 '여유'). 유효값이 q개 미만이거나 전부 같은 값이면(분위를 나눌 수
    없음) 전부 NaN. 13i '여유 4분위'·13e '분산4분위' 표에 공용."""
    v = x.dropna()
    if len(v) < q or v.nunique() < 2:
        return pd.Series(np.nan, index=x.index, dtype=object)
    try:
        lab = pd.qcut(v, q, labels=[f"Q{i + 1}" for i in range(q)], duplicates="drop")
    except ValueError:
        return pd.Series(np.nan, index=x.index, dtype=object)
    return lab.astype(object).reindex(x.index)


# [v0.12.0] 사전 고정 방어/경기민감 분류 — GICS 관례(방어=필수소비·유틸리티·헬스케어). 데이터로 고른 값이 아니며
#   13k 진단 표시 전용(배분 규칙에는 쓰지 않는다).
ROTATION_DEFENSIVE_SECTORS: Tuple[str, ...] = ("XLP", "XLU", "XLV")


def build_sector_prediction_accuracy(results: Dict[str, Dict[str, Any]],
                                     alloc: Optional[Dict[str, Any]] = None,
                                     horizons: Tuple[int, ...] = (1, 5, 21, 63)) -> pd.DataFrame:
    """[v0.16.0 / v0.17.0 정정] 01Y_섹터예측정확도 — 섹터별 국면 예측을 실제 결과로 채점.
    배분·신호는 전혀 건드리지 않는다.

    ⚠⚠ [v0.17.0] M의 12_예측정확도와 같은 두 오류를 바로잡았다.
    (1) 정렬 — 상태[t]는 t일 종가 확정 신호이고 체결은 t+1이므로 **상태[t] → 수익[t+1]**로 채점한다.
        v0.16.0은 같은 행 수익과 비교했다.
    (2) 기저 대비 — 하락 예측의 '적중률 0.35'는 0.5가 아니라 **그 지평의 기저 하락률**과 비교해야 한다.
        예: SPY h=63일 기저 하락률은 0.262라 적중률 0.382는 +12.0%p의 우위다. 0.5와 비교하면
        '절반도 못 맞힌다'로 정반대로 읽힌다 — 실제로 그렇게 오독할 뻔했다.
    그래서 모든 지평·모든 상태에 '기저 대비(%p)'와 '정보(있음/없음/역방향)' 판정을 나란히 넣는다.

    블록 A 익일 채점 · B 지평별(기저 대비 동반) · C 크게 틀린 구간 · D 연도별
    """
    if not results:
        return pd.DataFrame()
    rows: List[dict] = []
    tks = [t for t in results if isinstance(results.get(t), dict)
           and results[t].get("state") is not None and results[t].get("ret_cc_full") is not None]
    if not tks:
        return pd.DataFrame()
    UP, NU, DN = "RISK_ON", "NEUTRAL", "RISK_OFF"

    def _pack(t):
        st = pd.Series(results[t]["state"]).astype(object)
        r = pd.Series(results[t]["ret_cc_full"]).reindex(st.index).astype(float)
        C = (1.0 + r.fillna(0.0)).cumprod()
        return st, r, C

    def _verdict(x):
        return "있음" if x > 0.005 else ("없음" if x > -0.005 else "역방향")

    rows.append({"블록": "A. 익일 채점", "섹터": "── 상태[t] → 수익[t+1] ──",
                 "설명": "상승은 기저 상승률과, 하락은 기저 하락률과 비교한다 — 0.5와 비교하면 오독한다"})
    for t in tks:
        st, r, C = _pack(t)
        f1 = C.shift(-2) / C.shift(-1) - 1
        m = f1.notna() & st.notna()
        if int(m.sum()) < 60:
            continue
        base = float((f1[m] > 0).mean())
        mu, mn, md = st[m].eq(UP), st[m].eq(NU), st[m].eq(DN)
        hu = float((f1[m][mu] > 0).mean()) if int(mu.sum()) >= 5 else np.nan
        hd = float((f1[m][md] <= 0).mean()) if int(md.sum()) >= 5 else np.nan
        rows.append({"블록": "A. 익일 채점", "섹터": t, "표본일수": int(m.sum()),
                     "기저 상승": round(base, 4), "기저 하락": round(1 - base, 4),
                     "상승예측 일수": int(mu.sum()), "상승예측 적중": round(hu, 4) if hu == hu else np.nan,
                     "상승 기저대비(%p)": round((hu - base) * 100, 2) if hu == hu else np.nan,
                     "상승 정보": _verdict(hu - base) if hu == hu else "",
                     "중립 일수": int(mn.sum()),
                     "하락예측 일수": int(md.sum()), "하락예측 적중": round(hd, 4) if hd == hd else np.nan,
                     "하락 기저대비(%p)": round((hd - (1 - base)) * 100, 2) if hd == hd else np.nan,
                     "하락 정보": _verdict(hd - (1 - base)) if hd == hd else "",
                     "상승예측일 다음날(bp)": round(float(f1[m][mu].mean()) * 1e4, 2) if int(mu.sum()) >= 5 else np.nan,
                     "하락예측일 다음날(bp)": round(float(f1[m][md].mean()) * 1e4, 2) if int(md.sum()) >= 5 else np.nan})

    rows.append({"블록": "B. 지평별", "섹터": "── 예측이 사는 지평 ──",
                 "설명": "기저 대비가 양수인 칸만 정보가 있다"})
    for t in tks:
        st, r, C = _pack(t)
        for h in horizons:
            f = C.shift(-h - 1) / C.shift(-1) - 1
            m = f.notna() & st.notna()
            if int(m.sum()) < 60:
                continue
            bu = float((f[m] > 0).mean())
            mu, md = st[m].eq(UP), st[m].eq(DN)
            row = {"블록": "B. 지평별", "섹터": t, "구분": f"h={h}일", "표본일수": int(m.sum()),
                   "기저 상승": round(bu, 4), "기저 하락": round(1 - bu, 4)}
            if int(mu.sum()) >= 5:
                hu = float((f[m][mu] > 0).mean())
                row["상승 적중"] = round(hu, 4); row["상승 기저대비(%p)"] = round((hu - bu) * 100, 2)
                row["상승 정보"] = _verdict(hu - bu)
            if int(md.sum()) >= 5:
                hd = float((f[m][md] <= 0).mean())
                row["하락 적중"] = round(hd, 4); row["하락 기저대비(%p)"] = round((hd - (1 - bu)) * 100, 2)
                row["하락 정보"] = _verdict(hd - (1 - bu))
            rows.append(row)

    # ---- B2. 상태 지속성 [v0.20.0 신설] ----
    # ⚠ B블록은 "상태[t]를 h일 얼려 들고 있었다면"을 채점한다. 배분은 매일 다시 판단하므로 그 가정이
    #   깨진다(M v1.36.0 §3에서 같은 착시가 중립 변형 8번의 실패를 낳았음을 규명했다).
    #   섹터층은 상태만 쓰고 자체 비중을 쓰지 않으므로, 여기서는 '그 상태가 h일 뒤까지 유지되는 비율'을
    #   실어 B의 h열을 얼마나 믿어도 되는지 눈으로 확인할 수 있게 한다. 유지율이 낮으면 B의 h열은
    #   그 섹터의 실제 운용을 대표하지 않는다.
    rows.append({"블록": "B2. 상태 지속성", "섹터": "── B의 h열을 얼마나 믿을 수 있나 ──",
                 "설명": "상태[t]가 h일 뒤까지 그대로인 비율. 낮으면 B의 h열은 실제 운용과 다르다"})
    for t in tks:
        st, r, C = _pack(t)
        row = {"블록": "B2. 상태 지속성", "섹터": t}
        base_ok = st.notna()
        if int(base_ok.sum()) < 60:
            continue
        for h in horizons:
            nxt = st.shift(-h)
            m = base_ok & nxt.notna()
            if int(m.sum()) < 20:
                continue
            row[f"h={h}일 유지율"] = round(float((st[m] == nxt[m]).mean()), 4)
        rows.append(row)

    rows.append({"블록": "C. 크게 틀린 구간", "섹터": "── 방어적인데 크게 오른 달 ──",
                 "설명": "달 단위 복리라 해석 가능 — 지적하신 구간을 여기서 직접 찾을 수 있다"})
    for t in tks:
        st, r, _ = _pack(t)
        ok = r.notna() & st.notna()
        st2, r2 = st[ok], r[ok]
        low = st2.isin([NU, DN])
        if int(low.sum()) < 10:
            continue
        ym = pd.Series(r2.index.to_period("M").astype(str), index=r2.index)
        g = pd.DataFrame({"ym": ym[low], "r": r2[low]}).groupby("ym").agg(
            일수=("r", "size"), 수익=("r", lambda x: (1 + x).prod() - 1))
        g = g[g["일수"] >= 5].sort_values("수익", ascending=False).head(3)
        for k, v in g.iterrows():
            rows.append({"블록": "C. 크게 틀린 구간", "섹터": t, "구분": f"방어적이었는데 오름 · {k}",
                         "표본일수": int(v["일수"]), "그 달 수익(%)": round(float(v["수익"]) * 100, 2)})
        hi = st2.eq(UP)
        if int(hi.sum()) >= 10:
            g2 = pd.DataFrame({"ym": ym[hi], "r": r2[hi]}).groupby("ym").agg(
                일수=("r", "size"), 수익=("r", lambda x: (1 + x).prod() - 1))
            g2 = g2[g2["일수"] >= 5].sort_values("수익").head(2)
            for k, v in g2.iterrows():
                rows.append({"블록": "C. 크게 틀린 구간", "섹터": t, "구분": f"상승예측인데 빠짐 · {k}",
                             "표본일수": int(v["일수"]), "그 달 수익(%)": round(float(v["수익"]) * 100, 2)})

    rows.append({"블록": "D. 연도별 상승예측 기저대비(%p)", "섹터": "── 어느 해에 흔들렸나 ──",
                 "설명": "값은 '그 해 상승예측 적중률 - 그 해 기저 상승률'(%p). 음수면 그 해엔 정보가 없었다"})
    for t in tks:
        st, r, C = _pack(t)
        f1 = C.shift(-2) / C.shift(-1) - 1
        ok = f1.notna() & st.notna()
        st2, f2 = st[ok], f1[ok]
        yr = pd.Series(f2.index.year, index=f2.index)
        row = {"블록": "D. 연도별 상승예측 기저대비(%p)", "섹터": t}
        for y in sorted(set(yr)):
            my = yr.eq(y)
            mu = my & st2.eq(UP)
            if int(mu.sum()) >= 5 and int(my.sum()) >= 20:
                row[str(y)] = round((float((f2[mu] > 0).mean()) - float((f2[my] > 0).mean())) * 100, 1)
        rows.append(row)

    # ---- E. 기저 대비 '반대 방향' 정확도 [v0.40.0 §S4 신설] ------------------------
    # 사용자 질문 그대로: "실제 상승이 많은 섹터는 하락 정확도가 높은지, 반대도 마찬가지".
    # 기저↑ 내림차순으로 정렬해 **위쪽(상승이 많은 섹터)에서는 하락 판정을, 아래쪽에서는 상승 판정을**
    # 먼저 보게 한다. 적중률만으로는 부족하다 — 적중률이 올라도 그 판정 뒤 실제 수익이 무조건 평균보다
    # 높으면 '반등을 놓치는 하락 판정'이다(리포트39 XLY: 적중 +6.5%p인데 하락 뒤 μ +2.11% > 전체 +0.99%).
    # 그래서 세 값을 나란히 둔다: 기저 대비 적중(%p) · 판정 뒤 평균수익 − 무조건 평균 · MCC.
    # MCC는 상승/하락 판정만(중립 제외) 쓰는 기저율 무관 방향 판별력 — 0이면 동전, 음수면 거꾸로.
    h_main = 21 if 21 in horizons else horizons[-1]
    rows.append({"블록": "E. 기저 대비 반대방향", "섹터": f"── 상승 많은 섹터의 '하락' 정확도 (h={h_main}일) ──",
                 "설명": "기저↑ 내림차순. 위쪽은 하락 판정을, 아래쪽은 상승 판정을 본다. "
                        "적중이 올라도 '판정후μ−전체μ'가 양수면 반등을 놓치는 판정이고, MCC<0이면 방향이 거꾸로다"})
    e_rows: List[dict] = []
    for t in tks:
        st, r, C = _pack(t)
        for h in horizons:
            f = C.shift(-h - 1) / C.shift(-1) - 1
            m = f.notna() & st.notna()
            if int(m.sum()) < 60:
                continue
            fm, sm = f[m], st[m]
            bu = float((fm > 0).mean()); mu_all = float(fm.mean())
            mup, mdn = sm.eq(UP), sm.eq(DN)
            row = {"블록": "E. 기저 대비 반대방향", "섹터": t, "구분": f"h={h}일", "표본일수": int(m.sum()),
                   "기저 상승": round(bu, 4), "무조건 평균수익(%)": round(mu_all * 100, 3)}
            if int(mdn.sum()) >= 5:
                hd = float((fm[mdn] <= 0).mean()); md_mu = float(fm[mdn].mean())
                row["하락예측 일수"] = int(mdn.sum())
                row["하락 적중"] = round(hd, 4)
                row["하락 기저대비(%p)"] = round((hd - (1 - bu)) * 100, 2)
                row["하락후 평균수익(%)"] = round(md_mu * 100, 3)
                row["하락후μ − 전체μ(%p)"] = round((md_mu - mu_all) * 100, 3)
                row["하락 판정"] = ("정보 있음" if (hd - (1 - bu)) > 0.005 and md_mu < mu_all else
                                 ("적중↑·수익은 반대" if (hd - (1 - bu)) > 0.005 else
                                  ("적중↓·수익은 맞음" if md_mu < mu_all else "역방향")))
            if int(mup.sum()) >= 5:
                hu = float((fm[mup] > 0).mean()); mu_mu = float(fm[mup].mean())
                row["상승예측 일수"] = int(mup.sum())
                row["상승 적중"] = round(hu, 4)
                row["상승 기저대비(%p)"] = round((hu - bu) * 100, 2)
                row["상승후 평균수익(%)"] = round(mu_mu * 100, 3)
                row["상승후μ − 전체μ(%p)"] = round((mu_mu - mu_all) * 100, 3)
                row["상승 판정"] = ("정보 있음" if (hu - bu) > 0.005 and mu_mu > mu_all else
                                 ("적중↑·수익은 반대" if (hu - bu) > 0.005 else
                                  ("적중↓·수익은 맞음" if mu_mu > mu_all else "역방향")))
            # MCC(중립 제외) — 기저율에 무관한 방향 판별력
            sub = sm.isin([UP, DN])
            if int(sub.sum()) >= 60 and int((sm[sub].eq(DN)).sum()) >= 10:
                ss, ff = sm[sub], fm[sub]
                tp = float(((ss.eq(UP)) & (ff > 0)).sum()); fn = float(((ss.eq(DN)) & (ff > 0)).sum())
                tn = float(((ss.eq(DN)) & (ff <= 0)).sum()); fp = float(((ss.eq(UP)) & (ff <= 0)).sum())
                den = math.sqrt(max((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn), 0.0))
                row["MCC"] = round((tp * tn - fp * fn) / den, 4) if den > 0 else np.nan
            e_rows.append(row)
    if e_rows:
        eh = [x for x in e_rows if x["구분"] == f"h={h_main}일"]
        order = [x["섹터"] for x in sorted(eh, key=lambda z: -float(z.get("기저 상승", 0)))]
        rank = {t: i for i, t in enumerate(order)}
        e_rows.sort(key=lambda z: (rank.get(z["섹터"], 999), int(str(z["구분"]).split("=")[1].rstrip("일"))))
        rows.extend(e_rows)
        n_neg = sum(1 for x in eh if pd.notna(x.get("MCC", np.nan)) and float(x.get("MCC", 0)) < 0)
        n_rev = sum(1 for x in eh if float(x.get("하락후μ − 전체μ(%p)", -1) or -1) > 0)
        rows.append({"블록": "E. 기저 대비 반대방향", "섹터": "요약", "구분": f"h={h_main}일",
                     "설명": f"MCC<0(방향 판별력이 동전 이하) {n_neg}/{len(eh)}개 섹터 · "
                            f"하락 판정 뒤 수익이 무조건 평균보다 높은(반등을 놓친) 섹터 {n_rev}/{len(eh)}개"})

    # ---- F. 꼬리 포착 [v0.40.0 §S4 신설] ------------------------------------------
    # "하락을 제대로 회피하는가"를 적중률이 아니라 **비중**으로 본다. 최악 10% 구간 시작일의 상태
    # 분포와 그날 목표비중이 전체 평균 대비 얼마였나. 목표비중 배율이 1.0이면 무차별이다.
    rows.append({"블록": "F. 꼬리 포착", "섹터": f"── 최악·최고 10% {h_main}일 구간 시작일 (h={h_main}) ──",
                 "설명": "최악 구간을 하락/중립으로 잡았나, 그날 목표비중을 실제로 줄였나(배율<1.0이어야 함)"})
    for t in tks:
        st, r, C = _pack(t)
        pos = results[t].get("target_pos")
        f = C.shift(-h_main - 1) / C.shift(-1) - 1
        m = f.notna() & st.notna()
        if int(m.sum()) < 120:
            continue
        fm, sm = f[m], st[m]
        pm = pd.Series(pos).reindex(fm.index).astype(float) if pos is not None else pd.Series(np.nan, index=fm.index)
        q10, q90 = float(fm.quantile(0.10)), float(fm.quantile(0.90))
        worst, best = fm <= q10, fm >= q90
        base_pos = float(pm.mean()) if pm.notna().any() else np.nan
        rows.append({"블록": "F. 꼬리 포착", "섹터": t, "표본일수": int(m.sum()),
                     "최악10% 일수": int(worst.sum()),
                     "최악10%: 하락상태": round(float(sm[worst].eq(DN).mean()), 4),
                     "최악10%: 중립": round(float(sm[worst].eq(NU).mean()), 4),
                     "최악10%: 상승(놓침)": round(float(sm[worst].eq(UP).mean()), 4),
                     "최악10% 평균 목표비중": (round(float(pm[worst].mean()), 4) if pm.notna().any() else np.nan),
                     "전체 평균 목표비중": (round(base_pos, 4) if base_pos == base_pos else np.nan),
                     "최악10% 비중배율": (round(float(pm[worst].mean()) / base_pos, 3)
                                    if (base_pos == base_pos and base_pos > 0) else np.nan),
                     "최고10%: 상승상태": round(float(sm[best].eq(UP).mean()), 4),
                     "최고10%: 하락(놓침)": round(float(sm[best].eq(DN).mean()), 4),
                     "최고10% 비중배율": (round(float(pm[best].mean()) / base_pos, 3)
                                    if (base_pos == base_pos and base_pos > 0) else np.nan)})
    return pd.DataFrame(rows)


def build_prediction_accuracy(alloc: Dict[str, Any],
                              horizons: Tuple[int, ...] = (1, 5, 21, 63)) -> pd.DataFrame:
    """[v0.14.0] 13l_예측정확도 — 사용자 판단기준("국면·섹터별 상승/하락을 제대로 예측해서 수익을 얻고
    하락을 제대로 회피하는거야 … 정확도가 중요해")을 매 실행이 스스로 채점하는 진단 시트.
    배분 규칙은 전혀 건드리지 않는다(순수 관측·사후 측정).

    사용자가 리포트를 보고 반복해서 지적한 것은 "섹터별 일별 예측을 보면 맞는게 별로 없는거 같아"였다.
    리포트16 실측으로 그 지적은 **맞고**, 동시에 이 시스템이 원래 노리는 지평이 하루가 아니라는 것도
    같이 드러났다 — 그래서 두 사실을 한 표에 나란히 놓는다.

      A. 지평별 리더 적중률 : 그날 지정된 1위 섹터가 이후 h일 동안 SPY를 이겼는가.
         비교 기준선은 '섹터를 무작위로 고른 것'(=상장 섹터 동일가중)이다. 이게 없으면 50%가
         좋은 건지 나쁜 건지 알 수 없다.
      B. 확신 게이트의 효과 : 게이트 통과일 / 미달일 / 해당없음(폴백)일로 나눈 같은 지표.
         게이트가 실제로 좋은 날만 통과시키고 있는지 — 커버리지를 넓혀도 되는지의 근거.
      C. 큰 움직임 포착·회피 : 상위/하위 5% SPY 일에 포트폴리오 총노출이 평소 대비 얼마였나.
         1.0이면 무차별, 상승에서 높고 하락에서 낮아야 '정확한' 배분이다.
      D. 연도별 커버리지 : 리더 지정일수와 그해 초과수익. 어느 해에 이 계층이 일을 안 했는지.
    """
    if not alloc:
        return pd.DataFrame()
    lead = alloc.get("leader")
    ret  = alloc.get("ret_cc")
    spy  = alloc.get("spy_ret")
    if lead is None or ret is None or spy is None or len(ret) == 0:
        return pd.DataFrame()
    idx  = ret.index
    lead = pd.Series(lead).reindex(idx)
    spy  = pd.Series(spy).reindex(idx).astype(float)
    cols = [c for c in alloc.get("cols", []) if c in ret.columns]
    if len(cols) < 4:
        return pd.DataFrame()
    R = ret[cols].astype(float)
    logs = np.log1p(R.where(R.notna()))
    lspy = np.log1p(spy)
    # [v0.42.0 S-L ⚠ 정의 수정 — REPORT45 §2.5-1] 종전 isL은 `lead.isin(cols)`였는데 alloc["leader"]는
    #   **현금일(E_t=0)에도 남는 '잠재 리더'**라 리포트41에서 858일로 세어졌다. 실제로 그 섹터를 들고 있던
    #   날(13c 판단="리더")은 531일이고, 하락 국면 152일은 대부분 현금일이었다 — 둘을 한 열에 섞으면
    #   '리더 적중률'이 운용과 무관한 숫자가 된다. → A·B·D·E 블록은 **실보유일**만 센다.
    #   잠재 리더의 성과는 버리지 않고 블록 F로 따로 낸다(하락국면리더 격자의 판정 근거).
    tier_s = pd.Series(alloc.get("tier")).reindex(idx).astype(str) if alloc.get("tier") is not None \
        else pd.Series("", index=idx)
    held = tier_s.eq("리더") | tier_s.eq("하락국면리더")      # 실제로 그 섹터 하나를 들고 있던 날
    isL  = lead.isin(cols) & held
    isLatent = lead.isin(cols) & ~held                       # 지목은 됐지만 들고 있지 않은 날(현금·폴백)
    gate = pd.Series(alloc.get("gate")).reindex(idx).astype(str) if alloc.get("gate") is not None \
        else pd.Series("", index=idx)

    rows: List[dict] = []
    def _fwd(x: pd.Series, h: int) -> pd.Series:
        return x.rolling(h).sum().shift(-h)          # t+1..t+h 로그수익 합(사후 측정 전용)

    # ---------- A. 지평별 리더 적중률 ----------
    rows.append({"블록": "A. 지평별 리더 적중률", "구분": "── 리더가 SPY를 이긴 비율(실보유일만) ──",
                 "설명": "[v0.42.0 S-L] 표본 = 13c 판단이 '리더'·'하락국면리더'인 날(그 섹터를 실제로 들고 있던 날). "
                         "지목만 되고 현금이었던 날은 블록 F로 분리했다."})
    for h in horizons:
        fS = _fwd(lspy, h)
        fR = pd.DataFrame({c: _fwd(logs[c], h) for c in cols})
        m  = isL & fS.notna()
        if int(m.sum()) < 30:
            continue
        lr = pd.Series([fR.loc[i, lead.loc[i]] for i in idx[m]], index=idx[m])
        sp = fS[m]
        eq = fR.loc[m, cols].mean(axis=1)            # 무작위 섹터 선택의 기대치
        ok = lr.notna() & sp.notna()
        rows.append({"블록": "A. 지평별 리더 적중률", "구분": f"h={h}일",
                     "표본일수": int(ok.sum()),
                     "리더>SPY 비율": round(float((lr[ok] > sp[ok]).mean()), 4),
                     "무작위섹터>SPY 비율": round(float((eq[ok] > sp[ok]).mean()), 4),
                     "리더 평균초과(%/지평)": round(float(np.expm1(lr[ok] - sp[ok]).mean()) * 100, 4),
                     "무작위 평균초과(%/지평)": round(float(np.expm1(eq[ok] - sp[ok]).mean()) * 100, 4),
                     "리더 상승확률": round(float((lr[ok] > 0).mean()), 4),
                     "SPY 상승확률": round(float((sp[ok] > 0).mean()), 4)})
    rows.append({"블록": "A. 지평별 리더 적중률", "구분": "해석",
                 "설명": "일별(h=1)은 동전던지기에 가깝고 h가 길수록 벌어진다면, 이 계층의 예측은 "
                         "'내일 오를 섹터'가 아니라 '앞으로 몇 주 앞설 섹터'다. 리포트를 일별로 읽으면 "
                         "맞는 게 없어 보이는 것이 정상이다."})

    # ---------- B. 확신 게이트의 효과 ----------
    hB = horizons[-2] if len(horizons) >= 2 else horizons[-1]
    fS = _fwd(lspy, hB)
    fR = pd.DataFrame({c: _fwd(logs[c], hB) for c in cols})
    rank = alloc.get("composite_all_smooth", alloc.get("composite"))
    cand = None
    if rank is not None:
        rk = pd.DataFrame(rank).reindex(index=idx)
        rk = rk[[c for c in cols if c in rk.columns]]
        if rk.shape[1] >= 4:
            has = rk.notna().any(axis=1)
            cand = pd.Series(index=idx, dtype=object)
            cand.loc[has] = rk.loc[has].idxmax(axis=1)
    rows.append({"블록": f"B. 확신 게이트 효과 (h={hB}일)", "구분": "── 게이트가 좋은 날만 통과시키나 ──"})
    for nm, m in (("게이트 통과 = 실제 리더일", isL & fS.notna()),
                  ("게이트 미달 = 폴백", (~isL) & gate.eq("미달") & fS.notna()),
                  ("게이트 해당없음 = 폴백", (~isL) & (~gate.eq("미달")) & fS.notna())):
        pick = lead if "통과" in nm else cand
        if pick is None or int(m.sum()) < 30:
            continue
        mm = m & pick.notna() & pick.isin(cols)
        if int(mm.sum()) < 30:
            continue
        lr = pd.Series([fR.loc[i, pick.loc[i]] for i in idx[mm]], index=idx[mm])
        sp = fS[mm]; ok = lr.notna() & sp.notna()
        rows.append({"블록": f"B. 확신 게이트 효과 (h={hB}일)", "구분": nm,
                     "표본일수": int(ok.sum()),
                     "1위>SPY 비율": round(float((lr[ok] > sp[ok]).mean()), 4),
                     "1위 평균초과(%/지평)": round(float(np.expm1(lr[ok] - sp[ok]).mean()) * 100, 4)})
    rows.append({"블록": f"B. 확신 게이트 효과 (h={hB}일)", "구분": "해석",
                 "설명": "통과일의 '1위>SPY 비율'이 미달·해당없음일보다 뚜렷이 높다면 게이트는 제 일을 하고 "
                         "있고 커버리지를 넓히면 오히려 희석된다. 반대라면 게이트가 좋은 신호를 버리고 있다."})

    # ---------- C. 큰 움직임 포착·회피 ----------
    W = alloc.get("target_w")
    if W is not None and len(W):
        gross = pd.DataFrame(W).reindex(idx).sum(axis=1).shift(1)   # 그날 실제 보유(다음날 체결 정렬)
        ok = gross.notna() & spy.notna()
        g, sp2 = gross[ok], spy[ok]
        base = float(g.mean())
        rows.append({"블록": "C. 큰 움직임 포착·회피", "구분": "── 총노출 배율(1.0=무차별) ──",
                     "설명": f"전체 평균 총노출 {base:.4f}"})
        if base > 1e-9:
            for q, lab, cmp_ in ((0.95, "상위 5% 상승일", "높을수록 좋음"), (0.90, "상위10% 상승일", "높을수록 좋음"),
                                 (0.10, "하위10% 하락일", "낮을수록 좋음"), (0.05, "하위 5% 하락일", "낮을수록 좋음")):
                sel = (sp2 >= sp2.quantile(q)) if q >= 0.5 else (sp2 <= sp2.quantile(q))
                rows.append({"블록": "C. 큰 움직임 포착·회피", "구분": lab,
                             "표본일수": int(sel.sum()),
                             "평균 총노출": round(float(g[sel].mean()), 4),
                             "평균 대비 배율": round(float(g[sel].mean() / base), 3),
                             "설명": cmp_})

    # ---------- D. 연도별 커버리지 ----------
    rows.append({"블록": "D. 연도별 커버리지", "구분": "── 이 계층이 실제로 일한 해 ──"})
    yr = pd.Series(idx.year, index=idx)
    for y in sorted(set(yr)):
        m = yr.eq(y)
        rows.append({"블록": "D. 연도별 커버리지", "구분": str(y),
                     "표본일수": int(m.sum()),
                     "리더 지정일": int((isL & m).sum()),
                     "리더 비율": round(float((isL & m).mean() if m.sum() else np.nan), 4)})

    # ---------- [v0.41.0 S-B] E. SPY 국면별 리더 적중률 ----------
    # 왜(REPORT44 §2.1 증거2): 리더 정보는 **M=중립 국면에만** 있다(재계산 SCORE_PCT 1위−평균:
    #   중립 t 3.50 · 상승 t 0.53 · 하락 t 0.31; 13i도 중립 +2.82 / 상승 +0.32). S-B(중립 리더슬롯 격자)의
    #   판정 기준이 "중립 부분집합의 리더>SPY 비율 ≥ 0.60"이므로 그 숫자를 여기서 직접 낸다.
    reg = alloc.get("spy_state_short")
    if reg is not None:
        reg = pd.Series(reg).reindex(idx).astype(str)
        hE = 21 if 21 in horizons else horizons[-1]
        fS = _fwd(lspy, hE)
        fR = pd.DataFrame({c: _fwd(logs[c], hE) for c in cols})
        rows.append({"블록": f"E. SPY 국면별 리더 적중률 (h={hE}일)", "구분": "── 리더 정보가 어느 국면에 있나 ──"})
        for lab in ("상승", "중립", "하락"):
            m = isL & fS.notna() & reg.eq(lab)
            if int(m.sum()) < 20:
                rows.append({"블록": f"E. SPY 국면별 리더 적중률 (h={hE}일)", "구분": lab,
                             "표본일수": int(m.sum()), "설명": "표본 부족(<20일)"})
                continue
            lr = pd.Series([fR.loc[i, lead.loc[i]] for i in idx[m]], index=idx[m])
            sp = fS[m]
            eq = fR.loc[m, cols].mean(axis=1)
            ok = lr.notna() & sp.notna()
            if int(ok.sum()) < 20:
                continue
            rows.append({"블록": f"E. SPY 국면별 리더 적중률 (h={hE}일)", "구분": lab,
                         "표본일수": int(ok.sum()),
                         "리더>SPY 비율": round(float((lr[ok] > sp[ok]).mean()), 4),
                         "무작위섹터>SPY 비율": round(float((eq[ok] > sp[ok]).mean()), 4),
                         "리더 평균초과(%/지평)": round(float(np.expm1(lr[ok] - sp[ok]).mean()) * 100, 4)})
        rows.append({"블록": f"E. SPY 국면별 리더 적중률 (h={hE}일)", "구분": "해석",
                     "설명": "중립 국면의 '리더>SPY 비율'이 0.60 이상이고 상승 국면보다 뚜렷이 높으면 "
                             "[중립상한격자] 행을 채택 후보로 본다(격자 4기준을 함께 통과해야 채택)."})

    # ---------- [v0.42.0 S-L] F. 잠재 리더(지목됐지만 안 들고 있던 날) ----------
    # 왜 따로 내나: 이 날들은 대부분 E_t=0(현금)이라 '리더 적중률'과 섞으면 운용과 무관한 숫자가 된다.
    #   그러나 그 자체로는 정보다 — [하락리더격자](E_t=0에도 명확1위를 들면?)의 판정 근거가 여기 있다.
    if int(isLatent.sum()) >= 30:
        hF = 21 if 21 in horizons else horizons[-1]
        fS = _fwd(lspy, hF)
        fR = pd.DataFrame({c: _fwd(logs[c], hF) for c in cols})
        rows.append({"블록": f"F. 잠재 리더(지목·미보유) (h={hF}일)", "구분": "── 판단은 났지만 현금이었던 날 ──"})
        for nm, m in (("전체", isLatent & fS.notna()),
                      ("그중 현금일(E_t=0)", isLatent & tier_s.eq("현금") & fS.notna()),
                      ("그중 폴백·기타", isLatent & ~tier_s.eq("현금") & fS.notna())):
            if int(m.sum()) < 30:
                continue
            lr = pd.Series([fR.loc[i, lead.loc[i]] for i in idx[m]], index=idx[m])
            sp = fS[m]
            ok = lr.notna() & sp.notna()
            if int(ok.sum()) < 30:
                continue
            rows.append({"블록": f"F. 잠재 리더(지목·미보유) (h={hF}일)", "구분": nm,
                         "표본일수": int(ok.sum()),
                         "리더>SPY 비율": round(float((lr[ok] > sp[ok]).mean()), 4),
                         "리더 평균초과(%/지평)": round(float(np.expm1(lr[ok] - sp[ok]).mean()) * 100, 4),
                         "리더 상승확률": round(float((lr[ok] > 0).mean()), 4)})
        rows.append({"블록": f"F. 잠재 리더(지목·미보유) (h={hF}일)", "구분": "해석",
                     "설명": "'리더 상승확률'이 높고 초과도 양수면, E_t=0이어도 그 섹터를 드는 규칙"
                             "([하락리더격자]·ROTATION_DOWN_REGIME_POS)이 값을 한다는 뜻이다. "
                             "블록 A와 합치지 않는다 — 운용 중이던 날이 아니기 때문."})
    return pd.DataFrame(rows)


def build_sector_vs_m_attribution(sres: dict, alloc: Dict[str, Any],
                                  results: Dict[str, Dict[str, Any]], scfg: "SectorConfig") -> pd.DataFrame:
    """[v0.23.0] 13n_섹터대M귀속 — **"국면 판단이 잘나온 것에 비해 섹터 수익률이 안 나온다"**는
    사용자 지적을 매 실행이 스스로 채점하는 시트. 배분 규칙은 전혀 건드리지 않는 순수 관측이다.

    왜 필요한가(리포트24 실측 진단):
      주 전략 ★는 CAGR 29.24%로 M(22.49%)보다 +6.75pp 높은데, **샤프 1.958 < M 2.027 ·
      MDD -10.49% vs -7.07% · 칼마 2.787 < M 3.182**로 위험조정 지표가 전부 M보다 나쁘다.
      즉 섹터층은 M의 신호를 **더 높은 베타로 바꿔놓기만** 하고 위험조정 가치를 더하지 못한다.
      그 원인을 일별로 귀속시키면 다음이 보인다(리포트24):
        · 시장 큰상승일(상위 5%) 110일: 섹터가 M보다 **+6.1%p** 더 번다
        · 시장 큰하락일(하위 5%) 110일: 섹터가 M보다 **-15.5%p** 더 잃는다
        → 꼬리 순합 약 -9.4%p. 칼마 격차는 사실상 전부 여기서 나온다.
      또 하나의 구조적 사실: '순환매'라고 부르지만 **리더 판단은 504일(24%)뿐이고 폴백이 995일(47%)**
      이며, 2018~2020년은 **리더 판단이 0일**이다(워크포워드 채택 기준을 통과한 순환매 신호가
      그 시기에 없었다 — 13g 로그의 t통계가 전부 미달). 즉 초기 40% 구간의 '순환매'는 사실상
      주력+균등 슬리브 보유였다. 이것은 결함이 아니라 정직한 동작이지만, **기대와 실제의 간극**을
      매 실행에서 보이게 해야 오해가 없다.
      ⚠ 이번 라운드에 시도해 전부 기각한 것(다시 시도하지 말 것):
        (a) 주력 상한 격자 0.5~1.0 — **0.8이 이미 칼마 정점**(2.787), 낮추면 CAGR만 1:1로 준다.
        (b) 바스켓 위험 정규화(=M위험 / 1.15배 / 1.30배 상한) — 샤프는 1.948 → 1.975까지 오르지만
            칼마가 2.772 → 2.807에 그쳐 M의 3.182에 못 미치고 CAGR을 3.7~6.5pp 잃는다.
            배수(1.15/1.30)는 격자탐색이라 채택 대상도 아니다.
        (c) 주력 비중 = XLK 자체 목표비중(0~1) 스케일 — 칼마 2.720~2.736으로 오히려 악화,
            연도별 부호도 2/9·3/9로 불안정.
    """
    try:
        pc = sres.get("portfolio_curve")
        pp = sres.get("portfolio_perf")
        if pc is None or len(pc) == 0 or pp is None or len(pp) == 0:
            return pd.DataFrame()
        if not alloc or "spy_m_ret" not in alloc:
            return pd.DataFrame()
        curve = pc.copy()
        if "날짜" in curve.columns:
            curve["날짜"] = pd.to_datetime(curve["날짜"]); curve = curve.set_index("날짜")
        curve = curve.sort_index()
        star = None
        for c in curve.columns:
            if str(c).endswith("★"):
                star = c; break
        if star is None:
            star = curve.columns[0]
        sr = curve[star].astype(float).pct_change()
        mrr = pd.Series(alloc["spy_m_ret"]).reindex(sr.index).astype(float)
        # 시장 대용치: 11섹터 동일가중 일간수익(SPY 원계열이 이 스코프에 없다 — 꼬리 구간을
        # 가르는 용도로만 쓰며, 시트에도 '11섹터 균등' 기준임을 명시한다).
        _rr = {t: pd.Series(results[t]["ret_cc_full"]) for t in results
               if isinstance(results.get(t), dict) and results[t].get("ret_cc_full") is not None}
        mkt = pd.DataFrame(_rr).reindex(sr.index).mean(axis=1).astype(float) if _rr else None
        ok = sr.notna() & mrr.notna()
        sr, mrr = sr[ok], mrr[ok]
        if len(sr) < 120:
            return pd.DataFrame()
        exr = sr - mrr
        rows: List[dict] = []
        rows.append({"블록": "A. 총괄", "구분": "── 섹터 주 전략 vs SPY 국면전략(M) ──",
                     "설명": "CAGR만 보지 말 것 — 위험조정에서 M을 넘는지가 이 층의 존재 이유다"})
        rows.append({"블록": "A. 총괄", "구분": "일별 초과수익(섹터 − M)", "일수": int(len(exr)),
                     "연율(%p)": round(float(exr.mean()) * 252 * 100, 2),
                     "초과 변동성(%)": round(float(exr.std()) * np.sqrt(252) * 100, 2),
                     "정보비율(IR)": round(float(exr.mean() / exr.std() * np.sqrt(252)), 3) if float(exr.std()) > 0 else np.nan,
                     "양수일 비율": round(float((exr > 0).mean()), 4)})
        eqe = (1.0 + exr).cumprod()
        rows.append({"블록": "A. 총괄", "구분": "초과수익 곡선 최대낙폭",
                     "연율(%p)": round(float((eqe / eqe.cummax() - 1).min()) * 100, 2),
                     "설명": "초과수익이 꾸준한지, 특정 구간에 몰려 있는지"})
        if mkt is not None and mkt.notna().sum() > 200:
            mk = mkt[exr.index]
            hi, lo = mk.quantile(0.95), mk.quantile(0.05)
            rows.append({"블록": "B. 꼬리 귀속", "구분": "── 칼마 격차가 어디서 나오나 ──",
                         "설명": "큰하락일에 섹터가 M보다 더 잃으면 그것이 곧 낙폭 격차다 (꼬리 구분 기준: 11섹터 동일가중)"})
            for nm, msk in (("시장 큰상승일(상위5%)", mk >= hi), ("시장 큰하락일(하위5%)", mk <= lo),
                            ("나머지 날", (mk > lo) & (mk < hi))):
                if int(msk.sum()) < 5:
                    continue
                rows.append({"블록": "B. 꼬리 귀속", "구분": nm, "일수": int(msk.sum()),
                             "섹터 합(%)": round(float(sr[msk].sum()) * 100, 2),
                             "M 합(%)": round(float(mrr[msk].sum()) * 100, 2),
                             "차이(%p)": round(float(exr[msk].sum()) * 100, 2)})
        rows.append({"블록": "C. 연도별 초과수익", "구분": "── 어느 해에 벌고 어느 해에 잃나 ──"})
        for y, g in exr.groupby(exr.index.year):
            rows.append({"블록": "C. 연도별 초과수익", "구분": str(y), "일수": int(len(g)),
                         "차이(%p)": round(float((1 + g).prod() - 1) * 100, 2)})
        alloc_sheet = sres.get("alloc_sheet")
        if alloc_sheet is not None and len(alloc_sheet) and "판단" in alloc_sheet.columns:
            vc = alloc_sheet["판단"].astype(str).value_counts()
            tot = int(vc.sum())
            rows.append({"블록": "D. 순환매가 실제로 판단한 비율", "구분": "── '순환매'의 실체 ──",
                         "설명": "리더 판단 비율이 낮으면 이 층의 성과는 주력 보유가 만든 것이다"})
            for k, v in vc.items():
                rows.append({"블록": "D. 순환매가 실제로 판단한 비율", "구분": str(k), "일수": int(v),
                             "비중(%)": round(v / max(tot, 1) * 100, 2)})
        return pd.DataFrame(rows)
    except Exception:
        return pd.DataFrame()


def build_drawdown_episodes(sres: dict, alloc: Dict[str, Any], results: Dict[str, Dict[str, Any]],
                            scfg: "SectorConfig", top_n: int = 8) -> pd.DataFrame:
    """[v0.36.0 §B] 13o_낙폭에피소드 — 주 전략(★)의 독립 낙폭 에피소드를 **그 구간에 어떤 판단이
    내려져 있었는지**로 귀속시킨다. 배분 규칙은 전혀 건드리지 않는 순수 관측 시트다.

    왜 필요한가(리포트36에서 손으로 뽑아 본 결과 — 이번 라운드 최대 발견):
      ★의 최대낙폭 -9.75%는 **2019-04-24 ~ 2019-06-19**에 났는데, 그 40일 내내
        · M 시장상황 = 상승(위험선호) — 40일 전부
        · E_t = 1.00 — 40일 전부 (M은 한 번도 줄이지 않았다)
        · XLK 자기 국면 = 상승(위험선호) — 40일 전부
        · H 백분위 최고 0.64 (HAZARD_ENTER 0.90 근처에도 못 감)
      구간 누적은 SPY **+0.06%** vs XLK **-1.31%**, 저점에서는 SPY -6.6% vs XLK -9.8%.
      즉 **국면 판단이 틀린 사건이 아니라, 시장은 옳게 봤는데 주력 섹터 하나가 따로 빠진 사건**이다.
      M 자신의 같은 구간 낙폭은 -6.61%로, 격차 3.14%p가 통째로 90% 집중의 대가다.
      상위 6개 에피소드 중 4개가 상승(위험선호) 국면에서 저점을 찍는다 — 그래서 위험(H)·국면에
      연동한 조건부 축소는 원리적으로 이 낙폭을 줄일 수 없다(v0.36.0 §C 상대강도 가드 18/18 기각).

    이 시트가 있으면 매 라운드 같은 작업을 손으로 반복하지 않아도 된다.
    """
    try:
        pc = sres.get("portfolio_curve") if isinstance(sres, dict) else None
        if pc is None or not isinstance(pc, pd.DataFrame) or pc.empty:
            return pd.DataFrame()
        curve = pc.copy()
        if "날짜" in curve.columns:
            curve["날짜"] = pd.to_datetime(curve["날짜"]); curve = curve.set_index("날짜")
        curve = curve.sort_index()
        star = next((c for c in curve.columns if str(c).endswith("★")), None)
        if star is None:
            return pd.DataFrame()
        eq = curve[star].astype(float).dropna()
        if len(eq) < 120:
            return pd.DataFrame()
        dd = eq / eq.cummax() - 1.0
        # 독립 낙폭 에피소드(고점 회복 시점에 끊는다)
        eps: List[dict] = []
        cur = None
        for d, v in dd.items():
            if v < 0 and cur is None:
                cur = {"s": d, "e": d, "m": float(v), "t": d}
            elif v < 0:
                cur["e"] = d
                if v < cur["m"]:
                    cur["m"] = float(v); cur["t"] = d
            elif cur is not None:
                eps.append(cur); cur = None
        if cur is not None:
            eps.append(cur)
        if not eps:
            return pd.DataFrame()
        eps = sorted(eps, key=lambda x: x["m"])[:int(top_n)]
        prim = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "XLK")
        E = pd.Series(alloc.get("E")) if isinstance(alloc, dict) and alloc.get("E") is not None else None
        st_m = pd.Series(alloc.get("spy_state_short")) if isinstance(alloc, dict) and alloc.get("spy_state_short") is not None else None
        mrr = pd.Series(alloc["spy_m_ret"]).astype(float) if isinstance(alloc, dict) and "spy_m_ret" in alloc else None
        pst = None
        if prim in results and isinstance(results.get(prim), dict):
            _sh = results[prim].get("sheets", {}).get("daily")
            if isinstance(_sh, pd.DataFrame) and "섹터상황" in _sh.columns and "날짜" in _sh.columns:
                _t = _sh.copy(); _t["날짜"] = pd.to_datetime(_t["날짜"])
                pst = _t.set_index("날짜")["섹터상황"]
        R = {t: pd.Series(results[t]["ret_cc_full"]) for t in results
             if isinstance(results.get(t), dict) and results[t].get("ret_cc_full") is not None}
        pr = R.get(prim)
        rows: List[dict] = []
        rows.append({"구분": "── ★ 독립 낙폭 에피소드 상위 %d ──" % len(eps),
                     "설명": "‘국면 판단이 틀렸나’ vs ‘판단은 옳았는데 주력이 따로 빠졌나’를 가른다"})
        for e in eps:
            seg = slice(e["s"], e["e"])
            rec: dict = {"구분": f"{e['s'].date()}~{e['e'].date()}",
                         "최대낙폭(%)": round(e["m"] * 100, 2),
                         "저점일": str(e["t"].date()),
                         "거래일수": int(((dd.index >= e["s"]) & (dd.index <= e["e"])).sum())}
            if st_m is not None:
                _v = st_m.loc[seg].astype(str)
                if len(_v):
                    _vc = _v.value_counts()
                    rec["구간 최빈 시장상황"] = f"{_vc.index[0]} {int(_vc.iloc[0])}/{len(_v)}일"
                    rec["저점일 시장상황"] = str(st_m.reindex([e["t"]]).iloc[0])
            if E is not None:
                _e = E.loc[seg].astype(float)
                if len(_e):
                    rec["구간 평균 E_t"] = round(float(_e.mean()), 3)
                    rec["구간 최소 E_t"] = round(float(_e.min()), 3)
            if pst is not None:
                _p = pst.loc[seg].astype(str)
                if len(_p):
                    _pc2 = _p.value_counts()
                    rec[f"{prim} 최빈 상태"] = f"{_pc2.index[0]} {int(_pc2.iloc[0])}/{len(_p)}일"
            if pr is not None:
                _x = pr.loc[seg].dropna()
                if len(_x):
                    rec[f"{prim} 구간수익(%)"] = round(float((1.0 + _x).prod() - 1.0) * 100, 2)
            if mrr is not None:
                _m2 = mrr.loc[seg].dropna()
                if len(_m2):
                    rec["M 구간수익(%)"] = round(float((1.0 + _m2).prod() - 1.0) * 100, 2)
                    _me = (1.0 + mrr.loc[:e["e"]].dropna()).cumprod()
                    _md = (_me / _me.cummax() - 1.0).loc[seg]
                    if len(_md):
                        rec["M 동기간 낙폭(%)"] = round(float(_md.min()) * 100, 2)
                        rec["집중 대가(%p)"] = round(rec["최대낙폭(%)"] - rec["M 동기간 낙폭(%)"], 2)
            rows.append(rec)
        rows.append({"구분": "── 판정 ──",
                     "설명": "‘저점일 시장상황 = 상승(위험선호)’ 이면 국면 판단 오류가 아니라 집중 위험이다 — "
                             "위험(H)·국면 연동 축소로는 줄일 수 없고, 상한/대피처 같은 구조 레버만 듣는다"})
        return pd.DataFrame(rows)
    except Exception as _e:                                     # pragma: no cover
        log("ROTATION", kv(event="drawdown_episodes_failed", err=str(_e)[:160]), level="warning")
        return pd.DataFrame()


def build_sleeve_attribution(alloc: Dict[str, Any], results: Dict[str, Dict[str, Any]],
                             scfg: "SectorConfig") -> pd.DataFrame:
    """[v0.21.0] 13m_잔여슬리브기여 — 주력섹터(XLK) 상한 밖으로 나간 '잔여 슬리브'가 실제로 무엇을
    벌었는지 귀속시킨다. 배분 규칙은 전혀 건드리지 않는 순수 관측 시트다.

    왜 필요한가(리포트22 실측 진단):
      주력섹터 중심 배분에서 XLK는 상한 ROTATION_PRIMARY_CAP(v0.25.2부터 0.9, 종전 0.8)까지만 담고 나머지는
      대피 후보들에게 간다. 그런데 **대피 경로(XLK 미보유)는 43일(2.0%)뿐**이고, 실제로 비주력
      섹터가 돈을 받는 날의 대부분은 'XLK를 들고 있는 1486일의 잔여 20%'다. 성과 진단이 대피
      경로만 보면 표본의 2%만 보는 셈이라, 슬리브 쪽을 상설로 드러낸다.
      리포트22 실측: 슬리브 실제 +29.20% vs 10섹터 균등 +20.85% → **선택이 균등보다 낫다**(작동함).
      다만 같은 비중을 전부 XLK에 넣었으면 +38.87%였다 — 그 차이가 집중위험의 대가다
      (상한 1.0은 v0.16.0에서 MDD -3.39pp 악화로 이미 기각).
      섹터별로는 XLV -0.97% · XLU -0.04% · XLY -0.03%로 새는 곳이 있고, 01Y시트에서 XLV의
      하락 예측이 '역방향'(-3.12%p), XLE는 상·하락 모두 '없음/역방향'으로 찍힌다.
      ⚠ 무정보 섹터 배제는 이전 라운드에서 워크포워드로 시도해 **-2.14pp**로 실패했다.
      그래서 여기서는 규칙을 바꾸지 않고 **관측만** 한다.
    """
    if not alloc or "target_w" not in alloc:
        return pd.DataFrame()
    tw = alloc["target_w"]
    prim = str(getattr(scfg, "ROTATION_PRIMARY_SECTOR", "XLK") or "XLK")
    if prim not in tw.columns:
        return pd.DataFrame()
    tks = [c for c in tw.columns if c in results and results[c].get("ret_cc_full") is not None]
    if not tks:
        return pd.DataFrame()
    R = pd.DataFrame({t: pd.Series(results[t]["ret_cc_full"]) for t in tks}).reindex(tw.index).astype(float)
    others = [c for c in tks if c != prim]
    if not others or prim not in R.columns:
        return pd.DataFrame()
    hold = (tw[prim] > 1e-9) & R[tks].notna().all(axis=1)
    sl_w = tw[others].sum(axis=1)
    m = hold & (sl_w > 1e-9)
    rows: List[dict] = []
    if int(m.sum()) < 20:
        return pd.DataFrame()
    sl_r = (tw[others] * R[others]).sum(axis=1)
    ew = R[others].mean(axis=1)
    rows.append({"블록": "A. 슬리브 총괄", "구분": "── 주력 보유일의 잔여 비중이 무엇을 벌었나 ──",
                 "설명": "같은 비중을 다른 곳에 넣었다면? (산술 누적, 배분 규칙 무변경 관측)"})
    for nm, v in (("실제 배분", sl_r[m]),
                  (f"전부 {prim}", sl_w[m] * R[prim][m]),
                  ("전부 현금", pd.Series(0.0, index=sl_r[m].index)),
                  ("비주력 균등", sl_w[m] * ew[m])):
        rows.append({"블록": "A. 슬리브 총괄", "구분": nm, "일수": int(m.sum()),
                     "평균 슬리브비중": round(float(sl_w[m].mean()), 4),
                     "누적 기여(%)": round(float(v.sum()) * 100, 2),
                     "평균(bp/일)": round(float(v.mean()) * 1e4, 2)})
    rows.append({"블록": "B. 섹터별 귀속", "구분": "── 슬리브 안에서 누가 벌고 누가 새는가 ──",
                 "설명": "누적 기여가 음수인 섹터는 01Y시트의 '상승 정보/하락 정보'와 함께 볼 것"})
    for t in others:
        w = tw[t][m]
        nz = int((w > 1e-9).sum())
        if nz < 5:
            continue
        rows.append({"블록": "B. 섹터별 귀속", "구분": t, "일수": nz,
                     "평균 슬리브비중": round(float(w.mean()), 4),
                     "누적 기여(%)": round(float((w * R[t][m]).sum()) * 100, 2),
                     "평균(bp/일)": round(float(R[t][m].mean()) * 1e4, 2)})
    rows.append({"블록": "C. 대피 경로", "구분": "── 주력 미보유일(대피)은 표본의 몇 %인가 ──",
                 "설명": "여기가 얇으면 '순환매'의 실체는 주력 보유/현금 판단이다"})
    esc = (tw[prim] <= 1e-9) & (tw[others].sum(axis=1) > 1e-9) & R[tks].notna().all(axis=1)
    allw = R[tks].notna().all(axis=1)
    for nm, mm in ((f"{prim} 보유일", hold), ("대피일(비주력만)", esc),
                   ("전액 현금일", allw & (tw[tks].sum(axis=1) <= 1e-9))):
        n = int(mm.sum())
        rows.append({"블록": "C. 대피 경로", "구분": nm, "일수": n,
                     "비중(%)": round(n / max(int(allw.sum()), 1) * 100, 2)})
    # [v0.45.0 G3] 블록 D — 대피처 규칙별 슬리브 기여. 재시뮬레이션이 아니라 [대피처격자] 행이
    #   실제 엔진으로 만든 target_ws를 ★와 **같은 날 마스크(m)** 위에서 다시 합산한 것이라
    #   블록 A의 '실제 배분'과 1:1로 비교된다. 판정 요령: 어떤 규칙도 블록 A의 '비주력 균등'을
    #   뚜렷이 넘지 못하면 잔여 슬리브에서 순환매 판단은 값을 하지 못하는 것이고, 그때는 슬리브를
    #   균등으로 두는 편이 정직하다(REPORT48 §4 — 리포트44 실측 실제 10.64% vs 균등 10.38%).
    _tws_all = (alloc or {}).get("target_ws") or {}
    _sh_labels = [l for l in _tws_all if "[대피처격자" in str(l)]
    if _sh_labels:
        rows.append({"블록": "D. 대피처 규칙 비교", "구분": "── 같은 날(주력 보유일)에 규칙만 바꿨다면 ──",
                     "설명": "[대피처격자] 행의 실제 배분 가중을 블록 A와 같은 마스크로 합산 — "
                             "블록 A '비주력 균등'을 못 넘으면 슬리브의 순환매 판단은 값이 없다"})
        rows.append({"블록": "D. 대피처 규칙 비교", "구분": "복합순위 1위(현행·★)", "일수": int(m.sum()),
                     "평균 슬리브비중": round(float(sl_w[m].mean()), 4),
                     "누적 기여(%)": round(float(sl_r[m].sum()) * 100, 2),
                     "평균(bp/일)": round(float(sl_r[m].mean()) * 1e4, 2)})
        for _lab in sorted(_sh_labels):
            _twv = _tws_all.get(_lab)
            if not isinstance(_twv, pd.DataFrame):
                continue
            _o = [c for c in others if c in _twv.columns]
            if not _o:
                continue
            _wv = _twv[_o].reindex(tw.index)
            _rv = (_wv * R[_o]).sum(axis=1)
            _nm = str(_lab).split("대피처 ")[-1].replace(" [대피처격자]", "")
            rows.append({"블록": "D. 대피처 규칙 비교", "구분": _nm, "일수": int(m.sum()),
                         "평균 슬리브비중": round(float(_wv.sum(axis=1)[m].mean()), 4),
                         "누적 기여(%)": round(float(_rv[m].sum()) * 100, 2),
                         "평균(bp/일)": round(float(_rv[m].mean()) * 1e4, 2)})
    return pd.DataFrame(rows)


def build_regime_sector_structure(alloc: Dict[str, Any], results: Dict[str, Dict[str, Any]],
                                  horizons: Tuple[int, ...] = (1, 5, 21, 63)) -> pd.DataFrame:
    """[v0.12.0] 13k_국면섹터구조 — 사용자 질문("SPY 국면이 오르면 XLK가 오르고, 방어 섹터는 반대 아니냐,
    그 상관관계를 더 철저히 분석해서 국면 정보를 더 참고하라")에 매 실행이 스스로 답하도록 만든 진단 시트.
    배분 규칙은 전혀 건드리지 않는다(순수 관측).

    3개 블록:
      A. 국면×섹터 : SPY 시장상황(상승/중립/하락)별로 각 섹터의 향후 h일 '초과수익'(상장 섹터 평균 대비).
         사용자 가설이 맞다면 상승에서 XLK·XLY가, 하락에서 XLV·XLP·XLU가 양수로 나온다.
      B. 지평 프로파일 : (경기민감 바스켓 − 방어 바스켓)을 국면별·지평별로 NW-HAC t와 함께. **이 표가 핵심이다** —
         구조가 어느 지평에 사는지 보여준다. 배분 계층은 h=ROTATION_HORIZON(기본 21일)·최소보유 21일로 도는데,
         구조가 1~5일에만 있고 21일에서 사라진다면 그 구조는 이 아키텍처로는 못 잡는다는 뜻이다.
      C. 리더 성격 : 그날 복합순위 1위가 방어 섹터일 때와 아닐 때의 상위1 스프레드 — 방어 섹터 1위가 실제로
         약한지, 교차확인·확신 게이트가 이미 그것을 걸러내고 있는지 확인.
    """
    if not alloc or "composite" not in alloc:
        return pd.DataFrame()
    cols = list(alloc.get("cols", []))
    if not cols:
        return pd.DataFrame()
    idx = alloc["composite"].index
    rets = {}
    for t in cols:
        r = results.get(t, {}).get("ret_cc_full")        # 섹터 일간 종가수익(파이프라인 원본 — 리포트 조립과 무관)
        if r is None:
            continue
        r = pd.Series(r).reindex(idx)
        if r.notna().sum() >= 252:
            rets[t] = r
    if len(rets) < 4:
        return pd.DataFrame()
    RET = pd.DataFrame(rets)
    listed = RET.notna()
    lr = np.log1p(RET.where(listed))
    state = alloc.get("spy_state_short")
    state = (state.reindex(idx).astype(str) if state is not None else pd.Series("", index=idx))
    dfn = [t for t in RET.columns if t in ROTATION_DEFENSIVE_SECTORS]
    cyc = [t for t in RET.columns if t not in ROTATION_DEFENSIVE_SECTORS]
    rows: List[Dict[str, Any]] = []

    def _fwd(h):
        return (np.exp(lr.rolling(h).sum().shift(-h)) - 1.0).where(listed)

    # --- A. 국면 × 섹터 초과수익 ---
    for h in horizons:
        f = _fwd(h)
        xsr = f.sub(f.where(listed).mean(axis=1), axis=0)
        for st in ("상승", "중립", "하락"):
            m = (state == st).values
            if int(m.sum()) < 30:
                continue
            for t in RET.columns:
                v = xsr.loc[m, t].dropna()
                if len(v) < 30:
                    continue
                rows.append({"구분": "A. 국면×섹터 초과수익", "지평(일)": h, "국면": st, "항목": t,
                             "일수": int(len(v)), "평균(%/지평)": round(float(v.mean()) * 100, 3),
                             "NW-HAC t": np.nan})
    # --- B. 지평 프로파일: 경기민감 − 방어 ---
    for h in horizons:
        f = _fwd(h)
        g = f[cyc].mean(axis=1) - f[dfn].mean(axis=1) if dfn and cyc else pd.Series(np.nan, index=idx)
        for lab, m in (("전체", np.ones(len(idx), dtype=bool)),
                       ("상승", (state == "상승").values), ("중립", (state == "중립").values),
                       ("하락", (state == "하락").values)):
            v = g[m].dropna()
            if len(v) < 30:
                continue
            mu, tt, nn = _nw_mean_tstat(v, lag=max(h, 1))
            rows.append({"구분": "B. 경기민감−방어(지평 프로파일)", "지평(일)": h, "국면": lab,
                         "항목": f"{'·'.join(cyc[:3])}… − {'·'.join(dfn)}", "일수": int(nn),
                         "평균(%/지평)": round(float(mu) * 100, 3) if pd.notna(mu) else np.nan,
                         "NW-HAC t": round(float(tt), 2) if pd.notna(tt) else np.nan})
    # --- C. 1위가 방어냐 아니냐 ---
    comp = alloc.get("composite_all_smooth", alloc["composite"])
    comp = comp.reindex(index=idx, columns=RET.columns)
    has = comp.notna().any(axis=1)
    top = pd.Series(index=idx, dtype=object)
    if bool(has.any()):
        vals = comp.to_numpy(float)
        arr = np.where(np.isnan(vals), -np.inf, vals)
        pos = np.argmax(arr, axis=1)
        top = pd.Series([RET.columns[p] if ok else None for p, ok in zip(pos, has.values)], index=idx)
    for h in horizons:
        f = _fwd(h)
        xsr = f.sub(f.where(listed).mean(axis=1), axis=0)
        sp = pd.Series(np.nan, index=idx)
        for t in RET.columns:
            m = (top == t).values
            if m.any():
                sp[m] = xsr.loc[m, t].values
        for lab, m in (("1위=방어", top.isin(dfn).values), ("1위=비방어", (top.notna() & ~top.isin(dfn)).values)):
            v = sp[m].dropna()
            if len(v) < 30:
                continue
            mu, tt, nn = _nw_mean_tstat(v, lag=max(h, 1))
            rows.append({"구분": "C. 1위 성격별 상위1 스프레드", "지평(일)": h, "국면": "전체", "항목": lab,
                         "일수": int(nn), "평균(%/지평)": round(float(mu) * 100, 3) if pd.notna(mu) else np.nan,
                         "NW-HAC t": round(float(tt), 2) if pd.notna(tt) else np.nan})
    out = pd.DataFrame(rows)
    if len(out):
        out["해석"] = ""
        b = out["구분"].str.startswith("B.")
        out.loc[b & (out["NW-HAC t"].abs() >= 2.0), "해석"] = "유의(|t|≥2) — 이 지평엔 구조가 있음"
        out.loc[b & (out["NW-HAC t"].abs() < 2.0), "해석"] = "비유의 — 이 지평엔 구조 없음"
    return out


def build_gap_attribution(alloc: Dict[str, Any]) -> pd.DataFrame:
    """[v0.8.0] 13i_SPY대비격차분해: 주 전략 − SPY 국면전략(M)의 일별 초과수익(단순 합, %p)을 연도 × 판단(체결 지연 1일 반영) ×
    리더 섹터로 분해. 리포트 6 판독에서 손으로 하던 분해를 자동화 — '격차가 어느 해·어느 판단·어느 섹터에서 났는가'를 바로 본다.
    전부 진단(배분에 되돌아가지 않음).
    [v0.10.0 §1.B] tiers에 '폴백(여유부족)' 추가(확신 게이트 미달로 리더가 못 된 날의 초과수익을 '폴백'과 분리).
    [v0.10.0 §1.C] '구분'=='SPY 국면'(중립/상승(위험선호)/기타 × 리더일 초과·일수) · '구분'=='여유 4분위'(리더일의 1위
    여유값 Q1~Q4 × 초과·일수) 행 추가 — 둘 다 리더(ld) 마스크 위에서만 정의되며 판단/섹터 분해와 같은 %p·일수 산식."""
    if not alloc or "spy_m_ret" not in alloc:
        return pd.DataFrame()
    lp = alloc["diag"]["label_primary"]
    r_p = alloc["bts"][lp]["strategy_ret"]
    ex = (r_p - alloc["spy_m_ret"].reindex(r_p.index).fillna(0.0)) * 100.0
    tier_x = alloc["tier"].shift(1).fillna("현금")          # t일 판단 → t+1일 체결
    lead_x = alloc["leader"].shift(1).fillna("")
    yrs = r_p.index.year
    tiers = ["리더", "회피", "폴백", "폴백(여유부족)", "SPY우위", "하락국면리더", "전섹터하락SPY", "현금"]   # [v0.10.0 §1.B] 게이트 미달 폴백 분해 · [v0.15.0 §A] 하락국면 리더 · [v0.27.0] 전섹터하락 SPY 참여
    rows: List[dict] = []
    for y in sorted(set(yrs)):
        m = yrs == y
        row = {"구분": "연도", "항목": str(y), "일수": int(m.sum()), "초과수익 합계(%p)": round(float(ex[m].sum()), 2)}
        for t in tiers:
            mt = m & (tier_x == t).values
            row[f"{t}(%p)"] = round(float(ex[mt].sum()), 2)
            row[f"{t} 일수"] = int(mt.sum())
        rows.append(row)
    row = {"구분": "연도", "항목": "전체", "일수": int(len(ex)), "초과수익 합계(%p)": round(float(ex.sum()), 2)}
    for t in tiers:
        mt = (tier_x == t).values
        row[f"{t}(%p)"] = round(float(ex[mt].sum()), 2)
        row[f"{t} 일수"] = int(mt.sum())
    rows.append(row)
    ld = (tier_x == "리더").values
    for sec in sorted(set(lead_x[ld])):
        if not sec:
            continue
        ms = ld & (lead_x == sec).values
        rows.append({"구분": "리더 섹터", "항목": sec, "일수": int(ms.sum()), "초과수익 합계(%p)": round(float(ex[ms].sum()), 2),
                     "리더(%p)": round(float(ex[ms].sum()), 2), "리더 일수": int(ms.sum())})
    # [v0.10.0 §1.C] SPY 국면별 리더 초과수익 — 01Z '예측'/build_prediction_matrix()의 'SPY 시장상황'과 같은 원천
    #   (res["sig"]["state"] → STATE_SHORT, build_sector_allocation()이 alloc["spy_state_short"]로 실어둠). t일 판단 →
    #   t+1일 체결이므로 위 tier_x·lead_x와 같은 shift(1)로 정렬한다.
    spy_state_x = alloc.get("spy_state_short")
    if spy_state_x is not None:
        spy_state_x = spy_state_x.reindex(alloc["tier"].index).shift(1).fillna("-")
        for name, bm in (("중립", (spy_state_x == "중립").values),
                         ("상승(위험선호)", (spy_state_x == "상승").values),
                         ("기타", (~spy_state_x.isin(["중립", "상승"])).values)):
            mm = ld & bm
            rows.append({"구분": "SPY 국면", "항목": name, "일수": int(mm.sum()), "초과수익 합계(%p)": round(float(ex[mm].sum()), 2),
                        "리더(%p)": round(float(ex[mm].sum()), 2), "리더 일수": int(mm.sum())})
    # [v0.10.0 §1.C] 여유(1위−2위 평활순위) 4분위별 리더 초과수익 — §0.4 근거(Q1·Q2 정보 없음 vs Q3·Q4 유의)를 매 리포트에서
    #   재현. 분위는 리더일(ld)만의 여유값 분포로 정한다(§1.B 게이트가 참조하는 모집단과 동일). margin도 tier와 같은 shift(1).
    margin_x = alloc.get("margin")
    if margin_x is not None:
        margin_x = margin_x.reindex(alloc["tier"].index).shift(1)
        qlab = _quartile_labels(pd.Series(np.where(ld, margin_x.values, np.nan), index=margin_x.index))
        for ql in ["Q1", "Q2", "Q3", "Q4"]:
            mm = (qlab == ql).values
            rows.append({"구분": "여유 4분위", "항목": ql, "일수": int(mm.sum()), "초과수익 합계(%p)": round(float(ex[mm].sum()), 2),
                        "리더(%p)": round(float(ex[mm].sum()), 2), "리더 일수": int(mm.sum())})
    # 리더 구간(에피소드) — 시작·끝·섹터·초과수익
    cur, start, prev = None, None, None
    eps: List[Tuple[pd.Timestamp, pd.Timestamp, str]] = []
    for d, v in alloc["leader"].where(alloc["tier"] == "리더", "").items():
        if v != cur:
            if cur:
                eps.append((start, prev, cur))
            cur, start = v, d
        prev = d
    if cur:
        eps.append((start, prev, cur))
    for s, e, sec in eps:
        m = (ex.index > s) & (ex.index <= e + pd.Timedelta(days=4))
        rows.append({"구분": "리더 구간", "항목": f"{s.date()}~{e.date()} {sec}", "일수": int(((alloc['leader'] == sec) & (alloc['tier'] == '리더') & (alloc['leader'].index >= s) & (alloc['leader'].index <= e)).sum()),
                     "초과수익 합계(%p)": round(float(ex[m].sum()), 2), "리더(%p)": round(float(ex[m].sum()), 2)})
    out = pd.DataFrame(rows)
    return out


def rotation_validation(alloc: Dict[str, Any], scfg: SectorConfig, M,
                        perf_ctrl_label: str = ROT_LABEL_CTRL_A) -> Dict[str, Any]:
    """[v0.4.0 §1.F.1/§1.F.3] 횡단면 rank IC(신호별·복합, 지평 5/21/63) + 상위3−하위3 일별 스프레드(3구간) +
    사전 고정 수용기준 판정. 전부 진단 — 배분비중 계산에는 어떤 값도 되돌아가지 않는다(미래수익은 여기서만 사용).
    [v0.10.0 §1.C ⚠ 아님] 벤치를 '상장 평균' 대신 SPY로 바꾼 진단을 나란히 추가(⑤가 재는 잣대와 통일) — 13d 'vs SPY' 2열,
    13f ③′ 정보 행(판정 제외), 13e 후행63일 섹터분산 4분위×상위1−SPY 초과 표, 00시트 SCORE_PCT 국면별 요약 한 줄.
    기존 열·판정(①~⑤, ③ 자체 포함)은 전부 그대로."""
    if not alloc:
        return {}
    t0 = time.time()
    ret_cc = alloc["ret_cc"]
    eval_idx = ret_cc.index
    h_main = int(scfg.ROTATION_IC_HORIZON)
    horizons = sorted({5, h_main, 63})
    logr = np.log1p(ret_cc.fillna(0.0)).where(ret_cc.notna())

    def _fwd(h: int) -> pd.DataFrame:
        return (np.exp(logr.rolling(h).sum().shift(-h)) - 1.0).where(ret_cc.notna())

    # [v0.10.0 §1.C] SPY 자체를 벤치로 쓰는 'vs SPY' 진단(⑤가 재는 잣대와 동일)에 쓸 SPY 향후수익 — build_sector_allocation()이
    #   alloc["spy_ret"]로 실어둔 SPY 원시 종가수익(res 없이도 접근 가능). _fwd()와 같은 로그수익 롤링합 방식(인과, 룩어헤드 없음).
    spy_ret_v = alloc.get("spy_ret")
    if spy_ret_v is None:
        log("ROTATION", kv(event="spy_ret_missing_for_vs_spy_diag"), M=M, level="warning")

    def _fwd_s(s: Optional[pd.Series], h: int) -> pd.Series:
        if s is None:
            return pd.Series(np.nan, index=eval_idx)
        lr = np.log1p(s.fillna(0.0)).where(s.notna())
        return (np.exp(lr.rolling(h).sum().shift(-h)) - 1.0).where(s.notna())

    ic_rows: List[dict] = []
    # [v0.5.0] 원시 신호는 사전방향을 곱해 평가(+면 '앞선다' 방향이 맞다는 뜻). 복합순위는 워크포워드 채택 신호로만 만든
    # 것이라 평가창(2018~) IC는 사실상 표본외 추정치다.
    sig_mats: Dict[str, pd.DataFrame] = {}
    for name, mat in alloc["signals"].items():
        sign = ROTATION_SIGNAL_SPECS.get(name, (+1, "", ""))[0]
        sig_mats[name] = mat * sign
    smooth_days = int(alloc.get("diag", {}).get("smooth_days", 1))
    KEY_RAW = "복합순위(워크포워드 채택, 원시, 상장 전체)"
    KEY_USED = f"복합순위(워크포워드 채택, {smooth_days}일 평활 — 배분 사용, 상장 전체)"
    KEY_ELIG = "복합순위(평활, 적격만)"
    sig_mats[KEY_RAW] = alloc["composite_all"]
    sig_mats[KEY_USED] = alloc.get("composite_all_smooth", alloc["composite_all"])
    sig_mats[KEY_ELIG] = alloc["composite"]
    # [v0.7.0] 선택 통계에 맞춘 ③: "top1"이면 배분에 쓰는 평활 복합순위의 '상위1 스프레드' t, "ic"면 종전 rank IC t.
    #   13d에는 두 통계를 후보별·지평별로 모두 기록(상위1 스프레드는 원시 후보에도 같은 21일 평활을 적용해 배분 조건과 맞춤).
    stat = str((alloc.get("wf") or {}).get("stat", getattr(scfg, "ROTATION_SELECT_STAT", "top1"))).lower()
    listed = alloc["listed"]
    composite_t = np.nan          # ③에 쓰는 t(선택 통계 기준)
    composite_ic_t = np.nan
    composite_top1_t = np.nan
    composite_top1_mean = np.nan
    # [v0.10.0 §1.C] KEY_USED/SCORE_PCT 각각의 SPY 벤치 상위1 스프레드 — 13f ③′·13e 분산4분위·00시트 요약줄에 쓴다.
    composite_top1_t_spy = np.nan
    composite_top1_mean_spy = np.nan
    sp_spy_used_series: Optional[pd.Series] = None
    sp_spy_score_series: Optional[pd.Series] = None
    # [v0.10.0 §1.B] 확신 게이트 통과일만의 상위1 스프레드 — 기존 열(게이트 전, 위 t_sel/판정/③에 그대로 쓰임)과 나란히 13d에 기록
    #   해서 게이트가 얼마나 표본을 줄이고 t를 바꾸는지 보여준다. ③의 정의(게이트 전 상위1 스프레드) 자체는 바꾸지 않는다.
    margin_steps_v = float(getattr(scfg, "ROTATION_LEADER_MARGIN_STEPS", 0.0) or 0.0)
    # [v0.10.0 §1.C] 지평별 SPY 향후수익(호출마다 다시 만들지 않도록 h 루프 밖에서 1회씩) — 성능(우선순위 3): O(신호수)배 절약.
    fwd_spy_by_h = {h: _fwd_s(spy_ret_v, h) for h in horizons}
    for name, xm in sig_mats.items():
        spec = ROTATION_SIGNAL_SPECS.get(name)
        is_raw = spec is not None
        for h in horizons:
            fwd_h = _fwd(h)
            ic = _cs_rank_ic(xm, fwd_h)
            m, tstat, n = _nw_mean_tstat(ic, lag=h)
            # 상위1 스프레드: 원시 후보는 0~1 순위 후 평활(배분과 동일 조건), 복합순위 3종은 이미 순위·평활 상태라 그대로
            rk = _cs_rank01(xm.where(listed)) if is_raw else xm
            sp = _top1_spread_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1))
            m_tp, t_tp, n_tp = _nw_mean_tstat(sp, lag=h)
            # [v0.10.0 §1.B] 같은 상위1 스프레드를 확신 게이트 통과일만으로도 계산(게이트 후) — ③·판정·composite_top1_t는
            #   위 게이트 전 sp/t_tp를 그대로 쓴다(바뀌지 않음). 13c '확신 게이트=통과' 일수와 대조 가능해야 하므로 min_n은 동일.
            sp_g = _top1_spread_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1), margin_steps=margin_steps_v)
            m_tp_g, t_tp_g, n_tp_g = _nw_mean_tstat(sp_g, lag=h)
            # [v0.9.0] 하위1 스프레드(꼴찌의 향후 수익 − 평균; 정보가 있으면 음) — 규칙 ② 회피의 표본외 근거
            sb = _bottom1_spread_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1))
            m_bt, t_bt, n_bt = _nw_mean_tstat(sb, lag=h)
            # [v0.43.0 R1/R3] 소수 클래스(순서) 잣대 — 1위 → 실현 상위3 · 꼴찌 → 실현 하위3(무작위 ≈ 3/n). 평가창 전체.
            _ht = _top1_hit_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1), k=3).dropna()
            _hb = _bottom1_hit_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1), k=3).dropna()
            hit_top = float(_ht.mean()) if len(_ht) >= 30 else np.nan
            hit_bot = float(_hb.mean()) if len(_hb) >= 30 else np.nan
            # [v0.10.0 §1.C] 같은 상위1 스프레드를 '상장 평균' 대신 SPY의 같은 지평 향후수익을 벤치로(⑤가 재는 잣대와 동일).
            #   기존 sp/m_tp/t_tp(③·판정·composite_top1_t에 쓰임)는 그대로 — 이 값은 13d의 별도 열에만 쓰인다.
            sp_spy = _top1_spread_series(rk, listed, fwd_h, smooth=(smooth_days if is_raw else 1), bench_series=fwd_spy_by_h.get(h))
            m_tp_spy, t_tp_spy, n_tp_spy = _nw_mean_tstat(sp_spy, lag=h)
            t_sel = t_tp if stat == "top1" else tstat
            ic_rows.append({"신호": name, "종류": ("후보(원시, 사전방향 적용)" if spec else "복합순위"),
                            "사전방향": (spec[0] if spec else "+1"), "지평(일)": h,
                            "평균 rank IC": round(m, 4) if pd.notna(m) else np.nan,
                            "NW-HAC t": round(tstat, 2) if pd.notna(tstat) else np.nan, "검사일수": n,
                            "IC>0 비율": round(float((ic.dropna() > 0).mean()), 4) if n else np.nan,
                            "상위1 스프레드(%/지평)": round(m_tp * 100, 3) if pd.notna(m_tp) else np.nan,
                            "NW-HAC t(상위1)": round(t_tp, 2) if pd.notna(t_tp) else np.nan,
                            "상위1 스프레드(게이트 통과일)": round(m_tp_g * 100, 3) if pd.notna(m_tp_g) else np.nan,   # [v0.10.0 §1.B]
                            "NW-HAC t(상위1, 게이트)": round(t_tp_g, 2) if pd.notna(t_tp_g) else np.nan,
                            "게이트 통과일수": int(n_tp_g),
                            "상위1 스프레드 vs SPY(%/지평)": round(m_tp_spy * 100, 3) if pd.notna(m_tp_spy) else np.nan,   # [v0.10.0 §1.C]
                            "NW-HAC t(상위1 vs SPY)": round(t_tp_spy, 2) if pd.notna(t_tp_spy) else np.nan,
                            "하위1 스프레드(%/지평)": round(m_bt * 100, 3) if pd.notna(m_bt) else np.nan,
                            "NW-HAC t(하위1)": round(t_bt, 2) if pd.notna(t_bt) else np.nan,
                            "꼴찌 판별(하위1 t≤−기준)": ("유의(−)" if (pd.notna(t_bt) and t_bt <= -scfg.ROTATION_ACCEPT_IC_T) else "비유의"),
                            "1위 실현상위3 비율": round(hit_top, 3) if pd.notna(hit_top) else np.nan,      # [v0.43.0 R1]
                            "꼴찌 실현하위3 비율": round(hit_bot, 3) if pd.notna(hit_bot) else np.nan,     # [v0.43.0 R3]
                            "판정": ("유의(+)" if (pd.notna(t_sel) and t_sel >= scfg.ROTATION_ACCEPT_IC_T)
                                   else ("유의(−)" if (pd.notna(t_sel) and t_sel <= -scfg.ROTATION_ACCEPT_IC_T) else "비유의")),
                            "판정 통계": ("상위1 스프레드" if stat == "top1" else "rank IC"),
                            "설명": (spec[1] if spec else ""), "경제적 근거": (spec[2] if spec else "")})
            if name == KEY_USED and h == h_main:
                composite_ic_t, composite_top1_t, composite_top1_mean = tstat, t_tp, m_tp
                composite_t = t_sel
                composite_top1_t_spy, composite_top1_mean_spy = t_tp_spy, m_tp_spy   # [v0.10.0 §1.C] 13f ③′·13e용
                sp_spy_used_series = sp_spy
            if name == "SCORE_PCT" and h == h_main:
                sp_spy_score_series = sp_spy    # [v0.10.0 §1.C] 00시트 SCORE_PCT vs SPY 국면별 요약줄용
    ic_table = pd.DataFrame(ic_rows)

    # ---- 상위3−하위3 일별 스프레드(배분에 쓰는 평활 복합순위, 상장 전체; 익일 종가수익, 비용 없음 — 진단) ----
    comp = alloc.get("composite_all_smooth", alloc["composite_all"])
    nxt = ret_cc.shift(-1)
    rk = comp.rank(axis=1, ascending=False, method="first")
    n_avail = comp.notna().sum(axis=1)
    top = nxt.where(rk <= 3).mean(axis=1)
    bot = nxt.where(rk.gt(n_avail - 3, axis=0) & comp.notna()).mean(axis=1)
    spread = (top - bot).where(n_avail >= 6)
    periods = [("2018-01-01", "2020-12-31"), ("2021-01-01", "2023-12-31"), ("2024-01-01", "2026-12-31")]
    sp_rows: List[dict] = []
    n_pos = 0
    for a, b in periods:
        s = spread.loc[(spread.index >= pd.Timestamp(a)) & (spread.index <= pd.Timestamp(b))].dropna()
        if len(s) < 60:
            sp_rows.append({"구간": f"{a[:4]}~{b[:4]}", "일수": len(s), "일평균 스프레드(%)": np.nan, "연환산(%)": np.nan, "양수": "표본부족"})
            continue
        mean_d = float(s.mean())
        n_pos += int(mean_d > 0)
        sp_rows.append({"구간": f"{a[:4]}~{b[:4]}", "일수": len(s), "일평균 스프레드(%)": round(mean_d * 100, 4),
                        "연환산(%)": round(mean_d * 252 * 100, 2), "양수": "Y" if mean_d > 0 else "N"})
    m_all, t_all, n_all = _nw_mean_tstat(spread, lag=1)
    sp_rows.append({"구간": "전체", "일수": n_all, "일평균 스프레드(%)": round(m_all * 100, 4) if pd.notna(m_all) else np.nan,
                    "연환산(%)": round(m_all * 252 * 100, 2) if pd.notna(m_all) else np.nan,
                    "양수": f"NW-t {t_all:.2f}" if pd.notna(t_all) else "-"})
    spread_table = pd.DataFrame(sp_rows)

    # [v0.10.0 §1.C] 13e 추가 표: 후행 63일 섹터 횡단면 분산(연율 %) 4분위 × 상위1−SPY 초과(KEY_USED, 지평 h_main) —
    #   §2(v0.11 확장 근거)의 '분산이 클수록 1위 집중의 초과수익이 크다'는 주장을 매 리포트에서 갱신해 스스로 보여준다.
    #   분산 = 그날 섹터(SPY 제외) 일수익의 횡단면 표준편차, 63일 이동평균 후 연율화(×√252, 인과·룩어헤드 없음).
    sector_cols_only = [c for c in ret_cc.columns if c != "SPY"]
    disp63 = (ret_cc[sector_cols_only].std(axis=1).rolling(63).mean() * np.sqrt(252) * 100.0) if sector_cols_only else pd.Series(dtype=float)
    disp_rows: List[dict] = []
    if len(disp63) and sp_spy_used_series is not None:
        qlab_disp = _quartile_labels(disp63)
        for ql in ["Q1", "Q2", "Q3", "Q4"]:
            mm = (qlab_disp == ql)
            m_d, t_d, n_d = _nw_mean_tstat(sp_spy_used_series.where(mm), lag=h_main)
            disp_rows.append({"구분": "분산4분위", "구간": ql, "일수": int(n_d),
                              f"상위1−SPY 평균({h_main}일,%)": round(m_d * 100, 3) if pd.notna(m_d) else np.nan,
                              "연환산(%)": round(m_d * (252.0 / h_main) * 100, 2) if pd.notna(m_d) else np.nan,
                              "양수": (f"NW-t {t_d:.2f}" if pd.notna(t_d) else "-")})
    else:
        log("ROTATION", kv(event="dispersion_quartile_table_skipped", has_disp=bool(len(disp63)),
                           has_sp_spy_used=(sp_spy_used_series is not None)), M=M, level="warning")
    if disp_rows:
        spread_table = pd.concat([spread_table.assign(구분="기간"), pd.DataFrame(disp_rows)], ignore_index=True, sort=False)

    # ---- 수용기준(§1.F.3, 사전 고정) — 주 전략 vs 대조군A ----
    perf = alloc["perf"].set_index("전략")
    lp = alloc["diag"]["label_primary"]
    p_pri, p_ctl = perf.loc[lp], perf.loc[perf_ctrl_label]
    cagr_gain = float(p_pri["CAGR"] - p_ctl["CAGR"])
    mdd_worse = float(p_ctl["최대낙폭(MDD)"] - p_pri["최대낙폭(MDD)"])   # 양수 = 주 전략의 MDD가 더 깊음
    if stat == "top1":
        crit3_name = f"③ 복합순위 상위1 스프레드 NW-t ≥ {scfg.ROTATION_ACCEPT_IC_T:.1f} (지평 {h_main}일, 평활 순위 1위 − 상장 평균)"
        crit3_val = (f"t = {composite_t:.2f} (평균 {composite_top1_mean * 100:+.3f}%/{h_main}일; 참고 rank IC t = {composite_ic_t:.2f})"
                     if pd.notna(composite_t) else "계산불가")
    else:
        crit3_name = f"③ 복합순위 rank IC NW-t ≥ {scfg.ROTATION_ACCEPT_IC_T:.1f} (지평 {h_main}일)"
        crit3_val = (f"t = {composite_t:.2f} (참고 상위1 스프레드 t = {composite_top1_t:.2f})" if pd.notna(composite_t) else "계산불가")
    # [v0.7.0] ⑤ 목표: 주 전략 CAGR ≥ SPY 국면전략(M) CAGR + 여유 — 이 계층이 M만 쓰는 것보다 나은가(사용자 목표 그대로)
    spy_m = alloc.get("diag", {}).get("spy_m", {})
    spy_m_cagr = spy_m.get("CAGR", np.nan)
    vs_spy = float(p_pri["CAGR"] - spy_m_cagr) if pd.notna(spy_m_cagr) else np.nan
    margin5 = float(getattr(scfg, "ROTATION_ACCEPT_VS_SPY_M", 0.0))
    crit = [
        {"기준": f"① CAGR ≥ 대조군A + {scfg.ROTATION_ACCEPT_CAGR_GAIN:.1%}p",
         "측정값": f"{cagr_gain:+.2%}p (주 {p_pri['CAGR']:.2%} vs 대조군A {p_ctl['CAGR']:.2%})",
         "판정": "PASS" if cagr_gain >= scfg.ROTATION_ACCEPT_CAGR_GAIN else "FAIL"},
        {"기준": f"② MDD 악화 ≤ {scfg.ROTATION_ACCEPT_MDD_WORSE:.0%}p",
         "측정값": f"{mdd_worse:+.2%}p (주 {p_pri['최대낙폭(MDD)']:.2%} vs 대조군A {p_ctl['최대낙폭(MDD)']:.2%})",
         "판정": "PASS" if mdd_worse <= scfg.ROTATION_ACCEPT_MDD_WORSE else "FAIL"},
        {"기준": crit3_name, "측정값": crit3_val,
         "판정": "PASS" if (pd.notna(composite_t) and composite_t >= scfg.ROTATION_ACCEPT_IC_T) else "FAIL"},
        {"기준": f"④ 상위3−하위3 스프레드 양수 구간 ≥ {scfg.ROTATION_ACCEPT_SPREAD_PERIODS}/3",
         "측정값": f"{n_pos}/3 구간 양수",
         "판정": "PASS" if n_pos >= scfg.ROTATION_ACCEPT_SPREAD_PERIODS else "FAIL"},
        {"기준": f"⑤ 목표: CAGR ≥ SPY 국면전략(M)" + (f" + {margin5:.1%}p" if margin5 > 0 else ""),
         "측정값": (f"{vs_spy:+.2%}p (주 {p_pri['CAGR']:.2%} vs SPY M {spy_m_cagr:.2%}; MDD 주 {p_pri['최대낙폭(MDD)']:.2%} vs "
                  f"SPY M {spy_m.get('MDD', np.nan):.2%}, 샤프 주 {p_pri['샤프']} vs SPY M {spy_m.get('샤프', np.nan)})"
                  if pd.notna(vs_spy) else "계산불가(SPY M 성과 없음)"),
         "판정": "PASS" if (pd.notna(vs_spy) and vs_spy >= margin5) else "FAIL"},
    ]
    # [v0.5.0] 워크포워드 채택 현황 — 채택 신호가 한 해도 없으면 배분은 전 기간 폴백(=사실상 M 전략)이었다는 뜻
    sel_by_year = alloc.get("diag", {}).get("selected_by_year", {})
    years_with = [y for y, s in sel_by_year.items() if s]
    sel_items = ["%s:%s" % (y, "+".join(s)) for y, s in sorted(sel_by_year.items()) if s]
    sel_txt = (f"워크포워드 채택: {len(years_with)}/{len(sel_by_year)}개 연도에서 신호 채택"
               + ((" (" + ", ".join(sel_items) + ")") if years_with else " — 전 기간 미채택(폴백만 적용)"))
    # [v0.5.1] 채택 신호가 한 해도 없으면 순위 자체가 없으므로 ③④는 '해당 없음(N/A)' — FAIL로 표기하지 않는다.
    #   이때 ①②는 '폴백(SPY) vs 대조군A(균등 11)'의 비교일 뿐 순위 신호와 무관함을 명시.
    no_signal_all = len(sel_by_year) > 0 and not years_with
    if no_signal_all:
        for c in crit[2:4]:
            c["판정"] = "N/A"
            c["측정값"] = "해당 없음 — 채택 신호가 없어 순위·복합순위 자체가 만들어지지 않음"
        for c in crit[:2]:
            c["측정값"] += " [폴백 SPY vs 균등 11 비교 — 순위 신호 무관]"
        crit[4]["측정값"] += " [전 기간 폴백 = SPY M 자체 — 차이는 첫 행 처리·반올림뿐]"
    passed = all(c["판정"] == "PASS" for c in crit)
    goal_txt = (f"목표(⑤ CAGR ≥ SPY M) {'달성' if crit[4]['판정'] == 'PASS' else '미달'}: {vs_spy:+.2%}p"
                if pd.notna(vs_spy) else "목표(⑤) 계산불가")
    if no_signal_all:
        verdict = ("판정 불가(N/A) — 순환매 신호 없음: 후보 전부 워크포워드 기준 미달 → 배분은 전 기간 폴백(SPY에 E_t = M 전략). "
                   "이 상태에서는 '섹터를 고르지 않는 것'이 시스템의 판단이며, ①②는 폴백이 균등 바스켓보다 나았다는 뜻일 뿐이다. " + sel_txt)
    else:
        verdict = (("PASS — 순위 신호에 정보가 있고 목표를 달성(사전 고정 5기준 전부 충족). " if passed else
                    "FAIL — " + ", ".join(c["기준"].split(" ")[0] for c in crit if c["판정"] != "PASS")
                    + " 미달. " + goal_txt + ". 집중배분(3단계 규칙)은 사용자 요청으로 유지되나, 미달 기준이 뜻하는 바(①②④ 균등 대조군 대비 "
                    "정보 유무 / ③ 1위 판별력 / ⑤ M만 쓰는 것보다 나은가)를 13시트에서 확인할 것. ")
                   + sel_txt)
    overall = "N/A" if no_signal_all else ("PASS" if passed else "FAIL")
    # [v0.10.0 §1.C] ③′ 정보 행 — 복합순위 상위1 스프레드를 '상장 평균'이 아니라 SPY 벤치로 다시 잰 값(⑤가 재는 잣대와 동일).
    #   passed/overall/verdict는 이미 위에서 원본 crit(5개, ③은 상장평균 벤치)만으로 확정됐으므로 이 행은 판정에 관여하지
    #   않는다 — crit_table에 보여주기 위한 표시용 사본(crit_display)에만 끼워 넣는다.
    crit3b_val = (f"t = {composite_top1_t_spy:.2f} (평균 {composite_top1_mean_spy * 100:+.3f}%/{h_main}일; 참고 상장평균 벤치 "
                 f"t = {composite_top1_t:.2f})" if pd.notna(composite_top1_t_spy) else "계산불가")
    crit3b = {"기준": "③′ 복합순위 상위1 − SPY NW-t(정보, 판정 제외)", "측정값": crit3b_val, "판정": "정보"}
    crit_display = crit[:3] + [crit3b] + crit[3:]
    crit_table = pd.concat([pd.DataFrame(crit_display),
                            pd.DataFrame([{"기준": "종합", "측정값": verdict, "판정": overall}])],
                           ignore_index=True)
    # [v0.5.1] 순환매 예측 판정 요약(00시트용) — 최강 후보와 그 최대 학습 t(13g), 결론 한 줄
    wf_log = (alloc.get("wf") or {}).get("selection_log", pd.DataFrame())
    best_txt = "-"
    if isinstance(wf_log, pd.DataFrame) and len(wf_log) and "NW-HAC t" in wf_log.columns:
        agg = wf_log.groupby("신호")["NW-HAC t"].agg(["max", "min", "mean"]).sort_values("max", ascending=False)
        top3 = agg.head(3)
        best_txt = "; ".join(f"{n}: 학습 t 최대 {r['max']:.2f}(최소 {r['min']:.2f}, 평균 {r['mean']:.2f})" for n, r in top3.iterrows())
    mode_txt = f"채택 모드={str(getattr(scfg, 'ROTATION_SELECT_MODE', 'strict'))}, 선택 통계={'상위1 스프레드' if stat == 'top1' else 'rank IC'}"
    basis_cnt = {}
    if isinstance(wf_log, pd.DataFrame) and "채택 근거" in wf_log.columns:
        for b in wf_log.loc[wf_log["채택"] == "채택", "채택 근거"]:
            k = str(b).split("(")[0]
            basis_cnt[k] = basis_cnt.get(k, 0) + 1
    basis_txt = ", ".join(f"{k} {v}건" for k, v in basis_cnt.items()) if basis_cnt else "없음"
    if no_signal_all:
        pred_verdict = (f"예측 못함 — 후보 {wf_log['신호'].nunique() if len(wf_log) else 0}종 전부 기준 미달({mode_txt}: "
                        f"best_available이면 t≥{getattr(scfg, 'ROTATION_SELECT_T_MIN', 1.0):.1f}도 없음) → 섹터를 고르지 않고 M 전략(SPY)을 유지. "
                        f"상위 후보: {best_txt}")
    elif passed:
        pred_verdict = f"예측함(수용기준 PASS, {goal_txt}) — {sel_txt}. 채택 근거 등급(연도×신호): {basis_txt}. {mode_txt}. 상위 후보: {best_txt}"
    else:
        pred_verdict = (f"판단은 내리지만 근거는 약함 — 신호가 채택됐으나 수용기준 미달("
                        f"{', '.join(c['기준'].split(' ')[0] for c in crit if c['판정'] not in ('PASS', 'N/A'))}); {goal_txt}. "
                        f"채택 근거 등급(연도×신호): {basis_txt}. {mode_txt}. {sel_txt}. 상위 후보: {best_txt}")
    # [v0.10.0 §1.C] 00시트용 한 줄: SCORE_PCT 1위−SPY(E_t>0 구간만), 국면별(중립/상승) 분해 — §0.4 근거를 매 리포트에서 갱신.
    #   E_t>0(현금이 아닌 날)·h_main 지평 고정. SCORE_PCT가 ROTATION_SIGNALS에서 빠졌거나 상장 데이터가 없으면 '계산불가'.
    e_pos = (alloc["E"] > 0)
    spy_state_now = alloc.get("spy_state_short")
    if sp_spy_score_series is not None:
        base_mask = e_pos.reindex(sp_spy_score_series.index).fillna(False) & sp_spy_score_series.notna()
        m_sc, t_sc, n_sc = _nw_mean_tstat(sp_spy_score_series.where(base_mask), lag=h_main)
        regime_txt = "국면별 계산불가(SPY 국면라벨 없음)"
        if spy_state_now is not None:
            spy_state_now_r = spy_state_now.reindex(sp_spy_score_series.index)
            parts = []
            for lbl, key in (("중립", "중립"), ("상승", "상승")):
                v = sp_spy_score_series.where(base_mask & (spy_state_now_r == key)).dropna()
                parts.append(f"{lbl} {float(v.mean()) * 100:+.2f}" if len(v) else f"{lbl} 표본부족")
            regime_txt = "국면별 " + " / ".join(parts)
        score_diag_txt = (f"SCORE_PCT 1위−SPY(E_t>0): {m_sc * 100:+.2f}%/{h_main}일 t {t_sc:.1f}({n_sc}일); {regime_txt}"
                          if pd.notna(m_sc) else f"SCORE_PCT 1위−SPY(E_t>0) 계산불가(표본부족); {regime_txt}")
    else:
        score_diag_txt = "SCORE_PCT 1위−SPY(E_t>0) 계산불가(SCORE_PCT가 채택 후보 신호 목록에 없음)"
    pred_verdict = pred_verdict + " | " + score_diag_txt
    log("ROTATION", kv(event="validation_done", stat=stat, cagr_gain_pp=round(cagr_gain * 100, 2), mdd_worse_pp=round(mdd_worse * 100, 2),
                       composite_t=round(composite_t, 2) if pd.notna(composite_t) else None,
                       composite_ic_t=round(composite_ic_t, 2) if pd.notna(composite_ic_t) else None,
                       composite_top1_t=round(composite_top1_t, 2) if pd.notna(composite_top1_t) else None, spread_pos_periods=n_pos,
                       composite_top1_t_spy=round(composite_top1_t_spy, 2) if pd.notna(composite_top1_t_spy) else None,   # [v0.10.0 §1.C]
                       vs_spy_m_pp=round(vs_spy * 100, 2) if pd.notna(vs_spy) else None,
                       years_with_signal=len(years_with), verdict="PASS" if passed else "FAIL",
                       elapsed_s=round(time.time() - t0, 2)),
        M=M, level="info" if passed else "warning")
    wf = alloc.get("wf") or {}
    try:
        gap_table = build_gap_attribution(alloc)          # [v0.8.0] 13i
    except Exception as e:
        log("ROTATION", kv(event="gap_attribution_failed", err=type(e).__name__, msg=str(e)[:120]), M=M, level="warning")
        gap_table = pd.DataFrame()
    return {"ic_table": ic_table, "spread_table": spread_table, "criteria": crit_table, "passed": passed, "gap_table": gap_table,
            "verdict": verdict, "composite_ic_t": composite_ic_t, "composite_top1_t": composite_top1_t, "composite_t": composite_t,
            "composite_top1_t_spy": composite_top1_t_spy, "composite_top1_mean_spy": composite_top1_mean_spy,   # [v0.10.0 §1.C]
            "select_stat": stat, "cagr_gain": cagr_gain, "mdd_worse": mdd_worse, "vs_spy_m": vs_spy, "goal_txt": goal_txt,
            "spread_pos_periods": n_pos, "selection_log": wf.get("selection_log", pd.DataFrame()),
            "external_log": wf.get("external_log", pd.DataFrame()), "select_mode": wf.get("mode", "strict"),
            "selected_by_year": sel_by_year, "no_signal_all": no_signal_all, "prediction_verdict": pred_verdict}


def build_allocation_sheet(alloc: Dict[str, Any], nd_spy: Optional[dict], scfg: SectorConfig) -> pd.DataFrame:
    """13c_일별배분비중: 날짜 × (E_t, 배분합계, 현금, 적격섹터수, 섹터별 배분비중·순위). 각 행의 비중은 그날 종가로
    확정돼 다음 거래일 시가에 체결할 목표비중(M 규칙 그대로). nd_spy가 있으면 맨 끝에 '예측' 행(=마지막 실적 행의
    비중을 다음 영업일 날짜로 재표기 — 새 계산 없음)을 붙인다."""
    if not alloc:
        return pd.DataFrame()
    tw, cols, idx = alloc["target_w"], alloc["cols"], alloc["target_w"].index
    out = pd.DataFrame(index=idx)
    out["날짜"] = [d.date() for d in idx]
    out["구분"] = "실적"
    out["E_t(SPY목표비중)"] = alloc["E"].round(2)
    out["배분합계"] = tw.sum(axis=1).round(4)
    out["현금"] = (1.0 - tw.sum(axis=1)).clip(lower=0.0).round(4)
    out["적격섹터수"] = alloc["n_eligible"].astype(int)
    # [v0.5.0] 3단계 판단(리더/회피/폴백/현금)·리더·꼴찌·채택 신호 수·과반 투표
    if "tier" in alloc:
        out["판단"] = alloc["tier"]
        out["1위 섹터"] = alloc["leader"]
        out["회피 섹터"] = alloc["laggard"]
        out["채택신호수"] = alloc["n_selected"]
        out["1위 득표"] = alloc["votes_leader"]
        out["꼴찌 득표"] = alloc["votes_laggard"]
    if alloc.get("vote_loss_flag") is not None:   # [v0.48.0 L5] L2 격자 판독용 — 라이브 판단은 바꾸지 않는다
        out["득표 상실 중 보유"] = pd.Series(alloc["vote_loss_flag"]).reindex(idx).fillna(False).values
    if "margin" in alloc:   # [v0.10.0 §1.B] 확신 게이트 진단 — 1위가 2위를 얼마나 앞섰는지·문턱·통과 여부
        out["1위 여유(2위 대비)"] = alloc["margin"].round(4)
        out["여유 문턱"] = alloc["step"].round(4)
        out["확신 게이트"] = alloc["gate"]
    if "SPY" in tw.columns:
        out["SPY 배분비중"] = tw["SPY"].round(4)
    for t in cols:
        out[f"{t} 배분비중"] = tw[t].round(4)
    if "SPY" in alloc["rank_pos"].columns:          # [v0.8.0] SPY 후보 포함 시 SPY의 후보 순위
        out["SPY 순위"] = alloc["rank_pos"]["SPY"]
    for t in cols:
        out[f"{t} 순위"] = alloc["rank_pos"][t]
    out = out.reset_index(drop=True)
    if nd_spy is not None and len(out):
        row = out.iloc[-1].copy()
        row["날짜"] = nd_spy["다음거래일"].date()
        row["구분"] = "예측"
        out = pd.concat([out, pd.DataFrame([row])], ignore_index=True)
    return out


def build_allocation_trades(alloc: Dict[str, Any], results: Dict[str, Dict[str, Any]], res: dict,
                            nd_spy: Optional[dict] = None) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """[v0.9.0] 13j_배분거래내역 — 주 전략(집중배분)의 **실제 포트폴리오** 거래 로그. 13c의 일별 목표비중(섹터+SPY 합계 = E_t, 한 계좌)을
    자산별 '포지션 구간'(체결 비중 > 0이 이어지는 구간)으로 풀어 쓴다. 02 시트(섹터별 단독 거래)는 각 섹터를 그 섹터 하나만 100% 운용했을
    때의 진단이라 겹치지만, 이 시트는 같은 날 비중 합이 E_t를 넘지 않는 실제 거래다.
    체결: t일 종가 확정 목표비중 → t+1 시가 체결(M 규칙). 구간 = 체결일(시가 매수) ~ 마지막 보유일, 청산 = 그 다음 거래일 시가.
    자산수익 = 시가(진입)→시가(청산)의 총수익(ret_oc·ret_co 연쇄 — 백테스트와 같은 분해), 전략기여(%p) = Σ(비중×수익) − 그 자산의
    거래비용(백테스트와 동일 산식). 구간 안에서 비중은 E_t(SPY M 목표비중)를 따라 매일 바뀔 수 있다(평균비중·진입비중 병기).
    반환: (DataFrame, 요약 dict)."""
    if not alloc or "target_w" not in alloc:
        return pd.DataFrame(), {}
    tw = alloc["target_w"]
    idx = tw.index
    all_cols = list(tw.columns)
    cols = list(alloc.get("cols", [c for c in all_cols if c != "SPY"]))
    ret_co = alloc["ret_co"].reindex(index=idx, columns=all_cols).fillna(0.0)
    ret_oc = alloc["ret_oc"].reindex(index=idx, columns=all_cols).fillna(0.0)
    cost_rate = float(alloc.get("cost_bps", 0.0)) / 1e4
    exec_w = tw.shift(1)
    if alloc.get("init_exec") is not None:
        exec_w.iloc[0] = alloc["init_exec"].reindex(all_cols).fillna(0.0).values
    exec_w = exec_w.fillna(0.0)
    prev_w = exec_w.shift(1)
    if alloc.get("init_prev") is not None:
        prev_w.iloc[0] = alloc["init_prev"].reindex(all_cols).fillna(0.0).values
    prev_w = prev_w.fillna(0.0)
    tier = alloc.get("tier", pd.Series("", index=idx, dtype=object)).reindex(idx).fillna("")
    leader = alloc.get("leader", pd.Series("", index=idx, dtype=object)).reindex(idx).fillna("")
    laggard = alloc.get("laggard", pd.Series("", index=idx, dtype=object)).reindex(idx).fillna("")
    votes = alloc.get("votes_leader", pd.Series(0, index=idx)).reindex(idx).fillna(0).astype(int)
    margin = alloc.get("margin", pd.Series(np.nan, index=idx)).reindex(idx)          # [v0.10.0 §1.B]
    step = alloc.get("step", pd.Series(np.nan, index=idx)).reindex(idx)              # [v0.10.0 §1.B]
    margin_steps_cfg = float((alloc.get("diag") or {}).get("margin_steps_cfg", 0.0) or 0.0)   # 0이면 게이트 비활성(문구도 이전과 동일)
    n_sel = alloc.get("n_selected", pd.Series(0, index=idx)).reindex(idx).fillna(0).astype(int)
    E = alloc["E"].reindex(idx).fillna(0.0)
    state = alloc.get("state", pd.DataFrame(index=idx))
    spy_m_ret = alloc.get("spy_m_ret", pd.Series(0.0, index=idx)).reindex(idx).fillna(0.0)
    # 표시용 원시 시가/종가
    px_open: Dict[str, pd.Series] = {}
    px_close: Dict[str, pd.Series] = {}
    for t in cols:
        r = results.get(t, {})
        px_open[t] = r.get("px_open", pd.Series(dtype=float)).reindex(idx)
        px_close[t] = r.get("px_close", pd.Series(dtype=float)).reindex(idx)
    spy_df = res.get("px_dict", {}).get("SPY")
    if isinstance(spy_df, pd.DataFrame) and len(spy_df):
        spy_df = spy_df[~spy_df.index.duplicated(keep="last")].sort_index()
        px_open["SPY"] = spy_df["Open"].astype(float).reindex(idx) if "Open" in spy_df.columns else spy_df["Close"].astype(float).reindex(idx)
        px_close["SPY"] = spy_df["Close"].astype(float).reindex(idx)
    else:
        px_open["SPY"] = pd.Series(np.nan, index=idx); px_close["SPY"] = pd.Series(np.nan, index=idx)
    spy_oc = ret_oc["SPY"] if "SPY" in ret_oc.columns else pd.Series(0.0, index=idx)
    spy_co = ret_co["SPY"] if "SPY" in ret_co.columns else pd.Series(0.0, index=idx)
    n = len(idx)
    tier_kr_entry = {"리더": "리더 집중", "회피": "꼴찌 회피 바스켓", "폴백": "폴백(섹터 간 차이 없음 → SPY)",
                     "폴백(여유부족)": "폴백(1위는 있으나 확신 게이트 미달 → SPY)",   # [v0.10.0 §1.B]
                     "SPY우위": "SPY우위(SPY가 후보 1위)",
                     "하락국면리더": "하락국면리더(E_t=0이나 명확1위·게이트 통과 → 그 섹터 단독)",   # [v0.15.0 §A]
                     "전섹터하락SPY": "전섹터하락 SPY 참여(E_t>0인데 적격섹터 0 → SPY를 POS×E_t만큼)",   # [v0.27.0]
                     "현금": "현금"}
    state_kr = {"RISK_OFF": "하락(위험회피)", "TREND_ONLY_OUT": "추세필터-현금", "NO_SIGNAL": "신호없음"}
    rows: List[dict] = []
    for a in all_cols:
        w = exec_w[a].values
        held = w > 1e-12
        i = 0
        k = 0
        while i < n:
            if not held[i]:
                i += 1
                continue
            i0 = i
            while i + 1 < n and held[i + 1]:
                i += 1
            i1 = i
            i += 1
            k += 1
            has_exit = i1 + 1 < n
            d_dec = idx[i0 - 1] if i0 >= 1 else None                  # 진입 결정일(t) — 평가창 첫날이면 M의 이월 포지션
            d_entry = idx[i0]
            d_exit = idx[i1 + 1] if has_exit else None
            d_exit_dec = idx[i1]                                        # 청산을 결정한 날(비중 0으로 확정된 날)
            # 자산 총수익: 시가(진입) → 시가(청산) = Π(1+oc_d)(1+co_{d+1}), d=i0..i1 ; 청산 없으면 마지막 종가까지
            oc = ret_oc[a].values; co = ret_co[a].values
            g = 1.0
            for d in range(i0, i1 + 1):
                g *= (1.0 + oc[d])
                if d + 1 <= i1 or (d == i1 and has_exit):
                    g *= (1.0 + co[d + 1])
            asset_ret = g - 1.0
            # 전략 기여: Σ exec_w·oc + Σ prev_w·co − 비용(진입·구간 내 변동·청산)
            ew = exec_w[a].values; pw = prev_w[a].values
            contrib = 0.0
            for d in range(i0, i1 + 1):
                contrib += ew[d] * oc[d] + pw[d] * co[d]
            if has_exit:
                contrib += pw[i1 + 1] * co[i1 + 1]
            last_cost_day = i1 + 1 if has_exit else i1
            cost = sum(abs(ew[d] - pw[d]) for d in range(i0, last_cost_day + 1)) * cost_rate
            contrib -= cost
            # 같은 구간 SPY(단순보유) / SPY M
            gs = 1.0
            for d in range(i0, i1 + 1):
                gs *= (1.0 + spy_oc.iloc[d])
                if d + 1 <= i1 or (d == i1 and has_exit):
                    gs *= (1.0 + spy_co.iloc[d + 1])
            spy_ret = gs - 1.0
            spy_m_same = float(np.prod(1.0 + spy_m_ret.iloc[i0:i1 + 1].values) - 1.0)
            # 진입 판단(결정일 기준)
            if d_dec is None:
                t_in = "평가창 이전부터 이월(SPY M 포지션)"
            else:
                tr = tier.loc[d_dec]
                if a == "SPY":
                    t_in = tier_kr_entry.get(tr, tr)
                    if tr == "폴백":
                        t_in = ("폴백(채택 신호 없음 → SPY)" if int(n_sel.loc[d_dec]) == 0
                                else "폴백(명확한 1위·꼴찌 없음 — 섹터 간 차이 없음 → SPY)")
                elif tr == "리더":
                    # [v0.10.0 §1.B] margin_steps_cfg<=0(게이트 비활성)이면 문구를 이전과 완전히 동일하게 유지(동등성 보존)
                    mg, sp = margin.loc[d_dec], step.loc[d_dec]
                    mg_txt = f"(여유 {mg:.2f} ≥ {sp:.2f})" if (margin_steps_cfg > 0 and pd.notna(mg) and pd.notna(sp)) else ""
                    t_in = f"리더 집중 — 채택 {int(n_sel.loc[d_dec])}개 중 {int(votes.loc[d_dec])}개가 1위 지목{mg_txt}"
                elif tr == "회피":
                    t_in = f"꼴찌 {laggard.loc[d_dec]} 회피 — 적격 균등 바스켓"
                else:
                    t_in = tier_kr_entry.get(tr, tr)
            # 청산 사유(청산 결정일 = 마지막 보유일 t: 그날 확정된 목표비중이 0)
            if not has_exit:
                t_out = "보유중(평가창 마지막 날)"
            else:
                dd = d_exit_dec
                tr2 = tier.loc[dd]
                if float(E.loc[dd]) <= 1e-12:
                    t_out = "현금(E_t=0 — SPY M 위험회피)"
                elif a != "SPY" and a in state.columns and str(state.loc[dd, a]) in state_kr:
                    t_out = f"적격 상실({state_kr[str(state.loc[dd, a])]})"
                elif tr2 == "리더":
                    t_out = f"리더 교체 → {leader.loc[dd]}" if leader.loc[dd] != a else "리더 유지(비중 재조정)"
                elif tr2 == "폴백(여유부족)":
                    t_out = "여유 상실(확신 게이트 미달) → 폴백 SPY"   # [v0.10.0 §1.B]
                elif tr2 == "회피":
                    t_out = f"회피 바스켓(꼴찌 {laggard.loc[dd]})으로" if a == "SPY" else f"회피 바스켓 재구성(꼴찌 {laggard.loc[dd]})"
                elif tr2 == "SPY우위":
                    t_out = "SPY우위(SPY가 후보 1위) → SPY"
                elif tr2 == "폴백":
                    t_out = ("채택 신호 없음 → 폴백 SPY" if int(n_sel.loc[dd]) == 0 else "판단 없음(명확한 1위·꼴찌 없음) → 폴백 SPY")
                else:
                    t_out = tr2
            w_seg = exec_w[a].iloc[i0:i1 + 1]
            rows.append({"자산": a, "자산 번호": k, "진입 결정일": (str(d_dec.date()) if d_dec is not None else "-"),
                         "진입일(시가 체결)": str(d_entry.date()), "청산일(시가 체결)": (str(d_exit.date()) if has_exit else "보유중"),
                         "보유거래일": int(i1 - i0 + 1),
                         "진입가(시가)": round(float(px_open[a].iloc[i0]), 2) if pd.notna(px_open[a].iloc[i0]) else np.nan,
                         "청산가(시가)": (round(float(px_open[a].iloc[i1 + 1]), 2) if has_exit and pd.notna(px_open[a].iloc[i1 + 1])
                                       else (round(float(px_close[a].iloc[i1]), 2) if pd.notna(px_close[a].iloc[i1]) else np.nan)),
                         "진입비중": round(float(w_seg.iloc[0]), 4), "평균비중": round(float(w_seg.mean()), 4),
                         "최대비중": round(float(w_seg.max()), 4),
                         "자산수익률(구간)": round(asset_ret, 4), "전략기여(%p)": round(contrib * 100, 3),
                         "거래비용(%p)": round(cost * 100, 3),
                         "SPY 수익률(동일구간)": round(spy_ret, 4), "SPY M 수익률(보유일)": round(spy_m_same, 4),
                         "진입 판단": t_in, "진입 시 E_t": round(float(E.loc[d_dec]), 2) if d_dec is not None else np.nan,
                         "청산 사유": t_out})
    df = pd.DataFrame(rows)
    if len(df):
        df = df.sort_values(["진입일(시가 체결)", "자산"]).reset_index(drop=True)
        df.insert(0, "번호", range(1, len(df) + 1))
    # 요약(00시트용)
    summ: Dict[str, Any] = {}
    if len(df):
        sec = df[df["자산"] != "SPY"]
        summ = {"n_trades": int(len(df)), "n_sector": int(len(sec)), "n_spy": int((df["자산"] == "SPY").sum()),
                "avg_hold": round(float(df["보유거래일"].mean()), 1),
                "avg_hold_sector": round(float(sec["보유거래일"].mean()), 1) if len(sec) else np.nan,
                "win_vs_spy": round(float((sec["자산수익률(구간)"] > sec["SPY 수익률(동일구간)"]).mean()), 3) if len(sec) else np.nan,
                "contrib_sector_pp": round(float(sec["전략기여(%p)"].sum()), 2) if len(sec) else 0.0,
                "contrib_spy_pp": round(float(df.loc[df["자산"] == "SPY", "전략기여(%p)"].sum()), 2),
                "cost_pp": round(float(df["거래비용(%p)"].sum()), 2),
                "max_concurrent": int((exec_w > 1e-12).sum(axis=1).max()),
                "max_gross": round(float(exec_w.sum(axis=1).max()), 4),
                "by_tier": {}}
        for tr_name in ("리더", "회피", "폴백", "SPY우위"):
            m = df["진입 판단"].astype(str).str.startswith({"리더": "리더", "회피": "꼴찌", "폴백": "폴백", "SPY우위": "SPY우위"}[tr_name])
            if m.any():
                summ["by_tier"][tr_name] = {"n": int(m.sum()), "contrib_pp": round(float(df.loc[m, "전략기여(%p)"].sum()), 2)}
    return df, summ


def _binary_metrics(pred: pd.Series, real: pd.Series) -> Dict[str, float]:
    """[v0.43.0 R1] 이진 혼동행렬 → 소수 클래스 지표. pred/real: '하락'을 True로 둔 bool Series(같은 인덱스).
    반환: n·기저하락률·예측하락비율·하락 정밀도·하락 재현율·상승 재현율·균형정확도·MCC."""
    p = pred.astype(bool); r = real.astype(bool)
    tp = int((p & r).sum()); fn = int((~p & r).sum()); fp = int((p & ~r).sum()); tn = int((~p & ~r).sum())
    n = tp + fn + fp + tn
    rec_d = tp / (tp + fn) if (tp + fn) else np.nan
    prec_d = tp / (tp + fp) if (tp + fp) else np.nan
    rec_u = tn / (tn + fp) if (tn + fp) else np.nan
    bal = (rec_d + rec_u) / 2.0 if (pd.notna(rec_d) and pd.notna(rec_u)) else np.nan
    den = float(np.sqrt(float(tp + fp) * float(tp + fn) * float(tn + fp) * float(tn + fn)))
    mcc = (tp * tn - fp * fn) / den if den > 0 else np.nan
    return {"n": n, "base_down": ((tp + fn) / n if n else np.nan), "pred_down": ((tp + fp) / n if n else np.nan),
            "prec_down": prec_d, "rec_down": rec_d, "rec_up": rec_u, "balanced": bal, "mcc": mcc}


def build_minority_class_accuracy(results: Dict[str, Dict[str, Any]], alloc: Optional[Dict[str, Any]] = None,
                                  horizons: Tuple[int, ...] = (1, 5, 21), big_move: float = 0.05,
                                  asset_label: str = "섹터", exclude_rank: Tuple[str, ...] = ("SPY",),
                                  rot_extra_horizons: Tuple[int, ...] = (42, 63, 126)
                                  ) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """[v0.43.0 R1] 13p_소수클래스정확도 — 사용자 잣대("실제 상승/하락이 적은 쪽의 정확도가 높아야 예측력이 있다")를
    매 실행 자동으로 낸다. REPORT46 §1의 표를 그대로 코드로 옮긴 것이며 **새 계산·새 데이터 없음**(01_일별의 예측·종가,
    13c의 순위·판단만 쓴다). 배분·신호에 영향 없음(비트 동일).

    블록 A(국면·티커별): 예측 '하락'(state == RISK_OFF) vs 실현 하락(종가 향후 h일 수익 < 0) — 기저율·예측하락비율·
      하락 정밀도·하락 재현율·상승 재현율·균형정확도·MCC · 큰하락(−big_move) 집중배율 · 같은 지표를 '현금(목표비중 0)'
      기준으로 한 번 더. 정밀도 ≈ 기저율이면 그 방향에 정보가 없다.
    블록 B(순환매·연도별, alloc이 있을 때): 리더 판단일의 '리더 → 실현 상위3'(소수 클래스 27%)·'리더 → 실현 하위3'·
      '리더 > 중앙값', 순위가 있는 모든 날의 '모델 1위 → 상위3'·'모델 꼴찌 → 하위3'·'모델 꼴찌 → 상위3' + 무작위 기대.
    블록 C(국면·연도별 pooled, h=21): 기저·예측하락일·정밀도·재현율·중립일 실현하락률.
    [v0.48.0 L1 ★ 신규] 블록 B·E에 '판단일은 h=21로 고정, 실현 순위만 rot_extra_horizons(기본 42·63·126)로
      다시 잰' 열을 h=21 옆에 병기한다(리더 태그·보유일은 그대로 — 판단 지평은 바꾸지 않는다, 계산 전용 진단).
      근거: REPORT51 §2.2 — 같은 611일 교차 리더 판단을 h=63/126으로 재면 0.534/0.637(h=21은 0.4255)로
      오른다. 지평 불일치(신호는 2~6개월인데 판단·검증은 21일)를 매 실행 드러낸다. 배분·채택 신호 변경 없음.
    반환: (DataFrame, 요약 dict — 13f ⑦⑧·00시트 1줄용)."""
    rows: List[dict] = []
    summ: Dict[str, Any] = {}
    if not results:
        return pd.DataFrame(), summ
    tickers = list(results.keys())
    h_main = 21 if 21 in horizons else horizons[-1]
    # [v0.44.0 F3(1)] M(SPY) 상속 비교 — 그 섹터의 하락 예측을 **M의 판정**으로 대체했을 때의 같은 지표.
    #   REPORT47 §2.3: 섹터 자기 기계 MCC 0.055 vs M 현금 0.079 vs M 상승아님 0.088(11섹터 평균, h=21).
    #   M 자신은 정보가 있는데(현금 0.160) 섹터별 재추정이 깎는다 — 그 간극을 매 실행 자동으로 보인다.
    #   alloc이 없으면(산업 계층) 이 열은 비워 둔다.
    _m_cash = _m_notup = None
    if alloc:
        _E = alloc.get("E")
        _ss = alloc.get("spy_state_short")
        if _E is not None:
            _m_cash = pd.Series(_E).astype(float) <= 1e-12
        if _ss is not None:
            _m_notup = ~pd.Series(_ss).astype(str).eq("상승")

    # ---------- 블록 A ----------
    per_h_bal: Dict[int, List[float]] = {h: [] for h in horizons}
    per_h_mcc: Dict[int, List[float]] = {h: [] for h in horizons}
    per_h_prec: Dict[int, List[float]] = {h: [] for h in horizons}
    per_h_base: Dict[int, List[float]] = {h: [] for h in horizons}
    per_h_rec: Dict[int, List[float]] = {h: [] for h in horizons}
    pooled: List[pd.DataFrame] = []
    for t in tickers:
        r = results[t]
        st = r.get("state"); px = r.get("px_close"); tp_ = r.get("target_pos")
        if st is None or px is None or len(st) == 0:
            continue
        st = pd.Series(st).astype(str)
        px = pd.Series(px).astype(float).reindex(st.index)
        tp_ = pd.Series(tp_).astype(float).reindex(st.index) if tp_ is not None else pd.Series(np.nan, index=st.index)
        for h in horizons:
            fwd = px.shift(-h) / px - 1.0
            ok = fwd.notna() & px.notna()
            if int(ok.sum()) < 50:
                continue
            real_down = (fwd < 0)[ok]
            pred_down = st.eq("RISK_OFF")[ok]
            m = _binary_metrics(pred_down, real_down)
            bm = big_move if h >= 21 else (0.03 if h >= 5 else 0.015)
            big = (fwd < -bm)[ok]
            big_base = float(big.mean()) if len(big) else np.nan
            big_pred = float(big[pred_down].mean()) if int(pred_down.sum()) else np.nan
            cash = (tp_ <= 1e-12)[ok] & tp_[ok].notna()
            mc = _binary_metrics(cash, real_down)
            # [v0.44.0 F3(1)] 같은 표본에서 M 판정을 그 섹터의 예측으로 썼다면
            _mm = {}
            for _nm, _src in (("M현금", _m_cash), ("M상승아님", _m_notup)):
                if _src is None:
                    continue
                _p = _src.reindex(st.index).fillna(False)[ok]
                _mm[_nm] = _binary_metrics(_p, real_down)
            rows.append({"블록": "A. 국면 소수클래스(티커별)", "티커": t, "지평(일)": h, "표본일수": m["n"],
                         "기저 실현하락률": round(m["base_down"], 4),
                         "예측 하락 비율": round(m["pred_down"], 4),
                         "하락 정밀도(예측하락 중 실제하락)": (round(m["prec_down"], 4) if pd.notna(m["prec_down"]) else np.nan),
                         "하락 재현율(실제하락 중 예측하락)": (round(m["rec_down"], 4) if pd.notna(m["rec_down"]) else np.nan),
                         "상승 재현율": (round(m["rec_up"], 4) if pd.notna(m["rec_up"]) else np.nan),
                         "균형정확도": (round(m["balanced"], 4) if pd.notna(m["balanced"]) else np.nan),
                         "MCC": (round(m["mcc"], 4) if pd.notna(m["mcc"]) else np.nan),
                         f"큰하락(−{bm:.1%}) 기저": (round(big_base, 4) if pd.notna(big_base) else np.nan),
                         f"큰하락 비율(예측하락일)": (round(big_pred, 4) if pd.notna(big_pred) else np.nan),
                         "큰하락 집중배율": (round(big_pred / big_base, 2) if (pd.notna(big_pred) and big_base and big_base > 0) else np.nan),
                         "현금일 비율": round(mc["pred_down"], 4),
                         "현금 기준 하락 정밀도": (round(mc["prec_down"], 4) if pd.notna(mc["prec_down"]) else np.nan),
                         "현금 기준 하락 재현율": (round(mc["rec_down"], 4) if pd.notna(mc["rec_down"]) else np.nan),
                         "현금 기준 균형정확도": (round(mc["balanced"], 4) if pd.notna(mc["balanced"]) else np.nan),
                         "현금 기준 MCC": (round(mc["mcc"], 4) if pd.notna(mc["mcc"]) else np.nan),
                         # [v0.44.0 F3(1)] M 상속 비교 — 이 값이 '현금 기준'보다 높으면 섹터 재추정이 정보를 깎고 있다
                         **{f"M상속({_nm}) 정밀도": (round(_v["prec_down"], 4) if pd.notna(_v["prec_down"]) else np.nan)
                            for _nm, _v in _mm.items()},
                         **{f"M상속({_nm}) 균형정확도": (round(_v["balanced"], 4) if pd.notna(_v["balanced"]) else np.nan)
                            for _nm, _v in _mm.items()},
                         **{f"M상속({_nm}) MCC": (round(_v["mcc"], 4) if pd.notna(_v["mcc"]) else np.nan)
                            for _nm, _v in _mm.items()},
                         "M상속 우위(MCC차)": (round(float(max(_v["mcc"] for _v in _mm.values() if pd.notna(_v["mcc"])) - (mc["mcc"] if pd.notna(mc["mcc"]) else 0.0)), 4)
                                          if (_mm and any(pd.notna(_v["mcc"]) for _v in _mm.values())) else np.nan),
                         "판독": ("방향 정보 없음(정밀도 ≤ 기저율)" if (pd.notna(m["prec_down"]) and m["prec_down"] <= m["base_down"] + 1e-9)
                                 else ("약한 정보" if (pd.notna(m["mcc"]) and m["mcc"] < 0.10) else "정보 있음"))})
            if pd.notna(m["balanced"]): per_h_bal[h].append(m["balanced"])
            if pd.notna(m["mcc"]): per_h_mcc[h].append(m["mcc"])
            if pd.notna(m["prec_down"]): per_h_prec[h].append(m["prec_down"])
            per_h_base[h].append(m["base_down"])
            if pd.notna(m["rec_down"]): per_h_rec[h].append(m["rec_down"])
            if h == h_main:
                pooled.append(pd.DataFrame({"pred": st[ok], "down": real_down, "y": st[ok].index.year}))
    for h in horizons:
        if per_h_bal[h]:
            rows.append({"블록": "A. 국면 소수클래스(티커별)", "티커": f"── {asset_label} 평균 ──", "지평(일)": h,
                         "표본일수": len(per_h_bal[h]),
                         "기저 실현하락률": round(float(np.mean(per_h_base[h])), 4),
                         "하락 정밀도(예측하락 중 실제하락)": round(float(np.mean(per_h_prec[h])), 4) if per_h_prec[h] else np.nan,
                         "하락 재현율(실제하락 중 예측하락)": round(float(np.mean(per_h_rec[h])), 4) if per_h_rec[h] else np.nan,
                         "균형정확도": round(float(np.mean(per_h_bal[h])), 4),
                         "MCC": round(float(np.mean(per_h_mcc[h])), 4) if per_h_mcc[h] else np.nan,
                         "판독": "균형정확도 0.5 = 동전던지기, MCC 0 = 무정보. 정밀도가 기저율과 같으면 하락 예측에 정보가 없다"})
            if h == h_main:
                _dfrows = [r for r in rows if r.get("블록", "").startswith("A.") and r.get("지평(일)") == h and r.get("티커") in tickers]
                for _c, _k in (("M상속(M현금) MCC", "regime_m_cash_mcc"), ("M상속(M상승아님) MCC", "regime_m_notup_mcc"),
                               ("현금 기준 MCC", "regime_cash_mcc")):
                    _vals = [r[_c] for r in _dfrows if pd.notna(r.get(_c, np.nan))]
                    if _vals:
                        summ[_k] = float(np.mean(_vals))
                summ["regime_balanced_mean"] = float(np.mean(per_h_bal[h]))
                summ["regime_mcc_mean"] = float(np.mean(per_h_mcc[h])) if per_h_mcc[h] else np.nan
                summ["regime_prec_mean"] = float(np.mean(per_h_prec[h])) if per_h_prec[h] else np.nan
                summ["regime_base_mean"] = float(np.mean(per_h_base[h]))
                summ["regime_rec_mean"] = float(np.mean(per_h_rec[h])) if per_h_rec[h] else np.nan
                summ["regime_n_assets"] = len(per_h_bal[h])
                summ["regime_n_mcc_pos"] = int(sum(1 for v in per_h_mcc[h] if v > 0))
    if "regime_m_cash_mcc" in summ:
        _own = summ.get("regime_cash_mcc", np.nan)
        _best = max([v for v in (summ.get("regime_m_cash_mcc"), summ.get("regime_m_notup_mcc")) if pd.notna(v)] or [np.nan])
        rows.append({"블록": "A. 국면 소수클래스(티커별)", "티커": f"── M 상속 비교(h={h_main}) ──",
                     "지평(일)": h_main,
                     "현금 기준 MCC": (round(_own, 4) if pd.notna(_own) else np.nan),
                     "M상속(M현금) MCC": (round(summ.get("regime_m_cash_mcc", np.nan), 4) if pd.notna(summ.get("regime_m_cash_mcc", np.nan)) else np.nan),
                     "M상속(M상승아님) MCC": (round(summ.get("regime_m_notup_mcc", np.nan), 4) if pd.notna(summ.get("regime_m_notup_mcc", np.nan)) else np.nan),
                     "M상속 우위(MCC차)": (round(float(_best - _own), 4) if (pd.notna(_best) and pd.notna(_own)) else np.nan),
                     "판독": ("M 상속 MCC가 자기 기계(현금 기준)보다 높으면 섹터별 재추정이 방향 정보를 깎고 있다는 뜻. "
                             "REPORT47 §2.3 기준선: 자기 0.055 · M현금 0.079 · M상승아님 0.088 → 리포트44 재현 "
                             "0.055/0.080/0.088(우위 +0.033). "
                             "[v0.45.0 G7] **MCC 우위는 맞지만 배분으로 옮기면 손해다** — [국면상속격자] 2행은 "
                             "리포트44에서 CAGR 35.20%(−0.53%p) · 33.33%(−1.96%p)로 둘 다 열위였고 회전율이 "
                             "12.4 → 16.8로 늘었다(섹터 자기 국면의 드문 대피가 2022에 값을 했다는 뜻). 격자는 "
                             "비웠고 이 열은 측정용으로 남긴다 — 되살리려면 "
                             "s_overrides={'ROTATION_REGIME_INHERIT_GRID': ('m_off','m_up')}")})
    rows.append({"블록": "A. 국면 소수클래스(티커별)", "티커": "해석",
                 "판독": f"소수 클래스 = 실현 하락(기저율 < 0.5). '예측 하락'은 01_일별 예측이 하락인 날, '현금'은 목표비중 0인 날. "
                         f"정밀도 ≈ 기저율·재현율 ~10%·MCC ≈ 0이면 이 계층은 {asset_label} 하락을 예측하지 못한다(REPORT46 §1.1). "
                         f"'큰하락 집중배율'은 꼬리 집중(방향이 아니라 변동성)을 따로 보인다"})

    # ---------- 블록 C ----------
    if pooled:
        P = pd.concat(pooled)
        for y, d in P.groupby("y"):
            pd_ = d[d["pred"] == "RISK_OFF"]; nu = d[d["pred"] == "NEUTRAL"]
            rows.append({"블록": f"C. 국면 연도별 pooled(h={h_main}일)", "티커": str(int(y)), "지평(일)": h_main,
                         "표본일수": int(len(d)), "기저 실현하락률": round(float(d["down"].mean()), 4),
                         "예측 하락 비율": round(float((d["pred"] == "RISK_OFF").mean()), 4),
                         "하락 정밀도(예측하락 중 실제하락)": (round(float(pd_["down"].mean()), 4) if len(pd_) else np.nan),
                         "하락 재현율(실제하락 중 예측하락)": round(float(((d["pred"] == "RISK_OFF") & d["down"]).sum() / max(1, int(d["down"].sum()))), 4),
                         "중립일 실현하락률": (round(float(nu["down"].mean()), 4) if len(nu) else np.nan),
                         "예측하락일수": int(len(pd_)),
                         "판독": ("하락 예측 0일" if len(pd_) == 0 else
                                 ("정밀도 > 기저율" if float(pd_["down"].mean()) > float(d["down"].mean()) else "정밀도 ≤ 기저율"))})
        _pd_all = P[P["pred"] == "RISK_OFF"]
        summ["regime_pooled_prec"] = float(_pd_all["down"].mean()) if len(_pd_all) else np.nan
        summ["regime_pooled_base"] = float(P["down"].mean())
        summ["regime_pooled_rec"] = float(((P["pred"] == "RISK_OFF") & P["down"]).sum() / max(1, int(P["down"].sum())))
        _yrs0 = [str(int(y)) for y, d in P.groupby("y") if int((d["pred"] == "RISK_OFF").sum()) == 0]
        summ["regime_zero_down_years"] = _yrs0

    # ---------- 블록 B ----------
    if alloc and isinstance(alloc.get("rank_pos"), pd.DataFrame) and "leader" in alloc:
        rk_pred = alloc["rank_pos"].copy()
        cols = [c for c in rk_pred.columns if c in results and c not in exclude_rank]
        rk_pred = rk_pred[cols]
        idx = rk_pred.index
        P_ = pd.DataFrame({c: pd.Series(results[c]["px_close"]).astype(float).reindex(idx) for c in cols})
        fwd = P_.shift(-h_main) / P_ - 1.0
        rk_real = fwd.rank(axis=1, ascending=False, method="min")
        n_av = fwd.notna().sum(axis=1)
        # [v0.48.0 L1 ★ 신규] 같은 종가 매트릭스(P_)로 h_main 외 지평의 실현 순위도 미리 만들어 둔다.
        #   판단일·리더 태그는 위 h_main 계산과 완전히 같다 — 바뀌는 것은 '실현 성적을 재는 창'뿐이라
        #   룩어헤드가 늘지 않는다(전방 수익은 여전히 t일 이후만 본다, 다만 판독 시 인접일 중첩에 유의 — §11 함정).
        _extra_rk: Dict[int, pd.DataFrame] = {}
        _extra_nav: Dict[int, pd.Series] = {}
        for _he in rot_extra_horizons:
            if int(_he) == h_main or int(_he) <= 0:
                continue
            _fh = P_.shift(-int(_he)) / P_ - 1.0
            _extra_rk[int(_he)] = _fh.rank(axis=1, ascending=False, method="min")
            _extra_nav[int(_he)] = _fh.notna().sum(axis=1)

        def _hit_top3_extra(d, c) -> Dict[int, float]:
            """[v0.48.0 L1] 그날 실현 순위(지평별)로 c가 상위3인지 — n_av < 5인 지평은 NaN(비교 대상 부족)."""
            out: Dict[int, float] = {}
            for _he, _rk in _extra_rk.items():
                _nn = int(_extra_nav[_he].loc[d]) if d in _extra_nav[_he].index else 0
                _v = _rk.loc[d].get(c, np.nan) if d in _rk.index else np.nan
                out[_he] = float(_v <= 3) if (_nn >= 5 and pd.notna(_v)) else np.nan
            return out
        lead = pd.Series(alloc["leader"]).reindex(idx).astype(str)
        tier = pd.Series(alloc.get("tier", pd.Series("", index=idx))).reindex(idx).astype(str)
        held = tier.eq("리더") | tier.eq("하락국면리더")
        # 순위가 전부 NaN인 날(채택 전·상장 전)은 idxmin/idxmax가 ValueError를 내므로 먼저 걸러 낸다.
        _has = rk_pred.notna().sum(axis=1) >= 5
        top_pred = pd.Series(np.nan, index=idx, dtype=object)
        bot_pred = pd.Series(np.nan, index=idx, dtype=object)
        if bool(_has.any()):
            top_pred[_has] = rk_pred[_has].idxmin(axis=1).values
            bot_pred[_has] = rk_pred[_has].idxmax(axis=1).values
        # [v0.44.0 F1] 회피 쪽 두 계열을 함께 센다 — 이 잣대가 회피 규칙을 열지 말지를 정한다.
        #   (가) 꼴찌 지목(alloc["laggard"], 규칙 ②) — 현행 회피 규칙이 실제로 피하는 섹터.
        #   (나) 역방향 회피 대상 — 그 해 상위1 t ≤ −T였던 신호의 **1위**(REPORT47 §3.3의 REL_VOL_RATIO 경로).
        #        wf의 rank_full·reverse_avoid_by_year로 직접 구한다(배분과 같은 평활 순위 정의, 재계산 없음).
        lag = pd.Series(alloc.get("laggard", pd.Series("", index=idx))).reindex(idx).astype(str)
        rev_target = pd.Series(np.nan, index=idx, dtype=object)
        rev_sigs_by_year: Dict[int, List[str]] = {}
        _wf = alloc.get("wf") or {}
        _rev_by_y = _wf.get("reverse_avoid_by_year") or {}
        _rank_full = _wf.get("rank_full") or {}
        if _rev_by_y and _rank_full:
            _sm = int(_wf.get("smooth", 1) or 1)
            for _y, _sigs in _rev_by_y.items():
                _use = [n for n in (_sigs or []) if n in _rank_full]
                if not _use:
                    continue
                rev_sigs_by_year[int(_y)] = _use
                _rows_y = idx[idx.year == int(_y)]
                if len(_rows_y) == 0:
                    continue
                # 각 자격 신호의 1위를 모아 최빈(동률이면 첫 신호) — 여러 신호가 자격일 때의 합의 규칙
                _picks = []
                for n in _use:
                    _r = _rank_full[n].reindex(index=idx, columns=cols)
                    _rs = _r.rolling(_sm, min_periods=1).mean().where(_r.notna()) if _sm > 1 else _r
                    _rs = _rs.loc[_rows_y]
                    _ok = _rs.notna().sum(axis=1) >= 5
                    _p = pd.Series(np.nan, index=_rows_y, dtype=object)
                    if bool(_ok.any()):
                        _p[_ok] = _rs[_ok].idxmax(axis=1).values      # rank01은 클수록 1위
                    _picks.append(_p)
                _PK = pd.concat(_picks, axis=1)
                rev_target.loc[_rows_y] = _PK.mode(axis=1, dropna=True).iloc[:, 0].values if _PK.notna().any().any() else np.nan
        recs = []
        for d in idx:
            if n_av.loc[d] < 5:
                continue
            rr = rk_real.loc[d]; nn = int(n_av.loc[d]); med = fwd.loc[d].median()
            rec = {"y": int(d.year)}
            L = lead.loc[d]
            if held.loc[d] and L in cols and pd.notna(rr.get(L, np.nan)):
                rec["lead"] = L; rec["lead_top3"] = float(rr[L] <= 3); rec["lead_bot3"] = float(rr[L] >= nn - 2)
                rec["lead_med"] = float(fwd.loc[d, L] > med)
                # [v0.47.0 J1] '리더'(교차 순환매 리더)와 '하락국면리더'(E_t=0·명확1위 보유, v0.15.0 §A)를
                #   태그부터 분리한다 — REPORT50 §2.2 E8: "2026 16일 1.000"을 R2 성과로 잘못 인용한 원인이
                #   두 규칙이 '리더 판단일' 한 열에 섞여 있었던 것이었다. 재계산 없음(tier 라벨만 읽는다).
                rec["lead_type"] = str(tier.loc[d])
                for _he, _hv in _hit_top3_extra(d, L).items():   # [v0.48.0 L1]
                    rec[f"lead_top3_h{_he}"] = _hv
            tp1 = top_pred.loc[d]; bp1 = bot_pred.loc[d]
            if isinstance(tp1, str) and pd.notna(rr.get(tp1, np.nan)):
                rec["top_top3"] = float(rr[tp1] <= 3)
            if isinstance(bp1, str) and pd.notna(rr.get(bp1, np.nan)):
                rec["bot_bot3"] = float(rr[bp1] >= nn - 2); rec["bot_top3"] = float(rr[bp1] <= 3); rec["bot"] = bp1
            # [v0.44.0 F1] 회피 쪽 — 지목된 섹터가 실제로 뒤처졌나(초과는 그날 상장 평균 대비)
            _lg = lag.loc[d]
            if _lg in cols and pd.notna(rr.get(_lg, np.nan)):
                rec["avoid_bot3"] = float(rr[_lg] >= nn - 2); rec["avoid_top3"] = float(rr[_lg] <= 3)
                rec["avoid_exc"] = float(fwd.loc[d, _lg] - med)
            _rv = rev_target.loc[d]
            if isinstance(_rv, str) and _rv in cols and pd.notna(rr.get(_rv, np.nan)):
                rec["rev_bot3"] = float(rr[_rv] >= nn - 2); rec["rev_top3"] = float(rr[_rv] <= 3)
                rec["rev_exc"] = float(fwd.loc[d, _rv] - med); rec["rev"] = _rv
            recs.append(rec)
        R = pd.DataFrame(recs)
        if len(R):
            rand = 3.0 / max(1.0, float(n_av[n_av >= 5].mean()))
            def _mn(d: pd.DataFrame, c: str):
                return (round(float(d[c].mean()), 4) if (c in d.columns and d[c].notna().any()) else np.nan)

            def _blk(d: pd.DataFrame, label: str) -> dict:
                L_ = d.dropna(subset=["lead"]) if "lead" in d.columns else d.iloc[0:0]
                # [v0.47.0 J1] 리더 판단일을 유형별로 쪼갠다 — '교차'(순환매 복합순위 리더) vs
                #   '하락국면리더'(E_t=0인데 명확1위를 게이트 통과로 보유, v0.15.0 §A). 합계(리더 판단일)는
                #   하위 호환을 위해 그대로 두고, 두 유형 열을 나란히 낸다.
                _lt = L_["lead_type"] if "lead_type" in L_.columns else pd.Series(dtype=object)
                _Lx = L_[_lt.eq("리더")] if len(L_) else L_
                _Ld = L_[_lt.eq("하락국면리더")] if len(L_) else L_
                # [v0.47.0 J5(선택)] 연도별 최빈 리더(집중도) — 정적 편향(예: 2023~25 XLC)을 표에서 바로 드러낸다.
                #   계산 없음(13c 판단 열의 재집계, Block E와 같은 방식).
                _lead_vc_b = _Lx["lead"].value_counts() if len(_Lx) else pd.Series(dtype=object)
                # [v0.48.0 L1] h_main(21) 옆에 지평 진단 열 — 판단·리더 태그는 동일, 실현 순위 창만 다르다.
                _extra_h_cols: Dict[str, Any] = {}
                for _he in rot_extra_horizons:
                    if int(_he) == h_main:
                        continue
                    _c = f"lead_top3_h{int(_he)}"
                    _extra_h_cols[f"리더 → 실현 상위3(h={int(_he)})"] = (
                        round(float(L_[_c].mean()), 4) if (_c in L_.columns and L_[_c].notna().any()) else np.nan)
                    _extra_h_cols[f"리더(교차) → 실현 상위3(h={int(_he)})"] = (
                        round(float(_Lx[_c].mean()), 4) if (_c in _Lx.columns and _Lx[_c].notna().any()) else np.nan)
                    _extra_h_cols[f"하락국면리더 → 실현 상위3(h={int(_he)})"] = (
                        round(float(_Ld[_c].mean()), 4) if (_c in _Ld.columns and _Ld[_c].notna().any()) else np.nan)
                return {"블록": f"B. 순환매 소수클래스(연도별, h={h_main}일)", "티커": label, "지평(일)": h_main,
                        "리더 판단일": int(len(L_)),
                        "리더 → 실현 상위3": (round(float(L_["lead_top3"].mean()), 4) if len(L_) else np.nan),
                        "리더 → 실현 하위3": (round(float(L_["lead_bot3"].mean()), 4) if len(L_) else np.nan),
                        "리더 > 중앙값": (round(float(L_["lead_med"].mean()), 4) if len(L_) else np.nan),
                        "리더(교차) 판단일": int(len(_Lx)),
                        "리더(교차) → 실현 상위3": (round(float(_Lx["lead_top3"].mean()), 4) if len(_Lx) else np.nan),
                        "하락국면리더일": int(len(_Ld)),
                        "하락국면리더 → 실현 상위3": (round(float(_Ld["lead_top3"].mean()), 4) if len(_Ld) else np.nan),
                        **_extra_h_cols,
                        "최빈 리더(집중도, 교차만)": (f"{_lead_vc_b.index[0]} {float(_lead_vc_b.iloc[0]) / max(int(_lead_vc_b.sum()), 1):.2f}"
                                                if len(_lead_vc_b) else ""),
                        "순위 있는 날": int(d["top_top3"].notna().sum()) if "top_top3" in d.columns else 0,
                        "모델 1위 → 실현 상위3": (round(float(d["top_top3"].mean()), 4) if "top_top3" in d.columns and d["top_top3"].notna().any() else np.nan),
                        "모델 꼴찌 → 실현 하위3": (round(float(d["bot_bot3"].mean()), 4) if "bot_bot3" in d.columns and d["bot_bot3"].notna().any() else np.nan),
                        "모델 꼴찌 → 실현 상위3": (round(float(d["bot_top3"].mean()), 4) if "bot_top3" in d.columns and d["bot_top3"].notna().any() else np.nan),
                        # [v0.44.0 F1] 회피 쪽 — (가) 규칙 ② 꼴찌 지목일 (나) 역방향 회피 대상(상위1 t ≤ −T 신호의 1위)
                        "회피 지목일": (int(d["avoid_bot3"].notna().sum()) if "avoid_bot3" in d.columns else 0),
                        "회피 섹터 → 실현 하위3": _mn(d, "avoid_bot3"),
                        "회피 섹터 → 실현 상위3": _mn(d, "avoid_top3"),
                        "회피 섹터 초과(%/21일)": (round(_mn(d, "avoid_exc") * 100, 3) if pd.notna(_mn(d, "avoid_exc")) else np.nan),
                        "역방향 회피 대상일": (int(d["rev_bot3"].notna().sum()) if "rev_bot3" in d.columns else 0),
                        "역방향 대상 → 실현 하위3": _mn(d, "rev_bot3"),
                        "역방향 대상 → 실현 상위3": _mn(d, "rev_top3"),
                        "역방향 대상 초과(%/21일)": (round(_mn(d, "rev_exc") * 100, 3) if pd.notna(_mn(d, "rev_exc")) else np.nan),
                        "무작위 기대(상위3/하위3)": round(rand, 3),
                        "판독": ""}
            for y, d in R.groupby("y"):
                rows.append(_blk(d, str(int(y))))
            allrow = _blk(R, "── 전체 ──")
            allrow["판독"] = ("리더→상위3가 무작위보다 크면 상위 쪽 정보 있음. 꼴찌→하위3가 무작위와 같으면 하위 쪽 정보 없음"
                            "(회피 규칙이 열릴 수 없다). 연도별로 내려오면 채택 최근성(S-I②)이 걸러야 한다. "
                            "[v0.45.0 G6] 역방향 회피(F1)는 **퇴역**했다 — 리포트44 실측에서 '역방향 대상 → 실현 상위3'이 "
                            "0.303(무작위 0.274보다 **크고**) 초과도 +0.25%/21일로, 채택 조건('뚜렷이 작고 초과가 음수')의 "
                            "정반대였다. 아래 '역방향 자격 신호' 줄은 진단으로 남는다. "
                            "[v0.45.0 G5] 하위 쪽 후속은 [단독회피격자] — 자격 신호가 1개뿐이어도 **순서 잣대**"
                            "(학습창 꼴찌→하위3 ≥ 0.33 & 최근 252일 ≥ 0.40)를 넘으면 규칙 ②를 연다. "
                            "[v0.47.0 J1·G5(3) 퇴역·REPORT50 §2.3] [단독회피격자]는 세 번째 독립 측정(13p 블록 E)에서도 "
                            "회피→하위3 0.15·초과 +0.99%/21일로 무작위(0.273)에 크게 못 미쳐 **퇴역**했다(강세장 해에 방어 "
                            "섹터가 오히려 상위3에 더 자주 든다) — 되돌리기: s_overrides={'ROTATION_AVOID_STANDALONE_GRID': "
                            "('order','size+order')}. 13g '단독회피 자격(순서)' 열과 아래 계산은 진단으로 유지한다. "
                            "[v0.47.0 J1] '리더 판단일'은 **교차 순환매 리더**(복합순위 리더)와 **하락국면리더**(E_t=0인데 "
                            "명확1위를 게이트 통과로 보유, v0.15.0 §A)를 합친 값이다 — 인용은 옆의 '리더(교차)'/'하락국면리더일' "
                            "두 열로 나눠서 할 것. 이전 세 라운드(REPORT47~49)가 \"2026 리더 16일 → 실현 상위3 1.000\"을 R2(최근성 "
                            "문턱)의 성과로 인용했으나, 실측을 나눠 보면 그 16일은 **전부 하락국면리더**이고 2026년 교차 리더는 "
                            "**0일**이다(그 해 4개 채택 신호 중 과반 3표가 든 날이 16일뿐이라 리더가 열리지 않았다) — 서사 오류 "
                            "정정(REPORT50 §2.2 E8). 2023~25 교차 리더는 XLC가 351일(리더일의 40%, '최빈 리더(집중도, 교차만)' "
                            "열 참조)로 몰려 있고 그중 2024·2025는 0.354·0.383으로 무작위(0.273) 근처다 — ★의 순환매 몫은 "
                            "2020·2022·2023 세 에피소드에 크게 의존한다")
            rows.append(allrow)
            if rev_sigs_by_year:
                rows.append({"블록": f"B. 순환매 소수클래스(연도별, h={h_main}일)", "티커": "역방향 자격 신호(연도별)",
                             "판독": "; ".join(f"{y}:{'+'.join(v)}" for y, v in sorted(rev_sigs_by_year.items()))
                                     + " — 그 해 학습창에서 상위1 t ≤ −ROTATION_REVERSE_AVOID_T였던 신호(13g '역방향 회피 자격' Y)"})
            if "rev" in R.columns and R["rev"].notna().any():
                _vc = R["rev"].value_counts().head(5)
                rows.append({"블록": f"B. 순환매 소수클래스(연도별, h={h_main}일)", "티커": "역방향 회피 대상 분포",
                             "판독": "; ".join(f"{k} {int(v)}일" for k, v in _vc.items())
                                     + " — 한 섹터로 고정되면 '그 섹터를 빼는 규칙'이지 순환매 예측이 아니다(그래도 값이 있으면 격자가 잡는다)"})
            if "bot" in R.columns:
                vc = R["bot"].value_counts().head(5)
                rows.append({"블록": f"B. 순환매 소수클래스(연도별, h={h_main}일)", "티커": "모델 꼴찌 분포",
                             "판독": "; ".join(f"{k} {int(v)}일" for k, v in vc.items())
                                     + " — 강세장에서 강도 순위의 바닥이 '방어 섹터'로 고정되면 꼴찌 예측이 아니다"})
            L_all = R.dropna(subset=["lead"]) if "lead" in R.columns else R.iloc[0:0]
            summ["rot_lead_top3"] = float(L_all["lead_top3"].mean()) if len(L_all) else np.nan
            summ["rot_lead_days"] = int(len(L_all))
            summ["rot_bot_bot3"] = float(R["bot_bot3"].mean()) if "bot_bot3" in R.columns and R["bot_bot3"].notna().any() else np.nan
            summ["rot_random"] = rand
            # [v0.44.0 F1] 00시트·13f ⑧에 실을 회피 쪽 요약
            for _k, _c in (("rot_avoid_bot3", "avoid_bot3"), ("rot_avoid_top3", "avoid_top3"),
                           ("rot_rev_bot3", "rev_bot3"), ("rot_rev_top3", "rev_top3")):
                summ[_k] = (float(R[_c].mean()) if (_c in R.columns and R[_c].notna().any()) else np.nan)
            summ["rot_rev_days"] = int(R["rev_bot3"].notna().sum()) if "rev_bot3" in R.columns else 0
            summ["rot_rev_exc"] = (float(R["rev_exc"].mean()) if ("rev_exc" in R.columns and R["rev_exc"].notna().any()) else np.nan)
            _ly = R["y"].max()
            L_last = L_all[L_all["y"] == _ly] if len(L_all) else L_all
            summ["rot_last_year"] = int(_ly)
            summ["rot_lead_top3_last"] = float(L_last["lead_top3"].mean()) if len(L_last) else np.nan
            summ["rot_lead_days_last"] = int(len(L_last))
            # [v0.48.0 L4 ⚠ 결함수정 — REPORT51 §2.4 E5] 00시트 요약이 리더(교차)+하락국면리더를 합산해
            #   귀속 오류(REPORT47~49 "2026 16일 1.000"이 실은 전부 하락국면리더였던 것)를 재발시킬 위험이
            #   있었다 — 분리해서 낸다. 기존 rot_lead_top3/rot_lead_days(합산, 위)는 13f 등 다른 소비처와의
            #   하위호환을 위해 그대로 둔다.
            _lt_all = L_all["lead_type"] if "lead_type" in L_all.columns else pd.Series(dtype=object)
            _Lx_all = L_all[_lt_all.eq("리더")] if len(L_all) else L_all
            _Ld_all = L_all[_lt_all.eq("하락국면리더")] if len(L_all) else L_all.iloc[0:0]
            summ["rot_leadcross_top3"] = float(_Lx_all["lead_top3"].mean()) if len(_Lx_all) else np.nan
            summ["rot_leadcross_days"] = int(len(_Lx_all))
            summ["rot_downleader_top3"] = float(_Ld_all["lead_top3"].mean()) if len(_Ld_all) else np.nan
            summ["rot_downleader_days"] = int(len(_Ld_all))
            for _he in rot_extra_horizons:   # [v0.48.0 L1] 00시트 병기용(minority_summary_text가 h=63을 쓴다)
                if int(_he) == h_main:
                    continue
                _c = f"lead_top3_h{int(_he)}"
                if _c in _Lx_all.columns and _Lx_all[_c].notna().any():
                    summ[f"rot_leadcross_top3_h{int(_he)}"] = float(_Lx_all[_c].mean())
                if _c in L_all.columns and L_all[_c].notna().any():
                    summ[f"rot_lead_top3_h{int(_he)}"] = float(L_all[_c].mean())
                if _c in _Ld_all.columns and _Ld_all[_c].notna().any():
                    summ[f"rot_downleader_top3_h{int(_he)}"] = float(_Ld_all[_c].mean())

        # ---------- 블록 D [v0.45.0 G2 ★ 신규] 1위 득표 × M 국면 ----------
        # 왜: REPORT48 §3 — 복합순위 1위의 실현 상위3 적중은 '그날 몇 개의 채택 신호가 그 섹터를 1위로
        #   지목했나'(13c '1위 득표')에 **단조**이고, 그 정보는 M 국면이 중립일 때 집중된다. 리포트44 실측:
        #     득표 0표 0.182(313일) / 1표 0.296(433) / 2표 0.396(881) / 3표 0.821(56)
        #     득표≥2·M중립 0.565·초과 +2.74% vs 득표≥2·M상승 0.381·+1.50%
        #     득표≤1·M상승 **0.227·−0.71%** — 무작위(0.274)보다 나쁘다(644일)
        #   그런데 ★의 잔여 슬리브·대피처는 득표·국면과 무관하게 늘 복합 1위를 산다(§4). 이 블록은 그
        #   구조를 매 실행 드러내 [대피처격자](G3)의 판정 근거가 되고, 다음 라운드가 원자료를 다시
        #   재계산하지 않게 한다. **새 계산·새 신호 없음** — 13c '1위 득표'·순위 열과 01Z 'SPY 시장상황'뿐.
        #   현금일(E_t=0)은 제외한다: 그날 복합 1위는 사지 않는 섹터라 배분 판단이 아니다.
        _votes_s = alloc.get("votes_leader")
        _mst = alloc.get("spy_state_short")
        if _votes_s is not None and len(R):
            _v = pd.Series(_votes_s).reindex(idx).fillna(-1).astype(int)
            _ms = (pd.Series(_mst).reindex(idx).astype(str) if _mst is not None
                   else pd.Series("-", index=idx))
            _cash = tier.eq("현금")
            # 그날 복합 1위(top_pred)의 실현 성적 — 블록 B의 top_top3와 같은 정의에 초과 2종을 더한다.
            _spy_r = alloc.get("spy_ret")
            _spy_fwd = None
            if _spy_r is not None:
                _sr = pd.Series(_spy_r).reindex(idx).astype(float)
                _spy_fwd = ((1.0 + _sr).rolling(h_main).apply(np.prod, raw=True) - 1.0).shift(-h_main)
            _recs_d = []
            for d in idx:
                if n_av.loc[d] < 5 or bool(_cash.loc[d]):
                    continue
                _tp = top_pred.loc[d]
                if not isinstance(_tp, str) or _tp not in cols:
                    continue
                rr = rk_real.loc[d]
                if pd.isna(rr.get(_tp, np.nan)):
                    continue
                nn = int(n_av.loc[d])
                _recs_d.append({"y": int(d.year), "votes": int(_v.loc[d]), "m": str(_ms.loc[d]),
                                "top3": float(rr[_tp] <= 3), "bot3": float(rr[_tp] >= nn - 2),
                                "exc_ew": float(fwd.loc[d, _tp] - fwd.loc[d].mean()),
                                "exc_spy": (float(fwd.loc[d, _tp] - _spy_fwd.loc[d])
                                            if (_spy_fwd is not None and pd.notna(_spy_fwd.loc[d])) else np.nan)})
            D = pd.DataFrame(_recs_d)
            if len(D):
                _blk_d = f"D. 득표×국면(복합 1위, h={h_main}일)"

                def _row_d(dd: pd.DataFrame, label: str, note: str = "") -> dict:
                    return {"블록": _blk_d, "티커": label, "지평(일)": h_main, "표본일수": int(len(dd)),
                            "복합1위 → 실현 상위3": (round(float(dd["top3"].mean()), 4) if len(dd) else np.nan),
                            "복합1위 → 실현 하위3": (round(float(dd["bot3"].mean()), 4) if len(dd) else np.nan),
                            "복합1위 초과(균등,%/{}일)".format(h_main):
                                (round(float(dd["exc_ew"].mean()) * 100, 3) if len(dd) else np.nan),
                            "복합1위 초과(SPY,%/{}일)".format(h_main):
                                (round(float(dd["exc_spy"].mean()) * 100, 3)
                                 if (len(dd) and dd["exc_spy"].notna().any()) else np.nan),
                            "무작위 기대(상위3/하위3)": round(rand, 3), "판독": note}
                for _vv in sorted(D["votes"].unique()):
                    if int(_vv) < 0:
                        continue
                    rows.append(_row_d(D[D["votes"] == _vv], f"득표 {int(_vv)}표"))
                for _mm2 in ("상승", "중립", "하락"):
                    _d2 = D[D["m"] == _mm2]
                    if not len(_d2):
                        continue
                    rows.append(_row_d(D[(D["votes"] >= 2) & (D["m"] == _mm2)], f"득표≥2 · M {_mm2}"))
                    rows.append(_row_d(D[(D["votes"] <= 1) & (D["m"] == _mm2)], f"득표≤1 · M {_mm2}"))
                for _y2, _d3 in D.groupby("y"):
                    rows.append(_row_d(_d3[_d3["votes"] >= 2], f"{int(_y2)} 득표≥2"))
                    rows.append(_row_d(_d3[_d3["votes"] <= 1], f"{int(_y2)} 득표≤1"))
                _hi = D[D["votes"] >= 2]; _lo = D[D["votes"] <= 1]
                _lo_up = D[(D["votes"] <= 1) & (D["m"] == "상승")]
                summ["votes_hi_top3"] = float(_hi["top3"].mean()) if len(_hi) else np.nan
                summ["votes_lo_top3"] = float(_lo["top3"].mean()) if len(_lo) else np.nan
                summ["votes_lo_up_top3"] = float(_lo_up["top3"].mean()) if len(_lo_up) else np.nan
                summ["votes_lo_up_exc"] = float(_lo_up["exc_ew"].mean()) if len(_lo_up) else np.nan
                summ["votes_lo_up_days"] = int(len(_lo_up))
                summ["votes_hi_days"] = int(len(_hi))
                rows.append({"블록": _blk_d, "티커": "해석",
                             "판독": ("득표 = 그날 채택 신호 중 복합 1위와 같은 섹터를 1위로 지목한 수(13c '1위 득표'). "
                                     "현금일(E_t=0)은 제외 — 그날 1위는 사지 않는 섹터라 배분 판단이 아니다. "
                                     "적중이 득표수에 **단조**이고 득표≤1·M상승이 무작위(3/n) 아래면, ★의 잔여 슬리브가 "
                                     "그 날에도 1위를 사는 현행 규칙이 손해라는 뜻이다 — [대피처격자](v0.45.0 G3) 행과 "
                                     "13m 블록 D가 그 판정을 낸다. REPORT48 §3 기준선: 0표 0.182 / 1표 0.296 / 2표 0.396 / "
                                     "3표 0.821 · 득표≤1·상승 0.227(−0.71%/21일, 644일)")})

        # ---------- 블록 E [v0.46.0 H4 ★ 신규] 격자 변형별 소수 클래스 ----------
        # 왜: v0.45.0의 [단독회피격자]·(산업) [단독리더격자]는 **판정 지표 없이** CAGR만 보고 기각됐다.
        #   블록 B는 라이브 배분(alloc["leader"]/["laggard"])만 세는데 라이브는 회피 0일이라 잴 것이 없었고,
        #   격자 행이 실제로 연 회피·리더일의 적중은 어느 시트에도 남지 않았다(REPORT49 §1-5·§4 E4).
        #   → 격자가 '수익으로 졌다'만 알고 '예측으로도 졌는가'는 모르는 채 닫히는 것을 막는다.
        # 무엇: build_sector_allocation이 alloc["variants_diag"][라벨] = {"tier","leader","laggard"}로 남긴
        #   **이미 계산된 시계열**을 블록 B와 같은 정의(h_main 전방 순위)로 재집계한다. 신규 계산·신규 신호 없음.
        # 읽는 법: 리더→상위3 · 회피→하위3이 '무작위 기대'를 넘는지, 그리고 top_share(최빈 대상 쏠림)가
        #   작은지를 본다. top_share가 크면 그 규칙은 '그 섹터를 사고/빼는 규칙'이지 순환매 예측이 아니다.
        _vdiag = (alloc or {}).get("variants_diag") or {}
        if _vdiag:
            _blk_e = f"E. 격자 변형별 소수 클래스(h={h_main}일)"
            for _lab_v in sorted(_vdiag, key=lambda l_: ("[" in str(l_), str(l_))):
                _dv = _vdiag.get(_lab_v) or {}
                _tv = pd.Series(_dv.get("tier", pd.Series(dtype=object))).reindex(idx).astype(str)
                _lv = pd.Series(_dv.get("leader", pd.Series(dtype=object))).reindex(idx).astype(str)
                _gv = pd.Series(_dv.get("laggard", pd.Series(dtype=object))).reindex(idx).astype(str)
                _held_v = _tv.eq("리더") | _tv.eq("하락국면리더")
                _avoid_v = _tv.eq("회피")
                _lh, _ah, _ax = [], [], []
                _lh_extra: Dict[int, List[float]] = {int(_he): [] for _he in rot_extra_horizons if int(_he) != h_main}
                for d in idx:
                    if n_av.loc[d] < 5:
                        continue
                    rr = rk_real.loc[d]; nn = int(n_av.loc[d]); med = fwd.loc[d].median()
                    if bool(_held_v.loc[d]):
                        _c = _lv.loc[d]
                        if _c in cols and pd.notna(rr.get(_c, np.nan)):
                            _lh.append(float(rr[_c] <= 3))
                            for _he, _hv in _hit_top3_extra(d, _c).items():   # [v0.48.0 L1]
                                if pd.notna(_hv):
                                    _lh_extra[_he].append(_hv)
                    if bool(_avoid_v.loc[d]):
                        _c = _gv.loc[d]
                        if _c in cols and pd.notna(rr.get(_c, np.nan)):
                            _ah.append(float(rr[_c] >= nn - 2)); _ax.append(float(fwd.loc[d, _c] - med))
                _lag_vc = _gv[_avoid_v & _gv.isin(cols)].value_counts()
                _lead_vc = _lv[_held_v & _lv.isin(cols)].value_counts()
                # [v0.48.0 L1] 지평 진단 열 — 같은 held 일자(_lh와 동일 판단), 실현 순위 창만 다르다.
                _extra_h_cols_e = {f"리더 → 실현 상위3(h={_he})": (round(float(np.mean(_v)), 4) if _v else np.nan)
                                   for _he, _v in _lh_extra.items()}
                rows.append({"블록": _blk_e, "티커": str(_lab_v)[:60], "지평(일)": h_main,
                             "리더 판단일": int(len(_lh)),
                             "리더 → 실현 상위3": (round(float(np.mean(_lh)), 4) if _lh else np.nan),
                             **_extra_h_cols_e,
                             "회피 지목일": int(len(_ah)),
                             "회피 섹터 → 실현 하위3": (round(float(np.mean(_ah)), 4) if _ah else np.nan),
                             "회피 섹터 초과(%/21일)": (round(float(np.mean(_ax)) * 100, 3) if _ax else np.nan),
                             "무작위 기대(상위3/하위3)": round(rand, 3),
                             "최빈 리더(집중도)": (f"{_lead_vc.index[0]} {float(_lead_vc.iloc[0]) / max(int(_lead_vc.sum()), 1):.2f}"
                                             if len(_lead_vc) else ""),
                             "최빈 회피(집중도)": (f"{_lag_vc.index[0]} {float(_lag_vc.iloc[0]) / max(int(_lag_vc.sum()), 1):.2f}"
                                             if len(_lag_vc) else "")})
            rows.append({"블록": _blk_e, "티커": "해석",
                         "판독": ("격자 행을 **수익이 아니라 예측으로** 판정하는 표. 리더→상위3·회피→하위3이 무작위 기대를 "
                                 "넘으면 그 규칙은 '예측으로는 성립'이고, CAGR이 져도 그 사실을 기록한다(반대로 둘 다 "
                                 "무작위면 그 방향은 닫는다). 집중도(최빈 대상 비중)가 크면 '그 섹터를 사고/빼는 규칙'이지 "
                                 "순환매가 아니다. v0.45.0은 이 표가 없어 [단독회피격자]를 CAGR만 보고 닫았다(REPORT49 §4 E4). "
                                 "[v0.47.0 J1] '[라이브 기준]' 행과 '[★ 하락국면리더일]' 행은 이제 분리된다 — 전자는 교차 순환매 "
                                 "리더(611일)만, 후자는 E_t=0인데 명확1위를 게이트 통과로 보유한 날(264일)만 센다. 이전엔 "
                                 "_keep_diag가 tier Series를 참조로 저장해 라이브 행이 두 규칙을 합쳐 875일로 찍혔다(REPORT50 "
                                 "§2.4 E1) — 그 오염이 격자 판정 자체를 바꾸진 않았지만(리더만 보면 라이브 0.4255 = 격자 "
                                 "0.4255) 표의 비교 기준이 격자 행(611일, 하락국면리더 오버라이드 미적용)과 어긋났다. "
                                 "[v0.47.0 J1·REPORT50 §2.2 E8] 참고: 2026 '리더 16일 1.000'은 전부 '[★ 하락국면리더일]'류의 "
                                 "판단이었다 — 그 해 교차 순환매 리더는 라이브 0일이다. 순환매 리더 성과를 인용할 때는 "
                                 "'[라이브 기준]' 행만 볼 것. [v0.48.0 L1] '리더 → 실현 상위3(h=42/63/126)' 열은 같은 판단일에 "
                                 "실현 순위를 재는 창만 늘린 진단이다 — h=21보다 크게 오르면 그 규칙의 신호가 h=21보다 느리다는 "
                                 "뜻이지 h=21에서의 판단이 바뀐다는 뜻이 아니다(§9 지평 명시 규약: 지평 없이 적중률을 인용하지 말 것)")})
    df = pd.DataFrame(rows)
    if len(df):
        lead_cols = ["블록", "티커", "지평(일)", "표본일수"]
        df = df[[c for c in lead_cols if c in df.columns] + [c for c in df.columns if c not in lead_cols]]
    return df, summ


def _fit_logistic_w(X: np.ndarray, y: np.ndarray, w: Optional[np.ndarray] = None,
                    l2: float = 1.0, iters: int = 60, tol: float = 1e-7) -> Optional[np.ndarray]:
    """[v0.44.0 F4] 가중 L2-정규화 로지스틱 회귀 — IRLS(뉴턴). scikit-learn 의존을 만들지 않으려고
    직접 푼다(파이프라인의 나머지가 numpy/pandas만 쓴다). X는 절편 열을 **포함하지 않은** 설계행렬,
    반환은 [절편, 계수...]. 수렴 실패·특이행렬이면 None(호출부는 그 해를 건너뛴다).
    l2는 절편을 제외한 계수에만 건다(표본이 작은 해에 계수가 발산하지 않게)."""
    n, k = X.shape
    if n < 30 or k == 0:
        return None
    A = np.column_stack([np.ones(n), X])
    w = np.ones(n) if w is None else np.asarray(w, dtype=float)
    w = w / max(float(w.sum()), 1e-12) * n          # 평균 1로 정규화 — l2의 의미를 표본 수와 무관하게
    beta = np.zeros(k + 1)
    R = np.eye(k + 1) * float(l2)
    R[0, 0] = 0.0                                    # 절편은 정규화하지 않는다
    for _ in range(iters):
        eta = np.clip(A @ beta, -30.0, 30.0)
        p = 1.0 / (1.0 + np.exp(-eta))
        s = np.clip(p * (1.0 - p), 1e-6, None) * w
        g = A.T @ (w * (y - p)) - R @ beta
        H = (A * s[:, None]).T @ A + R
        try:
            step = np.linalg.solve(H, g)
        except np.linalg.LinAlgError:
            return None
        beta = beta + step
        if not np.all(np.isfinite(beta)):
            return None
        if float(np.max(np.abs(step))) < tol:
            break
    return beta


def _predict_logistic(beta: np.ndarray, X: np.ndarray) -> np.ndarray:
    A = np.column_stack([np.ones(len(X)), X])
    return 1.0 / (1.0 + np.exp(-np.clip(A @ beta, -30.0, 30.0)))


def build_down_probability(results: Dict[str, Dict[str, Any]], alloc: Optional[Dict[str, Any]], scfg: SectorConfig,
                           M, h: int = 21, asset_label: str = "섹터") -> Tuple[pd.DataFrame, Dict[str, pd.Series], Dict[str, Any]]:
    """[v0.44.0 F4 ★ 신규 측정 기능] 13q_하락확률보정 — **P(향후 h일 수익 < 0)** 을 섹터별·연도별
    워크포워드로 추정하고, 그 확률이 실제와 맞는지(보정)를 신뢰도 곡선·Brier로 잰다.

    왜 필요한가(REPORT47 §6 F4): 현재 계층은 3상태 라벨(상승/중립/하락)만 낸다. 하락 라벨이 전체의
    7%뿐이라 **재현율이 구조적으로 10% 언저리에 갇힌다** — 잣대를 아무리 바꿔도 이 한계는 안 풀린다.
    확률을 내면 (1) 운용점(문턱)을 기저율에 맞출 수 있고 (2) 정보가 없으면 신뢰도 곡선이 평평해
    그 사실이 바로 보인다. **배분·신호에는 쓰지 않는다**(순수 측정) — 쓸지는 이 시트가 정한다.

    설계(인과성):
      · 특징 3개(전부 t일 종가까지 확정): 복합점수 백분위(score_pct) · 자기 위험 백분위(haz_pct_own)
        · M 국면 더미(하락=1, 중립=0.5, 그 외 0). 전부 이미 01_일별에 있는 값이다.
      · 매년 cutoff = 1/1 − 35일. 학습 표본 = t < cutoff 이면서 t+h ≤ cutoff 인 날(전방창이 cutoff를
        넘지 않게 잘라 낸다 — regime_info_gate와 같은 관행). 감쇠 가중(M.decay_weights, asof=cutoff).
      · 그 해의 예측은 학습된 계수로만 낸다. 학습 표본 < MIN_TRAIN이면 그 해는 NaN(예측 없음).
    산출: (13q DataFrame, 섹터별 P 시계열 dict, 요약 dict). 요약은 00시트·13f 정보 행용.
    ※ 연구·교육용 측정 도구이며 투자 자문이 아니다."""
    rows: List[dict] = []
    probs: Dict[str, pd.Series] = {}
    summ: Dict[str, Any] = {}
    if not results:
        return pd.DataFrame(), probs, summ
    min_train = int(getattr(scfg, "DOWN_PROB_MIN_TRAIN", 250))
    n_bins = int(getattr(scfg, "DOWN_PROB_BINS", 10))
    hl = getattr(scfg, "HALF_LIFE_DAYS", None)
    # M 국면 더미 — alloc이 있으면 그 시리즈를, 없으면 특징에서 뺀다(산업 계층).
    m_dummy = None
    if alloc is not None and alloc.get("spy_state_short") is not None:
        _ss = pd.Series(alloc["spy_state_short"]).astype(str)
        m_dummy = _ss.map({"하락": 1.0, "중립": 0.5}).fillna(0.0)
    feat_names = ["복합점수백분위", "자기위험백분위(H)"] + (["M국면더미"] if m_dummy is not None else [])
    all_pred: List[pd.Series] = []
    all_real: List[pd.Series] = []
    for t in results:
        r = results[t]
        px = r.get("px_close")
        sp = r.get("score_pct")
        hz = r.get("haz_pct_sector")
        if px is None or sp is None:
            continue
        px = pd.Series(px).astype(float)
        idx = px.index
        sp = pd.Series(sp).astype(float).reindex(idx)
        hz = (pd.Series(hz).astype(float).reindex(idx) if hz is not None else pd.Series(np.nan, index=idx))
        fwd = px.shift(-h) / px - 1.0
        y_all = (fwd < 0).astype(float).where(fwd.notna())
        X_cols = [sp, hz] + ([m_dummy.reindex(idx)] if m_dummy is not None else [])
        X_all = pd.concat(X_cols, axis=1)
        X_all.columns = feat_names
        p_out = pd.Series(np.nan, index=idx, dtype=float)
        yrs = sorted({int(d.year) for d in idx})
        n_fit = 0
        for yv in yrs:
            cutoff = pd.Timestamp(year=yv, month=1, day=1) - pd.Timedelta(days=35)
            rows_y = idx[idx.year == yv]
            if len(rows_y) == 0:
                continue
            # 학습: t < cutoff 이고 전방창이 cutoff를 넘지 않는 날
            cand = idx[(idx < cutoff)]
            cand = cand[:-h] if len(cand) > h else cand[:0]
            if len(cand) == 0:
                continue
            Xc = X_all.reindex(cand)
            yc = y_all.reindex(cand)
            ok = Xc.notna().all(axis=1) & yc.notna()
            Xc, yc = Xc[ok], yc[ok]
            if len(Xc) < min_train or float(yc.sum()) < 20 or float((1 - yc).sum()) < 20:
                continue
            wts = None
            if hl is not None and hasattr(M, "decay_weights"):
                try:
                    _w = M.decay_weights(Xc.index, asof=cutoff, half_life_days=hl)
                    wts = None if _w is None else _w.values
                except Exception:   # noqa
                    wts = None
            beta = _fit_logistic_w(Xc.values, yc.values, wts, l2=float(getattr(scfg, "DOWN_PROB_L2", 1.0)))
            if beta is None:
                continue
            Xp = X_all.reindex(rows_y)
            okp = Xp.notna().all(axis=1)
            if bool(okp.any()):
                p_out.loc[rows_y[okp.values]] = _predict_logistic(beta, Xp[okp].values)
                n_fit += 1
        probs[t] = p_out
        pv = p_out.dropna()
        yv_ = y_all.reindex(pv.index)
        m = pv.notna() & yv_.notna()
        pv, yv_ = pv[m], yv_[m]
        if len(pv) < 100:
            rows.append({"블록": f"A. 섹터별 보정(h={h}일)", "티커": t, "표본일수": int(len(pv)),
                         "판독": "표본 부족 — 학습창이 짧거나 특징 결측"})
            continue
        base = float(yv_.mean())
        brier = float(np.mean((pv.values - yv_.values) ** 2))
        brier_base = float(np.mean((base - yv_.values) ** 2))
        # 십분위 신뢰도
        try:
            q = pd.qcut(pv, n_bins, labels=False, duplicates="drop")
        except ValueError:
            q = pd.Series(0, index=pv.index)
        rel = pd.DataFrame({"p": pv, "y": yv_, "q": q}).groupby("q").agg(n=("y", "size"), 예측=("p", "mean"), 실현=("y", "mean"))
        slope = (float(rel["실현"].iloc[-1] - rel["실현"].iloc[0]) if len(rel) >= 2 else np.nan)
        # 운용점: 기저율 분위(예측 상위 base 비율을 '하락'으로) — 라벨 방식의 7%와 대비
        thr = float(np.quantile(pv.values, 1.0 - base)) if 0 < base < 1 else np.nan
        pred_op = pv >= thr if pd.notna(thr) else pd.Series(False, index=pv.index)
        mo = _binary_metrics(pred_op, yv_.astype(bool))
        rows.append({"블록": f"A. 섹터별 보정(h={h}일)", "티커": t, "표본일수": int(len(pv)),
                     "학습 연도수": int(n_fit), "기저 실현하락률": round(base, 4),
                     "평균 예측확률": round(float(pv.mean()), 4),
                     "Brier": round(brier, 5), "Brier(기저율만)": round(brier_base, 5),
                     "Brier 개선": round(brier_base - brier, 5),
                     "신뢰도 기울기(상위십분위−하위십분위 실현)": (round(slope, 4) if pd.notna(slope) else np.nan),
                     "운용점 문턱": (round(thr, 4) if pd.notna(thr) else np.nan),
                     "운용점 정밀도": (round(mo["prec_down"], 4) if pd.notna(mo["prec_down"]) else np.nan),
                     "운용점 재현율": (round(mo["rec_down"], 4) if pd.notna(mo["rec_down"]) else np.nan),
                     "운용점 균형정확도": (round(mo["balanced"], 4) if pd.notna(mo["balanced"]) else np.nan),
                     "운용점 MCC": (round(mo["mcc"], 4) if pd.notna(mo["mcc"]) else np.nan),
                     "판독": ("방향 정보 있음" if (pd.notna(slope) and slope >= 0.10) else
                             ("약함" if (pd.notna(slope) and slope > 0.0) else "정보 없음(곡선이 평평하거나 거꾸로)"))})
        all_pred.append(pv); all_real.append(yv_)
    # ---------- 블록 B: 전 섹터 pooled 신뢰도 곡선 ----------
    if all_pred:
        P = pd.concat(all_pred); Y = pd.concat(all_real)
        base = float(Y.mean())
        try:
            q = pd.qcut(P, n_bins, labels=False, duplicates="drop")
        except ValueError:
            q = pd.Series(0, index=P.index)
        rel = pd.DataFrame({"p": P.values, "y": Y.values, "q": q.values}).groupby("q").agg(
            n=("y", "size"), 예측=("p", "mean"), 실현=("y", "mean"))
        for qi, rr in rel.iterrows():
            rows.append({"블록": f"B. 전{asset_label} 신뢰도 곡선(h={h}일, 십분위)", "티커": f"{int(qi) + 1}분위",
                         "표본일수": int(rr["n"]), "평균 예측확률": round(float(rr["예측"]), 4),
                         "기저 실현하락률": round(float(rr["실현"]), 4),
                         "판독": ("예측확률과 실현하락률이 같이 올라가면 보정이 맞다(대각선). "
                                 "평평하면 방향 정보가 없고, 예측이 실현보다 계속 크면 과대추정")})
        brier = float(np.mean((P.values - Y.values) ** 2)); brier_base = float(np.mean((base - Y.values) ** 2))
        slope = (float(rel["실현"].iloc[-1] - rel["실현"].iloc[0]) if len(rel) >= 2 else np.nan)
        thr = float(np.quantile(P.values, 1.0 - base)) if 0 < base < 1 else np.nan
        mo = _binary_metrics(P >= thr, Y.astype(bool)) if pd.notna(thr) else {}
        summ = {"n": int(len(P)), "base": base, "brier": brier, "brier_base": brier_base,
                "brier_gain": brier_base - brier, "slope": slope,
                "op_prec": mo.get("prec_down", np.nan), "op_rec": mo.get("rec_down", np.nan),
                "op_bal": mo.get("balanced", np.nan), "op_mcc": mo.get("mcc", np.nan),
                "features": ",".join(feat_names)}
        rows.append({"블록": f"B. 전{asset_label} 신뢰도 곡선(h={h}일, 십분위)", "티커": "── 전체 ──",
                     "표본일수": int(len(P)), "기저 실현하락률": round(base, 4),
                     "Brier": round(brier, 5), "Brier(기저율만)": round(brier_base, 5),
                     "Brier 개선": round(brier_base - brier, 5),
                     "신뢰도 기울기(상위십분위−하위십분위 실현)": (round(slope, 4) if pd.notna(slope) else np.nan),
                     "운용점 문턱": (round(thr, 4) if pd.notna(thr) else np.nan),
                     "운용점 정밀도": (round(mo.get("prec_down", np.nan), 4) if pd.notna(mo.get("prec_down", np.nan)) else np.nan),
                     "운용점 재현율": (round(mo.get("rec_down", np.nan), 4) if pd.notna(mo.get("rec_down", np.nan)) else np.nan),
                     "운용점 균형정확도": (round(mo.get("balanced", np.nan), 4) if pd.notna(mo.get("balanced", np.nan)) else np.nan),
                     "운용점 MCC": (round(mo.get("mcc", np.nan), 4) if pd.notna(mo.get("mcc", np.nan)) else np.nan),
                     "판독": (f"특징 {len(feat_names)}개({', '.join(feat_names)}) · 연도별 워크포워드 로지스틱(감쇠 가중). "
                             "기울기 ≥ 0.10이면 방향 정보가 있다는 뜻 — 그때 비로소 '문턱을 기저율에 맞춰' "
                             "재현율 한계(라벨 방식 ~10%)를 풀 수 있다. **배분에는 쓰지 않는다**(측정 전용)")})
    # ---------- 블록 C: 연도별 ----------
    if all_pred:
        P = pd.concat(all_pred); Y = pd.concat(all_real)
        D = pd.DataFrame({"p": P.values, "y": Y.values}, index=P.index)
        for yv2, d in D.groupby(D.index.year):
            if len(d) < 100:
                continue
            b = float(d["y"].mean())
            th = float(np.quantile(d["p"].values, 1.0 - b)) if 0 < b < 1 else np.nan
            mo2 = _binary_metrics(d["p"] >= th, d["y"].astype(bool)) if pd.notna(th) else {}
            rows.append({"블록": f"C. 연도별(h={h}일, pooled)", "티커": str(int(yv2)), "표본일수": int(len(d)),
                         "기저 실현하락률": round(b, 4), "평균 예측확률": round(float(d["p"].mean()), 4),
                         "Brier": round(float(np.mean((d["p"].values - d["y"].values) ** 2)), 5),
                         "운용점 정밀도": (round(mo2.get("prec_down", np.nan), 4) if pd.notna(mo2.get("prec_down", np.nan)) else np.nan),
                         "운용점 재현율": (round(mo2.get("rec_down", np.nan), 4) if pd.notna(mo2.get("rec_down", np.nan)) else np.nan),
                         "운용점 MCC": (round(mo2.get("mcc", np.nan), 4) if pd.notna(mo2.get("mcc", np.nan)) else np.nan),
                         "판독": ""})
    df = pd.DataFrame(rows)
    if len(df):
        lead = ["블록", "티커", "표본일수"]
        df = df[[c for c in lead if c in df.columns] + [c for c in df.columns if c not in lead]]
    return df, probs, summ


def minority_summary_text(summ: Dict[str, Any], asset_label: str = "섹터") -> str:
    """[v0.43.0 R1] 00시트 1줄 — 13p 요약."""
    if not summ:
        return "미산출"
    parts = []
    def _f(v, fmt=".3f"):
        return "-" if (v is None or (isinstance(v, float) and np.isnan(v))) else format(v, fmt)
    if "regime_balanced_mean" in summ:
        parts.append(f"국면(h=21, {summ.get('regime_n_assets', 0)}{asset_label} 평균): 하락 정밀도 {_f(summ.get('regime_prec_mean'))} vs 기저 "
                     f"{_f(summ.get('regime_base_mean'))} · 하락 재현율 {_f(summ.get('regime_rec_mean'))} · 균형정확도 {_f(summ.get('regime_balanced_mean'))} "
                     f"· MCC {_f(summ.get('regime_mcc_mean'), '+.3f')}(양수 {summ.get('regime_n_mcc_pos', 0)}/{summ.get('regime_n_assets', 0)})")
    if summ.get("regime_zero_down_years"):
        parts.append(f"하락 예측 0일인 해: {', '.join(summ['regime_zero_down_years'])}")
    if "rot_leadcross_top3" in summ and pd.notna(summ.get("rot_leadcross_top3", np.nan)):
        # [v0.48.0 L4 ⚠ 결함수정 — REPORT51 §2.4 E5] 종전엔 리더(교차)+하락국면리더를 합산한 값을 이 줄에
        #   찍었다(v0.47.0 J1은 13p 블록 B·E만 갈랐고 이 요약 줄은 그대로 두었다) — REPORT47~49가 "2026 리더
        #   16일 → 실현 상위3 1.000"을 순환매 리더 성과로 인용한 귀속 오류가 이 줄에서 재발할 수 있었다.
        #   이제 두 유형을 분리하고, [v0.48.0 L1] h=21 옆에 h=63을 병기한다(§9 지평 명시 규약).
        _h63 = summ.get("rot_leadcross_top3_h63", np.nan)
        parts.append(f"순환매: 리더(교차) → 실현 상위3 {summ['rot_leadcross_top3']:.3f}(h=21,{summ.get('rot_leadcross_days', 0)}일)"
                     + (f"/h=63 {_h63:.3f}" if pd.notna(_h63) else "")
                     + f" · 하락국면리더 → 실현 상위3 {_f(summ.get('rot_downleader_top3'))}(h=21,{summ.get('rot_downleader_days', 0)}일) · "
                     f"모델 꼴찌 → 실현 하위3 {summ['rot_bot_bot3']:.3f} · 무작위 {summ['rot_random']:.2f}")
    elif "rot_lead_top3" in summ and pd.notna(summ.get("rot_lead_top3", np.nan)):
        # 하위호환 — lead_type이 없는 소비처(예: 산업 계층, 하락국면리더 개념이 없다)는 종전 합산 표기 그대로.
        parts.append(f"순환매: 리더 → 실현 상위3 {summ['rot_lead_top3']:.3f}({summ['rot_lead_days']}일; "
                     f"{summ.get('rot_last_year')}년 {summ.get('rot_lead_top3_last', np.nan):.3f}/{summ.get('rot_lead_days_last', 0)}일) · "
                     f"모델 꼴찌 → 실현 하위3 {summ['rot_bot_bot3']:.3f} · 무작위 {summ['rot_random']:.2f}")
    if pd.notna(summ.get("rot_rev_top3", np.nan)):   # [v0.44.0 F1 — v0.45.0 G6로 격자는 퇴역, 진단만]
        parts.append(f"역방향 회피 대상 → 실현 상위3 {summ['rot_rev_top3']:.3f}(낮을수록 좋음) · 초과 "
                     f"{summ.get('rot_rev_exc', np.nan) * 100:+.2f}%/21일({summ.get('rot_rev_days', 0)}일) [격자 퇴역·진단]")
    if pd.notna(summ.get("votes_hi_top3", np.nan)):   # [v0.45.0 G2]
        parts.append(f"득표×국면: 득표≥2 {summ['votes_hi_top3']:.3f}({summ.get('votes_hi_days', 0)}일) vs 득표≤1 "
                     f"{_f(summ.get('votes_lo_top3'))} · 득표≤1·M상승 {_f(summ.get('votes_lo_up_top3'))}"
                     f"(초과 {summ.get('votes_lo_up_exc', np.nan) * 100:+.2f}%/21일, {summ.get('votes_lo_up_days', 0)}일)")
    return " | ".join(parts) + " — 13p_소수클래스정확도"


def allocation_summary_text(alloc: Dict[str, Any], d: pd.Timestamp, top_n: int = 5) -> str:
    """그날 배분(E_t 곱한 실제 비중) 상위 top_n을 'XLK 25.0% · XLF 20.0% (합 63%, 현금 37%)' 형태로."""
    if not alloc or d not in alloc["target_w"].index:
        return ""
    w = alloc["target_w"].loc[d]
    w = w[w > 1e-9].sort_values(ascending=False)
    total = float(w.sum())
    if total <= 1e-9:
        return f"전량 현금 (E_t={float(alloc['E'].loc[d]):.2f})"
    parts = [f"{t} {v:.1%}" for t, v in w.head(top_n).items()]
    more = f" +{len(w) - top_n}개" if len(w) > top_n else ""
    return " · ".join(parts) + more + f" (합 {total:.0%}, 현금 {max(0.0, 1 - total):.0%})"


def _rule_contrib_value(rule_contrib: pd.DataFrame, label: str, col: str) -> Any:
    """[v0.3.0 §1.G-1] 09b_규칙별기여 표에서 (규칙 라벨, 열) 하나를 뽑는다 — 12_섹터요약 신규 3열이
    이 표를 유일한 소스로 삼도록(값 재계산 없이 그대로 인용)."""
    if rule_contrib is None or not len(rule_contrib) or "규칙" not in rule_contrib.columns:
        return np.nan
    if col not in rule_contrib.columns:     # [v0.41.0] 새 진단 열이 없는 구버전 조각도 안전하게
        return np.nan
    hit = rule_contrib.loc[rule_contrib["규칙"] == label, col]
    return hit.iloc[0] if len(hit) else np.nan


def build_sector_error_detail(failed: Dict[str, str]) -> pd.DataFrame:
    """[v0.8.1] 12_섹터요약의 '비고'는 오류 첫 줄만(160자) 담아 실제 원인 추적에 부족했다(리포트7 실측: 11섹터 전부가
    'RecursionError: maximum recursion depth exceeded'로만 보여 정확한 발생 함수·줄을 알 수 없었음). run_sectors()가
    이미 잡아 두는 전체 트레이스백(최대 3000자, 순차 재시도까지 실패했으면 원본 병렬 오류도 함께)을 그대로 시트에 남긴다 —
    다음에 실패가 나면 이 시트로 바로 원인을 확인할 수 있다."""
    cols = ["티커", "섹터명", "오류 요약", "전체 트레이스백"]
    rows = []
    for t, err in (failed or {}).items():
        text = str(err)
        rows.append({"티커": t, "섹터명": SECTOR_NAME_KR.get(t, ""), "오류 요약": text.splitlines()[0][:200],
                     "전체 트레이스백": text})
    return pd.DataFrame(rows, columns=cols)


def build_sector_summary(results: Dict[str, Dict[str, Any]], failed: Dict[str, str], universe: pd.DataFrame,
                         alloc: Optional[Dict[str, Any]] = None) -> pd.DataFrame:
    rows = []
    for t in SECTORS:
        base = {"티커": t, "섹터명": SECTOR_NAME_KR.get(t, "")}
        if t in failed:
            rows.append({**base, "상태": "실패", "비고": str(failed[t]).splitlines()[0][:160]})
            continue
        sr = results.get(t)
        if sr is None:
            urow = universe.loc[universe["티커"] == t] if len(universe) else pd.DataFrame()
            rows.append({**base, "상태": (urow["상태"].iloc[0] if len(urow) else "제외")})
            continue
        sh = sr["sheets"]
        perf = sh["perf"].set_index("전략") if len(sh["perf"]) else pd.DataFrame()
        p_s = perf.iloc[0] if len(perf) > 0 else {}
        p_b = perf.iloc[1] if len(perf) > 1 else {}
        p_m = perf.iloc[2] if len(perf) > 2 else {}
        dist = sr["state"].value_counts().to_dict()
        aud = sh["audit"]
        if len(aud) and "일치" in aud.columns:
            chk = aud[~aud["일치"].astype(str).str.startswith("N/A")]
            audit_ok = "전체 통과" if (len(chk) == 0 or chk["일치"].astype(str).str.startswith("OK").all()) else "불일치 발생"
        else:
            audit_ok = "미실행"
        rc = sh.get("rule_contrib")
        # [v0.4.0 §1.F] 집중 배분에서 이 섹터가 받은 평균 비중(상장 기간 기준)·그날 1위였던 날 비율·적격일 비율
        alloc_cols: Dict[str, Any] = {}
        if alloc and t in alloc.get("cols", []):
            lst = alloc["listed"][t]
            tw = alloc["target_w"][t].where(lst)
            alloc_cols = {"배분 평균비중": round(float(tw.mean()), 4) if lst.any() else np.nan,
                          "배분 1위 빈도": round(float((alloc["rank_pos"][t] == 1).where(lst).mean()), 4) if lst.any() else np.nan,
                          "배분 적격일 비율": round(float(alloc["eligible"][t].where(lst).mean()), 4) if lst.any() else np.nan}
            if "leader" in alloc:   # [v0.5.0] 실제로 '명확한 1위'로 보유된 날 비율 / '명확한 꼴찌'로 회피된 날 비율
                alloc_cols["리더 보유일 비율"] = round(float((alloc["leader"] == t).where(lst).mean()), 4) if lst.any() else np.nan
                alloc_cols["꼴찌 회피일 비율"] = round(float((alloc["laggard"] == t).where(lst).mean()), 4) if lst.any() else np.nan
        rows.append({**base, "상태": "정상", "실제데이터시작": sr["info"]["실제데이터시작"],
                     "신호시작일(복합점수)": sr["first_signal"] or "-",
                     "후보지표수": sr["n_candidates"], "엄격채택(전체표본)": sh["n_strict_pass"],
                     "최신재추정 채택수": sh["latest_adopted"], "기간중 채택된 지표수": len(sr["adopted"]),
                     "상승일수": dist.get("RISK_ON", 0), "중립일수": dist.get("NEUTRAL", 0), "하락일수": dist.get("RISK_OFF", 0),
                     "추세필터일수": dist.get("TREND_ONLY_IN", 0) + dist.get("TREND_ONLY_OUT", 0),
                     "신호없음일수": dist.get("NO_SIGNAL", 0),
                     "전략CAGR": p_s.get("CAGR"), "전략샤프": p_s.get("샤프"), "전략MDD": p_s.get("최대낙폭(MDD)"),
                     "B&H CAGR": p_b.get("CAGR"), "B&H샤프": p_b.get("샤프"), "B&H MDD": p_b.get("최대낙폭(MDD)"),
                     "200일선벤치CAGR": p_m.get("CAGR"),
                     "국면정의검증": ("PASS" if sh["regime_validity"] else ("FAIL" if sh["regime_validity"] is False else "판정불가")),
                     "룩어헤드감사": audit_ok, "캐시사용": sr["cache_hit"],
                     "실행시간(초)": sr["timing"].get("12_run_sector()합계"),
                     "AdjClose지연": sr["info"]["AdjClose지연"],
                     # [v0.3.0 §1.G-1] 09b_규칙별기여에서 그대로 인용(단일 소스, 재계산 없음).
                     "H진입일 익일평균수익(%)": _rule_contrib_value(rc, "위험회피진입①(H)", "발동일 익일B&H평균수익(%)"),
                     "상승 미탑승(%p)": _rule_contrib_value(
                         rc, "[전체] 상승일 미탑승(비중=0 & B&H>0, %p)", "비중=0인 날 B&H수익 합(%p)"),
                     "하락 회피(%p)": _rule_contrib_value(
                         rc, "[전체] 하락일 회피(비중=0 & B&H<0, %p — 음수=회피한 손실)", "비중=0인 날 B&H수익 합(%p)"),
                     # [v0.41.0 S-E 진단] SPY-H 전파가 이 섹터에서 헛도는지 — 09b의 진단 행을 그대로 인용.
                     "H진입 중 200일선 위 비율": _rule_contrib_value(rc, "[진단·S-E] H진입일 중 자기200일선 위", "비율"),
                     "H진입(200일선 위) 익일평균(%)": _rule_contrib_value(
                         rc, "[진단·S-E] H진입일 중 자기200일선 위", "발동일 익일B&H평균수익(%)"),
                     "H진입(200일선 아래) 익일평균(%)": _rule_contrib_value(
                         rc, "[진단·S-E] H진입일 중 자기200일선 아래", "발동일 익일B&H평균수익(%)"),
                     # [v0.41.0 S-C-3 진단] 하락 에피소드 요약(09d와 같은 소스) — '회피합<0'이 수용기준 (나)다.
                     "하락 에피소드 수": (sh.get("regime_episode_summary") or {}).get("n"),
                     "에피소드 회피수익 합(%)": (round(float((sh.get("regime_episode_summary") or {}).get("sum")), 2)
                                        if pd.notna((sh.get("regime_episode_summary") or {}).get("sum", np.nan))
                                        else np.nan),
                     "에피소드 회피<0 비율": (round(float((sh.get("regime_episode_summary") or {}).get("neg_share")), 3)
                                     if pd.notna((sh.get("regime_episode_summary") or {}).get("neg_share", np.nan))
                                     else np.nan),
                     **alloc_cols})
    return pd.DataFrame(rows)


# =============================================================================
# [11] 리포트 — M.write_excel과 같은 서식(제목만 섹터용). 시트 구성은 M과 동일 + 통합 시트.
# =============================================================================
def _concat(results: Dict[str, Dict[str, Any]], key: str) -> pd.DataFrame:
    parts = [sr["sheets"][key] for t, sr in results.items()
             if isinstance(sr["sheets"].get(key), pd.DataFrame) and len(sr["sheets"][key])]
    return pd.concat(parts, ignore_index=True, sort=False) if parts else pd.DataFrame()


# =============================================================================
# [S-6c] 19_상승하락구간 (v0.49.0 Z1 ★ 신설 · 사용자 지시 "섹터별, 산업별 상승하락구간 시트")
#      ⚠ **industry_rotation.py v0.20.0 Y3의 같은 이름 함수를 그대로 복사한 것**이다(내용 동일).
#        왜 import가 아니라 복사인가: industry_rotation이 sector_rotation을 import하므로 반대 방향으로
#        의존하면 순환이 된다. 그래서 두 함수는 처음부터 **이 파일의 다른 부분에 의존하지 않는 순수 함수**로
#        설계했다(쓰는 것은 pandas·numpy와 이 파일의 log/kv뿐). 한쪽을 고치면 다른 쪽도 같이 고칠 것.
#      ⚠ 기존 05b_하락상승구간과 **다른 시트**다. 05b는 M.drawdown_episodes로 만든 '섹터 단독 전략'의
#        구간이고(02_섹터별단독거래의 짝), 19는 **S★ 배분이 그 섹터를 실제로 얼마나 들고 있었나**를 본다.
#        사용자 질문("어디가 문제인지")에 답하는 것은 19다.
# =============================================================================
def zigzag_segments(curve: pd.Series, min_move: float = 0.07, min_days: int = 3
                    ) -> List[Tuple[str, int, int]]:
    """[v0.49.0 Z1 · I v0.20.0 Y3와 동일 코드] 누적 총수익 곡선을 **고점→저점(하락) / 저점→고점(상승)** 교대 구간으로 나눈다.

    전환 규칙: 현재 방향의 극값에서 min_move(비율) 이상 되돌리면 그 극값을 전환점으로 확정한다.
    반환은 (구간유형, 시작 위치, 종료 위치) 리스트 — 위치는 curve의 정수 인덱스다.
    마지막 미확정 구간은 '…(진행중)'으로 붙인다(M의 05b와 같은 관행).

    ⚠ 이것은 **진단용 사후 분할**이다. 전 구간을 보고 나누므로 신호로 쓸 수 없고, 쓰지도 않는다
      (룩어헤드 감사 대상이 아닌 이유 — 목표비중 계산에 전혀 들어가지 않는다).
    ⚠ min_days보다 짧은 구간은 잡음으로 버린다. 버릴 때 **앞 구간과 병합하지 않는다** — 병합하면
      '고점→저점' 정의가 깨져 등락률이 실제 스윙보다 작아진다. 그냥 표에서 제외한다."""
    s = pd.Series(curve).dropna().astype(float)
    if len(s) < 3 or not np.isfinite(s.values).all() or float(s.min()) <= 0:
        # 0 이하 값이 있으면 비율 전환을 쓸 수 없다(총수익 곡선은 양수여야 한다)
        return []
    v = s.values
    n = len(v)
    out: List[Tuple[str, int, int]] = []
    hi_i = lo_i = 0
    dir_ = 0            # 0 미정 · +1 상승 추적 · −1 하락 추적
    piv = 0
    ext = 0
    for i in range(1, n):
        if dir_ == 0:
            if v[i] > v[hi_i]:
                hi_i = i
            if v[i] < v[lo_i]:
                lo_i = i
            if v[i] <= v[hi_i] * (1.0 - min_move):
                dir_, piv, ext = -1, hi_i, i
            elif v[i] >= v[lo_i] * (1.0 + min_move):
                dir_, piv, ext = 1, lo_i, i
        elif dir_ == 1:
            if v[i] > v[ext]:
                ext = i
            elif v[i] <= v[ext] * (1.0 - min_move):
                out.append(("상승", piv, ext))
                piv, dir_, ext = ext, -1, i
        else:
            if v[i] < v[ext]:
                ext = i
            elif v[i] >= v[ext] * (1.0 + min_move):
                out.append(("하락", piv, ext))
                piv, dir_, ext = ext, 1, i
    if dir_ != 0 and ext > piv:
        out.append((("상승" if dir_ == 1 else "하락") + "(진행중)", piv, ext))
    return [(k, a, b) for k, a, b in out if (b - a) >= int(min_days)]


def build_portfolio_segments(port_curve: pd.Series, port_exposure: pd.Series,
                             bench_curve: pd.Series, cfg: Any,
                             bench_label: str = "B&H", layer: str = "계층",
                             port_label: str = "★ 전략", M=None) -> pd.DataFrame:
    """[19 블록 C, v0.50.0 C1 ★ 신규] **포트폴리오 단위** 상승·하락 구간.

    왜 블록 A만으로는 부족한가(사용자 질문에 정확히 답하기 위해):
      블록 A는 "그 **자산**의 상승을 탔나"를 묻는다. 그런데 로테이션 전략은 **하루에 하나만** 든다 —
      11섹터 각각에 그것을 물으면 10개는 **정의상** 미참여가 되고(예산 전부를 한 자산에 주는 벤치는
      도달 가능하지만 **동시에 모든 자산에 대해서는 불가능**하다) 참여율 중위가 0.000으로 찍힌다.
      그것은 고장이 아니라 **단위가 틀린 질문**이다.
    블록 C는 올바른 단위로 묻는다 — "**B&H 대비** 이 계층이 하락을 피했고 상승을 탔나".
      구간은 **B&H 곡선**(시장/계층 벤치)의 지그재그로 나눈다. 그 구간에서:
        · 전략 구간수익 vs B&H 구간수익 → **벤치대비(%p)**
        · 총노출의 시작/최소/평균/최대/종료, 첫 대응일, 대응 지연
        · 판정: 하락구간은 '덜 빠졌나', 상승구간은 'B&H만큼 먹었나'
      ★ 하락구간의 이상은 **전략수익 ≥ 0**(피했다), 상승구간의 이상은 **전략수익 ≥ B&H**(다 먹었다).
    ⚠ 진단 전용 — 구간 분할은 사후(전 구간)이고 목표비중 계산에 전혀 들어가지 않는다."""
    rows: List[dict] = []
    mm = float(getattr(cfg, "SEG_MIN_MOVE", 0.07))
    md = int(getattr(cfg, "SEG_MIN_DAYS", 3))
    eps = float(getattr(cfg, "SEG_RESPONSE_EPS", 0.02))
    blk = "C. 포트폴리오 구간(B&H 대비)"
    pc = pd.Series(port_curve).astype(float).dropna()
    bc = pd.Series(bench_curve).astype(float).dropna()
    ex = pd.Series(port_exposure).astype(float)
    idx = pc.index.intersection(bc.index)
    if len(idx) < 60:
        rows.append({"블록": blk, "구분": "산출 불가",
                     "설명": f"전략·벤치 공통 관측이 {len(idx)}일뿐이다 — 다음 단계: 두 곡선의 색인 정렬 확인"})
        return pd.DataFrame(rows)
    pc, bc, ex = pc.reindex(idx), bc.reindex(idx), ex.reindex(idx).fillna(0.0)
    segs = zigzag_segments(bc, mm, md)
    rows.append({"블록": blk, "구분": "── 읽는 법 ──",
                 "설명": (f"구간은 **{bench_label} 곡선**을 지그재그(최소 변동 {mm:.0%} · 최소 {md}거래일)로 "
                        f"나눈 것이다 — 즉 '{bench_label}가 오른/내린 기간'이다. 그 기간에 "
                        f"**{port_label}이 얼마나 먹었고 노출이 어떻게 움직였나**를 붙였다. "
                        "★ 하락구간은 **전략수익 ≥ 0**이면 피한 것이고(벤치대비는 항상 양수여야 정상), "
                        "상승구간은 **전략수익 ≥ 벤치수익**이면 다 먹은 것이다. "
                        "블록 A(자산별)의 '참여율'은 로테이션 계층에서 구조적으로 낮게 나온다 — "
                        "하루에 한 자산만 들기 때문이다. **B&H와의 비교는 이 블록 C로 한다.**")})
    dn_gap = []; up_gap = []; dn_hit = []; up_hit = []
    for kind, a, b in segs:
        i0, i1 = idx[a], idx[b]
        bmv = float(bc.iloc[b] / bc.iloc[a] - 1.0)
        pmv = float(pc.iloc[b] / pc.iloc[a] - 1.0)
        gap = pmv - bmv
        sl = slice(a + 1, b + 1)
        es = ex.iloc[sl]
        e0 = float(ex.iloc[a]); emin = float(es.min()) if len(es) else e0
        emax = float(es.max()) if len(es) else e0
        eavg = float(es.mean()) if len(es) else e0
        eend = float(ex.iloc[b])
        is_dn = kind.startswith("하락")
        lag = None
        if len(es):
            dv = es - e0
            hit = dv[dv <= -eps] if is_dn else dv[dv >= eps]
            if len(hit):
                lag = int(idx.get_loc(hit.index[0]) - a)
        if is_dn:
            dn_gap.append(gap); dn_hit.append(1 if pmv >= 0 else 0)
            if pmv >= 0:
                verdict = f"★ 하락 회피 성공(전략 {pmv * 100:+.1f}% · 노출 {e0:.2f}→{emin:.2f})"
            elif pmv > bmv * 0.5:
                verdict = f"부분 방어(하락의 {abs(pmv / bmv) if abs(bmv) > 1e-9 else 0:.0%}만 맞음"
                verdict += (f", 감축 지연 {lag}거래일)" if lag is not None else ", 감축 없음)")
            else:
                verdict = (f"⚠ 방어 실패(하락의 {abs(pmv / bmv) if abs(bmv) > 1e-9 else 0:.0%}를 맞음"
                           + (f", 감축 지연 {lag}거래일)" if lag is not None else ", 감축 없음 — 노출 "
                              f"{eavg:.2f} 유지)"))
        else:
            up_gap.append(gap); up_hit.append(1 if pmv >= bmv - 1e-12 else 0)
            _part = (pmv / bmv) if abs(bmv) > 1e-9 else np.nan
            if pmv >= bmv - 1e-12:
                verdict = f"★ 상승 완전 참여(전략 {pmv * 100:+.1f}% ≥ 벤치 {bmv * 100:+.1f}%)"
            elif pd.notna(_part) and _part >= 0.7:
                verdict = (f"부분 참여(벤치의 {_part:.0%}"
                           + (f", 매수 지연 {lag}거래일)" if lag is not None else ", 노출 변화 없음)"))
            else:
                verdict = (f"⚠ 참여 실패(벤치의 {_part:.0%}만"
                           + (f", 매수 지연 {lag}거래일" if lag is not None else ", 매수 없음")
                           + f" · 노출 {e0:.2f}→최대 {emax:.2f})")
        rows.append({"블록": blk, "구분": kind, "시작일(고점/저점)": i0, "종료일": i1,
                     f"{bench_label} 등락률(%)": round(bmv * 100, 2),
                     f"{port_label} 수익(%)": round(pmv * 100, 2),
                     "벤치대비(%p)": round(gap * 100, 2), "거래일수": int(b - a),
                     "시작시 총노출": round(e0, 4), "구간최소 총노출": round(emin, 4),
                     "구간평균 총노출": round(eavg, 4), "구간최대 총노출": round(emax, 4),
                     "종료시 총노출": round(eend, 4),
                     "대응 지연(거래일)": (lag if lag is not None else "-"),
                     "판정": verdict})
    # ---- 요약 2행: 하락 / 상승 ----
    if dn_gap:
        rows.append({"블록": blk, "구분": "★ 하락구간 요약", "거래일수": len(dn_gap),
                     "벤치대비(%p)": round(float(np.nansum(dn_gap)) * 100, 2),
                     "판정": (f"하락 {len(dn_gap)}구간 · **회피 성공(전략수익 ≥ 0) "
                            f"{int(np.nansum(dn_hit))}/{len(dn_hit)}** · 벤치대비 합 "
                            f"{float(np.nansum(dn_gap)) * 100:+.1f}%p · 평균 "
                            f"{float(np.nanmean(dn_gap)) * 100:+.2f}%p. "
                            "벤치대비가 양수여야 '덜 빠졌다'는 뜻이다.")})
    if up_gap:
        rows.append({"블록": blk, "구분": "★ 상승구간 요약", "거래일수": len(up_gap),
                     "벤치대비(%p)": round(float(np.nansum(up_gap)) * 100, 2),
                     "판정": (f"상승 {len(up_gap)}구간 · **완전 참여(전략 ≥ 벤치) "
                            f"{int(np.nansum(up_hit))}/{len(up_hit)}** · 벤치대비 합 "
                            f"{float(np.nansum(up_gap)) * 100:+.1f}%p · 평균 "
                            f"{float(np.nanmean(up_gap)) * 100:+.2f}%p.")})
    if dn_gap and up_gap:
        _d = float(np.nansum(dn_gap)) * 100; _u = float(np.nansum(up_gap)) * 100
        rows.append({"블록": blk, "구분": "★★ 종합", "벤치대비(%p)": round(_d + _u, 2),
                     "판정": (f"{bench_label} 대비 총 {_d + _u:+.1f}%p = 하락에서 {_d:+.1f} + "
                            f"상승에서 {_u:+.1f}. "
                            + ("**하락 방어로 벌고 상승 참여로 잃는** 전형적 방어형이다 — "
                               "상승 참여를 올리는 것이 다음 개선 지점이다."
                               if _d > 0 and _u < 0 else
                               "**상승 참여로 벌고 하락에서 잃는** 공격형이다 — 방어가 다음 개선 지점이다."
                               if _u > 0 and _d < 0 else
                               "양쪽 다 플러스다(드문 경우 — 정의·데이터를 먼저 검산할 것)."
                               if _d > 0 and _u > 0 else
                               "⚠ 양쪽 다 마이너스다 — B&H보다 하락도 더 맞고 상승도 덜 먹었다는 뜻이므로 "
                               "노출 규칙을 근본적으로 다시 봐야 한다."))})
    log("ROT", kv(event="portfolio_segments_built", layer=str(layer), segments=len(segs),
                  down=len(dn_gap), up=len(up_gap),
                  down_avoided=(int(np.nansum(dn_hit)) if dn_hit else 0),
                  up_full=(int(np.nansum(up_hit)) if up_hit else 0),
                  bench=str(bench_label), min_move=mm,
                  note="B&H 대비 하락 회피·상승 참여 — 블록 A(자산별)와 단위가 다르다"), M=M)
    return pd.DataFrame(rows)



def build_prediction_quality(results: Dict[str, Dict[str, Any]], Et: Optional[pd.Series],
                             cfg: Any, name_map: Optional[Dict[str, str]] = None, M=None) -> pd.DataFrame:
    """[23_예측품질검정, v0.57.0 K3 ★★ 신규] 사용자 질문 두 개에 **매 실행 자동으로** 답하는 시트.

      질문 1: "모든 단일섹터 수익이 국면 판단이랑 비슷해보이는데 **예측이 잘 된건지 확인**"
      질문 2: "**하락 예측도 잘됐는지** 확인"

    ★★ 이 시트의 모든 숫자는 **체결정합**이다 — t일에 정해진 신호를 t+1일 수익과 맞춘다
      (엔진 규칙 exec_w(t)=target_w(t−1)). 같은 날 수익과 맞추면 거래 불가능한 수치가 나오고,
      그것이 이 프로젝트에서 네 번 반복된 오류다(누적 교훈 20).

    블록 A — **하락 예측 검정**: 섹터 자기 하락국면(t) → 다음날·향후5일 수익 vs 그 외.
             음수면 예측이 맞은 것. **반대 부호면 그 섹터는 신호가 반전된 것**이다.
    블록 B — **국면 위의 추가정보 검정**: E_t > 0인 날만 골라 섹터 자기 복합점수 5분위별 다음날 수익.
             단조 증가면 섹터 점수에 시장 국면을 넘는 정보가 있다는 뜻이다.
    블록 C — **초과보유 검정**: w > E_t인 날(②가 ③보다 더 드는 날)의 다음날 수익.
             ★ 이 부호가 ②>③ 성적과 1:1로 일치한다 — 이 계층 고유 알파의 **유일한** 출처다.
    블록 D — **종합 판정**: 왜 ②가 ③과 비슷해 보이는지를 한 문장으로.
    """
    blkA, blkB, blkC, blkD = ("A. 하락 예측 검정", "B. 국면 위의 추가정보 검정",
                              "C. 초과보유 검정(②가 ③을 이기는 유일한 출처)", "D. 종합 판정")
    rows: List[dict] = []
    cols = [t for t in results if isinstance(results[t], dict)]
    if not cols:
        return pd.DataFrame([{"블록": blkA, "섹터": "산출 불가", "판정": "results 비어 있음"}])
    E = (pd.to_numeric(pd.Series(Et), errors="coerce") if Et is not None else None)

    def _parts(t):
        r = pd.to_numeric(results[t].get("bh_ret"), errors="coerce")
        if r is None or not len(r):
            return None
        if float(pd.Series(r).abs().max() or 0.0) < 1.0:
            r = r * 100.0
        st = pd.Series(results[t].get("state")).astype(str).reindex(r.index)
        w = pd.to_numeric(results[t].get("target_pos"), errors="coerce").reindex(r.index)
        e = (E.reindex(r.index).ffill().fillna(0.0) if E is not None else None)
        return r, st, w, e

    # ---------- 블록 A ----------
    rows.append({"블록": blkA, "섹터": "── 읽는 법 ──",
                 "판정": ("섹터가 **하락**이라고 말한 날(t)의 **다음날** 수익을 그 외 날과 비교한다"
                        "(t+1 체결 규칙에 맞춘 것 — 같은 날 수익과 비교하면 거래 불가능한 숫자가 된다). "
                        "**'차'가 음수면 하락 예측이 맞은 것**이고, 양수면 그 섹터는 **신호가 반전**돼 있다.")})
    nA = nA_ok = 0
    for t in cols:
        p = _parts(t)
        if p is None:
            continue
        r, st, w, e = p
        rn = r.shift(-1)
        f5 = r.rolling(5).sum().shift(-5)
        off = st.str.upper().eq("RISK_OFF") & rn.notna()
        non = (~st.str.upper().eq("RISK_OFF")) & rn.notna()
        if not int(off.sum()):
            continue
        mo, mn = float(rn[off].mean()), float(rn[non].mean())
        nA += 1
        nA_ok += int(mo < mn)
        rows.append({"블록": blkA, "섹터": t, "이름": (name_map or {}).get(t, ""),
                     "일수": int(off.sum()), "비율(%)": round(float(off.sum()) / max(len(rn.dropna()), 1) * 100, 1),
                     "다음날 평균(%)": round(mo, 4), "그 외 다음날 평균(%)": round(mn, 4),
                     "차(%p)": round(mo - mn, 4),
                     "향후5일 평균(%)": (round(float(f5[off].mean()), 4) if f5[off].notna().any() else None),
                     "판정": ("★ 하락 예측이 맞다(뺀 날이 실제로 더 나빴다)" if mo < mn else
                            "⚠⚠ **신호 반전** — 하락이라고 한 날이 오히려 더 좋았다. 이 섹터의 하락 신호는 쓰지 말 것")})
    rows.append({"블록": blkA, "섹터": "★★ 종합", "일수": nA,
                 "판정": (f"하락 예측이 맞은 섹터 **{nA_ok}/{nA}**. "
                        + ("★ 하락 예측은 전반적으로 작동한다." if nA_ok * 2 > nA else
                           "⚠ 절반 이하 — 하락 신호 자체를 재검토할 것.")
                        + " ⚠ 단, 섹터 하락국면의 대부분은 시장(E_t=0)과 겹친다 — 블록 C가 '겹치지 않는 부분'의 값을 잰다.")})

    # ---------- 블록 B ----------
    rows.append({"블록": blkB, "섹터": "── 읽는 법 ──",
                 "판정": ("**E_t > 0인 날만** 골라(= 시장 국면을 고정하고) 섹터 자기 복합점수 5분위별 "
                        "**다음날** 수익을 본다. Q5(점수 최상위)가 Q1(최하위)보다 높아야 '섹터 점수에 "
                        "시장 국면을 넘는 정보가 있다'고 말할 수 있다. ★ 이것이 사용자 질문 "
                        "'단일섹터 수익이 국면이랑 비슷한데 예측이 잘 된 건가'에 대한 직접 검정이다.")})
    nB = nB_ok = 0
    pooled = {k: [] for k in range(5)}
    for t in cols:
        p = _parts(t)
        if p is None or p[3] is None:
            continue
        r, st, w, e = p
        sp = pd.to_numeric(results[t].get("score_pct"), errors="coerce")
        if sp is None or not len(sp):
            continue
        sp = sp.reindex(r.index)
        rn = r.shift(-1)
        m = (e > 0) & rn.notna() & sp.notna()
        if int(m.sum()) < 250:
            continue
        try:
            q = pd.qcut(sp[m], 5, labels=False, duplicates="drop")
        except Exception:
            continue
        row = {"블록": blkB, "섹터": t, "이름": (name_map or {}).get(t, ""), "일수": int(m.sum())}
        vals = []
        for k in range(int(q.max()) + 1):
            idx = sp[m][q == k].index
            v = float(rn.loc[idx].mean())
            row[f"Q{k + 1} 다음날(%)"] = round(v, 4)
            vals.append(v)
            pooled.setdefault(k, []).append(rn.loc[idx])
        if len(vals) >= 2:
            nB += 1
            nB_ok += int(vals[-1] > vals[0])
            row["Q5−Q1(%p)"] = round(vals[-1] - vals[0], 4)
            row["판정"] = ("★ 상위가 하위보다 낫다" if vals[-1] > vals[0] else
                         "✗ 상위가 하위보다 못하다 — 이 섹터 점수는 국면 위에 정보를 더하지 못한다")
        rows.append(row)
    if nB:
        prow = {"블록": blkB, "섹터": "★★ 종합(풀링)"}
        pv = []
        for k in sorted(pooled):
            if not pooled[k]:
                continue
            s = pd.concat(pooled[k])
            prow[f"Q{k + 1} 다음날(%)"] = round(float(s.mean()), 4)
            prow["일수"] = int(len(s))
            pv.append(float(s.mean()))
        mono = len(pv) >= 2 and all(pv[i] <= pv[i + 1] for i in range(len(pv) - 1))
        prow["판정"] = (f"Q5 > Q1 인 섹터 **{nB_ok}/{nB}**" +
                      (" · 풀링이 단조 증가 ⇒ ★ 섹터 점수에 국면을 넘는 정보가 있다." if mono else
                       " · 풀링이 **단조가 아니다** ⇒ ⚠⚠ 섹터 자기 점수는 시장 국면을 고정하면 "
                       "**다음날 방향 정보를 거의 주지 못한다**. ②가 ③과 비슷해 보이는 근본 이유가 이것이고, "
                       "비중 규칙을 바꿔 키울 수 있는 것이 아니다 — 신호 자체를 바꿔야 한다."))
        rows.append(prow)

    # ---------- 블록 C ----------
    rows.append({"블록": blkC, "섹터": "── 읽는 법 ──",
                 "판정": ("②(단일 섹터 예측)가 ③(국면 예측)보다 **더 드는 날**(w > E_t)의 다음날 수익이다. "
                        "③은 그 날 E_t만 들고 ②는 w를 드니, **초과분 (w−E_t)가 먹는 수익이 바로 이 값**이다. "
                        "★ 이 값의 **부호가 ②>③ 성적과 1:1로 일치한다** — 양수면 ②가 이기고 음수면 진다. "
                        "즉 이 계층의 고유 알파는 전부 여기서 나온다. 키우려면 이 값을 키워야 한다.")})
    nC = nC_ok = 0
    for t in cols:
        p = _parts(t)
        if p is None or p[3] is None or p[2] is None:
            continue
        r, st, w, e = p
        rn = r.shift(-1)
        over = (w > e + 1e-9) & rn.notna()
        base = (w <= e + 1e-9) & (e > 0) & rn.notna()
        if not int(over.sum()):
            continue
        mo = float(rn[over].mean())
        nC += 1
        nC_ok += int(mo > 0)
        rows.append({"블록": blkC, "섹터": t, "이름": (name_map or {}).get(t, ""),
                     "일수": int(over.sum()),
                     "비율(%)": round(float(over.sum()) / max(len(rn.dropna()), 1) * 100, 1),
                     "다음날 평균(%)": round(mo, 4),
                     "평균 초과분": round(float((w - e)[over].mean()), 4),
                     "그 외 다음날 평균(%)": (round(float(rn[base].mean()), 4) if int(base.sum()) else None),
                     "판정": ("★ 초과보유가 번다 — ② > ③ 이 되는 섹터" if mo > 0 else
                            "⚠ 초과보유가 잃는다 — ② < ③ 이 되는 섹터. 워크포워드 게이트(24 시트) 대상")})
    rows.append({"블록": blkC, "섹터": "★★ 종합", "일수": nC,
                 "판정": (f"초과보유 다음날 수익이 **양수인 섹터 {nC_ok}/{nC}** — 이 수가 곧 ②가 ③을 "
                        "이기는 섹터 수다. ★ 개선하려면 (a) 초과보유일을 **더 잘 고르거나** "
                        "(b) 지는 섹터의 초과보유를 **끄는**(24_초과보유판정) 두 길뿐이다. "
                        "(a)는 블록 B가 '점수에 추가정보가 없다'고 말하면 막혀 있는 길이다.")})

    # ---------- 블록 D ----------
    rows.append({"블록": blkD, "섹터": "★★★ 왜 ②가 ③과 비슷한가",
                 "판정": ("v0.56.0 규칙은 `w = 0 if E_t<=0 else max(w_sector, E_t)`다. "
                        "w_sector < E_t인 날에는 **정의상 ③과 완전히 같아진다** — 그런 날이 전체의 "
                        "약 70~85%다. 따라서 ②와 ③이 비슷한 것은 **버그가 아니라 규칙의 귀결**이고, "
                        "차이는 블록 C의 초과보유일(15~31%)에서만 생긴다. "
                        "★ 그 차이를 '훨씬' 키우려면 블록 B가 양성이어야 하는데, 측정 결과가 음성이면 "
                        "**비중 규칙으로는 불가능하고 신호를 새로 찾아야 한다**. "
                        "이 시트가 매 실행 그 판정을 낸다.")})
    log("PRED_Q", kv(event="prediction_quality_built", sectors=len(cols),
                     down_ok=f"{nA_ok}/{nA}", score_ok=f"{nB_ok}/{nB}", over_ok=f"{nC_ok}/{nC}",
                     note="전부 체결정합(t 신호 → t+1 수익)"), M=M)
    return pd.DataFrame(rows)

def build_curve_compare(ret_df: pd.DataFrame, solo_w: pd.DataFrame, regime_w: pd.DataFrame,
                        cfg: Any, name_map: Optional[Dict[str, str]] = None,
                        alloc_ret: Optional[pd.Series] = None,
                        focus: Optional[Tuple[str, ...]] = None, M=None) -> pd.DataFrame:
    """[00B_수익곡선비교, v0.55.0 H2 ★ 신규 · 맨 앞 시트] 사용자 지시로 만든 곡선 비교 표.

    지시: "buy and hold와 단일 섹터 예측, 국면 예측 수익 곡선 비교해서 맨 앞에 시트 새로 생성해"

    세 곡선을 **섹터마다** 나란히 놓는다(전부 복리 자산곡선 · 시작 1.0):
      ① **B&H**        — 그 섹터를 그냥 보유
      ② **단일 섹터 예측** — 그 섹터 **자기 신호**(자기 국면)로 낸 비중으로 거래
         [v0.61.2 R75 정정] 실제 입력은 01_일별 '목표비중' = 라이브 최종 비중(자기 신호 + E_t 바닥·퇴출 + 초과보유 게이트)
      ③ **국면 예측**    — **시장(SPY) 국면**이 준 노출(E_t)을 그 섹터에 그대로 적용
    ⇒ ②−①는 '그 섹터 예측의 값', ③−①는 '시장 국면 판단만의 값', ②−③는 '섹터 고유 정보의 값'이다.
       세 번째가 이 계층의 존재 이유다 — 섹터별로 따로 보는 것이 시장 하나만 보는 것보다 나은가.

    [v0.56.0 J3] 반환이 **(표, 일별곡선 DataFrame) 2튜플**로 바뀌었다. 두 번째가 00C_곡선데이터가 되고,
      write_sector_excel가 그것을 참조하는 **실제 꺾은선 차트**를 00B_곡선그래프 시트에 그린다
      (사용자 지시: "아니 수익 곡선 비교를 **그래프로** 나타내라고" — v0.55.0은 표만 냈다).

    블록 A: 섹터별 요약(최종배수 · 복리 · CAGR · MDD · 칼마 · 평균비중 · 3자 승패)
    블록 B: **곡선 표본**(연말 값) — 엑셀에서 바로 꺾은선 차트로 그릴 수 있게 날짜×계열로 낸다.
    블록 C: 지정 섹터(focus) 상세 — 사용자가 이번 라운드에 지목한 섹터만 연도별로 쪼갠다."""
    cols = [c for c in ret_df.columns if c in solo_w.columns]
    if not cols:
        # [v0.56.0 J3] 반환이 (표, 일별곡선) 2튜플로 바뀌었다 — 실패 경로도 같은 모양을 지켜야
        #   호출부의 언팩이 깨지지 않는다.
        return (pd.DataFrame([{"블록": "A. 섹터별 3곡선 비교", "섹터": "산출 불가",
                               "판정": "ret_df와 solo_w에 공통 섹터가 없다"}]), pd.DataFrame())
    idx = ret_df.index
    R = ret_df[cols].astype(float).fillna(0.0)
    # [v0.61.2 R75] ① 첫날 정렬 — ②③은 첫날 비중이 0(shift(1))이라 그날 수익을 못 받는데 ①만 받았다(하루 긴 곡선).
    if len(R):
        R.iloc[0] = 0.0
    WS = solo_w.reindex(index=idx, columns=cols).astype(float).fillna(0.0)
    WR = (regime_w.reindex(index=idx, columns=cols).astype(float).fillna(0.0)
          if regime_w is not None else None)
    rows: List[dict] = []

    def _m(s: pd.Series) -> dict:
        c = (1.0 + pd.Series(s).fillna(0.0)).cumprod()
        mdd = float((c / c.cummax() - 1.0).min())
        y = max(len(s) / 252.0, 1e-9)
        g = float(c.iloc[-1]) ** (1.0 / y) - 1.0
        return {"배수": float(c.iloc[-1]), "복리": (float(c.iloc[-1]) - 1.0) * 100.0,
                "CAGR": g, "MDD": mdd * 100.0,
                "칼마": (g / abs(mdd) if mdd < -1e-9 else float("nan")), "curve": c}

    rows.append({"블록": "A. 섹터별 3곡선 비교", "섹터": "── 읽는 법 ──",
                 "판정": ("① **B&H** = 그냥 보유 · ② **단일 섹터 예측** = 그 섹터의 **라이브 최종 비중**(자기 국면 신호 + 시장 예산 "
                        "E_t 바닥·퇴출 `0 if E_t≤0 else max(w, E_t)` + 초과보유 게이트 — 01_일별 '목표비중') · "
                        "③ **국면 예측** = **시장(SPY) 국면**이 준 노출을 그 섹터에 그대로 적용. "
                        "**②−①는 그 섹터 예측의 값**, **③−①는 시장 국면 판단만의 값**, "
                        "**②−③는 섹터를 따로 본 것의 값**이다 — 세 번째가 이 계층의 존재 이유다. "
                        "세 열을 다 이기는 것이 목표이며, 판정은 **복리와 칼마를 함께** 본다"
                        "(단순합은 비중 ≤ 1이면 구조적으로 B&H를 넘기 어렵다 — 00A 블록 B 참조). "
                        "블록 B에 **연말 곡선 값**이 있어 엑셀에서 바로 꺾은선으로 그릴 수 있다.")})
    curves: Dict[str, pd.Series] = {}
    n_w2 = n_w3 = n_w23 = 0
    for t in cols:
        a = _m(R[t]); b = _m(WS[t].shift(1).fillna(0.0) * R[t])
        c3 = _m(WR[t].shift(1).fillna(0.0) * R[t]) if WR is not None else None
        curves[f"{t} ① B&H"] = a["curve"]; curves[f"{t} ② 단일예측"] = b["curve"]
        if c3 is not None:
            curves[f"{t} ③ 국면예측"] = c3["curve"]
        _w2 = b["복리"] > a["복리"]; n_w2 += int(_w2)
        _w3 = (c3 is not None and c3["복리"] > a["복리"]); n_w3 += int(_w3)
        _w23 = (c3 is not None and b["복리"] > c3["복리"]); n_w23 += int(_w23)
        row = {"블록": "A. 섹터별 3곡선 비교", "섹터": t, "이름": (name_map or {}).get(t, ""),
               "관측일": int(len(R)),
               "① B&H 복리(%)": round(a["복리"], 1), "① B&H MDD(%)": round(a["MDD"], 2),
               "① B&H 칼마": (round(a["칼마"], 2) if pd.notna(a["칼마"]) else None),
               "② 단일예측 복리(%)": round(b["복리"], 1), "② 단일예측 MDD(%)": round(b["MDD"], 2),
               "② 단일예측 칼마": (round(b["칼마"], 2) if pd.notna(b["칼마"]) else None),
               "② 평균비중": round(float(WS[t].mean()), 4),
               "②−① 복리(%p)": round(b["복리"] - a["복리"], 1)}
        if c3 is not None:
            row.update({"③ 국면예측 복리(%)": round(c3["복리"], 1),
                        "③ 국면예측 MDD(%)": round(c3["MDD"], 2),
                        "③ 국면예측 칼마": (round(c3["칼마"], 2) if pd.notna(c3["칼마"]) else None),
                        "③ 평균비중": round(float(WR[t].mean()), 4),
                        "③−① 복리(%p)": round(c3["복리"] - a["복리"], 1),
                        "②−③ 복리(%p)": round(b["복리"] - c3["복리"], 1)})
        row["판정"] = (("★ " if _w2 else "✗ ") + f"②vs① {b['복리'] - a['복리']:+.1f}%p"
                     + ((" · " + ("★ " if _w3 else "✗ ") + f"③vs① {c3['복리'] - a['복리']:+.1f}%p"
                         + " · " + ("★ " if _w23 else "✗ ")
                         + f"②vs③ {b['복리'] - c3['복리']:+.1f}%p(섹터 고유 정보의 값)")
                        if c3 is not None else "")
                     + (" · MDD ②가 ① 대비 " + f"{b['MDD'] - a['MDD']:+.1f}%p"))
        rows.append(row)
    rows.append({"블록": "A. 섹터별 3곡선 비교", "섹터": "★★ 승패 요약",
                 "판정": (f"**② 단일예측 > ① B&H : {n_w2}/{len(cols)}** · "
                        f"③ 국면예측 > ① : {n_w3}/{len(cols)} · "
                        f"**② > ③ : {n_w23}/{len(cols)}(섹터를 따로 본 것이 시장 하나보다 나은 섹터 수)**. "
                        + ("★ ②가 과반에서 ③을 이긴다 — 섹터별 예측에 고유 정보가 있다."
                           if n_w23 * 2 > len(cols) else
                           "⚠ ②가 ③을 과반에서 못 이긴다 — 섹터를 따로 보는 값이 약하다는 뜻이므로 "
                           "이 계층의 존재 이유를 재검토할 것."))})
    # ---- 블록 B: 연말 곡선 표본(표로 읽는 용도 — 그래프는 00B_곡선그래프 시트) ----
    #   [v0.56.0 J3] 사용자 지시 "수익 곡선 비교를 **그래프로** 나타내라" ⇒ 실제 꺾은선 차트는
    #   00B_곡선그래프 시트에 xlsxwriter로 그리고, 그 데이터 원본은 00C_곡선데이터(일별 전체)다.
    #   이 블록 B는 숫자를 직접 읽고 싶을 때를 위한 연말 표본으로 남긴다.
    if curves:
        C = pd.DataFrame(curves)
        _ye = C.groupby(pd.DatetimeIndex(C.index).year).tail(1)
        for d, r0 in _ye.iterrows():
            _row = {"블록": "B. 곡선(연말 값 · 표로 읽기용 · 그래프는 00B_곡선그래프)",
                    "섹터": str(pd.Timestamp(d).date())}
            _row.update({k: round(float(v), 4) for k, v in r0.items()})
            rows.append(_row)
    # ---- 블록 C: 지정 섹터 연도별 ----
    _fc = [t for t in (focus or ()) if t in cols]
    if _fc:
        rows.append({"블록": "C. 지정 섹터 연도별", "섹터": "── 읽는 법 ──",
                     "판정": (f"이번 라운드에 지목된 {len(_fc)}섹터({', '.join(_fc)})를 연도별로 쪼갰다. "
                            "어느 해에 ②가 ①에 뒤지는지 보면 개선 대상 구간이 특정된다.")})
        for t in _fc:
            for y, g in R.groupby(pd.DatetimeIndex(R.index).year):
                _i = g.index
                _a = float((1.0 + R.loc[_i, t]).prod() - 1.0) * 100
                _b = float((1.0 + WS[t].shift(1).fillna(0.0).loc[_i] * R.loc[_i, t]).prod() - 1.0) * 100
                _c = (float((1.0 + WR[t].shift(1).fillna(0.0).loc[_i] * R.loc[_i, t]).prod() - 1.0) * 100
                      if WR is not None else None)
                # [v0.56.0 J4] 연도를 '관측일'이 아니라 **연도** 열에 넣는다(리포트4에서 헷갈렸다),
                #   그리고 차이가 0인 해를 '뒤졌다'로 쓰지 않는다(0은 동일 — 비중이 전 기간 1.0인 해다).
                _d = round(_b - _a, 1)
                rows.append({"블록": "C. 지정 섹터 연도별", "섹터": t, "연도": int(y), "관측일": int(y),
                             "① B&H 복리(%)": round(_a, 1), "② 단일예측 복리(%)": round(_b, 1),
                             "③ 국면예측 복리(%)": (round(_c, 1) if _c is not None else None),
                             "②−① 복리(%p)": _d,
                             "판정": ("★ 그 해 예측이 이겼다" if _d > 0.0 else
                                    ("= 그 해 B&H와 동일(그 해 비중이 줄지 않았다)" if abs(_d) < 0.05 else
                                     f"✗ 그 해 {_d:+.1f}%p 뒤졌다 — 개선 대상 구간"))})
    # ---- [v0.56.0 J3 ★ 신규] 00C_곡선데이터 — 실제 꺾은선 차트가 참조하는 **일별** 날짜×계열 표 ----
    #   사용자 지시: "아니 수익 곡선 비교를 **그래프로** 나타내라고". xlsxwriter 차트는 워크시트의
    #   셀 범위만 참조할 수 있으므로, 차트가 가리킬 데이터 시트를 따로 낸다(write_sector_excel가 그린다).
    #   ★ 지정 섹터(focus)를 앞에 두어 차트 계열 순서가 사용자가 지목한 순서와 같게 한다.
    curve_daily = pd.DataFrame()
    if curves:
        _C = pd.DataFrame(curves)
        _order = [t for t in (focus or ()) if t in cols] + [t for t in cols if t not in (focus or ())]
        _cc = [f"{t} {lbl}" for t in _order for lbl in ("① B&H", "② 단일예측", "③ 국면예측")
               if f"{t} {lbl}" in _C.columns]
        _C = _C[_cc].round(6)
        curve_daily = _C.reset_index().rename(columns={_C.index.name or "index": "날짜"})
        if curve_daily.columns[0] != "날짜":
            curve_daily = curve_daily.rename(columns={curve_daily.columns[0]: "날짜"})
    log("ROT", kv(event="curve_compare_built", sectors=len(cols),
                  solo_beats_bh=n_w2, regime_beats_bh=n_w3, solo_beats_regime=n_w23,
                  focus=";".join(_fc) if _fc else "-", curve_rows=len(curve_daily),
                  curve_series=(len(curve_daily.columns) - 1 if len(curve_daily) else 0),
                  note="① B&H · ② 단일 섹터 예측 · ③ 시장 국면 예측 · 그래프는 00B_곡선그래프"), M=M)
    return pd.DataFrame(rows), curve_daily


def build_asset_return_compare(ret_df: pd.DataFrame, alloc_w: pd.DataFrame, cfg: Any,
                               solo_w: Optional[pd.DataFrame] = None,
                               name_map: Optional[Dict[str, str]] = None,
                               parent_map: Optional[Dict[str, str]] = None,
                               layer: str = "자산",
                               bench_curves: Optional[List[Tuple[str, pd.Series]]] = None,
                               budget: Optional[pd.Series] = None,
                               extra_contrib: Optional[List[Tuple[str, pd.Series, pd.Series]]] = None,
                               port_ret: Optional[pd.Series] = None,
                               conviction: Optional[pd.Series] = None,
                               total_exposure: Optional[pd.Series] = None,
                               regime: Optional[pd.DataFrame] = None,
                               M=None) -> pd.DataFrame:
    """[00A_수익비교, v0.51.0 D1 ★ 신규] 사용자 지시로 만든 **맨 앞 시트**.

    지시: "각 섹터, 산업, 주식별 buy and hold시 수익률(이 때 수익률은 복리가 아닌 변동률 합산)과
          단독 예측으로 거래 시 수익률 비교하고 전략 수익률도 같이 표시해"
      ⇒ 자산 한 줄에 **세 수익**을 나란히 놓는다:
        ① **B&H 단순합**   = Σ r_t          — 그 자산을 그냥 들고 있었을 때(복리 아님, 지시대로)
        ② **단독예측 단순합** = Σ (w_solo·r) — 그 자산 **자기 신호만**으로 0/1 거래했을 때
        ③ **전략기여 단순합** = Σ (w_alloc·r) — **배분 전략**에서 그 자산이 실제로 기여한 몫
      왜 단순합인가(지시의 이유를 살리는 설명): 복리는 **경로**에 좌우되므로 세 계열의 '신호 품질'을
        비교할 때 큰 수익 한 번이 전부를 덮는다. 단순합은 일별 기여를 그대로 더하므로
        "며칠 벌었고 며칠 잃었나"가 보존된다. ⚠ 단 **실제로 손에 남는 것은 복리**이므로
        복리 열을 같은 행에 함께 싣는다(판정은 둘을 같이 본다 — 소수 클래스 규칙과 같은 정신).
      ★ ③은 자산별로 **복리를 쓰지 않는다**. 배분 전략에서 한 자산의 기여는 그 자산만의 곡선이
        아니기 때문이다(다른 자산과 현금이 같은 자본을 나눠 쓴다). 그래서 ③의 복리는
        **포트폴리오 블록에서만** 계산한다 — 그것이 수학적으로 옳은 유일한 지점이다.

    블록 B(포트폴리오)가 사용자의 두 번째 지시에 답한다:
      "배분전략 거래 할거면 전체자산을 1로 해서 그걸 배분해서 각 총합이 1이 되도록 하라고
       왜 자꾸 각 티커별로 비중이 1이냐고"
      ⇒ **비중 합계 감사** 행이 매 실행 합계의 최대·평균·1.0 초과일수를 찍는다.
        초과가 1일이라도 있으면 ⚠로 표시된다 — 조용히 넘어가지 않는다."""
    rows: List[dict] = []
    blkA = "A. 자산별 수익 비교"
    blkB = "B. 포트폴리오(전체자산 1.0)"
    cols = [c for c in ret_df.columns if c in alloc_w.columns]
    if not cols:
        return pd.DataFrame([{"블록": blkA, "자산": "산출 불가",
                              "판정": "ret_df와 alloc_w에 공통 자산이 없다 — 색인·열 정렬을 확인할 것"}])
    idx = ret_df.index
    R = ret_df[cols].astype(float)
    WA = alloc_w.reindex(index=idx, columns=cols).astype(float).fillna(0.0)
    WS = (solo_w.reindex(index=idx, columns=cols).astype(float).fillna(0.0)
          if solo_w is not None else None)

    def _mdd(r: pd.Series) -> float:
        c = (1.0 + pd.Series(r).astype(float).fillna(0.0)).cumprod()
        return float((c / c.cummax() - 1.0).min())

    def _cmp(r: pd.Series) -> float:
        return float((1.0 + pd.Series(r).astype(float).fillna(0.0)).prod() - 1.0)

    rows.append({"블록": blkA, "자산": "── 읽는 법 ──",
                 "판정": ("**단순합**은 일간 변동률을 그대로 더한 값이다(복리 아님 — 사용자 지시). "
                        "같은 행의 **복리**와 함께 읽을 것: 단순합은 '신호가 며칠 맞았나'를, "
                        "복리는 '실제로 얼마가 남나'를 말한다. "
                        "① B&H = 그냥 보유 · ② 단독예측 = 그 자산 **자기 신호만**으로 0/1 거래 · "
                        "③ 전략기여 = **배분 전략**에서 그 자산이 실제로 기여한 몫(비중 × 수익). "
                        f"③은 {layer} 계층이 전체자산 1.0을 나눠 쓴 결과이므로 자산별 합이 B&H보다 "
                        "작은 것이 **정상**이다 — 한 자산에 자본 전부를 주지 않기 때문이다. "
                        "따라서 ③은 B&H와 직접 비교하지 말고 **블록 B의 포트 합계**와 비교할 것. "
                        "②와 ①의 차이가 그 자산 **예측의 값**이고, 그것이 이 시트의 판정 대상이다.")})

    solo_tot = pd.Series(0.0, index=idx); n_ok = 0
    _pv: List[dict] = []          # [E2] 블록 C용 (자산, 예측의 값, 평균비중, 기여)
    for t in cols:
        r = R[t]
        ok = r.notna()
        n = int(ok.sum())
        if n < 20:
            rows.append({"블록": blkA, "자산": t, "이름": (name_map or {}).get(t, ""),
                         "부모": (parent_map or {}).get(t, ""), "관측일": n,
                         "판정": f"⚠ 관측 {n}일 — 20일 미만이라 건너뜀"})
            continue
        rf = r.fillna(0.0)
        bh_s = float(rf.sum()) * 100.0
        bh_c = _cmp(rf) * 100.0
        wa = WA[t]
        st_s = float((wa * rf).sum()) * 100.0
        row = {"블록": blkA, "자산": t, "이름": (name_map or {}).get(t, ""),
               "부모": (parent_map or {}).get(t, ""), "관측일": n,
               "① B&H 단순합(%)": round(bh_s, 2), "① B&H 복리(%)": round(bh_c, 2),
               "① B&H MDD(%)": round(_mdd(rf) * 100.0, 2)}
        if WS is not None:
            ws = WS[t]
            so = ws * rf
            solo_tot = solo_tot + so
            n_ok += 1
            so_s = float(so.sum()) * 100.0
            row.update({"② 단독예측 단순합(%)": round(so_s, 2),
                        "② 단독예측 복리(%)": round(_cmp(so) * 100.0, 2),
                        "② 단독예측 MDD(%)": round(_mdd(so) * 100.0, 2),
                        "② 평균비중": round(float(ws.mean()), 4),
                        "②−① 단순합(%p)": round(so_s - bh_s, 2)})
            _v = ("★ 예측이 B&H를 이겼다" if so_s > bh_s else
                  "예측이 B&H에 미달 — 참여 부족" if float(ws.mean()) < 0.95 else
                  "예측이 B&H에 미달 — 비중은 찼으니 타이밍 문제")
        else:
            _v = "단독예측 비중 미제공"
        row.update({"③ 전략기여 단순합(%)": round(st_s, 2),
                    "③ 전략 평균비중": round(float(wa.mean()), 4),
                    "③ 전략 최대비중": round(float(wa.max()), 4),
                    "판정": _v})
        rows.append(row)
        if WS is not None:
            _pv.append({"자산": t, "pred": so_s - bh_s, "w": float(wa.mean()), "contrib": st_s})

    # ---------------- 블록 B: 포트폴리오 ----------------
    RF = R.fillna(0.0)
    nA = max(1, len(cols))
    port_r = (RF * WA).sum(axis=1)                 # 배분 전략 포트 일간수익(총합 ≤ 1.0)
    eq_r = RF.mean(axis=1)                         # 동일가중 B&H(총 1.0)
    wsum = WA.sum(axis=1)
    rows.append({"블록": blkB, "자산": "── 읽는 법 ──",
                 "판정": ("여기서만 **총자본 1.0** 기준이다. 세 줄을 같은 잣대로 비교할 수 있는 곳은 "
                        "이 블록뿐이다 — 블록 A의 ③은 자산 한 칸의 기여일 뿐이기 때문이다. "
                        "맨 아래 **비중 합계 감사**가 '전체자산 1.0'이 실제로 지켜졌는지 매 실행 확인한다.")})
    _keep: Dict[str, dict] = {}
    def _mk(lbl, s, w, note):
        _c = _cmp(s); _m = _mdd(s)
        _y = max(len(s) / 252.0, 1e-9)
        _g = (1.0 + _c) ** (1.0 / _y) - 1.0
        _keep[lbl] = {"단순합": float(s.sum()) * 100.0, "복리": _c * 100.0,
                      "MDD": _m * 100.0, "CAGR": _g,
                      "칼마": (_g / abs(_m) if _m < -1e-9 else float("nan"))}
        rows.append(
            {"블록": blkB, "자산": lbl, "관측일": int(len(s)),
             "① B&H 단순합(%)": round(float(s.sum()) * 100.0, 2),
             "① B&H 복리(%)": round(_c * 100.0, 2),
             "① B&H MDD(%)": round(_m * 100.0, 2),
             "CAGR": round(_g, 4),
             "칼마(CAGR/MDD)": (round(_g / abs(_m), 3) if _m < -1e-9 else None),
             "③ 전략 평균비중": (round(float(w.mean()), 4) if w is not None else None),
             "③ 전략 최대비중": (round(float(w.max()), 4) if w is not None else None),
             "판정": note})
    _mk(f"★ {len(cols)}{'개' if layer != '개별주식' else '종목'} 동일가중 B&H (총 1.0)", eq_r,
        pd.Series(1.0, index=idx),
        "같은 자산군·같은 자본을 신호 없이 균등 보유 — **배분 기술만 남는 like-for-like 벤치**다")
    if WS is not None and n_ok:
        _mk("★ 단독예측 동일가중 (총 1.0)", solo_tot / float(n_ok), WS.mean(axis=1),
            "각 자산이 자기 신호로 0/1 거래하고 그것을 균등가중 — **예측만의 값**을 본다")
    _mk(f"★★ 전략(배분 · {layer} 계층)", port_r, wsum,
        "엔진이 실제로 집행한 배분. 위 두 줄을 **둘 다** 이겨야 이 계층이 값을 한 것이다")
    # ---- [v0.23.0 E1 ★] 이 계층이 쓰는 **다른 슬리브**(부모 ETF·잔여·현금대체)의 기여 ----
    #   왜 필요한가: 산업 계층은 자본의 일부만 산업 칸에 넣고 나머지를 **부모 섹터 ETF**로 보낸다.
    #     그래서 '산업 칸의 기여 합'만 더하면 전체 포트가 아니고, 그것을 동일가중 B&H와 비교하면
    #     **이 계층이 진다는 잘못된 결론**이 나온다(실측: 산업 칸만 85.28% vs B&H 116.3%).
    #     R59에서 고친 '도달 가능한 벤치'와 같은 종류의 오류다 — 단위를 맞춰야 비교가 성립한다.
    _ex_tot = None
    for _lbl, _r, _w in (extra_contrib or []):
        _rr = pd.Series(_r).astype(float).reindex(idx).fillna(0.0)
        _ww = (pd.Series(_w).astype(float).reindex(idx).fillna(0.0)
               if _w is not None else pd.Series(0.0, index=idx))
        _ex_tot = _rr if _ex_tot is None else (_ex_tot + _rr)
        _mk(f"  └ {_lbl}", _rr, _ww, "이 계층이 산업/섹터 칸 밖으로 보낸 자본의 기여(참고)")
    if _ex_tot is not None:
        _mk("★★ 전략 합계(배분 + 위 슬리브 전부)", port_r + _ex_tot, wsum + (
            sum(pd.Series(_w).astype(float).reindex(idx).fillna(0.0)
                for _, _, _w in (extra_contrib or []) if _w is not None)
            if any(_w is not None for _, _, _w in (extra_contrib or [])) else pd.Series(0.0, index=idx)),
            "★ 이 줄이 **이 계층의 실제 포트**다 — 동일가중 B&H와 비교할 단위는 이것이다")
    for _bl, _bc in (bench_curves or []):
        _b = pd.Series(_bc).astype(float).reindex(idx).ffill()
        _br = _b.pct_change().fillna(0.0)
        _mk(f"참고: {_bl}", _br, None, "외부 벤치(참고용)")
    # ---- [v0.24.0 F1 ★★ 신규] 판정 행 — "전략이 B&H를 얼마나 이겼나"를 시트가 직접 말한다 ----
    #   왜 필요한가(사용자 지적): "예측 수익이 buy and hold 보다 훨씬 많이 나와야 해 지금 보니까 그런게 없어".
    #     그런데 실측은 전략이 이미 크게 이기고 있었다 — **시트가 그렇게 말하지 않았을 뿐이다.**
    #     블록 B가 숫자만 나열하고 '몇 배 이겼는가'를 계산해 주지 않아서 읽는 사람이 직접 비교해야 했다.
    #   ★★ 그리고 **단순합만 보면 예측의 값이 구조적으로 과소평가된다**:
    #     비중 w ∈ [0,1]이면 Σ(w·r) − Σ(r) = −Σ((1−w)·r)이므로, 빼 둔 날의 수익 합이 음수일 때만
    #     단순합에서 이긴다. 하락을 피해 **복리로 번 것**은 단순합에 전혀 반영되지 않는다.
    #     실측(섹터): 단순합으로 B&H를 이긴 섹터 2/11인데 **복리로는 7/11**, MDD는 **11/11** 개선.
    #     그래서 판정은 **단순합·복리·MDD·칼마 넷을 함께** 본다.
    _star = next((k for k in _keep if k.startswith("★★ 전략 합계")), None) \
        or next((k for k in _keep if k.startswith("★★ 전략")), None)
    _benches = [k for k in _keep if k.startswith("★ ") and k != _star]
    if _star and _benches:
        _S = _keep[_star]
        for _b in _benches:
            _B = _keep[_b]
            _rs = (_S["단순합"] / _B["단순합"]) if abs(_B["단순합"]) > 1e-9 else float("nan")
            _rc = (_S["복리"] / _B["복리"]) if abs(_B["복리"]) > 1e-9 else float("nan")
            _rk = (_S["칼마"] / _B["칼마"]) if (pd.notna(_B["칼마"]) and abs(_B["칼마"]) > 1e-9) else float("nan")
            _wins = sum([_S["단순합"] > _B["단순합"], _S["복리"] > _B["복리"],
                         _S["MDD"] > _B["MDD"], (pd.notna(_S["칼마"]) and pd.notna(_B["칼마"])
                                                 and _S["칼마"] > _B["칼마"])])
            rows.append({"블록": blkB, "자산": f"★★★ 판정: 전략 vs {_b.lstrip('★ ')[:28]}",
                         "① B&H 단순합(%)": round(_S["단순합"] - _B["단순합"], 2),
                         "① B&H 복리(%)": round(_S["복리"] - _B["복리"], 2),
                         "① B&H MDD(%)": round(_S["MDD"] - _B["MDD"], 2),
                         "CAGR": round(_S["CAGR"] - _B["CAGR"], 4),
                         "칼마(CAGR/MDD)": (round(_S["칼마"] - _B["칼마"], 3)
                                        if pd.notna(_S["칼마"]) and pd.notna(_B["칼마"]) else None),
                         "판정": (f"**{_wins}/4 승** — 단순합 {_S['단순합']:.1f}% vs {_B['단순합']:.1f}%"
                                + (f"(**{_rs:.2f}배**)" if pd.notna(_rs) and _rs > 0 else "")
                                + f" · **복리 {_S['복리']:.1f}% vs {_B['복리']:.1f}%"
                                + (f"(**{_rc:.2f}배**)" if pd.notna(_rc) and _rc > 0 else "") + "**"
                                + f" · CAGR {_S['CAGR']:.2%} vs {_B['CAGR']:.2%}"
                                + f" · MDD {_S['MDD']:.1f}% vs {_B['MDD']:.1f}%"
                                + (f" · **칼마 {_S['칼마']:.2f} vs {_B['칼마']:.2f}({_rk:.1f}배)**"
                                   if pd.notna(_rk) and _rk > 0 else "")
                                + (" → ★★ 전략이 확실히 낫다."
                                   if _wins >= 3 else
                                   " → ⚠ 전략이 이 벤치를 못 이긴다 — 이 계층의 존재 이유를 재검토할 것."))})
        rows.append({"블록": blkB, "자산": "── 단순합만 보면 안 되는 이유 ──",
                     "판정": ("비중 w ≤ 1이면 **단순합 Σ(w·r)은 Σ(r)을 크게 넘을 수 없다** — "
                            "빼 둔 날의 수익 합이 음수일 때만 이긴다. 하락을 피해 **복리로 번 것**은 "
                            "단순합에 반영되지 않는다(실측 섹터: 단순합 2/11 승 ↔ **복리 7/11 · MDD 11/11 승**). "
                            "따라서 '예측이 B&H보다 훨씬 많이 벌었나'는 **복리와 칼마로** 판정해야 하고, "
                            "단순합은 '며칠 맞았나'를 보는 보조 지표로 쓴다. "
                            "★ 단순합에서도 크게 이기려면 **뺀 자본을 다른 자산에 넣어야** 하며 "
                            "그것이 바로 이 계층의 배분이다 — 위 ★★★ 판정 행이 그 결과다.")})
    # ---- 비중 합계 감사 ----
    #   ★ 판정을 **초과 규모로 나눈다**. v0.51.0 첫 실행에서 최대 1.0002(8일)를 잡고
    #     "총 1.0배 레버리지가 된다"고 써서 우스꽝스러웠다 — 부동소수 잔차와 실제 레버리지는
    #     전혀 다른 문제이고 **처방도 다르다**(반올림 vs 배분층 재설계).
    _over = int((wsum > 1.0 + 1e-6).sum())
    _bad = int((WA > 1.0 + 1e-9).sum().sum())
    _mx = float(wsum.max())
    _resid = (_over > 0 and _mx <= 1.001 and _bad == 0)     # 1.001 이하 = 부동소수 잔차
    if _over == 0 and _bad == 0:
        _verd = "★ 전체자산 1.0 제약이 지켜졌다(초과 0일)."
    elif _resid:
        _verd = (f"△ 부동소수 잔차 — 최대 {_mx:.6f}(초과분 {(_mx - 1.0) * 1e4:.1f}bp)가 {_over}일. "
                 "레버리지가 아니라 **반올림 문제**다. 배분 로직은 정상이며, 합계를 소수 6자리로 "
                 "맞추는 것으로 해결된다(자본 영향 사실상 0).")
    else:
        _verd = (f"⚠⚠ **제약 위반** — 합계가 1.0을 넘는 날이 {_over}일, 최대 **{_mx:.2f}배**다. "
                 f"전체자산을 1로 두고 나눠 담아야 한다. 자산마다 1.0을 주면 총 {_mx:.1f}배 "
                 "레버리지이며 이것은 배분이 아니다 — 배분층을 확인할 것."
                 + (f" 개별 자산이 1.0을 넘은 칸도 {_bad}개 있다." if _bad else ""))
    rows.append({"블록": blkB, "자산": "★ 비중 합계 감사",
                 "③ 전략 평균비중": round(float(wsum.mean()), 4),
                 "③ 전략 최대비중": round(_mx, 6),
                 "관측일": int(len(wsum)),
                 "판정": (f"일별 비중 합계: 평균 {float(wsum.mean()):.4f} · 최대 {_mx:.6f} · "
                        f"**1.0 초과일 {_over}일** · 개별 자산이 1.0을 넘은 칸 {_bad}개. " + _verd)})
    if budget is not None and len(budget):
        _bg = pd.Series(budget).astype(float).reindex(idx).fillna(0.0)
        _use = (wsum / _bg.replace(0.0, np.nan))
        rows.append({"블록": blkB, "자산": "★ 예산 사용률(상위 계층 대비)",
                     "③ 전략 평균비중": round(float(_bg.mean()), 4),
                     "③ 전략 최대비중": round(float(_bg.max()), 4),
                     "판정": (f"상위 계층이 준 예산 평균 {float(_bg.mean()):.4f}(최대 {float(_bg.max()):.4f}) 중 "
                            f"이 계층이 쓴 비율 중위 **{float(_use.median()):.3f}** · "
                            f"예산을 덜 쓴 날 {int((wsum < _bg - 1e-9).sum())}일. "
                            "★ 사용률이 1.0에 가까우면 **상승 참여의 천장은 이 계층이 아니라 상위 계층의 "
                            "예산**이다 — 그 경우 이 계층을 고쳐도 참여는 올라가지 않는다.")})
    # ---- [v0.23.0 E2 ★★ 신규 블록 C] 예측의 값 vs 배분이 준 비중 ----
    #   사용자 질문("상승을 제대로 탔나 · 못했으면 원인")에 대한 **새로운 층의 답**:
    #     ②−①(그 자산 예측의 값)과 ③ 전략 평균비중의 관계를 본다.
    #     양수 상관 = 잘 맞추는 자산에 비중을 준다(예측이 배분에 연결돼 있다).
    #     음수 상관 = **예측을 잘하는 자산에는 비중을 안 주고 못하는 자산에 준다.**
    #   ⚠ 음수라고 곧 손해는 아니다 — 선택이 모멘텀으로 이뤄지고 그것이 더 잘 듣는 경우일 수 있다.
    #     그래서 '전략기여'도 같이 싣고, 두 열을 함께 읽게 한다.
    if WS is not None and len(_pv) >= 5:
        _d = pd.DataFrame(_pv)
        _pe = float(_d["pred"].corr(_d["w"])) if _d["w"].std() > 0 else float("nan")
        _sp = float(_d["pred"].corr(_d["w"], method="spearman")) if _d["w"].std() > 0 else float("nan")
        _k = max(1, len(_d) // 3)
        _tw_set = set(_d.nlargest(_k, "w")["자산"]); _tp_set = set(_d.nlargest(_k, "pred")["자산"])
        _ov = len(_tw_set & _tp_set); _exp = _k * _k / max(1, len(_d))
        _hi = _d.nlargest(_k, "w")["pred"].mean(); _all = _d["pred"].mean()
        rows.append({"블록": "C. 예측의 값 vs 배분 비중", "자산": "── 읽는 법 ──",
                     "판정": ("②−①(그 자산 **예측의 값**)과 ③(배분이 준 **평균비중**)의 관계다. "
                            "양수면 '잘 맞추는 자산에 비중을 준다'(예측이 배분에 연결돼 있다), "
                            "음수면 '**예측을 잘하는 자산에 비중을 안 준다**'는 뜻이다. "
                            "⚠ 음수가 곧 손해는 아니다 — 선택이 모멘텀으로 이뤄지고 그쪽이 더 잘 듣는 "
                            "경우일 수 있다. 그래서 같은 블록의 **전략기여**를 반드시 함께 볼 것.")})
        rows.append({"블록": "C. 예측의 값 vs 배분 비중", "자산": "★ 상관(피어슨)",
                     "③ 전략 평균비중": (round(_pe, 4) if pd.notna(_pe) else None),
                     "판정": f"피어슨 {_pe:+.4f} · 스피어만 {_sp:+.4f} (자산 {len(_d)}개)"})
        rows.append({"블록": "C. 예측의 값 vs 배분 비중", "자산": f"★ 비중 상위{_k} ∩ 예측 상위{_k}",
                     "관측일": _ov,
                     "판정": (f"겹침 **{_ov}개** / 무작위 기대 {_exp:.1f}개. "
                            + ("★ 무작위보다 많다 — 배분이 예측 성적을 어느 정도 반영한다."
                               if _ov > _exp + 1e-9 else
                               "⚠ 무작위 이하다 — **배분이 예측 성적을 반영하지 않는다.**"))})
        rows.append({"블록": "C. 예측의 값 vs 배분 비중", "자산": f"★★ 비중 상위{_k}의 평균 예측값",
                     "②−① 단순합(%p)": round(float(_hi), 2),
                     "판정": (f"비중 상위{_k} 자산의 ②−① 평균 **{_hi:+.2f}%p** vs 전체 평균 {_all:+.2f}%p. "
                            + ("★ 비중을 준 쪽이 예측도 더 좋다."
                               if _hi > _all else
                               "⚠ **비중을 많이 준 자산이 평균보다 예측을 더 못한다.** "
                               "선택 점수가 '그 자산의 국면 예측이 맞는지'를 보지 않기 때문이다 — "
                               "다음 개선 후보는 **예측 성적을 선택 점수에 섞는 것**이며, "
                               "라이브가 아니라 **격자로 채점**해야 한다(과거 3회 실패 교훈)."))})
        _bw = _d.nlargest(3, "w")[["자산", "pred", "w", "contrib"]]
        rows.append({"블록": "C. 예측의 값 vs 배분 비중", "자산": "비중 상위3 상세",
                     "판정": " · ".join(f"{r['자산']}: 예측 {r['pred']:+.1f}%p · 비중 {r['w']:.4f} · "
                                      f"기여 {r['contrib']:+.1f}%" for _, r in _bw.iterrows())})
    # ---- [v0.24.0 F2 ★★ 신규 블록 D] 회피일 분해 — "뺀 날이 실제로 내렸나" ----
    #   이것이 **예측 품질의 직접 측정**이다. ②−①(단순합 차)은 비중 수준에 좌우되지만,
    #   '회피일의 실제 평균수익'은 **예측이 나쁜 날을 골라냈는지만** 묻는다.
    #   실측(섹터 v0.52.0): 회피일 평균수익이 **음수인 섹터 7/11** · 중위 −0.0039% vs
    #     보유일 +0.0674% · 격차가 음수인 섹터 **10/11**. ⇒ **예측은 실제로 작동한다.**
    #     그런데 회피일 평균이 0에 가까워 단순합 이득이 작고, 부분 보유(w=0.5)한 날이
    #     상승일이면 거기서 잃는다 — 그것이 ②−①가 음수인 진짜 이유다.
    if WS is not None and cols:
        rows.append({"블록": "D. 회피일 분해(예측 품질)", "자산": "── 읽는 법 ──",
                     "판정": ("단독예측이 **비중을 뺀 날**(w<0.5)의 실제 수익을 보유일과 비교한다. "
                            "**회피일 평균수익이 음수**면 예측이 나쁜 날을 제대로 골라낸 것이고, "
                            "**격차(회피−보유)가 음수**면 두 집합이 실제로 갈렸다는 뜻이다 — "
                            "이 두 열이 **예측 품질의 직접 증거**다(②−①는 비중 수준에 좌우돼 흐려진다). "
                            "★ '부분보유일'은 w가 0과 1 사이인 날이다. 여기서 상승을 절반만 먹으면 "
                            "②−①가 음수가 되는데, **그것은 예측이 틀린 것이 아니라 비중이 중간이어서**다. "
                            "그 경우 고칠 곳은 예측이 아니라 **상위 계층의 예산(E_t)**이다.")})
        _dn = 0; _gn = 0; _nn = 0
        for t in cols:
            r = R[t]; w = WS[t]
            m = r.notna() & w.notna()
            if int(m.sum()) < 50:
                continue
            _rr = r[m]; _ww = w[m]
            _out = _ww < 0.5; _in_ = _ww > 0.999; _mid = (~_out) & (~_in_)
            _mo = float(_rr[_out].mean()) * 100 if bool(_out.any()) else float("nan")
            _mi = float(_rr[_in_].mean()) * 100 if bool(_in_.any()) else float("nan")
            _mm = float(_rr[_mid].mean()) * 100 if bool(_mid.any()) else float("nan")
            _gap = (_mo - _mi) if (pd.notna(_mo) and pd.notna(_mi)) else float("nan")
            _nn += 1
            _dn += int(pd.notna(_mo) and _mo < 0)
            _gn += int(pd.notna(_gap) and _gap < 0)
            rows.append({"블록": "D. 회피일 분해(예측 품질)", "자산": t,
                         "이름": (name_map or {}).get(t, ""), "관측일": int(m.sum()),
                         "회피일수(w<0.5)": int(_out.sum()),
                         "부분보유일수(0<w<1)": int(_mid.sum()),
                         "전량보유일수(w=1)": int(_in_.sum()),
                         "회피일 평균수익(%)": (round(_mo, 4) if pd.notna(_mo) else None),
                         "부분보유일 평균수익(%)": (round(_mm, 4) if pd.notna(_mm) else None),
                         "전량보유일 평균수익(%)": (round(_mi, 4) if pd.notna(_mi) else None),
                         "격차(회피−보유)%p": (round(_gap, 4) if pd.notna(_gap) else None),
                         "판정": ("★ 회피가 유효(뺀 날이 실제로 더 나빴다)" if pd.notna(_gap) and _gap < 0
                                else "⚠ 회피일이 보유일보다 좋았다 — 이 자산에서 예측이 반대 방향")})
        if _nn:
            rows.append({"블록": "D. 회피일 분해(예측 품질)", "자산": "★★ 종합",
                         "관측일": _nn,
                         "판정": (f"회피일 평균수익이 **음수인 자산 {_dn}/{_nn}** · "
                                f"격차(회피−보유)가 **음수인 자산 {_gn}/{_nn}**. "
                                + ("★★ 예측은 **실제로 작동한다** — 뺀 날이 든 날보다 나빴다. "
                                   "그런데도 ②−①(단순합)이 음수라면 원인은 예측이 아니라 "
                                   "**비중 수준**이다(부분보유일에서 상승을 절반만 먹는다). "
                                   "고칠 곳은 상위 계층의 예산이거나, 뺀 자본을 다른 자산에 넣는 "
                                   "**배분**이다 — 후자가 이 계층이 이미 하는 일이고 블록 B ★★★ 판정이 그 성적이다."
                                   if _gn > _nn / 2 else
                                   "⚠ 절반 이상의 자산에서 회피일이 보유일보다 좋았다 — "
                                   "**예측 신호 자체를 다시 봐야 한다.**"))})
    # ---- [v0.24.0 F3 ★★ 신규 블록 E] 노출 상향 격자 — "수익을 더 내려면 무엇을 내놓아야 하나" ----
    #   사용자 요구: "예측 수익이 buy and hold 보다 **훨씬** 많이 나와야 해".
    #   총합 1.0 제약 안에서 수익을 더 내는 **유일하게 남은 레버는 총노출을 올리는 것**이다
    #   (비중 하한 상향·확신 비례 비중·예측성적 게이트는 아래 '측정으로 닫힌 것'에 있다).
    #   ★ 그런데 그것은 **리스크 파라미터**이므로 이 시트는 **측정만 하고 라이브를 바꾸지 않는다.**
    #     상충을 표로 내고 사용자가 고르게 한다 — 조용히 위험을 올리지 않는다는 원칙.
    if port_ret is not None and len(port_ret) > 60:
        _pr = pd.Series(port_ret).astype(float).reindex(idx).fillna(0.0)
        # ★ 총**위험**노출이 필요하다. extra_contrib의 비중은 '현금 포함 잔여'라서 그것을 더하면
        #   합이 정의상 1.0이 되고 격자가 전부 같은 값으로 나온다(첫 구현에서 실제로 그랬다 —
        #   다섯 행이 소수점까지 동일했다). 그래서 호출자가 **투자된 총노출**을 명시로 넘긴다.
        _tot0 = (pd.Series(total_exposure).astype(float).reindex(idx).fillna(0.0)
                 if total_exposure is not None else wsum)
        if float(_tot0.max()) <= 1e-9:
            _tot0 = wsum
        _cv = (pd.Series(conviction).reindex(idx).fillna(False).astype(bool)
               if conviction is not None else pd.Series(True, index=idx))
        rows.append({"블록": "E. 노출 상향 격자(진단)", "자산": "── 읽는 법 ──",
                     "판정": ("총합 1.0 제약 안에서 **총노출을 올렸을 때** 수익·위험이 어떻게 움직이는지다. "
                            "★ 이 격자는 **진단만 한다 — 라이브를 바꾸지 않는다**(리스크 파라미터를 "
                            "조용히 올리지 않는다는 원칙). 마지막 열의 **한계비율 = ΔCAGR / ΔMDD악화**로 "
                            "판정한다: 1.0보다 크면 '위험 1단위로 수익 1단위 이상을 산다'는 뜻이고, "
                            "작으면 비싸게 사는 것이다. 참고로 산업 계층이 라이브로 채택한 변경들의 "
                            "한계비율은 1.1~2.0이었다. 켜려면 아래 '되돌리기' 문구의 오버라이드를 쓴다.")})
        _base = None
        for _lbl, _k, _gate_only in (("현행(변경 없음)", None, False),
                                     ("게이트 통과일만 → 0.75", 0.75, True),
                                     ("게이트 통과일만 → 1.00", 1.00, True),
                                     ("전일 → 0.75", 0.75, False),
                                     ("전일 → 1.00", 1.00, False)):
            if _k is None:
                _sc = pd.Series(1.0, index=idx); _tgt = _tot0
            else:
                _want = pd.Series(np.where(_cv if _gate_only else True, _k, _tot0), index=idx)
                _tgt = pd.concat([_want, pd.Series(1.0, index=idx)], axis=1).min(axis=1)
                _tgt = pd.concat([_tgt, _tot0], axis=1).max(axis=1)      # 줄이지는 않는다
                _sc = (_tgt / _tot0.replace(0.0, np.nan)).fillna(1.0)
            _s = _pr * _sc.shift(1).fillna(1.0)
            _c = (1.0 + _s).cumprod()
            _m = float((_c / _c.cummax() - 1.0).min())
            _y = max(len(_s) / 252.0, 1e-9)
            _g = float(_c.iloc[-1]) ** (1.0 / _y) - 1.0
            _row = {"블록": "E. 노출 상향 격자(진단)", "자산": _lbl,
                    "① B&H 단순합(%)": round(float(_s.sum()) * 100.0, 2),
                    "① B&H 복리(%)": round((float(_c.iloc[-1]) - 1.0) * 100.0, 2),
                    "① B&H MDD(%)": round(_m * 100.0, 2), "CAGR": round(_g, 4),
                    "칼마(CAGR/MDD)": (round(_g / abs(_m), 3) if _m < -1e-9 else None),
                    "③ 전략 평균비중": round(float(_tgt.mean()), 4),
                    "③ 전략 최대비중": round(float(_tgt.max()), 4)}
            if _base is None:
                _base = (_g, _m)
                _row["판정"] = "기준선 — 아래 행들은 이 행 대비 한계비율로 판정한다"
            else:
                _dg = _g - _base[0]; _dm = abs(_m) - abs(_base[1])
                if abs(_dg) < 1e-9 and _dm <= 1e-9:
                    _row["판정"] = ("변화 없음 — 이 목표가 현재 노출보다 낮아 상향이 일어나지 않았다"
                                  f"(현재 평균 노출 {float(_tot0.mean()):.3f})")
                else:
                    _mr = (_dg / _dm) if _dm > 1e-9 else float("inf")
                    # ★ 한계비율이 **음수**면 CAGR이 내리고 MDD도 나빠진 것 = 양쪽 다 손해다.
                    #   '1.0 미만'으로만 쓰면 그 경우가 '수익은 오르지만'이라는 틀린 설명을 얻는다.
                    if _dm > 1e-9 and _dg <= 0:
                        _verd_e = ("⚠⚠ **양쪽 다 손해** — CAGR이 내리고 MDD도 나빠졌다(열등 지배). "
                                   "이 방향은 검토할 가치가 없다.")
                    elif _mr >= 1.0:
                        _verd_e = "★ 1.0 이상 — 위험 대비 값이 있다(승격 후보)"
                    else:
                        _verd_e = ("⚠ 1.0 미만 — 위험을 비싸게 산다. **수익은 오르지만 칼마는 나빠진다** — "
                                   "사용자가 '수익 극대화'와 '위험조정 극대화' 중 무엇을 원하는지에 달렸다")
                    _row["판정"] = (f"ΔCAGR {_dg:+.4f} · ΔMDD악화 {_dm:+.4f} · "
                                  + (f"**한계비율 {_mr:+.3f}** " if _dm > 1e-9
                                     else "**MDD 악화 없음(한계비율 무한)** ")
                                  + _verd_e)
            rows.append(_row)
        rows.append({"블록": "E. 노출 상향 격자(진단)", "자산": "★★ 측정으로 닫힌 방향(재시도 금지)",
                     "판정": ("같은 목적으로 시도해 **측정상 나빠진** 것들 — 다시 하지 말 것: "
                            "(1) **단독예측 비중 하한 상향** 0.3/0.5 → 섹터별 칼마 중위 8.37 → 6.05 / 4.82 "
                            "(2) **확신 비례 비중**(0.3+0.7·복합점수백분위) → 칼마 2.92, 복리도 131.6 → 68.5로 급락 "
                            "(3) **워크포워드 예측성적 상위 k 재배분** → 현행 복리 1039 대비 상위3 133.9 · "
                            "상위5 167.6 · 상위7 195.8 · 상위11 214.1로 **전부 크게 낮다**(집중이 깨진다). "
                            "⇒ 이 계층의 수익은 **모멘텀 집중**에서 나오고, 예측은 **하락 회피**로 기여한다. "
                            "두 역할을 섞으려 하면 둘 다 잃는다.")})
    # ---- [v0.54.0 G3 ★★★ 신규 블록 F] 국면 버킷 손익 분해 — "예측이 어디서 틀렸나" ----
    #   이것이 사용자 지시("예측 틀린 부분에서 문제 원인 찾아서")의 **직접 답**이다.
    #   ②−①(자산 단위)를 **국면 버킷 단위**로 쪼개면 손실이 어느 버킷에 몰렸는지 한 표에서 보인다.
    #   ★ 리포트53 실측이 이 표로 원인을 특정했다(11섹터 집계):
    #       중립 8,040일 · 평균수익 **+0.0466%(양수)** · 비중 **0.261** → **−203.5%p**  ← 손실의 전부
    #       상승 12,736일 · +0.0783% · 0.917 → −54.6%p
    #       하락 1,655일 · **−0.0942%** · 0.000 → **+150.4%p**  ← 방어가 번 것
    #     ⇒ 하락 예측은 훌륭하고 **중립을 현금으로 두던 것이 과했다.** 그 한 줄이 v0.54.0 G1의 근거다.
    #   읽는 법: **평균수익이 양수인데 비중이 1보다 작은 버킷**이 놓치는 곳이다.
    if WS is not None and regime is not None and len(regime):
        _rg = regime.reindex(index=idx).astype(str)
        _acc: Dict[str, dict] = {}
        for t in cols:
            if t not in _rg.columns:
                continue
            r = R[t]; w = WS[t]; g = _rg[t]
            m0 = r.notna() & w.notna() & g.notna() & g.ne("nan")
            for _g in sorted(set(g[m0])):
                m = m0 & g.eq(_g)
                if int(m.sum()) < 20:
                    continue
                a = _acc.setdefault(_g, {"n": 0, "rsum": 0.0, "wsum": 0.0, "contrib": 0.0, "bh": 0.0})
                a["n"] += int(m.sum())
                a["rsum"] += float(r[m].sum()); a["wsum"] += float(w[m].sum())
                a["contrib"] += float((w[m] * r[m]).sum()); a["bh"] += float(r[m].sum())
        if _acc:
            rows.append({"블록": "F. 국면 버킷 손익 분해", "자산": "── 읽는 법 ──",
                         "판정": ("②(단독예측)이 ①(B&H)에 미달하는 금액을 **국면 버킷별로** 쪼갠 것이다. "
                                "**'그날 평균수익'이 양수인데 '평균비중'이 1보다 작은 버킷이 놓치는 곳**이고, "
                                "평균수익이 음수이고 비중이 0이면 **방어가 번 곳**이다. "
                                "'놓친 것(%p)' = Σ((비중−1)·수익) — 음수면 그 버킷에서 B&H에 뒤진 금액이다. "
                                "★ 이 표가 v0.54.0의 라이브 변경(중립 비중 워크포워드 상향)을 낳았다: "
                                "중립 버킷 하나가 손실의 전부였다.")})
            _tot = 0.0
            for _g, a in sorted(_acc.items(), key=lambda kv2: (kv2[1]["contrib"] - kv2[1]["bh"])):
                _miss = (a["contrib"] - a["bh"]) * 100.0
                _tot += _miss
                _mu = (a["rsum"] / a["n"]) * 100.0
                _mw = a["wsum"] / a["n"]
                rows.append({"블록": "F. 국면 버킷 손익 분해", "자산": _g, "관측일": a["n"],
                             "② 평균비중": round(_mw, 4),
                             "① B&H 단순합(%)": round(a["bh"] * 100.0, 1),
                             "② 단독예측 단순합(%)": round(a["contrib"] * 100.0, 1),
                             "②−① 단순합(%p)": round(_miss, 1),
                             "그날 평균수익(%)": round(_mu, 4),
                             "판정": (f"평균수익 {_mu:+.4f}% · 비중 {_mw:.3f} → "
                                    + ("★ **방어가 번 곳**(수익 음수 · 비중 낮음)"
                                       if _mu < 0 and _mw < 0.5 else
                                       f"⚠⚠ **놓치는 곳** — 실제로 오르는 날인데 비중이 {_mw:.2f}다. "
                                       "이 버킷의 비중을 올리는 것이 1번 개선 후보다"
                                       if _mu > 0 and _mw < 0.9 else
                                       "거의 다 참여(개선 여지 작음)" if _mu > 0 else
                                       "⚠ 수익 음수인데 비중이 높다 — 이 버킷 예측이 반대 방향이다"))})
            rows.append({"블록": "F. 국면 버킷 손익 분해", "자산": "★★ 합계",
                         "②−① 단순합(%p)": round(_tot, 1),
                         "판정": (f"버킷 합계 **{_tot:+.1f}%p** — 이 값이 ②가 ①에 미달(또는 초과)하는 "
                                "총액이고, 위 행들이 그 출처다. **가장 음수인 행이 개선 1순위**다.")})
    log("ROT", kv(event="asset_return_compare_built", layer=str(layer), assets=len(cols),
                  port_simple_sum=round(float(port_r.sum()) * 100.0, 2),
                  eq_bh_simple_sum=round(float(eq_r.sum()) * 100.0, 2),
                  w_sum_max=round(float(wsum.max()), 4), w_over_1=_over,
                  note="단순합(복리 아님) = 사용자 지시"), M=M)
    return pd.DataFrame(rows)


def build_up_down_segments(curve_df: pd.DataFrame, exec_w: pd.DataFrame, ret_df: pd.DataFrame,
                           cfg: Any, name_map: Optional[Dict[str, str]] = None,
                           parent_map: Optional[Dict[str, str]] = None,
                           bench_w: Optional[pd.DataFrame] = None,
                           layer: str = "산업", M=None) -> pd.DataFrame:
    """[19_상승하락구간, v0.49.0 Z1 ★ · I v0.20.0 Y3와 동일 코드] 자산별 상승·하락 구간과 **그 구간에서 비중이 어떻게 움직였는지**.

    입력
      curve_df : 날짜 × 자산 — 누적 **총수익** 곡선(구간 분할의 기준)
      exec_w   : 날짜 × 자산 — 그날 실제로 **집행된** 비중(exec_w(t) = target_w(t−1) 규칙 적용 후)
      ret_df   : 날짜 × 자산 — 일간 총수익률(기여 계산용)
      cfg      : SEG_MIN_MOVE·SEG_DETAIL_MAX·SEG_RESPONSE_EPS·SEG_MIN_DAYS를 읽는다

    블록 A(자산별 요약) — "어디가 문제인지"를 한 표에서 본다:
      하락구간 수·평균 등락·**방어 이득 합(%p)**(= −Σ기여, 0 대비) · 감축 성공률(구간 최소비중 < 시작비중)
      상승구간 수·평균 등락·**참여 부족 합(%p)**(= Σ(기여 − 등락률)) · 참여율(기여/등락률 중위)
      문제 유형: 두 합의 절대값을 비교해 '하락 방어 실패' / '상승 미참여' / '양호'
    블록 B(구간 상세): M의 05b와 같은 열 구성 + 벤치대비(%p).

    벤치 정의(중요 · v0.20.0에서 한 번 고쳤다) —
      상승구간: **그 계층이 실제로 쓸 수 있는 비중 예산**(bench_w)을 그 자산에 전부 넣었을 때의 수익.
        산업 계층이면 부모 섹터의 그날 비중(w_s)이다. ⚠ '비중 1.0 완전 참여'를 벤치로 두면 안 된다 —
        산업 한 칸은 부모 비중의 일부만 받을 수 있으므로(최대 = 부모 비중) 도달 불가능한 벤치가 되고,
        그러면 '참여 부족'이 구조적으로 거대해져 하락·상승 비교가 무의미해진다(첫 구현의 결함).
        bench_w가 None이면 1.0(완전 참여)로 되돌아간다 — 계층 예산이 1.0인 자산(예: M의 SPY)용이다.
      하락구간: **무포지션**(0). 안 들고 있는 것은 언제나 도달 가능하므로 벤치로 옳다.
    그래서 '벤치대비'가 음수면 그 구간에서 **도달 가능한 것 대비** 돈을 잃은 것이고,
      음수 합을 상승·하락으로 나누면 손실의 출처가 갈린다."""
    rows: List[dict] = []
    mm = float(getattr(cfg, "SEG_MIN_MOVE", 0.07))
    md = int(getattr(cfg, "SEG_MIN_DAYS", 3))
    eps = float(getattr(cfg, "SEG_RESPONSE_EPS", 0.02))
    cap = int(getattr(cfg, "SEG_DETAIL_MAX", 4000))
    cols = [c for c in curve_df.columns if c in exec_w.columns and c in ret_df.columns]
    rows.append({"블록": "A. 자산별 요약", "자산": "── 읽는 법 ──",
                 "판정": (f"지그재그 최소 변동 {mm:.0%} · 최소 {md}거래일. **벤치대비**가 판정의 중심이다 — "
                        + (f"상승구간은 **그 계층이 쓸 수 있는 비중 예산**({layer} 계층이 그 자산 하나에 줄 수 "
                           "있는 최대 — 산업이면 부모 섹터 비중, 섹터면 그날 섹터에 쓴 총 비중)을 그 자산에 "
                           "전부 넣었을 때 대비, 하락구간은 무포지션(0) 대비. 둘 다 **도달 가능한** 벤치다 "
                           "(비중 1.0을 벤치로 두면 산업 한 칸은 절대 닿을 수 없어 비교가 무의미해진다). "
                           if bench_w is not None else
                           "상승구간은 완전 참여(비중 1.0 = 등락률) 대비, 하락구간은 무포지션(0) 대비. ")
                        + "'참여 부족 합'이 '방어 이득 합'보다 크면 이 계층의 문제는 하락 방어가 아니라 "
                        "**상승 참여**다(13l 블록 E의 손실 분해와 같은 결론이어야 한다). "
                        "'감축 성공률'은 하락구간 안에서 비중이 시작보다 낮아진 적이 있는 구간의 비율이다. "
                        "⚠ 읽을 때 주의할 구조 하나 — 지그재그 상승구간은 **저점에서 시작**하고 그 시점의 "
                        "모멘텀은 음수다. 그래서 **역추세 신호는 상승 참여율이 높게** 나오고(저점에 이미 들고 "
                        "있으므로 랠리 초반을 먹는다) **추세추종 신호는 하락 감축 성공률이 높게** 나온다. "
                        "두 열을 따로 읽어야 하며 한 열만 보고 '이 신호가 낫다'고 판단하면 안 된다 "
                        "(I 계층에서 역추세 신호가 평균초과는 플러스인데 '리더>부모'는 0.4711인 것과 같은 구조다).")})
    detail: List[dict] = []
    for t in cols:
        cur = curve_df[t].dropna()
        if len(cur) < 30:
            continue
        segs = zigzag_segments(cur, mm, md)
        if not segs:
            continue
        w = exec_w[t].reindex(cur.index).astype(float)
        r = ret_df[t].reindex(cur.index).astype(float)
        bw = (bench_w[t].reindex(cur.index).astype(float)
              if (bench_w is not None and t in bench_w.columns) else None)
        dn_bench = []; up_bench = []; dn_cut = []; up_part = []
        dn_mv = []; up_mv = []
        for kind, a, b in segs:
            i0, i1 = cur.index[a], cur.index[b]
            mv = float(cur.iloc[b] / cur.iloc[a] - 1.0)
            # 구간 안(시작 다음날 ~ 종료일)의 집행 비중·수익으로 그 자산의 기여를 만든다
            sl = slice(a + 1, b + 1)
            ws = w.iloc[sl]; rs = r.iloc[sl]
            contrib = float((ws.fillna(0.0) * rs.fillna(0.0)).sum())
            w0 = float(w.iloc[a]) if pd.notna(w.iloc[a]) else 0.0
            wmin = float(ws.min()) if len(ws) else w0
            wmax = float(ws.max()) if len(ws) else w0
            wavg = float(ws.mean()) if len(ws) else w0
            wend = float(w.iloc[b]) if pd.notna(w.iloc[b]) else 0.0
            is_dn = kind.startswith("하락")
            if is_dn:
                bench = 0.0
            elif bw is not None:
                bench = float((bw.iloc[sl].fillna(0.0) * rs.fillna(0.0)).sum())
            else:
                bench = mv
            gap = contrib - bench
            # 첫 대응일 — 하락이면 '줄인' 첫 날, 상승이면 '늘린' 첫 날.
            #   ⚠ 반대 방향(하락 중 '늘린' 날)도 따로 잡는다 — 그것이 M 05b의 '하락 중 진입'이고
            #     진단에서 가장 중요한 실패 유형 하나다(비중 0에서 하락 중에 사 버린 경우).
            resp_d = None; lag = None; opp_d = None; opp_lag = None
            if len(ws):
                dv = (ws - w0)
                _down = dv[dv <= -eps]
                _up_ = dv[dv >= eps]
                hit = _down if is_dn else _up_
                opp = _up_ if is_dn else _down
                if len(hit):
                    resp_d = hit.index[0]
                    lag = int(cur.index.get_loc(resp_d) - a)
                if len(opp):
                    opp_d = opp.index[0]
                    opp_lag = int(cur.index.get_loc(opp_d) - a)
            if is_dn:
                dn_bench.append(gap); dn_mv.append(mv)
                dn_cut.append(1 if wmin < w0 - eps else 0)
            else:
                up_bench.append(gap); up_mv.append(mv)
                up_part.append((contrib / bench) if abs(bench) > 1e-9 else np.nan)
            # 판정 문자열(M 05b의 관행을 따른다)
            if is_dn:
                if wavg <= eps and wmax <= eps:
                    verdict = "무포지션 통과(전 구간 0)"
                elif w0 <= eps and wmax > eps:
                    # ★ 비중 0으로 시작했는데 하락 중에 샀다 — M 05b의 '하락 중 진입'과 같은 유형.
                    #   v0.20.0/v0.49.0 첫 구현에서 이 경우가 '선행 감축'으로 잘못 붙었다(기여는 음수인데
                    #   라벨은 방어 성공처럼 읽혔다). 순서를 바꿔 먼저 잡는다.
                    verdict = (f"⚠ 구간내 매수(하락 중 진입"
                               + (f", 고점 후 {opp_lag}거래일" if opp_lag is not None else "")
                               + f", 0.00→{wmax:.2f})")
                elif wmin < w0 - eps and lag is not None:
                    verdict = f"기간내 감축(지연 {lag}거래일, {w0:.2f}→{wmin:.2f})"
                elif w0 <= eps:
                    verdict = "선행 감축(구간 시작 시 이미 0)"
                else:
                    verdict = f"감축 없음(비중 {wavg:.2f} 보유 통과)"
            else:
                if wavg <= eps:
                    verdict = "매수 없음(미참여)"
                elif w0 >= wmax - eps and w0 > eps:
                    verdict = f"저점 보유(구간 내내 {wavg:.2f} 유지)"
                elif lag is not None:
                    _frac = float((cur.iloc[min(a + lag, b)] / cur.iloc[a] - 1.0) / mv) if abs(mv) > 1e-9 else np.nan
                    verdict = (f"매수(저점 후 {lag}거래일"
                               + (f", 상승분 {_frac:.0%} 지점" if pd.notna(_frac) else "")
                               + f", {w0:.2f}→{wmax:.2f})")
                else:
                    verdict = f"비중 유지({wavg:.2f})"
            detail.append({"블록": "B. 구간 상세", "자산": t,
                           "이름": (name_map or {}).get(t, ""),
                           "부모": (parent_map or {}).get(t, ""),
                           "구간유형": kind, "시작일(고점/저점)": i0, "종료일": i1,
                           "등락률(%)": round(mv * 100, 2), "거래일수": int(b - a),
                           "시작시 비중": round(w0, 4), "구간최소비중": round(wmin, 4),
                           "구간평균비중": round(wavg, 4), "구간최대비중": round(wmax, 4),
                           "종료시 비중": round(wend, 4),
                           "첫 대응일": (resp_d.date().isoformat() if resp_d is not None else "-"),
                           "대응 지연(거래일)": (lag if lag is not None else "-"),
                           "그 자산 기여(%p)": round(contrib * 100, 3),
                           "벤치(%p)": round(bench * 100, 3),
                           "벤치비중(평균)": (round(float(bw.iloc[sl].mean()), 4)
                                        if (bw is not None and len(bw.iloc[sl])) else None),
                           "벤치대비(%p)": round(gap * 100, 3),
                           "판정": verdict})
        _dn_sum = float(np.nansum(dn_bench)) * 100 if dn_bench else 0.0
        _up_sum = float(np.nansum(up_bench)) * 100 if up_bench else 0.0
        if abs(_up_sum) < 1e-9 and abs(_dn_sum) < 1e-9:
            prob = "구간 없음"
        elif _up_sum < 0 and abs(_up_sum) >= abs(min(_dn_sum, 0.0)):
            prob = "★ 상승 미참여가 더 크다"
        elif _dn_sum < 0:
            prob = "★ 하락 방어 실패가 더 크다"
        else:
            prob = "양호(둘 다 플러스)"
        rows.append({"블록": "A. 자산별 요약", "자산": t,
                     "이름": (name_map or {}).get(t, ""), "부모": (parent_map or {}).get(t, ""),
                     "하락구간 수": len(dn_bench),
                     "하락 평균등락(%)": (round(float(np.nanmean(dn_mv)) * 100, 2) if dn_mv else None),
                     "방어 벤치대비 합(%p)": round(_dn_sum, 2),
                     "감축 성공률": (round(float(np.mean(dn_cut)), 3) if dn_cut else None),
                     "상승구간 수": len(up_bench),
                     "상승 평균등락(%)": (round(float(np.nanmean(up_mv)) * 100, 2) if up_mv else None),
                     "참여 벤치대비 합(%p)": round(_up_sum, 2),
                     "참여율(중위)": (round(float(np.nanmedian(up_part)), 3)
                                    if (up_part and any(pd.notna(x) for x in up_part)) else None),
                     "판정": prob})
    # 전체 합계 행 — 13l 블록 E의 손실 분해와 같은 방향인지 여기서 바로 비교한다
    _A = [r for r in rows if r.get("블록") == "A. 자산별 요약" and r.get("자산") != "── 읽는 법 ──"]
    if _A:
        _dn = float(np.nansum([r.get("방어 벤치대비 합(%p)") or 0.0 for r in _A]))
        _up = float(np.nansum([r.get("참여 벤치대비 합(%p)") or 0.0 for r in _A]))
        _neg = abs(min(_dn, 0.0)) + abs(min(_up, 0.0))
        rows.append({"블록": "A. 자산별 요약", "자산": "★ 전체 합계",
                     "하락구간 수": int(np.nansum([r.get("하락구간 수") or 0 for r in _A])),
                     "방어 벤치대비 합(%p)": round(_dn, 2),
                     "상승구간 수": int(np.nansum([r.get("상승구간 수") or 0 for r in _A])),
                     "참여 벤치대비 합(%p)": round(_up, 2),
                     "벤치": (f"계층 비중 예산({layer} 계층이 그 자산 하나에 쓸 수 있는 최대)"
                            if bench_w is not None else "완전 참여(비중 1.0)"),
                     "판정": (f"음수 합 기준 손실 출처 — 상승 미참여 "
                            f"{(abs(min(_up, 0.0)) / _neg if _neg > 1e-9 else 0):.0%} vs 하락 방어 실패 "
                            f"{(abs(min(_dn, 0.0)) / _neg if _neg > 1e-9 else 0):.0%}. "
                            "13l 블록 E의 '상승미달이 손실의 63%'와 같은 방향이어야 한다 — "
                            "다르면 두 정의 중 하나가 틀렸다는 뜻이므로 어느 쪽도 믿지 말고 정의를 먼저 맞춘다.")})
    # 블록 B 크기 제어 — 넘치면 |벤치대비| 큰 순으로 남긴다(최악 구간이 항상 표에 있다)
    _n_all = len(detail)
    if _n_all > cap:
        detail = sorted(detail, key=lambda d: -abs(float(d.get("벤치대비(%p)") or 0.0)))[:cap]
        detail = sorted(detail, key=lambda d: (str(d["자산"]), str(d["시작일(고점/저점)"])))
    out = pd.DataFrame(rows + detail)
    # [v0.20.0] pandas 2.x에서 DataFrame.applymap이 제거됐다 — 열별 문자 길이 합으로 대체한다.
    _bytes = int(sum(int(out[c].astype(str).str.len().sum()) for c in out.columns)) if len(out) else 0
    log("ROT", kv(event="updown_segments_built", layer=str(layer), assets=len(cols),
                  segments_all=_n_all, segments_kept=len(detail), rows=len(out),
                  approx_bytes=_bytes, min_move=mm, min_days=md,
                  note="⚠ 진단 전용 — 구간 분할은 사후(전 구간)이고 목표비중 계산에 들어가지 않는다. "
                       "approx_bytes는 문자 길이 합(압축 전 상한) — 리포트 30MB 제약 감시용"), M=M)
    return out


def build_sector_report(sres: Dict[str, Any], M=None, path: Optional[str] = None) -> str:
    t0 = time.time()
    scfg: SectorConfig = sres.get("scfg", CFG)
    path = path or scfg.OUT_XLSX
    if sres.get("aborted"):
        st = sres.get("selftest", {})
        meta = [("버전", f"{VERSION} ({VERSION_DATE})"),
                ("판별력 자기검사", f"FAIL (참신호 {st.get('n_true_pass')}/3, 잡음오채택 {st.get('n_noise_pass')}/5) — 실데이터 실행 중단"),
                ("면책", "본 산출물은 연구·교육 목적의 백테스트 결과이며 투자 자문이 아닙니다.")]
        write_sector_excel(path, {}, meta, M=M)
        return path
    results = sres["sectors"]
    M_cfg = sres["M_cfg"]
    st = sres["selftest"]
    summary = sres["summary"]
    ok_t = [t for t in scfg.SECTORS if t in results]

    alloc = sres.get("alloc") or {}
    rot_val = sres.get("rot_val") or {}
    sheets: Dict[str, pd.DataFrame] = {}
    sheets["01Z_섹터일별예측"] = sres["matrix"]
    sheets["12_섹터요약"] = summary
    sheets["12b_섹터오류상세"] = build_sector_error_detail(sres.get("failed", {}))   # [v0.8.1] 실패 원인 전체 트레이스백
    sheets["13_섹터배분전략"] = sres["portfolio_perf"]
    sheets["13b_배분전략자산곡선"] = sres["portfolio_curve"]
    if alloc:   # [v0.4.0 §1.F]
        sheets["13c_일별배분비중"] = sres.get("alloc_sheet", pd.DataFrame())
        sheets["13d_횡단면IC"] = rot_val.get("ic_table", pd.DataFrame())
        sheets["13e_순위스프레드"] = rot_val.get("spread_table", pd.DataFrame())
        # [v0.40.0 §S4] 13f에 정보 항목 ⑥ — 섹터 국면 판별력(MCC21>0인 섹터 수). 판정에는 관여하지
        #   않는다(다음 라운드에 판정 편입 여부를 결정). 13f는 '배분(순위)' 기준이고 ⑥은 '국면' 기준이라
        #   성격이 다르므로 종합 PASS/FAIL 계산에서 제외한 채 같은 자리에 나란히 둔다.
        _crit = rot_val.get("criteria", pd.DataFrame())
        try:
            _h = int(getattr(scfg, "REGIME_ACCEPT_HORIZON", 21) or 21)
            _mcc_col = f"MCC({_h}일)"
            _vals = {}
            for t in ok_t:
                _rs = results[t]["sheets"].get("regime_stats")
                if isinstance(_rs, pd.DataFrame) and _mcc_col in _rs.columns and _rs[_mcc_col].notna().any():
                    _vals[t] = float(_rs[_mcc_col].dropna().iloc[0])
            if _vals and isinstance(_crit, pd.DataFrame) and len(_crit):
                _pos = sorted([k for k, v in _vals.items() if v > 0], key=lambda k: -_vals[k])
                _neg = sorted([k for k, v in _vals.items() if v <= 0], key=lambda k: _vals[k])
                _row = pd.DataFrame([{
                    "기준": f"⑥ 섹터 국면 MCC{_h} > 0인 섹터 수 (정보, 판정 제외)",
                    "측정값": (f"{len(_pos)}/{len(_vals)} — 양수: "
                            + ", ".join(f"{k} {_vals[k]:+.3f}" for k in _pos[:6])
                            + (" …" if len(_pos) > 6 else "")
                            + " | 음수(방향이 거꾸로): "
                            + (", ".join(f"{k} {_vals[k]:+.3f}" for k in _neg) if _neg else "없음")
                            + " — 01Y 블록 E, 09_국면통계"),
                    "판정": "정보"}])
                _crit = pd.concat([_crit, _row], ignore_index=True)
        except Exception as _e:   # noqa
            log("ROTATION", kv(event="crit6_failed", err=str(_e)[:120]), M=M, level="warning")
        # [v0.43.0 R1] 13f 정보 항목 ⑦⑧ — 소수 클래스 잣대(판정 제외; 기준선을 한 라운드 본 뒤 문턱을 정한다).
        _ms = sres.get("minority_summary") or {}
        try:
            if _ms and isinstance(_crit, pd.DataFrame) and len(_crit):
                _r7 = {"기준": "⑦ 섹터 국면 하락 균형정확도(h=21, 11섹터 평균) — 소수 클래스 잣대 (정보, 판정 제외)",
                       "측정값": (f"균형정확도 {_ms.get('regime_balanced_mean', np.nan):.3f} · 하락 정밀도 {_ms.get('regime_prec_mean', np.nan):.3f} "
                               f"vs 기저 {_ms.get('regime_base_mean', np.nan):.3f} · 하락 재현율 {_ms.get('regime_rec_mean', np.nan):.3f} · "
                               f"MCC {_ms.get('regime_mcc_mean', np.nan):+.3f} — 0.5/0/기저율이면 하락 예측에 정보 없음. 13p 블록 A·C"),
                       "판정": "정보"}
                _r8 = {"기준": "⑧ 순환매 소수 클래스: 리더 → 실현 상위3 · 모델 꼴찌 → 실현 하위3 (정보, 판정 제외)",
                       "측정값": (f"리더→상위3 {_ms.get('rot_lead_top3', np.nan):.3f}({_ms.get('rot_lead_days', 0)}일, "
                               f"{_ms.get('rot_last_year', '-')}년 {_ms.get('rot_lead_top3_last', np.nan):.3f}) · "
                               f"꼴찌→하위3 {_ms.get('rot_bot_bot3', np.nan):.3f} · 무작위 {_ms.get('rot_random', np.nan):.2f} — "
                               f"꼴찌 쪽이 무작위와 같으면 회피 규칙이 열릴 수 없다. 13p 블록 B") if pd.notna(_ms.get("rot_lead_top3", np.nan))
                              else "배분 없음",
                       "판정": "정보"}
                # [v0.44.0 F1] ⑨ 회피 쪽 — 역방향 회피 격자를 채택 후보로 볼지의 판단 근거.
                _r9 = {"기준": "⑨ 회피 쪽 소수 클래스: 역방향 회피 대상 → 실현 상위3(낮을수록 좋음) (정보, 판정 제외)",
                       "측정값": ((f"역방향 대상→상위3 {_ms.get('rot_rev_top3', np.nan):.3f} · →하위3 {_ms.get('rot_rev_bot3', np.nan):.3f} · "
                                f"초과 {_ms.get('rot_rev_exc', np.nan) * 100:+.2f}%/21일({_ms.get('rot_rev_days', 0)}일) | "
                                f"규칙② 꼴찌 지목→하위3 {_ms.get('rot_avoid_bot3', np.nan):.3f} · →상위3 {_ms.get('rot_avoid_top3', np.nan):.3f} · "
                                f"무작위 {_ms.get('rot_random', np.nan):.2f} — [v0.45.0 G6] 역방향 회피는 퇴역(리포트44 실측 "
                                f"상위3 0.303 > 무작위 · 초과 +0.25%로 조건의 정반대). 하위 쪽 후속은 [단독회피격자](G5). 13p 블록 B")
                               if pd.notna(_ms.get("rot_rev_top3", np.nan)) else
                               (f"역방향 자격 신호 없음(그 해 상위1 t ≤ −{float(getattr(scfg, 'ROTATION_REVERSE_AVOID_T', 2.0)):.1f}인 신호 0개) · "
                                f"규칙② 꼴찌 지목→하위3 {_ms.get('rot_avoid_bot3', np.nan):.3f}")),
                       "판정": "정보"}
                _rows78 = [_r7, _r8, _r9]
                # [v0.44.0 F4] ⑩ 하락확률 보정 — 라벨 방식의 재현율 한계를 풀 수 있는지의 판정 근거.
                _qs = sres.get("down_prob_summary") or {}
                if _qs:
                    _rows78.append({
                        "기준": "⑩ 하락확률 보정: 신뢰도 곡선 기울기·Brier 개선·기저율 문턱 운용점 (정보, 판정 제외)",
                        "측정값": (f"기울기 {_qs.get('slope', np.nan):+.3f}(≥0.10이면 방향 정보) · Brier {_qs.get('brier', np.nan):.5f} "
                                f"vs 기저율만 {_qs.get('brier_base', np.nan):.5f}(개선 {_qs.get('brier_gain', np.nan):+.5f}) · "
                                f"기저율 문턱 운용점: 정밀도 {_qs.get('op_prec', np.nan):.3f} · 재현율 {_qs.get('op_rec', np.nan):.3f} · "
                                f"MCC {_qs.get('op_mcc', np.nan):+.3f}(라벨 방식 재현율 {_ms.get('regime_rec_mean', np.nan):.3f}와 대비) — "
                                f"특징 [{_qs.get('features', '-')}]. 배분 미사용. 13q_하락확률보정"),
                        "판정": "정보"})
                # [v0.45.0 G2] ⑪ 득표 × M 국면 — [대피처격자](G3) 채택 후보를 볼지의 판단 근거.
                if pd.notna(_ms.get("votes_hi_top3", np.nan)):
                    _rows78.append({
                        "기준": "⑪ 득표 × 국면: 복합 1위의 실현 상위3을 '1위 득표수'로 가른다 (정보, 판정 제외)",
                        "측정값": (f"득표≥2 {_ms.get('votes_hi_top3', np.nan):.3f}({_ms.get('votes_hi_days', 0)}일) vs "
                                f"득표≤1 {_ms.get('votes_lo_top3', np.nan):.3f} | "
                                f"득표≤1·M상승 {_ms.get('votes_lo_up_top3', np.nan):.3f} · "
                                f"초과 {_ms.get('votes_lo_up_exc', np.nan) * 100:+.2f}%/{int(getattr(scfg, 'ROTATION_SELECT_HORIZON', 21))}일"
                                f"({_ms.get('votes_lo_up_days', 0)}일) · 무작위 {_ms.get('rot_random', np.nan):.2f} — "
                                f"득표≤1·상승이 무작위 아래면 ★ 잔여 슬리브가 그 날 복합 1위를 사는 현행 규칙이 손해다. "
                                f"[대피처격자] 행과 13m 블록 D로 판정. 13p 블록 D"),
                        "판정": "정보"})
                _crit = pd.concat([_crit, pd.DataFrame(_rows78)], ignore_index=True)
        except Exception as _e:   # noqa
            log("ROTATION", kv(event="crit78_failed", err=str(_e)[:120]), M=M, level="warning")
        sheets["13f_배분수용기준"] = _crit
        sheets["13g_순환매신호채택"] = rot_val.get("selection_log", pd.DataFrame())   # [v0.5.0] 워크포워드 연도별 채택 로그
        sheets["13h_외부검증FF49"] = rot_val.get("external_log", pd.DataFrame())     # [v0.6.0] Ken French 49업종 외부 검증
        sheets["13i_SPY대비격차분해"] = rot_val.get("gap_table", pd.DataFrame())     # [v0.8.0] 연도×판단×리더 섹터 분해
        sheets["13j_배분거래내역"] = sres.get("alloc_trades", pd.DataFrame())        # [v0.9.0] 실제 포트폴리오 거래 로그(한 계좌)
    # [v0.43.0 R1] 13p — 배분과 무관하게(국면 블록은 항상) 낸다.
    _mdf = sres.get("minority")
    if isinstance(_mdf, pd.DataFrame) and len(_mdf):
        sheets["13p_소수클래스정확도"] = _mdf
    _qdf = sres.get("down_prob")            # [v0.44.0 F4] 13q — 배분과 무관(측정 전용)
    if isinstance(_qdf, pd.DataFrame) and len(_qdf):
        sheets["13q_하락확률보정"] = _qdf
    if alloc:
        # [v0.12.0] 사용자 질문("SPY 국면↔섹터 상관관계를 더 철저히 분석해서 국면 정보를 더 참고하라")에 매 실행이
        #   스스로 답하는 진단 시트. 배분 규칙은 무변경 — 순수 관측.
        sheets["13k_국면섹터구조"] = build_regime_sector_structure(alloc, results)
        # [v0.21.0] 잔여 슬리브(주력섹터 상한 밖 비중) 귀속 — 사용자 지시("섹터 순환매 판단 정확도
        #   더 높이도록 개선해 틀린부분이 어딘지 파악해서"). 배분 규칙 무변경 — 순수 관측.
        sheets["13m_잔여슬리브기여"] = build_sleeve_attribution(alloc, results, scfg)
        # [v0.23.0] 사용자 지적("국면 판단이 잘나온거에 비해 섹터 수익률이 많이 안나온다")을
        #   매 실행이 스스로 채점하는 시트. 배분 규칙 무변경 — 순수 관측.
        sheets["13n_섹터대M귀속"] = build_sector_vs_m_attribution(sres, alloc, results, scfg)
        # [v0.36.0 §B] ★의 낙폭이 '국면 오판'인지 '주력 집중'인지를 매 실행이 스스로 가른다.
        #   리포트36 수작업 진단(최대낙폭 2019-05, 40일 전부 상승국면·E_t=1.00)을 상설화. 규칙 무변경.
        sheets["13o_낙폭에피소드"] = build_drawdown_episodes(sres, alloc, results, scfg)
        # [v0.14.0] 사용자 판단기준("정확도가 중요해", "섹터별 일별 예측을 보면 맞는게 별로 없는거 같아")을
        #   매 실행이 스스로 채점하는 시트. 배분 규칙 무변경 — 순수 관측.
        sheets["13l_예측정확도"] = build_prediction_accuracy(alloc)
    # [v0.16.0] 사용자 지시("섹터별로 실제랑 예측 틀린게 많은데 … 정확도 시트좀 따로 만들고") —
    #   섹터별 자기 국면 예측을 실제 결과로 채점. 배분·신호 무변경.
    sheets["01Y_섹터예측정확도"] = build_sector_prediction_accuracy(results, alloc)
    for t in ok_t:
        sheets[f"01_일별_{t}"] = results[t]["sheets"]["daily"]
    # [v0.9.0] 종전 '02_거래내역' — 각 섹터를 '그 섹터 하나만 100% 운용'했을 때의 M식 거래(11벌의 독립 백테스트)라 날짜가 겹친다.
    #   실제 포트폴리오(한 계좌, 합계 ≤ E_t) 거래는 13j. 오해를 막기 위해 시트 이름에 '(진단)'을 명시.
    sheets["02_섹터별단독거래(진단)"] = _concat(results, "trades")
    sheets["03_지표검증"] = _concat(results, "val_sheet")
    sheets["04_채택근거상세"] = _concat(results, "detail")
    sheets["05_이벤트스터디"] = _concat(results, "events")
    sheets["05b_하락상승구간"] = _concat(results, "episodes")
    sheets["06_성과요약"] = _concat(results, "perf")
    sheets["06b_운용통계"] = _concat(results, "extra")
    sheets["06c_임계값민감도"] = _concat(results, "sens")
    sheets["07_연도별성과"] = _concat(results, "annual")
    sheets["08_워크포워드가중치"] = _concat(results, "wf")
    sheets["09_국면통계"] = _concat(results, "regime_stats")
    sheets["09b_규칙별기여"] = _concat(results, "rule_contrib")  # [v0.3.0 §1.G-1]
    # [v0.40.0 §S2] 09c_국면정보게이트 — 섹터×연도로 "그 해 하락 판정에 정보가 있었나"와 판정 결과.
    _gate_all = _concat(results, "regime_gate")
    if isinstance(_gate_all, pd.DataFrame) and len(_gate_all):
        sheets["09c_국면정보게이트"] = _gate_all
    # [v0.41.0 S-C-3] 09d_하락에피소드 — 섹터×에피소드(진입·청산·길이·회피수익·청산후 h일).
    #   REPORT44 §2.2 표를 매 실행 자동 재현한다. 판정 보조(에피소드 수가 2~10개라 단독 판정에는 안 쓴다).
    _ep_all = _concat(results, "regime_episodes")
    if isinstance(_ep_all, pd.DataFrame) and len(_ep_all):
        sheets["09d_하락에피소드"] = _ep_all
    # [v0.42.0 S-N] 09e_H자기확인게이트 — 섹터×연도로 "자기 200일선 위 H진입에 정보가 있었나"와 판정.
    #   게이트를 켠 실행에서만 생긴다(기본 꺼짐).
    _hc_all = _concat(results, "hazard_confirm")
    if isinstance(_hc_all, pd.DataFrame) and len(_hc_all):
        sheets["09e_H자기확인게이트"] = _hc_all
    q = sres.get("quality", pd.DataFrame())
    u = sres.get("universe", pd.DataFrame())
    sheets["10_데이터품질"] = pd.concat([u, q], ignore_index=True, sort=False) if len(q) else u
    sheets["11_룩어헤드감사"] = _concat(results, "audit")

    # ---- [v0.49.0 Z1 ★] 19_상승하락구간 — 사용자 지시("어디가 문제인지 판단하도록") ----
    #   05b_하락상승구간과 **다른 시트**다: 05b는 섹터 단독 전략(02의 짝), 19는 **S★ 배분**이 그 섹터를
    #   실제로 얼마나 들고 있었나를 본다. 비중은 엔진 체결 규칙 그대로 exec_w(t) = target_w(t−1).
    if bool(getattr(scfg, "SHOW_UPDOWN_SEGMENTS", True)) and alloc:
        try:
            _tw = alloc.get("target_w")
            _sc = [t for t in ok_t if _tw is not None and t in _tw.columns and t in results]
            if _tw is not None and len(_tw) and _sc:
                _ret = pd.DataFrame({t: pd.Series(results[t].get("bh_ret"), dtype=float) for t in _sc})
                _ret = _ret.reindex(_tw.index).astype(float)
                _cur = (1.0 + _ret.fillna(0.0)).cumprod()
                _ex = _tw[_sc].shift(1).fillna(0.0)
                # 벤치 = 그날 S★가 **섹터에 쓴 총 비중**(SPY 폴백·현금 제외)을 그 섹터 하나에 전부 넣었을 때.
                #   leader3는 명확한 1위에 섹터 슬리브 전부를 주므로 실제 도달 가능한 천장이다.
                _budget = _tw[_sc].sum(axis=1).shift(1).fillna(0.0)
                _bw = pd.DataFrame({t: _budget for t in _sc})
                _seg = build_up_down_segments(
                    _cur, _ex, _ret, scfg,
                    name_map={t: SECTOR_NAME_KR.get(t, "") for t in _sc},
                    parent_map={t: "SPY" for t in _sc},
                    bench_w=_bw, layer="섹터", M=M)
                # ---- [v0.50.0 C1 ★] 블록 C — **포트폴리오 단위** B&H 대비 ----
                #   블록 A(자산별)의 '참여율'은 leader3가 하루에 한 섹터만 들기 때문에 구조적으로 0에 가깝다.
                #   사용자 질문("B&H 대비 하락을 피했나·상승을 탔나")의 올바른 단위가 블록 C다.
                _cbs: List[pd.DataFrame] = []
                try:
                    _pcv = sres.get("portfolio_curve")
                    _pcur = None
                    if isinstance(_pcv, pd.DataFrame) and len(_pcv):
                        _scol = next((c for c in _pcv.columns if str(c).endswith("★")), None)
                        if _scol is not None:
                            _pcur = pd.to_numeric(_pcv[_scol], errors="coerce")
                            _pcur.index = _tw.index[:len(_pcur)] if len(_pcur) == len(_tw) else _pcur.index
                    if _pcur is None:
                        _bt = (alloc.get("bts") or {}).get(alloc.get("label_star"))
                        if _bt is not None and "strategy_ret" in _bt:
                            _pcur = (1.0 + pd.Series(_bt["strategy_ret"]).astype(float).fillna(0.0)).cumprod()
                    _tot_ex = _tw.sum(axis=1)            # 총노출(섹터 + SPY 폴백)
                    _benches: List[Tuple[str, pd.Series]] = []
                    if isinstance(_pcv, pd.DataFrame) and "SPY B&H" in _pcv.columns:
                        _b = pd.to_numeric(_pcv["SPY B&H"], errors="coerce")
                        if len(_b) == len(_tw):
                            _b.index = _tw.index
                        _benches.append(("SPY 단순보유(B&H)", _b))
                    if isinstance(_pcv, pd.DataFrame) and "11섹터균등B&H" in _pcv.columns:
                        _b2 = pd.to_numeric(_pcv["11섹터균등B&H"], errors="coerce")
                        if len(_b2) == len(_tw):
                            _b2.index = _tw.index
                        _benches.append(("11섹터 균등 B&H", _b2))
                    if _pcur is not None:
                        for _bl, _bcur in _benches:
                            _cbs.append(build_portfolio_segments(
                                _pcur, _tot_ex, _bcur, scfg, bench_label=_bl, layer="섹터",
                                port_label="S★", M=M))
                except Exception as e:
                    log("ROT", kv(event="portfolio_segments_failed", err=str(e)[:160]), M=M, level="warning")
                _out = pd.concat([_seg] + _cbs, ignore_index=True) if _cbs else _seg
                if isinstance(_out, pd.DataFrame) and len(_out):
                    sheets["19_상승하락구간"] = _out
            else:
                log("ROT", kv(event="updown_segments_skipped",
                              reason="alloc.target_w 또는 섹터 열이 비었다"), M=M)
        except Exception as e:
            log("ROT", kv(event="updown_segments_failed", err=str(e)[:200],
                          suggest="alloc['target_w']와 results[t]['bh_ret'] 존재 확인"), M=M, level="warning")
    # [v0.48.0 L6 ★ 신규 — REPORT51 §3.4 E2·§5 L6] rot_raw(순환매 원시신호) 절단재계산 감사. 11_룩어헤드감사가
    #   다루지 않는 REL_MOM_*·HAZ_PCT_OWN·S_REL_*·BETA·MACRO_TAILWIND·MACRO_BETA_FCST 등을 별도로 감사한다.
    sheets["11b_순환매신호감사"] = _concat(results, "rot_audit")

    # ---- 00 실행요약 ----
    n_ok = len(ok_t)
    audit_all = sheets["11_룩어헤드감사"]
    if len(audit_all) and "일치" in audit_all.columns:
        chk = audit_all[~audit_all["일치"].astype(str).str.startswith("N/A")]
        audit_line = ("전체 통과" if (len(chk) == 0 or chk["일치"].astype(str).str.startswith("OK").all())
                      else "불일치 발생 - 확인 필요") + f" ({len(chk)}건 검사)"
    else:
        audit_line = "미실행"
    # [v0.48.0 L6] rot_raw 감사 요약 — 11_룩어헤드감사와 같은 형식의 별도 줄(합치지 않는다, §5 L6).
    rot_audit_all = sheets["11b_순환매신호감사"]
    if len(rot_audit_all) and "일치" in rot_audit_all.columns:
        _rchk = rot_audit_all[~rot_audit_all["일치"].astype(str).isin(("N/A", "오류"))]
        rot_audit_line = ("전체 통과" if (len(_rchk) == 0 or _rchk["일치"].astype(str).eq("OK").all())
                          else "불일치 발생 - 확인 필요") + f" ({len(_rchk)}건 검사, {rot_audit_all['티커'].nunique()}티커)"
    else:
        rot_audit_line = "미실행"
    regime_pass = int(sum(1 for t in ok_t if results[t]["sheets"]["regime_validity"]))
    # [v0.40.0 §S1·§S2·§S3] 이번 라운드 규칙 3개 요약 + 게이트 결과 요약(00시트 2줄).
    _cap = getattr(scfg, "SECTOR_MARKET_BLOCK_CAP", None)
    _tmin = getattr(scfg, "SECTOR_MACRO_T_MIN", None)
    _rmt = getattr(scfg, "ROTATION_RECENT_MIN_T", None)
    _recent_txt = "끔" if _rmt is None else f"t ≥ {float(_rmt):.2f}"   # [v0.42.0 S-I]
    _gstat = str(getattr(scfg, "SECTOR_REGIME_GATE_STAT", "next_day"))
    _astat = str(getattr(scfg, "REGIME_ACCEPT_STAT", "next_day_episode"))
    _regime_rule_line = (
        f"[v0.41.0 S-A 되돌림] 매크로 블록캡 {('끔' if _cap is None else f'{float(_cap):.0%}')}"
        f"(SECTOR_MARKET_BLOCK_CAP) · 매크로 후보 t문턱 {('끔' if _tmin is None else f'{float(_tmin):.1f}')}"
        f"(SECTOR_MACRO_T_MIN) — 리포트44 §2.1(③ 2.08→1.37 FAIL, 리더>SPY 63.8%→51.4%)로 v0.39.0 값으로 복귀. "
        f"추세오버라이드 점수문턱 {float(getattr(scfg, 'SECTOR_OVERRIDE_SCORE_PCT', 0.5)):.2f}"
        f"{'·시장확인 요구' if getattr(scfg, 'SECTOR_OVERRIDE_NEED_MARKET', False) else '·시장확인 없음'} · "
        f"하락 정보 게이트 {'켬' if getattr(scfg, 'SECTOR_REGIME_GATE', False) else '끔'}"
        f"(통계 {'익일 NW' if _gstat == 'next_day' else '전방 %d일' % int(getattr(scfg, 'SECTOR_REGIME_GATE_HORIZON', 21) or 21)}"
        f", t ≤ {float(getattr(scfg, 'SECTOR_REGIME_GATE_T', -1.0)):.1f}이면 유지 · 표본 "
        f"{'신호기간만' if getattr(scfg, 'SECTOR_REGIME_GATE_SIGNAL_ONLY', True) else '전체이력'}) · "
        f"국면정의 수용기준 {'익일+에피소드' if _astat != 'fwd21' else '전방 %d일+MCC' % int(getattr(scfg, 'REGIME_ACCEPT_HORIZON', 21) or 21)}"
        f"(S-C — 09d_하락에피소드 병기). "
        f"게이트 통계 가중 {'감쇠(M과 같은 반감기)' if getattr(scfg, 'SECTOR_REGIME_GATE_DECAY', True) else '균등'}"
        f"(v0.42.0 S-M — 09c에 균등 t 병기) · "
        f"순환매 최근성 조건 {_recent_txt}(v0.42.0 S-I — 13g 최근창 3열은 항상 산출). "
        f"⚠ 전부 신호·판정을 바꾸는 파라미터다 — 되돌리기는 SectorConfig(SECTOR_MARKET_BLOCK_CAP=0.5, "
        f"SECTOR_MACRO_T_MIN=2.5, SECTOR_REGIME_GATE_STAT=\"fwd21\", REGIME_ACCEPT_STAT=\"fwd21\", "
        f"SECTOR_REGIME_GATE_DECAY=False, SECTOR_OVERRIDE_SCORE_PCT=0.5, SECTOR_OVERRIDE_NEED_MARKET=False, "
        f"SECTOR_REGIME_GATE=False).")
    _gt = _concat(results, "regime_gate")
    if isinstance(_gt, pd.DataFrame) and len(_gt) and "판정" in _gt.columns:
        _dg = _gt[_gt["판정"].astype(str).eq("강등")]
        _by_t = _dg.groupby("티커")["적용연도"].apply(lambda x: "+".join(str(int(v)) for v in sorted(x))).to_dict()
        _keep_t = sorted(set(_gt["티커"]) - set(_by_t))
        _gate_line = (f"강등(하락 판정에 정보 없음) {len(_dg)}개 섹터×연도 / 전체 {len(_gt)} — "
                      + ("; ".join(f"{k}:{v}" for k, v in sorted(_by_t.items())) or "없음")
                      + f" | 전 연도 유지(하락 판정 유효): {', '.join(_keep_t) if _keep_t else '없음'}"
                      + " — 09c_국면정보게이트, 01_일별_* '국면정보게이트(강등)' 열")
    else:
        _gate_line = "게이트 꺼짐 또는 판정 없음 — 09c 시트 없음"
    # [v0.42.0 S-N] H진입 자기확인 게이트 요약
    _hc = _concat(results, "hazard_confirm")
    if not bool(getattr(scfg, "SECTOR_HAZARD_CONFIRM_GATE", False)):
        _hconf_line = ("꺼짐(기본) — REPORT45 §3.4의 처방을 사전등록만 해 둔 상태. XLE는 H진입 129회 중 "
                       "119회(92%)가 자기 200일선 위에서 났고 그 날들의 익일 합이 +3.3%p(정보 0)였다. "
                       "⚠ 단독 실행으로 판정할 것: s_overrides={\"SECTOR_HAZARD_CONFIRM_GATE\": True} — 09e 시트가 생긴다")
    elif isinstance(_hc, pd.DataFrame) and len(_hc) and "판정" in _hc.columns:
        _need = _hc[_hc["판정"].astype(str).eq("자기확인 요구")]
        _by_t2 = _need.groupby("티커")["적용연도"].apply(lambda x: "+".join(str(int(v)) for v in sorted(x))).to_dict()
        _keep2 = sorted(set(_hc["티커"]) - set(_by_t2))
        _hconf_line = (f"켬 — 자기확인 요구(200일선 위 H진입에 정보 없음) {len(_need)}개 섹터×연도 / 전체 {len(_hc)} — "
                       + ("; ".join(f"{k}:{v}" for k, v in sorted(_by_t2.items())) or "없음")
                       + f" | 전 연도 유지: {', '.join(_keep2) if _keep2 else '없음'}"
                       + " — 09e_H자기확인게이트, 01_일별_* 'H자기확인(차단)' 열")
    else:
        _hconf_line = "켬 — 판정 없음(표본부족) 또는 09e 시트 없음"
    # [v0.3.0 §1.A] '구분'==실적만 사용 — build_prediction_matrix()가 맨 끝에 붙이는 '예측' 행이
    # 여기 섞이면 "최근 예측"이 확정되지 않은 다음 거래일 값으로 잘못 표시된다.
    mtx = sres["matrix"]
    mtx_actual = mtx[mtx["구분"] == "실적"] if "구분" in mtx.columns else mtx
    up_line = ""
    if len(mtx_actual):
        last = mtx_actual.iloc[-1]
        preds = [f"{t}:{last.get(f'{t} 예측', '')}" for t in scfg.SECTORS]
        up_line = f"{last['날짜']} 기준 — SPY:{last.get('SPY 시장상황', '')} | " + ", ".join(preds)
    pp = sres["portfolio_perf"].set_index("전략") if len(sres["portfolio_perf"]) else pd.DataFrame()

    def _pf(name: str) -> str:
        if name in pp.index:
            r = pp.loc[name]
            return f"CAGR {r.get('CAGR')} / 샤프 {r.get('샤프')} / MDD {r.get('최대낙폭(MDD)')}"
        return "-"

    n_cand = results[ok_t[0]]["n_candidates"] if ok_t else "-"

    # [v0.3.0 §1.A] '다음 거래일 예측' meta 블록 — M의 build_report() 패턴 그대로(새 계산 없음, t일
    # 종가로 이미 확정된 target_pos를 표시만 재구성). SPY 1줄 + 섹터 11줄 + 안내 1줄.
    nd_spy = sres.get("nd_spy")
    nd_rows: List[Tuple[str, str]] = []
    if nd_spy is not None:
        # [v0.61.0 R73] 데이터 신선도 1행(M v1.56.0 freshness_summary_line 재사용 — 단일 출처) + 대상일 경과 표시
        if hasattr(M, "freshness_summary_line"):
            _fl = M.freshness_summary_line({"data_freshness": sres.get("data_freshness"), "cfg": sres.get("M_cfg"),
                                            "last_close_missing": sres.get("last_close_missing"),     # [v0.61.1 R74]
                                            "last_close_day": sres.get("last_close_day")})
            if sres.get("calendar_truncated"):
                _fl += f" · ⚠ [달력절단] 섹터 {len(sres['calendar_truncated'])}개가 M 달력보다 최신(10시트)"
            nd_rows.append(("데이터 신선도", _fl))
        nd_rows.append(("다음 거래일 예측 - 기준일(데이터)", f"{nd_spy['기준일'].date()}{nd_spy['기준일_경과주의']}"))
        nd_rows.append(("다음 거래일 예측 - 대상일",
                        f"{nd_spy['다음거래일'].date()} (NYSE 정규 휴장일 반영 — 임시 휴장은 미반영)"
                        + ("  ⚠ 실행 시점에 이미 지난 날" if nd_spy.get("대상일_경과") else "")))
        nd_rows.append(("다음 거래일 예측 - SPY", f"{nd_spy['확정국면']} / 목표비중 {nd_spy['목표비중']:.2f} / "
                                               f"{nd_spy['예상행동_kr']}"))
        for t in scfg.SECTORS:
            nd_t = results.get(t, {}).get("sheets", {}).get("next_day") if t in results else None
            if nd_t is None:
                nd_rows.append((f"다음 거래일 예측 - {t}", "실패/제외" if t not in results else "판정불가(재구성 실패)"))
                continue
            nd_rows.append((f"다음 거래일 예측 - {t}", f"{nd_t['확정국면']} / 목표비중 {nd_t['목표비중']:.2f} / "
                                                     f"{nd_t['예상행동_kr']}"))
        nd_rows.append(("다음 거래일 예측 - 안내", "t일 종가로 확정된 target_pos를 t+1일 시가에 체결하는 기존 체결 "
                                               "규칙을 표시만 재구성한 것 — 새 계산이 아니며 06/07 등 백테스트 성과 "
                                               "시트에는 영향 없음. 01Z_섹터일별예측 마지막 행(구분=예측)·01_일별_티커 "
                                               "마지막 행에도 같은 값이 있음"))
    else:
        nd_rows.append(("다음 거래일 예측", "미제공(M 번들이 v1.24.0 미만이거나 계산 실패 — '최근 예측'/09b_규칙별기여 참고)"))

    # [v0.4.0 §1.F] '다음 거래일 배분' — 마지막 확정일의 집중배분 비중(= 다음 거래일 시가에 체결할 비중, 새 계산 없음)
    # + 사전 고정 수용기준 판정. 사용자가 실제로 실행할 숫자이므로 예측 블록 바로 아래에 둔다.
    if alloc:
        tw_last = alloc["target_w"].iloc[-1]
        d_last = alloc["target_w"].index[-1]
        e_last = float(alloc["E"].iloc[-1])
        total = float(tw_last.sum())
        dg = alloc["diag"]
        yr_last = int(d_last.year)
