        nd_rows.append(("다음 거래일 배분 - 요약", f"{d_last.date()} 종가 확정 → 다음 거래일 시가 체결: {allocation_summary_text(alloc, d_last, top_n=12)}"))
        order = tw_last.sort_values(ascending=False).index.tolist()
